void free_mac_e_context(MAC_E_CONTEXT **mac_e_ctx, int num_entities) {
    for (int i = 0; i < num_entities; i++) {
        if ((*mac_e_ctx)[i]->num_lchan > 0) {
            for (int j = 0; j < (*mac_e_ctx)[i]->num_lchan; j++) {
                free((*mac_e_ctx)[i]->lchan_array[j].ce_array);
            }
            free((*mac_e_ctx)[i]->lchan_array);
        }
    }
    free(*mac_e_ctx);
}
