#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define MAX_COUNT 1000
#define DEFAULT_COUNT 10
#define MANPAGE_USAGE "Usage: %s [-c <count>] [-s] [-o <output_file>] [--manpage]\n"

int main(int argc, char **argv) {
    int line_count = 0;
    FILE *input_file = NULL;
    FILE *output_file = stdout;
    int print_line_numbers = 1;
    int count = DEFAULT_COUNT;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            count = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-s") == 0) {
            print_line_numbers = 0;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                perror("Error opening output file");
                return 1;
            }
        } else if (strcmp(argv[i], "--manpage") == 0) {
            printf(MANPAGE_USAGE, argv[0]);
            return 0;
        } else {
            char *endptr = NULL;
            long int input_file_offset = strtol(argv[i], &endptr, 10);
            if (*endptr == '\0') {
                input_file = fopen(argv[i], "r");
                if (!input_file) {
                    perror("Error opening input file");
                    return 1;
                }
            } else {
                printf(MANPAGE_USAGE, argv[0]);
                return 1;
            }
        }
    }

    if (!input_file && !strcmp(argv[1], "--manpage")) {
        printf(MANPAGE_USAGE, argv[0]);
        return 0;
    }

    if (!input_file) {
        fprintf(stderr, "Error: No input file provided.\n");
        return 1;
    }

    clock_t start = clock();
    while (fgets(buf, MAX_LINE_LENGTH, input_file)) {
        line_count++;
        if (print_line_numbers)
            printf("%d. %s", line_count, buf);
        else
            printf("%s", buf);

        if (ferror(input_file) || feof(input_file)) {
            break;
        }

        if (line_count > count && !strcmp(argv[1], "-c")) {
            break;
        }
    }

    fclose(input_file);
    if (output_file != stdout)
        fclose(output_file);

    clock_t end = clock();
    printf("Total processing time: %.2f seconds\n", (double)(end - start) / CLOCKS_PER_SEC);
}
