#include <string.h>

typedef struct {
    char *event_type;
    int count;
} EventSummary;

EventSummary* summarize_log_file(char *input_file, char *output_file, char *target_events, int verbose) {
    FILE *fp = fopen(input_file, "r");
    if (!fp) return NULL;

    EventSummary* summaries = (EventSummary*)malloc(sizeof(EventSummary));
    EventSummary* current_summary = summaries;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        // Process log event
        if (strstr(buffer, target_events)) {
            EventSummary* new_summary = (EventSummary*)malloc(sizeof(EventSummary));
            *new_summary = *current_summary;
            current_summary->event_type = strdup(strtok(buffer, ":"));
            int count = atoi(strtok(NULL, " "));
            current_summary->count = count;
            while (*buffer != '\n') {
                buffer++;
            }
            buffer[0] = '\0';
            current_summary->event_type = strtok(buffer, " ");
            if (verbose) printf("%s: %d\n", current_summary->event_type, current_summary->count);
            current_summary = new_summary;
        }
    }

    fclose(fp);

    FILE *output_fp = fopen(output_file, "w");
    if (!output_fp) return summaries;

    while (summaries) {
        fprintf(output_fp, "%s: %d\n", summaries->event_type, summaries->count);
        free(summaries->event_type);
        free(summaries);
        summaries = summaries->next;
    }

    fclose(output_fp);

    return NULL;
}']

