int dns_resolve(const char *hostname, u_char **ipaddr_out) {
    // Initialize DNS cache and rate limits
    HostIP* cached_ip = NULL;
    int cached_ip_count = 0;

    // Limit concurrent DNS requests
    static int concurrent_queries = 0;
    if (concurrent_queries >= dns_cache_max_size)
        return -EAGAIN; // too many concurrent queries

    // Get the rate limit for this hostname
    HostRateLimit* rate_limit = get_host_rate_limit(hostname);

    // Check rate limit and sleep if necessary
    time_t now = time(NULL);
    if (rate_limit->last_query + rate_limit_threshold < now) {
        rate_limit->count = 0;
        rate_limit->last_query = now;
    } else if (++rate_limit->count >= rate_limit_threshold)
        usleep(100000); // sleep for 10ms

    // Perform DNS query
    struct hostent* he = gethostbyname(hostname);
    if (!he) {
        // Handle error
        return -EHOSTUNREACH;
    }

    // Extract IP addresses from the hostent structure
    u_char* ipaddr = NULL;
    int num_ip = 0;
    for (int i = 0; i < he->h_addr_len; i++) {
        if (!ipaddr) {
            ipaddr = malloc(MAX_IPADDR);
            num_ip = 0;
        }
        memcpy(ipaddr + num_ip * inet_ntoa(he->h_addr).sa_len, he->h_addr[i], inet_ntoa(he->h_addr).sa_len);
        num_ip++;
    }

    // Cache resolved IP addresses
    if (!cached_ip || cached_ip_count < dns_cache_max_size) {
        cached_ip[cached_ip_count].hostname[0] = '\0';
        memcpy(cached_ip[cached_ip_count].ipaddr, ipaddr, num_ip * inet_ntoa(he->h_addr).sa_len);
        cached_ip[cached_ip_count++].num_ip = num_ip;
    }

    // Return the IP addresses
    if (cached_ip && !prioritize_ipv4) {
        // Use the first available IPv6 address
        u_char* ipaddr6 = NULL;
        for (int i = 0; i < num_ip; i++) {
            if (!ipaddr6 && inet_ntoa(he->h_addr[i]).sa_family == AF_INET6)
                ipaddr6 = ipaddr + i * inet_ntoa(he->h_addr).sa_len;
        }
        *ipaddr_out = ipaddr6;
    } else {
        *ipaddr_out = ipaddr;
    }

    // Release any allocated memory
    if (cached_ip && cached_ip_count > 0) {
        for (int i = 0; i < cached_ip_count; i++) {
            free(cached_ip[i].ipaddr);
        }
        free(cached_ip);
    }

    // Reset the rate limit and concurrent queries
    rate_limit->count = 0;
    rate_limit->last_query = time(NULL);
    concurrent_queries--;

    return 0;
}

int main() {
    u_char* ipaddr_out;
    dns_resolve("example.com", &ipaddr_out);
    log_dns_query("example.com", ipaddr_out);

