#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>

#define MAX_INTS 1000
#define MAX_INT_VALUE 2147483647

int* readInts(int* count) {
    int i = 0;
    *count = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        char* token = strtok(buffer, ",");
        if (!token) break;

        int num;
        if (sscanf(token, "%d", &num) != 1 || num < -MAX_INT_VALUE || num > MAX_INT_VALUE) {
            free((void*)buffer);
            return NULL; // invalid input
        }

        if (i >= MAX_INTS) {
            fprintf(stderr, "Error: too many integers\n");
            free((void*)buffer);
            return NULL; // memory limit exceeded
        }

        *(int*)malloc(sizeof(int)) = num;
        (*count)++;
    }

    free((void*)buffer);
    return (int*)realloc(NULL, sizeof(int) * (*count));
}

void printLargest(int* ints, int count) {
    if (count == 0) {
        printf("No valid integers provided\n");
    } else {
        int max = ints[0];
        for (int i = 1; i < count; i++) {
            if (ints[i] > max) max = ints[i];
        }
        printf("Largest integer: %d\n", max);
    }
}

int main() {
    signal(SIGINT, SIG_DFL); // reset signal handling
    int count;
    int* ints = readInts(&count);

    if (!ints) return 1; // error occurred

    printLargest(ints, count);
    free((void*)ints);
    return 0;
}
