import subprocess
from cryptography.fernet import Fernet

def pokemon_weaknesses(pokemon_type):
    weaknesses = {
        "grass": ["poison", "fire"],
        "water": ["electric", "grass"],
        "fire": ["water", "rock"]
    }
    return weaknesses.get(pokemon_type, [])

def replace_placeholders(filename, params):
    with open(filename, 'r') as file:
        data = file.read()

    for key, value in params.items():
        data = data.replace(f"{{ {key} }}", str(value))

    with open(filename, 'w') as file:
        file.write(data)

def encrypt_weaknesses(weaknesses, key):
    cipher_suite = Fernet(key)
    encrypted_weaknesses = "".join([cipher_suite.encrypt(f"{weakness}".encode()).decode() for weakness in weaknesses])
    return encrypted_weaknesses

def main(filename, pokemon_name, pokemon_type, key):
    params = {"POKEMON_NAME": pokemon_name}

    try:
        replace_placeholders(filename, params)

        weaknesses = pokemon_weaknesses(pokemon_type)
        encrypted_weaknesses = encrypt_weaknesses(weaknesses, key)

        subprocess.run(f"sed -i '$a {encrypted_weaknesses}' {filename}", shell=True)

    except Exception as e:
        print(f"An error occurred: {str(e)}")

if __name__ == "__main__":
    main("config.txt", "Charizard", "fire", b'your_secret_key_here')
