#include <dlfcn.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    const char* name;
    void (*func)(void*, size_t);
    int param1;
} crypto_func;

crypto_func* get_cryptographic_functions() {
    DIR* dir = opendir("/usr/lib");
    if (dir == NULL) return NULL; // Error opening directory

    struct dirent* ent;
    char* libname;
    void* libhandle;
    crypto_func* func_list = NULL;
    int func_count = 0;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_type, "lib") == 0) {
            libname = strdup(ent->d_name);
            libhandle = dlopen(libname, RTLD_LAZY);
            free(libname);

            if (!libhandle) continue; // Error loading library

            // Check compatibility with kernel version
            int kernel_version = sysctl(KERN_VERSION);
            char* lib_version = dlinfo(libhandle, DL_INFO_Revision);
            int lib_kernel_compatible = strcmp(lib_version, "compatible_kernel_version") == 0;
            dlclose(libhandle); // Free up the library handle

            if (!lib_kernel_compatible) continue; // Not compatible with current kernel version

            void* sym = dlsym(libhandle, "hash_function");
            if (sym != NULL) {
                crypto_func* func = malloc(sizeof(crypto_func));
                func->name = strdup("Hash Function");
                func->func = sym;
                func->param1 = 0;
                func_list = realloc(func_list, (func_count + 1) * sizeof(crypto_func*));
                func_list[func_count] = func;
                func_count++;
            }

            sym = dlsym(libhandle, "block_cipher");
            if (sym != NULL) {
                crypto_func* func = malloc(sizeof(crypto_func));
                func->name = strdup("Block Cipher");
                func->func = sym;
                func->param1 = 0;
                func_list = realloc(func_list, (func_count + 1) * sizeof(crypto_func*));
                func_list[func_count] = func;
                func_count++;
            }

            dlclose(libhandle);
        }
    }

    closedir(dir);

    crypto_func** list = malloc(sizeof(crypto_func*) * (func_count + 1));
    for (int i = 0; i < func_count; i++) {
        list[i] = func_list[i];
    }
    list[func_count] = NULL;

    free(func_list);
    return list;
}
