#include <pthread.h>
#include <stdlib.h>

typedef void *(*thread_task)(void *);

struct thread_pool {
    int max_threads;
    pthread_t *threads;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

struct thread_pool* create_thread_pool(int max_threads) {
    struct thread_pool* pool = (struct thread_pool*) malloc(sizeof(struct thread_pool));
    pool->max_threads = max_threads;
    pool->threads = (pthread_t *)malloc(max_threads * sizeof(pthread_t));
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void submit_task(struct thread_pool* pool, thread_task task) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->max_threads; i++) {
        if (!pthread_equal(pool->threads[i], pthread_self())) {
            pthread_create(&pool->threads[i], NULL, task, NULL);
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void join_pool(struct thread_pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->max_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
    pthread_mutex_unlock(&pool->mutex);
    free(pool->threads);
    pthread_cond_destroy(&pool->cond);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
