void insertAfter(Node* head, int target, int value) {
    if (head == nullptr || head->data != target) {
        Node* current = head;
        while (current && current->next) {
            if (current->next->data == target) {
                Node* new_node = new Node(value);
                new_node->prev = current;
                new_node->next = current->next;
                if (new_node->next) {
                    new_node->next->prev = new_node;
                } else {
                    current->next = nullptr;  // Update the next pointer of the previous node
                }
                current->next = new_node;
                return;
            }
            current = current->next;
        }
    }

    Node* current = head;
    while (current) {
        if (current->data == target) {
            Node* new_node = new Node(value);
            new_node->prev = current;
            new_node->next = current->next;
            if (new_node->next) {
                new_node->next->prev = new_node;
            } else {
                current->next = nullptr;  // Update the next pointer of the previous node
            }
            current->next = new_node;
            return;
        }
        current = current->next;
    }

    Node* last = head;
    while (last->next) {
        last = last->next;
    }
    Node* new_node = new Node(value);
    new_node->prev = last;
    last->next = new_node;
}
