#include <boost/beast.hpp>
#include <gtest/gtest.h>

namespace beast = boost::beast;
using namespace beast::http;

class SandeshClient {
public:
    SandeshClient() : timer_(boost::get_system_time()) {}

    void sendRequest(const std::string& method, const std::string& url,
                     const std::string& body, const std::string& contentType) {
        request_.version(11);
        request_.method(method);
        request_.target(url);

        auto header = request_.prepare_payload();
        if (!body.empty()) {
            header.push("Content-Length", std::to_string(body.size()));
            header.push("Content-Type", "application/" + contentType);
            request_.set_body(beast::buffer(body), body.size());
        }

        beast::error_code ec;
        boost::asio::io_context io_ctx;
        tcp::resolver r(io_ctx);
        tcp::socket sock(io_ctx);

        auto host = r.resolve("localhost", "8080").end();
        if (host != r.end()) {
            beast::get_lowest_layer(sock).async_connect(host, ec);
            if (ec) {
                std::cerr << "Connection failed: " << ec.message() << std::endl;
                return;
            }
        }

        beast::ssl_set_socket sock_ssl(sock);

        beast::streambuf sb;
        beast::output_stream os(sb);
        request_.body().prepare_copy(os, 0, request_.body().size(), ec);
        if (ec) {
            std::cerr << "Write failed: " << ec.message() << std::endl;
            return;
        }

        beast::error_code error;
        boost::asio::io_context io_ctx_;
        beast::ssl_set_socket sock_ssl_;
        beast::streambuf sb_;
        beast::output_stream os_;
        request_.body().prepare_copy(os_, 0, request_.body().size(), error);
        if (error) {
            std::cerr << "Write failed: " << error.message() << std::endl;
            return;
        }

        // Simulate network conditions
        if (method == "GET" && url.find("metadata") != std::string::npos)
            request_.set_response(beast::http::status::service unavailable);
    }

private:
    beast::timer timer_;
};

