        // Simulate different network conditions
        EXPECT_TRUE(SandeshClient().findVmUuidFromMetadataIp("192.168.1.100"));
        EXPECT_FALSE(SandeshClient().findVmUuidFromMetadataIp("192.168.1.101"));
