        // Send GET request with JSON content type
        SandeshClient client;
        client.sendRequest("GET", "/metadata/abc", "", "json");
        // Verify response

        // Send POST request with XML content type
        client.sendRequest("POST", "/metadata/xyz", "<data><value>test</value></data>", "xml");
