namespace MyLog {
    class Logger {
    public:
        static boost::log::attributes::attribute_value_ref<std::string> logger_name;
        static void init();
        static void set_log_level(boost::log::trivial::severity_level level);
        static void log_message(const std::string& message, boost::log::trivial::severity_level severity = boost::log::trivial::info);

    private:
        Logger() {}
        ~Logger() {}

        static boost::log::core& get_core();

        friend class Logger;
    };

    namespace attributes {
        attribute_value_ref<std::string> logger_name = "MyLog";
    }

    void Logger::init() {
        auto core = &get_core();
        core->add_common_attributes(boost::log::attributes::make_attribute("LoggerName", "MyLog"));
        boost::log::add_common_attribute("MyLog", "Version", 1.0);
    }

    void Logger::set_log_level(boost::log::trivial::severity_level level) {
        auto& core = get_core();
        core.set_filter(boost::log::make_severity_filter(level));
    }

    void Logger::log_message(const std::string& message, boost::log::trivial::severity_level severity) {
        auto& core = get_core();
        boost::log::record rec = boost::log::core::get()->current_record();
        rec.set_attribute(boost::log::attributes::make_attribute_value("Message", message));
        rec.set_attribute(boost::log::attributes::make_attribute_value("Severity", boost::log::trivial::to_name(severity)));
        core.add_multistatement(record(rec), severity);
    }

    boost::log::core& Logger::get_core() {
        static auto core = boost::log::core::get();
        return *core;
    }
}
