public static Dictionary<string, object> ExecuteStoredProcedure(SqlConnection connection, string procedureName, List<SqlParameter> inputParameters, List<SqlParameter> outputParameters)
{
    using (var command = new SqlCommand(procedureName, connection))
    {
        command.CommandType = CommandType.StoredProcedure;

        foreach (var parameter in inputParameters)
        {
            command.Parameters.Add(parameter);
        }

        try
        {
            command.ExecuteNonQuery();

            var result = new Dictionary<string, object>();

            foreach (var outputParameter in outputParameters)
            {
                outputParameter.Value = command.ExecuteScalar();
                result.Add(outputParameter.ParameterName, outputParameter.Value);
            }

            return result;
        }
        catch (SqlException ex)
        {
            // Handle SQL exceptions
            Console.WriteLine("SQL Exception: " + ex.Message);

            throw;
        }
        catch (Exception ex)
        {
            // Handle other exceptions
            Console.WriteLine("General Exception: " + ex.Message);

            throw;
        }
    }
}
