from typing import Dict, List

class SettingsManager:
    def __init__(self):
        self.settings: Dict[str, dict] = {}

    def get_setting(self, key: str) -> dict:
        if key not in self.settings:
            return {"error": f"Setting '{key}' not found"}
        return self.settings[key]

    def update_setting(self, key: str, updates: dict) -> dict:
        if key not in self.settings:
            return {"error": f"Setting '{key}' not found"}
        self.settings[key].update(updates)
        return {"success": f"Updated setting '{key}'"}

    def delete_setting(self, key: str) -> dict:
        if key not in self.settings:
            return {"error": f"Setting '{key}' not found"}
        del self.settings[key]
        return {"success": f"Deleted setting '{key}'"}

    def batch_process_settings(self, keys: List[str], updates: Dict[str, dict]) -> List[Dict]:
        results = []
        for key in keys:
            if key not in self.settings:
                results.append({"error": f"Setting '{key}' not found"})
            else:
                updated_setting = self.settings[key]
                updated_setting.update(updates.get(key, {}))
                results.append({"success": f"Updated setting '{key}'"})
        return results
