using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public List<XElement> ParseXml(string xmlString, string nodeName)
    {
        List<XElement> result = new List<XElement>();

        try
        {
            XmlDocument doc = new XmlDocument();
            doc.LoadXml(xmlString);

            XPathNavigator nav = doc.CreateNavigator();
            XPathExpression expression = nav.Compile("/" + nodeName);

            XPathNodeIterator nodes = nav.Select(expression);

            foreach (XPathNode node in nodes)
            {
                if (node.NodeType == XmlNodeType.Element)
                {
                    XElement element = new XElement(node.Name);
                    result.Add(element);
                }
                else
                {
                    Log($"Non-element node encountered: {node.Name}");
                }
            }
        }
        catch (XmlException ex)
        {
            Log("Error parsing XML: " + ex.Message);
        }

        return result;
    }

    private void Log(string message)
    {
        // Implement your logging mechanism here, e.g., using NLog or Serilog
        Console.WriteLine(message);
    }
}
