import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.cache.CacheManager;
import javax.cache.spi.CachingProvider;

public class MD5Processor {
    private final int THREAD_POOL_SIZE = 10; // adjust this value to change the thread pool size
    private final int CACHE_CAPACITY = 1000; // adjust this value to change the cache capacity

    private CachingProvider provider;
    private CacheManager manager;

    public String processBatch(String[] inputs) {
        if (inputs == null || inputs.length == 0) return "";

        if (!initCache());
        try {
            return processBatchParallel(inputs);
        } catch (Exception e) {
            // handle exception gracefully
            return "Error processing batch";
        }
    }

    private boolean initCache() {
        provider = Caching.getCachingProvider();
        manager = provider.getCacheManager();

        if (manager == null) {
            throw new RuntimeException("Failed to initialize cache");
        }

        manager.createCache("md5-cache", javax.cache.spi.CachingSPI.DEFAULT_CACHE_CONFIGURATION);
        return true;
    }

    private String processBatchParallel(String[] inputs) {
        java.util.concurrent.ForkJoinPool pool = new java.util.concurrent.ForkJoinPool(THREAD_POOL_SIZE);

        java.util.stream.Stream<String> stream = java.util.stream.of(inputs)
                .parallel()
                .map(this::computeMD5Hash);

        return stream.reduce("", (s1, s2) -> s1 + "," + s2);
    }

    private String computeMD5Hash(String input) {
        if (input == null || input.isEmpty()) return "";

        try (MessageDigest md = MessageDigest.getInstance("MD5")) {
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xFF & b);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash");
        }
    }
}
