    public MoSTState loadStateObject(File file) throws IOException {
        MoSTState state = null;
        int attempts = 0;

        while (attempts < MAX_LOAD_ATTEMPTS) {
            try (ObjectInputStream inputStream = new ObjectInputStream(new FileInputStream(file))) {
                state = (MoSTState) inputStream.readObject();
                break;
            } catch (EOFException e) {
                // File is empty
            } catch (IOException e) {
                // Try again
            }

            attempts++;
        }

        if (state == null || !isValidState(state)) {
            // Log error and retry
            logError("Failed to load state object from file: " + file);
            return loadStateObject(file); // Retry once
        }

        cache.put(file, state);
        loadCount.incrementAndGet();
        return state;
