async function readConfigFile(directory) {
  try {
    const fs = require('fs');
    const filePath = `${directory}/config.json`;

    if (!await fs/promises/exists(filePath)) {
      throw new Error(`Config file not found at ${filePath}`);
    }

    const configBuffer = await fs.promises.readFile(filePath, 'utf8');
    const configJson = JSON.parse(configBuffer.toString());

    return configJson;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
