const blueslip = require('blueslip');
let totalPassed = 0;
let totalFailed = 0;

const runTests = (moduleName, testLabel, testFunction, { loggingLevel = 'info', resetBlueslip = true, timeout = 5000 } = {}) => {
    return new Promise((resolve, reject) => {
        try {
            const moduleToTest = require(moduleName);
            blueslip.reset();

            testFunction().then(() => {
                console.log(`Test ${testLabel} passed for module ${moduleName}`);
                totalPassed++;
                resolve({ result: 'passed', moduleName, testLabel });
            }, (err) => {
                console.error(`Test ${testLabel} failed for module ${moduleName}: ${err}`);
                totalFailed++;
                reject({ result: 'failed', moduleName, testLabel, error: err });
            }).catch((err) => {
                console.error(`Test ${testLabel} failed for module ${moduleName}: ${err}`);
                totalFailed++;
                reject({ result: 'failed', moduleName, testLabel, error: err });
            });
        } catch (error) {
            console.error(`Error while testing module ${moduleName}: ${error}`);
            reject({ result: 'errored', moduleName, testLabel, error });
        }
    });
};

module.exports = runTests;
