const fetch = require('node-fetch');
const bibleApiUrl = 'https://api.example.com/bible/books/old-testament';
const punctuationRegex = /[^a-zA-Z0-9\s]/g;
const bibleBookRegex = /\b(Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclastics|SongofSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Micah|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;
const API_CALLS = 0;

async function getBibleBooks() {
  const response = await fetch(bibleApiUrl);
  return await response.json();
}

function processText(text) {
  text = text.toLowerCase().replace(punctuationRegex, '');
  const bookNames = {};
  let matches;
  while ((matches = bibleBookRegex.exec(text))) {
    if (!bookNames[matches[1]]) bookNames[matches[1]] = 0;
    bookNames[matches[1]]++;
  }
  return bookNames;
}

async function searchBibleText(text, filterLessCommon) {
  const bibleBooks = await getBibleBooks();
  const processedText = processText(text);
  let result = {};
  for (const [book, count] of Object.entries(processedText)) {
    if (bibleBooks.includes(book) && (filterLessCommon || count >= 5)) {
      result[book] = count;
    }
  }
  console.log(`API calls: ${++API_CALLS}`);
  return result;
}

module.exports = searchBibleText;
```"]

