function generateConfigPage(configs) {
  const html = [];
  let activeSections = {};

  configs.forEach((config) => {
    const sectionHtml = `
      <div class="section">
        <h2>${config.title}</h2>
        <ul id="${config.section}-options" class="option-list">
          ${config.options.map((option, index) => `<li>${index + 1}. ${option}</li>`).join('')}
        </ul>
      </div>
    `;
    html.push(sectionHtml);

    activeSections[config.section] = true;
  });

  const searchInput = `
    <input type="search" id="search-input" placeholder="Search by section title">
  `;

  let searchResults = '';

  document.getElementById('search-button').addEventListener('click', () => {
    const query = document.getElementById('search-input').value.toLowerCase();
    activeSections = {};

    configs.forEach((config) => {
      if (config.title.toLowerCase().includes(query)) {
        activeSections[config.section] = true;
        searchResults += `
          <div class="section">
            <h2>${config.title}</h2>
            <ul id="${config.section}-options" class="option-list">
              ${config.options.map((option, index) => `<li>${index + 1}. ${option}</li>`).join('')}
            </ul>
          </div>
        `;
      }
    });

    const configPageHtml = `
      <header>
        ${searchInput}
        <button id="search-button">Search</button>
      </header>
      ${html.join('')}
      ${searchResults !== '' ? searchResults : ''}
    `;

    return configPageHtml;
  });
}']

