function collectAndGraphData(stream) {
  const dataArray = [];
  let paused = false;

  stream.on('data', (chunk) => {
    if (!paused) {
      dataArray.push(chunk);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
  });

  const graph = new Graph();

  dataArray.forEach((chunk) => {
    chunk.split(',').forEach((vertexData) => {
      const vertex = graph.addVertex({
        id: Math.random(),
        properties: {
          name: randomString(5),
          value: Math.random() * 100,
        },
      });

      if (vertexData.includes('edge')) {
        const edge = graph.addEdge({
          from: vertex.id,
          to: Math.floor(Math.random() * 10),
          properties: {
            weight: Math.random(),
            direction: randomString(3),
          },
        });
      }
    });
  });

  function randomString(length) {
    let result = '';
    for (let i = length; i > 0; --i) {
      result += (Math.floor(Math.random() * 26)).toString(36);
    }
    return result;
  }
}

class Graph {
  constructor() {
    this.vertices = [];
    this.edges = [];
  }

  addVertex(properties) {
    const vertex = { ...properties };
    this.vertices.push(vertex);
    return vertex.id;
  }

  addEdge(edgeProperties) {
    const edge = { ...edgeProperties };
    this.edges.push(edge);
    return edge.id;
  }
}
