function copyBytes(chunks, numBytes) {
    if (chunks.length > 10000 || numBytes > Math.pow(2, 20)) {
        throw new Error("Invalid input");
    }

    let targetBuffer = Buffer.allocUnsafe(numBytes);
    let bufferOffset = 0;

    for (let i = 0; i < chunks.length; i++) {
        const chunk = chunks[i];
        const chunkLength = chunk.length;
        const bytesLeft = numBytes - bufferOffset;

        if (bytesLeft <= 0) break;

        let bytesRead = Math.min(chunkLength, bytesLeft);
        targetBuffer.set(chunk, bufferOffset, bufferOffset + bytesRead);
        bufferOffset += bytesRead;
    }

    return targetBuffer;
}
