function collectElementsByAttr(rootElement, attrName, attrValue, callback) {
  const elements = [];
  (function traverse(node) {
    if (!node) return;
    for (const child of node.children) {
      traverse(child);
    }
    if (node.hasAttribute(attrName)) {
      if (node.getAttribute(attrName) === attrValue) {
        elements.push(node);
      }
    }
  })(rootElement);

  callback(null, elements);
}

// Example usage:
collectElementsByAttr(document.body, 'class', 'example-class', function(err, result) {
  if (err) console.error(err);
  else console.log(result);
});
