// dynamicFileLoader.js

class DynamicFileLoader {
  constructor() {
    this.fileQueue = [];
    this.loadedFiles = {};
    this.errorHandlingEnabled = true;
  }

  async loadAndExecuteFiles(fileNames) {
    this.fileQueue = fileNames;
    await this.executeFiles();
  }

  async executeFiles() {
    while (this.fileQueue.length > 0) {
      const fileName = this.fileQueue.shift();
      try {
        await this.loadFileAndExecute(fileName);
      } catch (error) {
        if (!this.errorHandlingEnabled) throw error;
        console.error(`Error executing file "${fileName}"`);
      }
    }
  }

  async loadFileAndExecute(fileName) {
    if (this.loadedFiles[fileName]) return;

    try {
      const fileContent = await this.loadFileContent(fileName);
      eval(fileContent); // execute the file content as JavaScript
      this.loadedFiles[fileName] = true;
    } catch (error) {
      console.error(`Error loading and executing file "${fileName}"`);
      throw error;
    }
  }

  async loadFileContent(fileName) {
    try {
      const response = await fetch(fileName);
      if (!response.ok) {
        throw new Error(`Failed to load file "${fileName}"`);
      }
      return await response.text();
    } catch (error) {
      console.error(`Error loading file "${fileName}"`);
      throw error;
    }
  }

  setErrorMessageHandling(enabled) {
    this.errorHandlingEnabled = enabled;
  }
}

export default DynamicFileLoader;
