import java.util.*;

class SessionLog {
    long timestamp;
    String ip;

    public SessionLog(long timestamp, String ip) {
        this.timestamp = timestamp;
        this.ip = ip;
    }
}

public class SessionAnalyzer {
    private Map<String, List<SessionLog>> sessionLogs;

    public void analyzeSessions(List<SessionLog> logs) {
        sessionLogs = new HashMap<>();
        for (SessionLog log : logs) {
            String sessionId = log.timestamp + "_" + log.ip;
            if (!sessionLogs.containsKey(sessionId)) {
                sessionLogs.put(sessionId, new ArrayList<>());
            }
            sessionLogs.get(sessionId).add(log);

            long startTime = System.nanoTime();
            analyzeSessionLog(sessionId);
            long endTime = System.nanoTime();

            // Log time taken to analyze each session log entry
            System.out.println("Time taken to analyze " + sessionId + ": " + (endTime - startTime) + " ms");
        }
    }

    private void analyzeSessionLog(String sessionId) {
        List<SessionLog> logs = sessionLogs.get(sessionId);
        if (logs.size() > 1) {
            for (int i = 0; i < logs.size() - 1; i++) {
                SessionLog currentLog = logs.get(i);
                SessionLog nextLog = logs.get(i + 1);

                // Analyze session hijacking attempts based on timestamp and IP address differences
                if (Math.abs(nextLog.timestamp - currentLog.timestamp) < 1000 && !nextLog.ip.equals(currentLog.ip)) {
                    System.out.println("Potential session hijacking attempt detected for " + sessionId);
                }
            }
        }
    }
}']

