import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.Socket;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class StreamManager {

    private Socket socket;
    private DataOutputStream outputStream;
    private DataInputStream inputStream;
    private int buffer_size = 1024; // default buffer size
    private int timeout = 5000; // default timeout in ms

    public void establishConnection(String host, int port) throws IOException {
        socket = new Socket(host, port);
        outputStream = new DataOutputStream(socket.getOutputStream());
        inputStream = new DataInputStream(socket.getInputStream());
    }

    public void setBufferSizes(int readBufferSize, int writeBufferSize) {
        buffer_size = Math.max(readBufferSize, writeBufferSize);
    }

    public void setTimeout(int timeoutMs) {
        this.timeout = timeoutMs;
    }

    public void sendData(byte[] data) throws IOException {
        outputStream.write(data);
        outputStream.flush();
    }

    public byte[] receiveData() throws IOException {
        byte[] buffer = new byte[buffer_size];
        int bytesRead = inputStream.read(buffer, 0, buffer_size);
        return Arrays.copyOfRange(buffer, 0, bytesRead);
    }

    public void closeConnection() throws IOException {
        socket.close();
        outputStream.close();
        inputStream.close();
    }

    public void manageStream(BlockingQueue<Byte[]> receiveQueue) {
        new Thread(() -> {
            while (true) {
                try {
                    byte[] data = receiveData();
                    receiveQueue.put(data);
                } catch (IOException | InterruptedException e) {
                    // handle connection loss
                    reconnect();
                }
            }
        }).start();

        new Thread(() -> {
            while (true) {
                try {
                    byte[] sendBuffer = receiveQueue.take();
                    sendData(sendBuffer);
                } catch (InterruptedException | IOException e) {
                    // handle connection loss
                    reconnect();
                }
            }
        }).start();
    }

    private void reconnect() {
        try {
            // implement reconnection logic here
        } catch (IOException e) {
            // handle reconnection failure
        }
    }
}
