public class ThemeCacheManager {
    private final Map<String, Bitmap> themeCache = new HashMap<>();
    private String defaultThemeDir;
    private final File cacheRootDir;

    public ThemeCacheManager(File cacheRootDir, String defaultThemeDir) {
        this.cacheRootDir = cacheRootDir;
        this.defaultThemeDir = defaultThemeDir;
        initDefaultThemeDirectory();
    }

    public Bitmap getThemeBitmap(String themeName) {
        if (themeCache.containsKey(themeName)) {
            Bitmap bitmap = themeCache.get(themeName);
            if (!isBitmapInUse(bitmap)) {
                themeCache.remove(themeName); // safely dispose of the bitmap
            }
            return bitmap;
        } else {
            File themeDir = new File(cacheRootDir, defaultThemeDir);
            File themeFile = new File(themeDir, themeName + ".png");
            if (themeFile.exists()) {
                try {
                    Bitmap bitmap = BitmapFactory.decodeStream(new FileInputStream(themeFile));
                    themeCache.put(themeName, bitmap);
                    return bitmap;
                } catch (FileNotFoundException e) {
                    // handle file not found exception
                }
            }
        }
        return null; // no theme bitmap found or in use
    }

    private boolean isBitmapInUse(Bitmap bitmap) {
        // implement a robust mechanism to check if the bitmap is still in use
        // for example, using a WeakReference or a concurrent hashmap
        // this can be a complex topic, please research and implement accordingly
    }

    private void initDefaultThemeDirectory() {
        if (!cacheRootDir.exists()) {
            cacheRootDir.mkdirs();
        }
        File defaultThemeDirFile = new File(cacheRootDir, defaultThemeDir);
        if (!defaultThemeDirFile.exists()) {
            defaultThemeDirFile.mkdir();
        }
    }
