    public function __construct($apiUrl, $apiKey) {
        $this->apiUrl = $apiUrl;
        $this->apiKey = $apiKey;
    }

    public function getWeatherData($location) {
        if (file_exists($this->cacheFile) && (time() - filemtime($this->cacheFile)) < $this->cacheDuration) {
            $data = unserialize(file_get_contents($this->cacheFile));
        } else {
            $api = new WeatherAPI($this->apiUrl, $this->apiKey);
            $data = $api->getWeatherData($location);

            file_put_contents($this->cacheFile, serialize($data));

            foreach ($this->plugins as $plugin) {
                $data = $plugin->processWeatherData($data);
            }
        }

        return $data;
    }

    public function addPlugin(Plugin $plugin) {
