async fn create_http_client(
    disable_cert_validation: bool,
    custom_headers: Vec<(String, String)>,
    timeout: u64,
) -> (reqwest::Client, mpsc::Receiver<String>) {
    let client = if disable_cert_validation {
        reqwest::blocking::get("https://example.com")
            .send()
            .unwrap()
            .error_for_status()
            .text()
            .unwrap();
    } else {
        reqwest::blocking::get("https://example.com")
            .send()
            .unwrap()
            .error_for_status()
            .text()
            .unwrap();
    };

    let (tx, rx) = mpsc::channel(10);

    let client = reqwest::Client::builder()
        .timeout_timeout(timeout as f64)
        .header("User-Agent", "My-App")
        .header("Accept-Language", "en-US,en;q=0.8")
        .build()?;

    let request_builder = |url: &str| async {
        if disable_cert_validation {
            client.get(url).send().await?.text().await?
        } else {
            client.get(url).send().await?.text().await?
        };
    };

    (client, tx)
}
