use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use std::mem;
use crossbeam::sync::channel as channel;

async fn compile_and_measure() -> i32 {
    let start = Instant::now();
    let mut process = Command::new("rustc")
        .arg("-Zcustom-logging-hook=your_custom_hook")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();

    let mut rss_before = mem::MaybeUninit::uninit();
    get_resident_set_size(&mut rss_before).unwrap();

    match process.wait() {
        Ok(exit_code) => {
            let end = Instant::now();
            let duration = end - start;

            let mut rss_after = mem::MaybeUninit::uninit();
            get_resident_set_size(&mut rss_after).unwrap();

            println!("Compilation took: {:?}", duration);
            println!("Peak RSS usage was: {} MB", (rss_after.assume_init() - rss_before.assume_init()) / 1024);
        }
        Err(err) => {
            early_error(format!("Error during compilation: {}", err));
            panic!("Program terminated abnormally");
        }
    };

    process.wait().unwrap();
    process.output().unwrap_or_default();
}

fn main() {
    compile_and_measure().await.unwrap();
}
