function generateRegistrationToken($length = 10) {
    $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $token .= $charSet[rand(0, strlen($charSet) - 1)];
    }
    return $token;
}

function hashPassword($password) {
    return password_hash($password, PASSWORD_BCRYPT);
}

function registerUser($username, $email, $password, $additionalInfo = []) {
    $token = generateRegistrationToken();

    // Hash the provided password
    $hashedPassword = hashPassword($password);

    // Store user data in database (optimize for read/write operations)
    $dbConn = dbConnect();
    try {
        $stmt = $dbConn->prepare("INSERT INTO users (username, email, token, hashed_password) VALUES (:username, :email, :token, :hashed_password)");
        $stmt->execute([
            ':username' => $username,
            ':email' => $email,
            ':token' => $token,
            ':hashed_password' => $hashedPassword
        ]);
    } catch (PDOException $e) {
        // Handle potential database errors
        echo "Error: " . $e->getMessage();
    }

    // Store additional user information (if provided)
    foreach ($additionalInfo as $key => $value) {
        $stmt = $dbConn->prepare("INSERT INTO user_info (user_id, key, value) VALUES ((SELECT id FROM users WHERE token = :token), :key, :value)");
        $stmt->execute([
            ':token' => $token,
            ':key' => $key,
            ':value' => $value
        ]);
    }

    return $token;
}
