import requests
from datetime import datetime, timedelta
import pickle
import time

class WeatherAPI:
    def __init__(self, api_key):
        self.api_key = api_key
        self.cache_file = 'weather_cache.pkl'
        self.cache_timeout = 3600  # 1 hour by default
        self.rate_limit = 5  # requests per minute by default
        self.last_request_time = datetime.now()

    def get_weather_data(self, location):
        if (datetime.now() - self.last_request_time).total_seconds() / 60 > self.rate_limit:
            time.sleep(1)  # wait for the rate limit to expire

        url = f'https://api.weather.com/{location}'
        headers = {'X-API-KEY': self.api_key}
        response = requests.get(url, headers=headers)

        if response.status_code == 200:
            return pickle.loads(response.content)
        else:
            raise Exception('Failed to retrieve weather data')

    def cache_weather_data(self, location, data):
        with open(self.cache_file, 'wb') as f:
            pickle.dump({location: data}, f)

    def get_cached_weather_data(self, location):
        try:
            with open(self.cache_file, 'rb') as f:
                cache = pickle.load(f)
                return cache.get(location)
        except FileNotFoundError:
            return None

    def set_cache_timeout(self, seconds):
        self.cache_timeout = seconds

def fetch_weather_data(api_key, location, cache_timeout=3600):
    api = WeatherAPI(api_key)
    if cache_timeout < 1:
        raise ValueError('Cache timeout must be at least 1 second')

    cached_data = api.get_cached_weather_data(location)
    if cached_data is not None:
        return cached_data

    data = api.get_weather_data(location)
    if data is not None:
        api.cache_weather_data(location, data)

    time.sleep(api.cache_timeout)

    return data"]

