public class PasswordDAO {
    private final UserService userService;
    private final AuthenticationService authService;
    private final RetryPolicy retryPolicy;

    public PasswordDAO(UserService userService, AuthenticationService authService, RetryPolicy retryPolicy) {
        this.userService = userService;
        this.authService = authService;
        this.retryPolicy = retryPolicy;
    }

    public void updatePassword(String userId, String oldPassword, String newPassword) {
        // Validate password strength
        if (!validatePasswordStrength(newPassword)) {
            throw new WeakPasswordException();
        }

        // Start a transaction to ensure atomicity
        Transaction tx = userService.startTransaction();

        try {
            // Attempt to update the user's password
            updateUserPassword(tx, userId, oldPassword, newPassword);

            // Commit the transaction if all services responded successfully
            tx.commit();
        } catch (ServiceUnavailableException e) {
            // Roll back the transaction and retry the operation
            tx.rollback();
            retryPolicy.retryOperation(() -> updateUserPassword(tx, userId, oldPassword, newPassword));
        }
    }

    private void updateUserPassword(Transaction tx, String userId, String oldPassword, String newPassword) {
        // Check if the user's password is valid
        authService.validatePassword(userId, oldPassword);

        // Update the user's password in the database
        userService.updateUserPassword(tx, userId, newPassword);
    }
}

public class RetryPolicy {
    public void retryOperation(Runnable operation) throws ServiceUnavailableException {
        int maxRetries = 3;
        for (int i = 0; i < maxRetries; i++) {
            try {
                operation.run();
                return;
            } catch (ServiceUnavailableException e) {
                // Wait for a short period before retrying
                try { Thread.sleep(500); } catch (InterruptedException ignore) {}
            }
        }

        throw new ServiceUnavailableException("Failed to update password after " + maxRetries + " retries");
    }
}

public class UserService {
