#include <stdlib.h>
#include <stdio.h>

struct State {
    int id;
    struct State* next;
};

struct FSA {
    int* transitions;
    int num_states;
};

struct StateList {
    struct State* head;
    int size;
};

struct StateList* manageStateList(int* initialStates, int numInitial, struct FSA* fsa, int lastState, int totalStates) {
    struct StateList* stateList = (struct StateList*)malloc(sizeof(struct StateList));
    if (!stateList) return NULL;

    stateList->head = NULL;
    stateList->size = 0;

    for (int i = 0; i < numInitial; i++) {
        int initialStateId = initialStates[i];
        struct State* currentState = fsa->transitions[initialStateId * totalStates].next;
        while (currentState) {
            if (currentState->id == lastState) {
                struct StateList* tempList = stateList;
                stateList = (struct StateList*)malloc(sizeof(struct StateList));
                if (!stateList) return NULL;

                stateList->head = currentState;
                stateList->size = 1;

                // Link the new state list to the existing state list
                while (tempList->next) tempList = tempList->next;
                tempList->next = stateList;

                free(tempList);
                break;
            }
            currentState = currentState->next;
        }
    }

    return stateList;
}

