#include <iostream>
#include <memory>

class OctreeNode {
public:
    std::shared_ptr<OctreeNode> child[8];
    bool isLeaf;
};

std::unique_ptr<OctreeNode> initOctree(int featureSize, int numLeafNodes, int dataCapacity) {
    if (dataCapacity <= 0) {
        throw std::invalid_argument("Data capacity must be greater than zero");
    }

    std::unique_ptr<OctreeNode> root(new OctreeNode);
    root->isLeaf = false;

    // Calculate the depth of the octree
    int depth = (int)log2(dataCapacity);

    for (int i = 0; i < (1 << depth); i++) {
        int leafIndex = i;
        int nodeIndex = leafIndex;

        std::shared_ptr<OctreeNode> current = root.get();

        // Traverse the octree, creating nodes as needed
        for (int d = 0; d < depth; d++) {
            int mask = (1 << d) - 1;
            int bit = (nodeIndex >> d) & mask;

            if (!current->child[bit]) {
                current->child[bit] = std::shared_ptr<OctreeNode>(new OctreeNode);
            }

            nodeIndex >>= 1;
            current = current->child[bit];
        }

        // Mark the leaf node
        current->isLeaf = true;

        // Create the remaining leaf nodes
        for (int i = 0; i < numLeafNodes - (1 << depth); i++) {
            int index = i + (1 << depth);
            current = root->child[index]->child[7].get();

            while (!current->isLeaf) {
                if (!current->child[0]) {
                    current->child[0] = std::shared_ptr<OctreeNode>(new OctreeNode);
                }

                current = current->child[0].get();
            }
        }
    }

    return root;
}
