#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WINDOW_SIZE (5 * 1000) // 5 seconds in milliseconds
#define THRESHOLD 500000 // predefined threshold for transaction weight
#define UNIQUE_TRANS_ID 256 // maximum number of unique transaction IDs

typedef struct {
    int id;
    time_t timestamp;
    double amount;
    double weight;
} Transaction;

typedef struct {
    int count;
    double sum;
    double average;
} TransMetrics;

Transaction transactions[WINDOW_SIZE];
TransMetrics metrics[UNIQUE_TRANS_ID];

double max_weight_sum = 0.0;
int max_weight_id = -1;
int accepted_count = 0;

void process_transaction(Transaction* transaction) {
    time_t current_time = time(NULL);
    int age = (current_time - transaction->timestamp) / 1000; // convert to seconds
    if (age > 3 || transaction->weight > THRESHOLD || metrics[transaction->id].count >= 100) {
        return;
    }

    double rolling_average = (metrics[transaction->id].sum + transaction->amount) / (metrics[transaction->id].count + 1);
    metrics[transaction->id].count++;
    metrics[transaction->id].sum += transaction->amount;

    if (rolling_average > max_weight_sum && transaction->weight > 0.0) {
        max_weight_sum = rolling_average;
        max_weight_id = transaction->id;
    }

    accepted_count++;
}

int get_max_weight_id() {
    return (accepted_count == 0) ? -1 : max_weight_id;
}
