using System;

public class RandomValueGenerator
{
    private double _min;
    private double _max;

    public RandomValueGenerator(double min = 0, double max = 1)
    {
        SetRange(min, max);
    }

    public void SetRange(double min, double max)
    {
        if (double.IsNaN(min) || double.IsInfinity(min))
        {
            throw new ArgumentException("Minimum value cannot be NaN or infinity.", nameof(min));
        }
        if (double.IsNaN(max) || double.IsInfinity(max))
        {
            throw new ArgumentException("Maximum value cannot be NaN or infinity.", nameof(max));
        }
        if (min >= max)
        {
            throw new ArgumentException("Invalid range. Minimum value must be less than maximum value.");
        }
        _min = min;
        _max = max;
    }

    public double GenerateRandomDouble()
    {
        var rand = new Random();
        return rand.NextDouble() * (_max - _min) + _min;
    }

    public int GenerateRandomInt()
    {
        var rand = new Random();
        return rand.Next((int)_min, (int)_max + 1);
    }

    public double GetMin()
    {
        return _min;
    }

    public double GetMax()
    {
        return _max;
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: Min={_min}, Max={_max}";
    }

    public void ResetRange(double min, double max)
    {
        SetRange(min, max);
    }

    public int[] GenerateRandomSequence(int length)
    {
        var randomValues = new int[length];
        for (int i = 0; i < length; i++)
        {
            randomValues[i] = GenerateRandomInt();
        }
        return randomValues;
    }
}
