const axios = require('axios');

async function robustReduce(arr, initialValue, callback) {
  try {
    let result = initialValue;
    for await (let num of arr) {
      result = await new Promise((resolve, reject) => {
        callback(result, num, (err, accumulator) => {
          if (err) reject(err);
          else resolve(accumulator);
        });
      });
    }
    return result;
  } catch (error) {
    console.error('Error during reduction:', error);
    throw error;
  }
}

// Example usage:
const fetchData = async (url) => {
  try {
    const response = await axios.get(url);
    return response.data;
  } catch (error) {
    console.error('Error fetching data:', error);
    return [];
  }
};

async function enhancedReduce(arr, initialValue, callback) {
  try {
    let result = initialValue;
    for await (let num of arr) {
      const externalData = await fetchData(`https://example.com/api/data/${num}`);
      if (!externalData || !Array.isArray(externalData)) continue;
      for (const dataPoint of externalData) {
        result = await new Promise((resolve, reject) => {
          callback(result, dataPoint.value, (err, accumulator) => {
            if (err) reject(err);
            else resolve(accumulator);
          });
        });
      }
    }
    return result;
  } catch (error) {
    console.error('Error during enhancement:', error);
    throw error;
  }
}

// Example test cases:
const testArray = [1, 2, 3, 4, 5];
const initialValue = 0;

test('Basic reduction', async () => {
  const result = await robustReduce(testArray, initialValue, (acc, num) => acc + num);
  expect(result).toBe(15);
});

test('Enhanced reduction with API data', async () => {
  const result = await enhancedReduce(testArray, initialValue, (acc, num) => acc + num);
  expect(result).toBeGreaterThan(20); // Assuming the API returns additional values that increase the sum
});
