#include <string.h>

int load_resource_bundle(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        return -1; // File not found or corrupted
    }

    int num_items = 0;
    int max_items = 100; // Maximum number of items to load

    char** bundle = malloc(sizeof(char*) * max_items);
    for (int i = 0; i < max_items; i++) {
        bundle[i] = NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* key = strtok(line, ",");
        if (key == NULL) {
            continue; // Invalid line
        }

        char* value = strtok(NULL, "\n");
        if (value == NULL) {
            continue; // Invalid line
        }

        bundle[num_items] = malloc(strlen(key) + 1 + strlen(value) + 1);
        sprintf(bundle[num_items], "%s,%s", key, value);
        num_items++;
    }

    fclose(file);

    for (int i = 0; i < num_items; i++) {
        free(bundle[i]);
    }
    free(bundle);

    return num_items;
}
