char* modify_string(char* str, int size_limit, int max_modifications) {
    if (!str || !size_limit || max_modifications < 0) {
        log_error("Invalid input");
        return NULL;
    }

    if (strlen(str) > size_limit) {
        log_error("String exceeds size limit");
        return NULL;
    }

    char* new_str = malloc(strlen(str) + 2);
    if (!new_str) {
        log_error("Memory allocation failed");
        return NULL;
    }

    strcpy(new_str, str);

    int modifications = 0;
    for (int i = 0; i < max_modifications && strlen(new_str) < size_limit; i++) {
        new_str[strlen(new_str)] = '/';
        modifications++;
    }

    if (modifications >= max_modifications || strlen(new_str) > size_limit) {
        free(new_str);
        return str;
    }

    return new_str;
}
