#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 20

typedef struct {
    int *fields;
    int field_count;
} entry_t;

int process_entry(FILE *file, entry_t *entry) {
    char line[MAX_LINE_LENGTH];
    fgets(line, sizeof(line), file);

    entry->field_count = 0;
    entry->fields = (int *)malloc(MAX_FIELDS * sizeof(int));

    char *token = strtok(line, " ");
    int i = 0;

    while(token && i < MAX_FIELDS) {
        if(sscanf(token, "%d", &entry->fields[i]) == 1) {
            entry->field_count++;
            i++;
        } else {
            free(entry->fields);
            return 0;
        }
        token = strtok(NULL, " ");
    }

    int last_two_fields[2];
    for(int j = entry->field_count - 2; j >= 0 && j < 2; j--) {
        last_two_fields[j] = entry->fields[j];
    }

    double avg = (double)(last_two_fields[0] + last_two_fields[1]) / 2.0;
    printf("%s%.2f\n", line, avg);

    int sum = 0;
    for(int i = 0; i < entry->field_count; i++) {
        sum += entry->fields[i];
    }

    printf("Sum: %d\n", sum);

    return 1;
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if(!file) {
        perror("Error opening file");
        return 1;
    }

    entry_t current_entry;

    int line_count = 0;
    while(fgets(line, sizeof(line), file)) {
        line_count++;
        process_entry(file, &current_entry);
        free(current_entry.fields);
        current_entry.field_count = 0;
    }

    fclose(file);

    return 0;
}
