char* modify_filename(char *filename) {
    char *p = strrchr(filename, '.');
    if (p == NULL) {
        p = filename + strlen(filename);
    }

    int extension_len = p - filename;
    char new_extension[16];
    sprintf(new_extension, "_%d", extension_len);

    char base_name[128], new_filename[256];
    strncpy(base_name, filename, p - filename);
    base_name[p - filename] = '\0';

    for (int i = 0; i < strlen(filename); i++) {
        if (!isalnum((unsigned char)filename[i])) {
            filename[i] = '_';
        }
    }

    strcat(new_filename, base_name);
    int random_number = rand() % 10000;
    sprintf(new_extension + extension_len, "_%04d", random_number);

    if (strlen(new_filename) + strlen(new_extension) > 128) {
        return "Error: filename too long";
    } else {
        strcpy(new_filename + strlen(new_filename), new_extension);
        return strcat(new_filename, new_extension);
    }
}
