    int count = sizeof(algo_list) / sizeof(algo_list[0]);

    for (int i = 0; i < count; i++) {
        if (strncasecmp(algorithms, algo_list[i], strlen(algo_list[i])) == 0) {
            // Add the specified cipher and digest algorithms using EVP_add_cipher and EVP_add_digest functions
            int result = EVP_add_cipher_alias(NULL, algo_list[i]);
            if (result != 1) return -1;  // Handle error: adding cipher failed

            // Create necessary aliases for the added algorithms using EVP_add_cipher_alias
            EVP_add_cipher_alias(NULL, "AES-128-CBC");
            EVP_add_cipher_alias(NULL, "AES-256-CBC");
            EVP_add_cipher_alias(NULL, "Camellia-128-CBC");
            EVP_add_cipher_alias(NULL, "Camellia-256-CBC");

            // Add the specified digest algorithms using EVP_add_digest function
            result = EVP_add_digest(algo_list[i]);
            if (result != 1) return -2;  // Handle error: adding digest failed

            // Create necessary aliases for the added digest algorithms using EVP_add_digest_alias
            EVP_add_digest_alias(NULL, "SHA-256");
        }
    }

    // Implement error handling to manage cases where the addition fails due to existing algorithm conflicts or unsupported parameters
