    // Derive the encryption key and IV using PBKDF2
    unsigned char salt[] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55};
    int derived_key_len = 32;
    int derived_iv_len = 16;
    unsigned char* derived_key = OPENSSL_malloc(derived_key_len);
    unsigned char* derived_iv = OPENSSL_malloc(derived_iv_len);

    PBKDF2_hmac_sha256(password, strlen(password), salt, sizeof(salt), &password[0], strlen(password), iterations, derived_key_len, 1, derived_key, NULL, 0);
    PBKDF2_hmac_sha256(password, strlen(password), salt, sizeof(salt), &password[0], strlen(password), iterations, derived_iv_len, 1, derived_iv, NULL, 0);

    // Initialize AES-256-CBC cipher
    CipherContext* ctx = OPENSSL_malloc(sizeof(struct CipherContext));
    ctx->aes_ctx = AES_new();
    AES_set_encrypt_key(derived_key, derived_key_len, ctx->aes_ctx);
    ctx->iv = OPENSSL_malloc(derived_iv_len);
