        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char file_path[1024];
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);

        int fd = open(file_path, O_RDONLY);
        if (fd < 0) return 1;

        // Apply watermark here
        system("watermark_tool -i input_file.jpg -o output_file.png");

        // Add to PDF file
        system("pdftk input_file.pdf add output_file.png output all_pages.pdf");
    }

    closedir(dp);

    system("pdftk all_pages.pdf output final_output.pdf");

    return 0;
