#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <semaphore.h>

#define MAX_BACKGROUND_PROCESSES 1000
#define TERMINATION_SIGNAL SIGTERM

int background_process_limit = 0;
sem_t process_limit_semaphore;

void handle_termination(int signum) {
    pid_t pid;
    while ((pid = waitpid(-1, NULL, WNOHANG)) > 0) {
        // Process has terminated, remove from running list
    }
}

void start_background_process(char *command) {
    if (sem_wait(&process_limit_semaphore) == -1) {
        // Block further calls until resources become available
        return;
    }

    if (++background_process_limit > MAX_BACKGROUND_PROCESSES) {
        sem_post(&process_limit_semaphore);
        return;
    }

    pid_t child_pid = fork();
    if (child_pid < 0) {
        // Error forking, exit
        sem_post(&process_limit_semaphore);
        return;
    } else if (child_pid == 0) {
        // Child process, start command in background
        signal(SIGTERM, SIG_DFL);
        system(command);
        _exit(0);
    } else {
        // Parent process, wait for child to finish
        signal(TERMINATION_SIGNAL, handle_termination);
        while (waitpid(child_pid, NULL, 0) < 0) {
            // Wait for child process to terminate
        }
    }

    --background_process_limit;
    sem_post(&process_limit_semaphore);

    return 1; // Command started successfully in background
}

int main() {
    if (sem_init(&process_limit_semaphore, 0, 0) == -1) {
        // Error initializing semaphore, exit
        return 1;
    }

    int result = start_background_process("your_command_here");
    sem_destroy(&process_limit_semaphore);

    return result;
}
