    {
        if (!Directory.Exists(directoryPath))
            return "Invalid directory path";

        var webConfigPath = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigPath))
            return "No web.config file found in the directory";

        try
        {
            using (var hosting = new WebHostBuilder()
                .UseIISIntegration()
                .UseWebConfig(webConfigPath)
                .Build())
            {
                hosting.Start();
                IISManager.AddSite(siteName, hosting);
                return $"Website '{siteName}' added and started successfully";
            }
        }
        catch (Exception ex)
        {
            return $"Error adding website: {ex.Message}";
        }
    }
