import java.io.*;
import java.util.concurrent.*;

public class ShellCommandProcessor {
    private static final Logger logger = LoggerFactory.getLogger(ShellCommandProcessor.class);
    private static final int MAX_THREADS = 5;
    private static final int MAX_RETRIES = 3;

    public void processDirectory(String directoryPath) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        Files.walk(directoryPath).forEach(file -> {
            try {
                for (String command : getCommands()) {
                    File fileToProcess = new File(file);
                    if (!fileToProcess.exists()) {
                        logger.warn("File {} not found, skipping", file);
                        continue;
                    }

                    executor.submit(() -> processCommand(file, command));
                }
            } catch (IOException e) {
                logger.error("Error processing file {}", file, e);
            }
        });

        executor.shutdown();
    }

    private void processCommand(String file, String command) throws IOException {
        try {
            Runtime.getRuntime().exec(new String[]{"rm", "-f", file}).waitFor();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }

        try (Process process = Runtime.getRuntime().exec(command)) {
            process.waitFor();

            try (BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream())),
                     stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

                File stdoutFile = new File(file + ".stdout");
                File stderrFile = new File(file + ".stderr");

                try (PrintWriter stdoutWriter = new PrintWriter(new FileWriter(stdoutFile)),
                       stderrWriter = new PrintWriter(new FileWriter(stderrFile))) {
                    String line;
                    while ((line = stdoutReader.readLine()) != null) {
                        stdoutWriter.println(line);
                    }

                    while ((line = stderrReader.readLine()) != null) {
                        stderrWriter.println(line);
                    }
                }
            }
        } catch (IOException | InterruptedException e) {
            logger.error("Error executing command {} for file {}", command, file, e);

            // Retry failed operations up to the specified limit
            int retryCount = 0;
            while (retryCount <= MAX_RETRIES && !processComplete(process)) {
                try {
                    process.waitFor();
                    break;
                } catch (InterruptedException e1) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException(e);
                }
                logger.error("Command {} for file {} failed, retrying...", command, file);

                try {
                    Runtime.getRuntime().exec(new String[]{"rm", "-f", file}).waitFor();
                } catch (IOException | InterruptedException e2) {
                    logger.error("Error retrying to delete file {}", file, e2);
                }

                // Wait before retrying
                Thread.sleep(1000);
            }
        }
    }

    private boolean processComplete(Process process) throws IOException {
        return process.exitValue() == 0;
    }

    private String[] getCommands() {
        // Implement your shell commands here
        return new String[]{"your_command1", "your_command2"};
    }
}
