public class Md5Hasher
{
    public static void ProcessBatch(string[] batch, out string[] hashes)
    {
        using (var md5 = MD5.Create())
        {
            var result = new List<string>();
            foreach (var item in batch)
            {
                try
                {
                    using (var stream = new MemoryStream(Encoding.UTF8.GetBytes(item)))
                    {
                        var hashValue = md5.ComputeHash(stream);
                        result.Add(BitConverter.ToString(hashValue).Replace("-", "").ToLower());
                    }
                }
                catch (Exception ex)
                {
                    // Handle data retrieval issue
                    Console.WriteLine($"Error processing item: {ex.Message}");
                }
            }
            hashes = result.ToArray();
        }
    }
}
