using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] encryptionKey, byte[] iv, string paddingScheme, string hmacSignature)
{
    using (var aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = iv;

        var decryptor = aes.CreateDecryptor();

        using (var ms = new MemoryStream(ciphertext))
        {
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                if (paddingScheme == "PKCS7")
                {
                    byte[] paddedBytes;
                    using (var memoryStream = new MemoryStream())
                    {
                        cs.CopyTo(memoryStream);
                        paddedBytes = memoryStream.ToArray();
                    }
                    var unpaddedBytes = UnpadPaddedData(paddedBytes, aes.BlockSize);
                    return unpaddedBytes;
                }
                else if (paddingScheme == "PKCS5")
                {
                    byte[] paddedBytes;
                    using (var memoryStream = new MemoryStream())
                    {
                        cs.CopyTo(memoryStream);
                        paddedBytes = memoryStream.ToArray();
                    }
                    var unpaddedBytes = UnpadPaddedData(paddedBytes, aes.BlockSize);
                    return unpaddedBytes;
                }
            }
        }
    }

    // Helper method to unpad PKCS7/PKCS5 padding
    static byte[] UnpadPaddedData(byte[] paddedData, int blockSize)
    {
        for (int i = paddedData.Length - 1; i >= 0; i--)
        {
            if (paddedData[i] != blockSize)
                return paddedData;
        }
        return paddedData;
    }
}
