public static void LoadDataFromFile(string filePath)
{
    byte[] buffer = new byte[1024];
    BinaryFormatter formatter = new BinaryFormatter();

    using (FileStream fileStream = File.OpenRead(filePath))
    {
        if (Path.GetExtension(filePath).Equals(".gz", StringComparison.OrdinalIgnoreCase))
        {
            using (GZipStream zipStream = new GZipStream(fileStream, CompressionMode.Decompress))
            {
                object obj;
                while (zipStream.ReadByte() > -1)
                {
                    int readBytes = zipStream.Read(buffer, 0, buffer.Length);
                    using (MemoryStream ms = new MemoryStream(buffer, 0, readBytes))
                    {
                        try
                        {
                            obj = formatter.Deserialize(ms);
                            // Handle your custom data structure here
                            // For example:
                            if (obj is YourCustomDataStructure)
                            {
                                YourCustomDataStructure customData = (YourCustomDataStructure)obj;
                                // Process the deserialized data
                            }
                            else
                            {
                                throw new FormatException("Unsupported file format");
                            }
                        }
                        catch (Exception ex)
                        {
                            throw new IOException("Error reading file", ex);
                        }
                    }
                }
            }
        }
        else if (Path.GetExtension(filePath).Equals(".zip", StringComparison.OrdinalIgnoreCase))
        {
            using (ZipInputStream zipStream = new ZipInputStream(fileStream))
            {
                ZipEntry entry;
                while ((entry = zipStream.ReadNextEntry()) != null)
                {
                    if (entry.CompressedLength > 0)
                    {
                        object obj;
                        byte[] buffer = new byte[1024];
                        using (MemoryStream ms = new MemoryStream())
                        {
                            Stream zipStreamCopy = zipStream.GetInputStream(entry);
                            int readBytes;
                            while ((readBytes = zipStreamCopy.Read(buffer, 0, buffer.Length)) > 0)
                            {
                                ms.Write(buffer, 0, readBytes);
                            }
                            zipStreamCopy.Close();
                            try
                            {
                                ms.Position = 0;
                                obj = formatter.Deserialize(ms);
                                // Handle your custom data structure here
                                // For example:
                                if (obj is YourCustomDataStructure)
                                {
                                    YourCustomDataStructure customData = (YourCustomDataStructure)obj;
                                    // Process the deserialized data
                                }
                                else
                                {
                                    throw new FormatException("Unsupported file format");
                                }
                            }
                            catch (Exception ex)
                            {
                                throw new IOException("Error reading file", ex);
                            }
                        }
                    }
                }
            }
        }
        else
        {
            throw new FormatException("Unsupported compression format");
        }
    }
}
