const { Uploader } = require('uppy');
const logger = require('./logger');

async function uploadFiles(urls) {
  const uploader = new Uploader({
    meta: true,
    retry: 3, // configurable max number of retries
  });

  const logs = [];

  await Promise.all(
    urls.map((url) => {
      return uploader.upload({
        url,
        method: 'GET',
        headers: { Accept: 'text/plain' },
      })
        .then((file) => {
          logs.push({
            name: file.name,
            size: file.size,
            type: file.type,
            status: 'success',
          });
          return Promise.resolve(file);
        })
        .catch((error) => {
          const maxRetries = 3; // configurable max number of retries
          let retryCount = 0;
          return promisify(() => uploader.upload(url)).delay(1000).try(async () => {
            if (retryCount >= maxRetries) {
              logs.push({
                name: file.name,
                size: file.size,
                type: file.type,
                status: 'failure',
                error: error.message,
              });
              return Promise.reject(error);
            }
            retryCount++;
          }).call();
        })
        .then((file) => {
          logs.push({
            name: file.name,
            size: file.size,
            type: file.type,
            status: 'success',
          });
          return Promise.resolve(file);
        });
    })
  );

  logger.info('File uploads complete:', logs);

  const successfulUploads = logs.filter((log) => log.status === 'success');
  return Promise.resolve(successfulUploads.map((log) => log.name));
}
