use tokio;
use std::path::{Path, PathBuf};
use std::fs;

async fn load_plugin(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let module = path.file_stem().unwrap();
    let module_name = module.to_str().unwrap();

    // Load the plugin module
    let mut module_path = path.to_path_buf();
    module_path.set_extension("rs");
    let module_file = module_path.as_path();

    if !module_file.exists() {
        return Err(format!("Plugin '{}' not found", module_name).into());
    }

    // Dynamically load and execute the plugin
    let plugin_module = tokio::runtime::TokioRuntime::new().block_on(
        rustpython::eval::eval(&format!("mod={};", &module_file.display()), None)
    );

    if let Some(plugin) = plugin_module {
        println!("Loaded '{}'", module_name);
        // Execute the plugin
        match plugin.as_ref().unwrap().execute() {
            Ok(_) => println!("Plugin '{}' executed successfully", module_name),
            Err(e) => eprintln!("Error executing plugin '{}' : {}", module_name, e),
        }
    } else {
        eprintln!("Failed to load '{}'", module_name);
    }

    Ok(())
}

async fn discover_plugins(directory: &Path) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
    let mut plugins = Vec::new();

    for entry in fs::read_dir(directory)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() && path.file_name().unwrap().to_str().unwrap().ends_with(".plugin") {
            plugins.push(path);
        }
    }

    Ok(plugins)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let directory = PathBuf::from("path/to/plugins/directory");
    let plugins = discover_plugins(directory).await?;

    for plugin in plugins {
        load_plugin(plugin.as_path()).await?;
    }

    Ok(())
}
