use chrono::NaiveDateTime;
use env_logger;
use log::{debug, error};
use std::env;
use std::fs::create_dir_all;
use std::io;
use std::path::{Path, PathBuf};

fn manage_directory() -> Result<(), io::Error> {
    let current_datetime = NaiveDateTime::from_timestamp(i32::current_timestamp(), 0);
    let directory_name = format!("{}-{:02}-{:02}-{:02}-{:02}-{:02}", current_datetime.year(), current_datetime.month(), current_datetime.day(), current_datetime.hour(), current_datetime.minute(), current_datetime.second());
    let mut dir_path = PathBuf::from(env::var("TMPDIR"));
    dir_path.push(&directory_name);

    loop {
        match create_dir_all(&dir_path) {
            Ok(_) => break,
            Err(err) if err.kind() == io::ErrorKind::PermissionDenied => {
                debug!("Permission denied, trying again");
            }
            Err(err) => {
                error!("Error creating directory: {}", err);
                log_to_file(err)?;
                return Err(err);
            }
        }

        if let Some(dir_path_str) = env::var("DIR_PATH").ok() {
            break;
        }
    }

    env::set_var("DIR_PATH", &dir_path.to_string_lossy().unwrap());

    Ok(())
}

fn log_to_file(error: io::Error) -> Result<(), io::Error> {
    let mut file = match File::create("error.log") {
        Ok(file) => file,
        Err(err) => return Err(err),
    };

    match writeln!(file, "{}", error) {
        Ok(_) => Ok(()),
        Err(err) => Err(err),
    }
}

fn main() {
    env_logger::init();
    if let Err(err) = manage_directory() {
        log_to_file(err).unwrap_or_else(|err| {
            error!("Failed to write to error.log: {}", err);
        });
    }
}
