#define MAX_BUNDLES 10
#define MAX_ITEMS 1000
#define FILE_EXTENSION ".bundle"

typedef struct {
    char* name;
    int size;
} Bundle;

Bundle bundles[MAX_BUNDLES];
int bundle_count = 0;
int max_items = MAX_ITEMS;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void load_bundle(const char* path) {
    pthread_mutex_lock(&lock);
    FILE* file = fopen(path, "r");
    if (!file) {
        printf("Error opening file: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);
        return;
    }

    Bundle new_bundle;
    int line_count = 0;

    char* line = NULL;
    size_t line_len = 0;
    while (getline(&line, &line_len, file) != -1) {
        if (strchr(line, '=') && strchr(line, ',')) {
            line_count++;
        } else {
            printf("Invalid bundle format: %s\n", path);
            fclose(file);
            free(line);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    new_bundle.name = strdup(path);
    new_bundle.size = line_count;

    if (bundle_count >= MAX_BUNDLES) {
        int i = 0;
        for (; i < bundle_count; i++) {
            if (bundles[i].size == 0) {
                break;
            }
        }

        if (i == bundle_count) {
            printf("Maximum number of bundles exceeded: %s\n", path);
            fclose(file);
            free(line);
            pthread_mutex_unlock(&lock);
            return;
        }

        for (int j = i; j < bundle_count - 1; j++) {
            bundles[j] = bundles[j + 1];
        }
        bundles[i].size = new_bundle.size;
    } else {
        bundles[bundle_count++] = new_bundle;
    }

    free(line);
    fclose(file);

    pthread_mutex_unlock(&lock);
}

int get_bundle_count() {
    return bundle_count;
}

int get_max_items() {
    return max_items;
}
