int processImagesToPDF(const char* dirPath, const char* templateFilePath, const char* outputFilePath) {
    // Initialize logger
    logging_init();

    // Iterate over directory
    DIR *dir = opendir(dirPath);
    if (dir == NULL)
        return 1;

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char filePath[1024];
        sprintf(filePath, "%s/%s", dirPath, ent->d_name);

        // Check for image files
        if (strcmp(ent->d_type, "dir") == 0 || strcmp(ent->d_name, templateFilePath) == 0)
            continue;

        // Apply watermark and generate PDF
        int result = applyWatermarkAndGeneratePDF(filePath);
        if (result != 0)
            return 1;

        // Log processed image
        logging_logDebug("Processed image: %s", filePath);
    }

    closedir(dir);

    // Compile images into PDF file
    int pdfResult = compileImagesIntoPDF(outputFilePath);
    if (pdfResult != 0)
        return 1;

    return 0;
}

int applyWatermarkAndGeneratePDF(const char* filePath) {
    // Apply watermark
    int watermarkResult = applyWatermark(filePath);
    if (watermarkResult != 0)
        return 1;

    // Generate PDF
    int pdfResult = generatePDF(filePath);
    if (pdfResult != 0)
        return 1;

    return 0;
}

int compileImagesIntoPDF(const char* outputFilePath) {
    // Compile images into PDF file
    int pdfResult = compileImages(outputFilePath);
    if (pdfResult != 0)
        return 1;

    return 0;
}
