List<string> parseXMLForElements(string xmlDocument, string elementName) {
    XDocument doc = XDocument.Parse(xmlDocument);
    XPathExpression expression;
    try {
        expression = doc.CreateXPathExpression("@name() = '" + elementName + "'");
    } catch (Exception ex) {
        logging_logError("Error parsing XML: " + ex.Message);
        return new List<string>();
    }

    var results = expression.Evaluate().Cast<XElement>().Select(x => x.Value).Distinct().ToList();
    foreach (var result in results)
        logging_logDebug("Found element: " + result);

    return results;
}
