char* modifyFilenameExtension(char* filePath) {
    int len = strlen(filePath);
    for (int i = len - 1; i >= 0; i--) {
        if (filePath[i] == '.') {
            char* newFilePath = malloc(len + 5);
            strcpy(newFilePath, filePath);
            sprintf(newFilePath, "%s_%d%s", filePath, len - i - 1, filePath + i));
            return newFilePath;
        }
    }

    return filePath;
}
