// C: mergeAndFilterLogs
int mergeAndFilterLogs(const char* dirPath, const char* filterCriteria, const char* outputFileName) {
    DIR* dp = opendir(dirPath);
    if (dp == NULL) return 1;

    FILE* outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) return 1;

    struct dirent* entry;
    while ((entry = readdir(dp)) != NULL) {
        char filePath[256];
        sprintf(filePath, "%s/%s", dirPath, entry->d_name);

        FILE* logFile = fopen(filePath, "r");
        if (logFile == NULL) continue; // Ignore errors

        char line[1024];
        while (fgets(line, sizeof(line), logFile)) {
            if (strstr(line, filterCriteria) != NULL) {
                fprintf(outputFile, "%s", line);
            }
        }

        fclose(logFile);
    }

    closedir(dp);
    fclose(outputFile);

    return 0;
}

