            string line;
            while ((line = reader.ReadLine()) != null) {
                string[] columns = line.Split(new char[] { ',' }, StringSplitOptions.None);
                if (columns.Length < 3) continue; // Ignore malformed CSV

                DateTime date;
                if (DateTime.TryParse(columns[1], out date)) {
                    columns[1] = date.ToString("yyyy-MM-dd");
                }

                using (StreamWriter writer = new StreamWriter("output.csv", true)) {
                    writer.WriteLine(string.Join(",", columns));
                }
            }
        }
    } catch (Exception ex) {
        Console.WriteLine(ex.Message);
        return 1;
    }

    return 0;
}

// C: renameFilesByDate
int renameFilesByDate(const char* dirPath) {
    DIR* dp = opendir(dirPath);
    if (dp == NULL) return 1;

    struct dirent* entry;
    while ((entry = readdir(dp)) != NULL) {
        char filePath[256];
        sprintf(filePath, "%s/%s", dirPath, entry->d_name);

        FILE* file = fopen(filePath, "r");
        if (file == NULL) continue; // Ignore errors

        struct stat statbuf;
        fstat(file, &statbuf);
        time_t creationTime = statbuf.st_ctime;

        char newFileName[256];
        strftime(newFileName, sizeof(newFileName), "%Y-%m-%d_%s", localtime(&creationTime));

        rename(filePath, newFileName);

        fclose(file);
    }

    closedir(dp);

    return 0;
}
