#include <tinyxml2.h>

class Octree {
public:
    void init(int featureSize, int numLeafNodes) {
        this->featureSize = featureSize;
        this->numLeafNodes = numLeafNodes;
        // Initialize octree structure
        root = new Node(featureSize, numLeafNodes);
    }

    std::vector<std::string> parseXML(const std::string& xmlFilepath, const std::string& elementName) {
        tinyxml2::XMLDocument doc;
        doc.LoadFile(xmlFilepath.c_str());

        if (!doc.Error()) {
            tinyxml2::XMLElement* rootElement = doc.FirstChildElement("root");
            if (rootElement != nullptr) {
                return parseXMLElement(rootElement, elementName);
            }
        }

        // Handle error
        std::cout << "Error parsing XML document: " << doc.ErrorStr() << std::endl;
        return {};
    }

private:
    struct Node {
        int featureSize;
        int numLeafNodes;
        std::vector<Node*> children;
        std::string value;

        Node(int featureSize, int numLeafNodes) : featureSize(featureSize), numLeafNodes(numLeafNodes), children(), value() {}
    };

    tinyxml2::XMLElement* findElement(tinyxml2::XMLElement* node, const std::string& elementName) {
        if (node->FirstChildElement(elementName.c_str()) != nullptr) {
            return node->FirstChildElement(elementName.c_str());
        }

        for (auto child : node->Children()) {
            tinyxml2::XMLElement* childNode = child->ToElement();
            if (childNode != nullptr && findElement(childNode, elementName) != nullptr) {
                return childNode;
            }
        }

        return nullptr;
    }

    std::vector<std::string> parseXMLElement(tinyxml2::XMLElement* node, const std::string& elementName) {
        std::vector<std::string> uniqueElements;

        if (node->ValueStr() != nullptr) {
            uniqueElements.push_back(node->ValueStr());
        }

        for (auto child : node->Children()) {
            tinyxml2::XMLElement* childNode = child->ToElement();
            if (childNode != nullptr && findElement(childNode, elementName) != nullptr) {
                auto elements = parseXMLElement(childNode, elementName);
                uniqueElements.insert(uniqueElements.end(), elements.begin(), elements.end());
            }
        }

        return uniqueElements;
    }

    int featureSize;
    int numLeafNodes;
    Node* root;
};

