import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class FileDownloader {
    private static final int MAX_CACHE_SIZE = 100;
    private static final int FIXED_THREADS = 5;

    public void downloadFiles(List<FileObject> fileObjects) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(FIXED_THREADS);
        CachingFileDownloader cachingDownloader = new CachingFileDownloader(MAX_CACHE_SIZE);

        for (FileObject fileObject : fileObjects) {
            executor.submit(() -> {
                try {
                    cachingDownloader.downloadAndCache(fileObject.getFilePath());
                } catch (Exception e) {
                    // Handle exceptions gracefully
                    System.out.println("Error downloading: " + fileObject.getFilePath() + ": " + e.getMessage());
                }
            });
        }

        executor.shutdown();
    }

    private static class CachingFileDownloader {
        private final int maxCacheSize;
        private final LRU Cache cache = new LRUCache(maxCacheSize);

        public CachingFileDownloader(int maxCacheSize) {
            this.maxCacheSize = maxCacheSize;
        }

        public void downloadAndCache(String filePath) throws Exception {
            File file = new File(filePath);
            if (!file.exists()) {
                // Handle missing files
                System.out.println("File not found: " + filePath);
                return;
            }

            Future<File> downloadFuture = DownloadThread.executeDownload(file);
            File downloadedFile = downloadFuture.get();

            if (downloadedFile != null) {
                cache.add(filePath, downloadedFile);
                System.out.println("Downloaded and cached: " + filePath);
            } else {
                // Handle network failures or large files
                System.out.println("Failed to download: " + filePath);
            }
        }
    }

    private static class LRUCache<K, V> extends LinkedHashMap<K, V> {
        public LRUCache(int capacity) {
            super(capacity, 0.75f, true); // Load factor and initial capacity
        }

        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > MAX_CACHE_SIZE;
        }
    }

    private static class DownloadThread extends Thread {
        public static Future<File> executeDownload(File file) throws Exception {
            return executor.submit(() -> {
                // Download the file asynchronously using a fixed thread pool
                try {
                    return new File("downloaded_" + file.getName());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });
        }

        private static ExecutorService executor = Executors.newFixedThreadPool(FIXED_THREADS);

        @Override
        public void run() {
            // Track progress and notify user upon completion or failure
            System.out.println("Download started");
            try {
                executeDownload(new File("path_to_your_file.txt"));
            } catch (Exception e) {
                System.out.println("Error during download: " + e.getMessage());
            }
        }
    }
}

public class FileObject {
    private String filePath;

    public FileObject(String filePath) {
        this.filePath = filePath;
    }

    public String getFilePath() {
        return filePath;
    }
}
