#include <pthread.h>

#define MAX_BACKGROUND_PROCESSES 100
#define CACHE_SIZE 1000

typedef struct {
    pid_t pid;
    int exit_status;
} BackgroundProcess;

BackgroundProcess *background_processes = NULL;
int background_process_count = 0;
int max_background_processes = MAX_BACKGROUND_PROCESSES;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cache_available = PTHREAD_COND_INITIALIZER;
pthread_mutex_t bg_process_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t bg_process_available = PTHREAD_COND_INITIALIZER;

void handle_sigterm(int signum) {
    pthread_mutex_lock(&bg_process_lock);
    while (background_process_count > 0) {
        pid_t pid = waitpid(-1, NULL, WNOHANG);
        if (pid != -1) {
            BackgroundProcess *process;
            for (int i = 0; i < background_process_count; i++) {
                if (background_processes[i].pid == pid) {
                    process = &background_processes[i];
                    break;
                }
            }
            if (process) {
                free(process);
                background_processes[i] = background_processes[--background_process_count];
            } else {
                --background_process_count;
            }
        }
    }
    pthread_mutex_unlock(&bg_process_lock);
}

int start_background_command(const char *command, int timeout) {
    pid_t pid = fork();
    if (pid == -1) {
        return 0; // Error forking
    } else if (pid == 0) {
        // Child process
        signal(SIGTERM, SIG_DFL);
        execlp("sh", "-c", command, NULL);
        exit(1); // If execlp fails
    } else {
        // Parent process
        background_processes = realloc(background_processes, (background_process_count + 1) * sizeof(BackgroundProcess));
        background_processes[background_process_count].pid = pid;
        background_processes[background_process_count].exit_status = -1; // Set to unknown
        if (++background_process_count >= max_background_processes) {
            pthread_mutex_lock(&bg_process_lock);
            while (background_process_count >= max_background_processes) {
                pthread_cond_wait(&bg_process_available, &bg_process_lock);
            }
            pthread_mutex_unlock(&bg_process_lock);
        } else {
            pthread_mutex_lock(&cache_lock);
            pthread_cond_signal(&cache_available);
            pthread_mutex_unlock(&cache_lock);
        }
    }
    return 1;
}

void *thread_func(void *arg) {
    while (1) {
        pthread_mutex_lock(&cache_lock);
        while (background_process_count >= max_background_processes) {
            pthread_cond_wait(&cache_available, &cache_lock);
        }
        pid_t pid = waitpid(-1, NULL, WNOHANG);
        if (pid != -1) {
            BackgroundProcess *process;
            for (int i = 0; i < background_process_count; i++) {
                if (background_processes[i].pid == pid) {
                    process = &background_processes[i];
                    break;
                }
            }
            if (process) {
                free(process);
                background_processes[i] = background_processes[--background_process_count];
            } else {
                --background_process_count;
            }
        }
        pthread_mutex_unlock(&cache_lock);
    }
}

void monitor_background_processes() {
    pthread_t thread;
    pthread_create(&thread, NULL, thread_func, NULL);
}

int main() {
    // Initialize the cache
    background_processes = (BackgroundProcess *)malloc(CACHE_SIZE * sizeof(BackgroundProcess));
    pthread_cond_init(&cache_available, NULL);
    pthread_mutex_init(&cache_lock, NULL);
    pthread_mutex_init(&bg_process_lock, NULL);
    pthread_cond_init(&bg_process_available, NULL);

    // Handle SIGTERM signal
    signal(SIGTERM, handle_sigterm);

    // Start a batch of background commands
    int i;
    for (i = 0; i < 10; i++) {
        start_background_command("sleep 1", 2); // Replace with your command and timeout
    }

    monitor_background_processes();

    return 0;
}
