void* manage_mac_e_context() {
    // Initialize mutex for thread safety
    pthread_mutex_t mac_e_context_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Open configuration file
    int config_fd = open("config_file.conf", O_RDONLY);

    if (config_fd < 0) {
        perror("Error opening configuration file");
        return NULL;
    }

    // Read number of MAC Entities from configuration file
    char line[256];
    fgets(line, sizeof(line), config_fd);
    int num_mac_entities = atoi(strtok(line, ":"));

    close(config_fd);

    // Create dynamic array for MAC E CONTEXT structures
    MAC_E_CONTEXT* mac_e_context_array = (MAC_E_CONTEXT*)malloc(num_mac_entities * sizeof(MAC_E_CONTEXT));

    // Initialize each MAC Entity with unique ID and configurable number of LCHANS
    for (int i = 0; i < num_mac_entities; i++) {
        mac_e_context_array[i].mac_id = i;
        int lchan_count = rand() % 10 + 1; // Randomly generate number of LCHANS per MAC Entity
        mac_e_context_array[i].num_lchan = lchan_count;

        // Initialize each LCHAN with valid PDU indicators and random CE
        for (int j = 0; j < lchan_count; j++) {
            mac_e_context_array[i].lchan[j].pdu_indicator = rand() % 255 + 1;
            sprintf(mac_e_context_array[i].lchan[j].ce, "%c", 'A' + rand() % 10);
        }
    }

    // Validate MAC E CONTEXT structures for consistency and integrity
    for (int i = 0; i < num_mac_entities; i++) {
        for (int j = 0; j < mac_e_context_array[i].num_lchan; j++) {
            // Validate PDU indicators and CE for each LCHAN
            if (!validate_pdu_indicator(mac_e_context_array[i].lchan[j].pdu_indicator) || !validate_ce(mac_e_context_array[i].lchan[j].ce)) {
                printf("Invalid MAC E CONTEXT structure at index %d\n", i);
                return NULL;
            }
        }
    }

    // Perform periodic checks for consistency and integrity
    sleep(5); // Simulate periodic check interval

    free(mac_e_context_array);

    return NULL;
}

// Function to validate MAC PDU indicators
int validate_pdu_indicator(int pdu_indicator) {
    // Check for valid PDU indicator values (1-255)
    if (pdu_indicator < 1 || pdu_indicator > 255) {
        return 0; // Invalid PDU indicator
    }

    return 1; // Valid PDU indicator
}

// Function to validate MAC CE strings
int validate_ce(char* ce) {
    // Check for valid CE string length (10 characters)
    if (strlen(ce) != 10) {
        return 0; // Invalid CE string
    }

    return 1; // Valid CE string
}

