    private static final int MAX_CONCURRENT_UPLO ADS = 5; // Adjust this value based on available resources
    private static final int RETRY_ATTEMPTS = 3; // Adjust this value based on the reliability of your external services

    public void processBatchOfFiles(List<File> files) throws IOException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_UPLOADS);

        List<Future<?>> futures = new ArrayList<>();
        for (File file : files) {
            Callable<Object> task = () -> processSingleFile(file);
            Future<?> future = executor.submit(task);
            futures.add(future);
        }

        for (Future<?> future : futures) {
            try {
                future.get(); // Wait for all tasks to complete
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException("Upload interrupted");
            }
        }

        executor.shutdown();
