        _maxValue = 1.0;
        _minIntValue = 0;
        _maxIntValue = int.MaxValue;
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void SetRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value");

        _minIntValue = minValue;
        _maxIntValue = maxValue;
    }

    public double GenerateDouble()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateInt()
    {
        return _random.Next(_maxIntValue - _minIntValue + 1) + _minIntValue;
    }

    public override string ToString()
    {
        return $"Random range: {(_minValue, _maxValue)}";
