namespace Asp.NetCoreApp
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = "Cookies";
                options.DefaultChallengeScheme = "Cookies";
            })
            .AddCookie("Cookies", options =>
            {
                options.LoginPath = "/Login";
                options.LogoutPath = "/Logout";
                options.SlidingExpiration = true;
                options.ExpireTimeSpan = TimeSpan.FromHours(2);
            });

            services.AddSession(options => { options.IdleTimeout = TimeSpan.FromDays(1); });
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseAuthentication();
            app.UseAuthorization();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class AuthController : ControllerBase
    {
        private readonly IHttpContextAccessor _httpContextAccessor;
        private readonly IOptions<AuthenticationOptions> _options;

        public AuthController(IHttpContextAccessor httpContextAccessor, IOptions<AuthenticationOptions> options)
        {
            _httpContextAccessor = httpContextAccessor;
            _options = options;
        }

        [HttpPost]
        public IActionResult Login([FromBody]LoginModel loginModel)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            var user = AuthenticateUser(loginModel.Username, loginModel.Password);

            if (user == null) return Unauthorized();

            // Perform MFA
            if (_options.Value.RequireMfa && !MfaVerified())
                return RedirectToAction("VerifyMfa");

            _httpContextAccessor.HttpContext.SignInAsync(user);
            return Ok();
        }

        [HttpPost]
        public IActionResult Logout()
        {
            _httpContextAccessor.HttpContext.SignOutAsync();
            return Redirect("/");
        }
    }
}

