import requests
from datetime import timedelta
from functools import lru_cache
from cachetools import TTLCache

API_URL = "https://api.example.com/activity-logs"

def fetch_activity_logs(user_id: int, cache_duration: int = None) -> list:
    @lru_cache(maxsize=None)
    def get_user_logs(user_id: int):
        try:
            response = requests.get(f"{API_URL}/{user_id}", timeout=5)
            if response.status_code == 200:
                return response.json()
            elif response.status_code == 404:
                raise ValueError("User not found")
            else:
                raise Exception(f"Error fetching logs: {response.status_code}")
        except (requests.exceptions.RequestException, ConnectionResetError) as e:
            print(f"Request error: {e}")
            return []

    @lru_cache(maxsize=None)
    def get_paged_logs(user_id: int):
        logs = []
        page_number = 1
        while True:
            response = requests.get(
                f"{API_URL}/{user_id}/logs?page={page_number}", timeout=5
            )
            if response.status_code != 200:
                break
            logs.extend(response.json()["logs"])
            page_number += 1

    user_logs = get_user_logs(user_id)
    paged_logs = get_paged_logs(user_id)

    if cache_duration is not None:
        cache_ttl = timedelta(minutes=cache_duration)
        cache = TTLCache(maxsize=None, ttl=cache_ttl)
    else:
        cache = {}

    def cache_log(log):
        if log not in cache:
            cache[log] = 1
        else:
            cache[log] += 1

    for log in paged_logs:
        cache_log(log)

    return user_logs + paged_logs
