use actix::{Actor, AsyncContext, Context};
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use directories::{ProjectDirs, UserDirs};
use log::info;
use std::{
    collections::HashMap,
    fs::DirEntry,
    path::{Path, PathBuf},
};

struct PluginLoader {
    plugin_dir: PathBuf,
    cache: HashMap<String, Box<dyn Fn() -> String>>,
}

impl Actor for PluginLoader {}

impl PluginLoader {
    async fn load_plugin(&mut self, name: &str) -> Result<String, String> {
        if let Some(plugin) = self.cache.get(name) {
            return Ok(plugin().to_string());
        }

        let plugin_dir = &self.plugin_dir;
        let plugins_dir = UserDirs::new().unwrap();
        let plugin_path = plugin_dir.join(plugins_dir.config_dir()).join("plugins").join(name);

        if !plugin_path.exists() || !plugin_path.is_dir() {
            return Err(format!("Plugin {} not found", name));
        }

        info!("Loading plugin {}", name);
        let mut module = reqwest::get(&format!("{}/module.json", plugin_path))
            .await?
            .json::<String>()
            .await?;

        // Execute the module
        actix::spawn(async move {
            // Your plugin execution code goes here
            println!("Plugin {} executed successfully", name);
        });

        self.cache.insert(name.to_string(), Box::new(move || module));
        Ok(module)
    }
}

#[actix_web::main]
async fn main() -> Result<(), std::io::Error> {
    let plugin_loader = PluginLoader {
        plugin_dir: ProjectDirs::new(None, None, "my_plugin").unwrap().lib_dir().join("plugins"),
        cache: HashMap::new(),
    };

    HttpServer::new(|| {
        App::new()
            .app_data(plugin_loader.clone())
            .service(web::resource("/load-plugin/{name}").to_async(move |ctx, name| async move {
                let plugin_loader = ctx.app_data::<PluginLoader>().clone();
                match plugin_loader.load_plugin(&name).await {
                    Ok(result) => HttpResponse::Ok().body(result),
                    Err(err) => HttpResponse::InternalServerError().body(err),
                }
            }))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await?;

    info!("Server started on http://localhost:8080");

    Ok(())
}
