            if (fptr) {
                fgets(dir_path, 256, fptr);
                fclose(fptr);
            }
            fptr = fopen("file_type.txt", "r");
            if (fptr) {
                fgets(file_type, 16, fptr);
                fclose(fptr);
            }

            // Append file type as extension
            char *new_filename = malloc(strlen(base_name) + strlen(file_type) + 2);
            sprintf(new_filename, "%s_%s", base_name, file_type);

            // Replace non-alphanumeric characters with underscores
            char *new_base_name = malloc(strlen(new_filename));
            strcpy(new_base_name, new_filename);
            char *p = new_base_name;
            while (*p) {
                if (!isalnum(*p)) {
                    *p = '_';
                }
                p++;
            }

            // Append directory path length as suffix
            int dir_path_len = strlen(dir_path);
            char *new_filename2 = malloc(strlen(new_base_name) + 10);
            sprintf(new_filename2, "%s_%d", new_base_name, dir_path_len);

