            struct tm *time_info = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, 20, "%Y%m%d_%H%M%S", time_info);
            char *new_filename3 = malloc(strlen(new_filename2) + strlen(timestamp) + 1);
            sprintf(new_filename3, "%s_%s", new_filename2, timestamp);

            // Truncate directory path to 100 characters
            dir_path_len = (dir_path_len > 100) ? 100 : dir_path_len;
