                    *p = '_';
                }
                p++;
            }

            // Generate timestamp and append it to the filename
            time_t current_time = time(NULL);
            struct tm *time_info = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, 20, "%Y%m%d_%H%M%S", time_info);
            char *new_filename2 = malloc(strlen(new_base_name) + strlen(timestamp) + 1);
            sprintf(new_filename2, "%s%s", new_base_name, timestamp);

            // Ensure filename length does not exceed 255 characters
            int len = strlen(new_filename2);
            if (len > 255) {
                char *new_filename3 = malloc(256);
                sprintf(new_filename3, "%.*s", 255 - len, new_filename2);
                free(new_base_name);
                free(new_filename2);
                new_base_name = new_filename3;
