#include <forward_list>
#include <string>

void insertAfterForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            list.insert_after(it, insertion);
            return;
        }
        ++it;
    }
    list.push_back(insertion);
}
