#include <pthread.h>
#include <stdlib.h>

typedef void* (*task_func)(void*);

struct ThreadPool {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int max_threads;
    int running_threads;
    pthread_t* threads;
    task_func task;
};

ThreadPool* thread_pool_create(int max_threads, task_func task) {
    ThreadPool* pool = (ThreadPool*)malloc(sizeof(ThreadPool));
    pool->max_threads = max_threads;
    pool->running_threads = 0;
    pool->threads = (pthread_t*)calloc(max_threads, sizeof(pthread_t));
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->task = task;
    return pool;
}

void thread_pool_submit(ThreadPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->running_threads >= pool->max_threads) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    int new_thread_id = 0;
    while (new_thread_id < pool->max_threads && pool->threads[new_thread_id] != 0) {
        ++new_thread_id;
    }
    if (new_thread_id >= pool->max_threads) {
        pthread_mutex_unlock(&pool->mutex);
        return;
    }
    pool->threads[new_thread_id] = pthread_self();
    pool->running_threads++;
    pthread_mutex_unlock(&pool->mutex);
}

void thread_pool_join(ThreadPool* pool) {
    for (int i = 0; i < pool->max_threads; ++i) {
        if (pool->threads[i] != 0) {
            pthread_join(pool->threads[i], NULL);
        }
    }
    free(pool->threads);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
}

void* thread_pool_task(void* arg) {
    // Call the Python function when the thread pool is done processing tasks
    PyObject_CallFunctionObjArgs(None, None);  // Replace with actual call to Python function
}
