using System;
using System.Collections.Generic;
using Newtonsoft.Json;

public class RandomValueGenerator
{
    private List<Range> Ranges { get; set; } = new List<Range>();

    public void AddRange(int min, int max, bool isExclusive)
    {
        Ranges.Add(new Range(min, max, isExclusive));
    }

    public float GenerateFloat(int index)
    {
        return (float)Generator(index);
    }

    public int GenerateInt(int index)
    {
        return Generator(index).ToInt32();
    }

    private RandomGenerator Generator(int index)
    {
        var rand = new Random();
        var range = Ranges[index];
        if (!range.IsExclusive)
        {
            return rand.Next(range.Min, range.Max + 1);
        }
        else
        {
            return rand.Next(range.Min, range.Max);
        }
    }

    public string Serialize()
    {
        return JsonConvert.SerializeObject(Ranges);
    }

    public void MergeRange(int oldIndex, int newIndex, bool isExclusive)
    {
        var oldRange = Ranges[oldIndex];
        if (isExclusive)
        {
            if (newIndex < oldRange.Min) Ranges[newIndex] = new Range(oldRange.Min, oldRange.Min, true);
            else if (newIndex > oldRange.Max) Ranges[newIndex] = new Range(oldRange.Max + 1, oldRange.Max + 1, true);
            else
            {
                Ranges.RemoveAt(oldIndex);
                return;
            }
        }
        else
        {
            if (newIndex < oldRange.Min)
            {
                Ranges[newIndex] = new Range(newIndex, oldRange.Min - 1, false);
            }
            else if (newIndex > oldRange.Max)
            {
                Ranges[newIndex] = new Range(oldRange.Max + 1, newIndex, false);
            }
            else
            {
                Ranges.RemoveAt(oldIndex);
                return;
            }
        }
    }

    public override string ToString()
    {
        var output = "";
        foreach (var range in Ranges)
        {
            output += $"[{range.Min} {(range.IsExclusive ? "exclusive" : "inclusive")} {range.Max}], ";
        }
        return output.TrimEnd(', ');
    }

    public class Range
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public bool IsExclusive { get; set; }

        public Range(int min, int max, bool isExclusive)
        {
            Min = min;
            Max = max;
            this.IsExclusive = isExclusive;
        }
    }
}
