using System;
using System.Xml;
using System.Collections.Generic;

public List<XmlElement> GetElementsByXpath(string xml, string xpath)
{
    XmlDocument doc = new XmlDocument();
    try
    {
        doc.LoadXml(xml);
        XmlElement root = doc.DocumentElement;
        XmlNodeList nodes = root.SelectNodes(xpath);

        if (nodes == null || nodes.Count == 0) return new List<XmlElement>();

        List<XmlElement> result = new List<XmlElement>();
        foreach (XmlNode node in nodes)
            result.Add(node as XmlElement);

        return result;
    }
    catch (XmlException ex)
    {
        // Handle exceptions
        Console.WriteLine("Error parsing XML: " + ex.Message);
        return new List<XmlElement>();
    }
}
