using System;
using System.Collections.Generic;
using Newtonsoft.Json;

public class DynamicRangeManager
{
    private readonly Dictionary<string, Range> _ranges = new();
    private readonly object _lock = new();

    public void AddRange(string name, int min, int max, bool inclusive)
    {
        _ranges.Add(name, new Range(min, max, inclusive));
    }

    public void GenerateRandomValue(string rangeName, out double value)
    {
        lock (_lock)
        {
            if (!_ranges.TryGetValue(rangeName, out var rng))
                throw new ArgumentException("Invalid range name");
            value = rng.GenerateRandomValue();
        }
    }

    public string SerializeRanges()
    {
        return JsonConvert.SerializeObject(_ranges.Values, Formatting.Indented);
    }

    public void MergeRanges(string oldRangeName, string newRangeName, int newMin, int newMax, bool newInclusive)
    {
        lock (_lock)
        {
            if (!_ranges.TryGetValue(oldRangeName, out var oldRange))
                throw new ArgumentException("Invalid old range name");
            if (oldRange.Inclusive && !newInclusive) oldRange.Max = newMin - 1;
            else if (!oldRange.Inclusive && newInclusive) oldRange.Min = newMax + 1;

            _ranges[oldRangeName] = null; // remove the original range
            _ranges[newRangeName] = new Range(newMin, newMax, newInclusive);
        }
    }

    public void ExpandOrContractRange(string rangeName, int amount)
    {
        lock (_lock)
        {
            if (!_ranges.TryGetValue(rangeName, out var rng))
                throw new ArgumentException("Invalid range name");
            if (rng.Inclusive && amount > 0) rng.Max += amount;
            else if (!rng.Inclusive && amount < 0) rng.Min -= -amount;
            else if (rng.Inclusive && amount < 0) rng.Max += amount;
            else if (!rng.Inclusive && amount > 0) rng.Min -= amount;
        }
    }

    public override string ToString()
    {
        return JsonConvert.SerializeObject(_ranges, Formatting.Indented);
    }
}

public class Range
{
    public int Min { get; set; }
    public int Max { get; set; }
    public bool Inclusive { get; set; }

    public Range(int min, int max, bool inclusive)
    {
        Min = min;
        Max = max;
        Inclusive = inclusive;
    }

    public double GenerateRandomValue()
    {
        return new Random().NextDouble() * (Max - Min) + Min;
    }
}
