int mergeAndFilterLogs(const char* logDir, const char* filterCriteria, const char* outputFileName, int concurrencyLevel) {
    // Initialize logging variables
    FILE* logFile = fopen("log.txt", "a");
    if (!logFile) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize thread variables
    pthread_t threads[concurrencyLevel];
    int threadCount = concurrencyLevel;

    // Loop through all files in the directory
    DIR* dir = opendir(logDir);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        // Create a new thread for each file
        pthread_create(&threads[threadCount], NULL, processFile, entry->d_name);
        threadCount--;

        if (threadCount == 0) {
            for (int i = 0; i < concurrencyLevel; i++) {
                pthread_join(threads[i], NULL);
            }
            threadCount = concurrencyLevel;
        }
    }

    closedir(dir);

    // Close the log file
    fclose(logFile);

    return 0;
}

void* processFile(void* filename) {
    char filePath[1024];
    sprintf(filePath, "%s/%s", logDir, (char*)filename);
    FILE* file = fopen(filePath, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Process the file
    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break;

        // Filter the line based on the criteria
        if (filterLine(line, filterCriteria)) {
            // Append the filtered line to the output file
            FILE* outputFile = fopen(outputFileName, "a");
            if (outputFile) fprintf(outputFile, "%s", line);
            fclose(outputFile);
