using System;
using System.IO;
using System.Linq;

public int extractAndNormalizeData(string inputFile, string[] columnHeaders, string outputFile) {
    try {
        // Read the CSV file
        string[] lines = File.ReadAllLines(inputFile);

        // Create a dictionary to store the extracted columns
        Dictionary<string, List<string>> extractedColumns = new Dictionary<string, List<string>>();

        foreach (string header in columnHeaders) {
            extractedColumns.Add(header, new List<string>());
        }

        // Loop through each line in the CSV file
        foreach (string line in lines) {
            string[] fields = line.Split(',');

            // Extract and normalize the columns
            foreach (KeyValuePair<string, List<string>> pair in extractedColumns) {
                string value = fields[Array.IndexOf(columnHeaders, pair.Key)];
                if (!string.IsNullOrEmpty(value)) {
                    // Normalize the value based on its header
                    switch (pair.Key) {
                        case "Date":
                            DateTime date;
                            if (DateTime.TryParse(value, out date)) {
                                value = date.ToString("yyyy-MM-dd");
                            }
                            break;
                        // TO DO: Add more normalization logic for other column headers
                    }

                    pair.Value.Add(value);
                }
            }
        }

        // Write the extracted columns to the output file
        using (StreamWriter writer = File.CreateText(outputFile)) {
            foreach (KeyValuePair<string, List<string>> pair in extractedColumns) {
                writer.WriteLine(pair.Key + ":");
                foreach (string value in pair.Value) {
                    writer.WriteLine("  " + value);
                }
            }
        }

        return 0;
    } catch (Exception ex) {
        Console.WriteLine($"Error: {ex.Message}");
        return 1;
    }
}
