import csv
import os
from collections import Counter
from statistics import mean
from itertools import islice

class EmailProcessor:
    def __init__(self, directory_path):
        self.directory_path = directory_path
        self.email_counts = {}
        self.domain_counts = Counter()

    def process_csv_file(self, file_path):
        try:
            with open(file_path, 'r') as file:
                chunk_size = 1000
                chunk = list(islice(csv.reader(file), chunk_size))
                while chunk:
                    for row in chunk:
                        email = row[1]  # Assuming the second column is the email address
                        if '@' in email and '.' in email.split('@')[1]:
                            domain = email.split('@')[1].split('.')[0]
                            self.email_counts[email] = 1
                            self.domain_counts[domain] += 1
                    chunk = list(islice(csv.reader(file), chunk_size))
        except FileNotFoundError:
            print(f"Error: File not found at {file_path}")
        except IsADirectoryError:
            print(f"Error: Provided path is a directory, not a file")
        except PermissionError:
            print(f"Error: Insufficient permissions to access the file")

    def calculate_metrics(self):
        try:
            total_count = len(self.email_counts)
            average_length = mean(len(email) for email in self.email_counts)
            most_common_domain = self.domain_counts.most_common(1)[0][0]
            return {
                'unique_emails': total_count,
                'average_email_length': average_length,
                'most_common_domain': most_common_domain
            }
        except ZeroDivisionError:
            print("Error: No emails found in the file")
        except Exception as e:
            print(f"Error: {e}")

    def process_all_csv_files(self):
        try:
            for file_name in os.listdir(self.directory_path):
                file_path = os.path.join(self.directory_path, file_name)
                if file_path.endswith('.csv'):
                    self.process_csv_file(file_path)
        except Exception as e:
            print(f"Error: {e}")

    def start_processing(self):
        try:
            total_files = len(os.listdir(self.directory_path))
            for i, file_name in enumerate(os.listdir(self.directory_path)):
                print(f"Processing file {i+1}/{total_files}...")
                self.process_csv_file(os.path.join(self.directory_path, file_name))
            metrics = self.calculate_metrics()
            return metrics
        except KeyboardInterrupt:
            print("Process interrupted by user. Calculating metrics...")
            return self.calculate_metrics()

if __name__ == "__main__":
    processor = EmailProcessor('/path/to/your/csv/files')
    metrics = processor.start_processing()
    print(f"Metrics: {metrics}")
