#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <arpa/inet.h>
#include <resolv.h>

typedef unsigned char u_char;

void processAndTransformString(const char* str, size_t sizeLimit, int modLimit, const char** ipAddr) {
    struct hostent* host;
    void* addr;
    int ret = gethostbyname(str, &host, &addr);

    if (ret != 0 && *ipAddr != NULL) {
        free(*ipAddr);
    }

    if (ret == 0 || *ipAddr != NULL) {
        size_t strLen = strlen(str);

        if (strLen > sizeLimit || modLimit > 1) {
            if (*ipAddr != NULL) {
                free(*ipAddr);
            }

            if (strLen > sizeLimit) {
                return NULL;
            } else {
                return str;
            }
        }

        *ipAddr = malloc(INET6_ADDRSTRLEN);
        inet_ntop(AF_INET, addr, *ipAddr, INET6_ADDRSTRLEN);

        char* newStr = malloc((strLen + 2) * sizeof(char));
        strcpy(newStr, str);
        strcat(newStr, "/");

        return newStr;
    } else {
        log_error("Failed to resolve host");
        if (*ipAddr != NULL) {
            free(*ipAddr);
        }

        return str;
    }
}
