// Function to process log filenames and generate a new list of filenames
char** processLogFilenames(int argc, char* argv[], int* length) {
    // Initialize the result array with enough space for all filenames
    int numFiles = argc;
    char** result = (char**)malloc((numFiles + 1) * sizeof(char*));

    // Loop through each command-line argument (filename)
    for(int i = 0; i < numFiles; i++) {
        // Extract the base name from the filename
        char* baseName = basename(argv[i]);

        // Check if the base name has an extension
        int hasExtension = strcasecmp(strrchr(baseName, '.'), ".log") == 0 || strcasecmp(strrchr(baseName, '.'), ".txt") == 0;

        // If the filename has no extension, determine its directory path and file type using system calls
        if (!hasExtension) {
            struct stat sb;
            char* dirPath = realpath(argv[i], NULL);
            if (dirPath != NULL && stat(dirPath, &sb) == 0) {
                free(dirPath);
                // Determine the file type based on the directory path and file name
                char* fileType = ".log";
                if (strcmp(sb.st_name, "logs") == 0) {
                    fileType = ".txt";
                }

                // Append the file type as an extension to the base name
                char* fileName = malloc(strlen(baseName) + strlen(fileType) + 2);
                strcpy(fileName, baseName);
                strcat(fileName, fileType);
                free(baseName);
                baseName = fileName;
            } else {
                // Handle error: unable to determine directory path or file type
                printf("Error: Unable to determine directory path or file type for filename '%s'\n", argv[i]);
                continue;
            }
        }

        // Replace all occurrences of non-alphanumeric characters in the base name with underscores
        char* baseNameCopy = malloc(strlen(baseName) + 1);
        strcpy(baseNameCopy, baseName);
        baseName = str_replace(baseNameCopy, " ", "_");
        free(baseNameCopy);

        // Calculate the length of the current directory path and truncate it to 100 characters
        int dirPathLength;
        char* dirPathCopy = malloc(strlen(dirPath) + 1);
        strcpy(dirPathCopy, dirPath);
        for (dirPathLength = 0; dirPathCopy[dirPathLength] != '\0' && dirPathLength < 100; dirPathLength++) {
            if (!isalnum(dirPathCopy[dirPathLength])) {
                break;
            }
        }
        char* truncatedDirPath = malloc(dirPathLength + 1);
        strncpy(truncatedDirPath, dirPathCopy, dirPathLength);
        truncatedDirPath[dirPathLength] = '\0';
        free(dirPathCopy);

        // Generate a unique timestamp in the format YYYYMMDD_HHMMSS
        time_t now = time(NULL);
        char* timestamp = malloc(20);
        strftime(timestamp, 20, "%Y%m%d_%H%M%S", localtime(&now));

        // Construct the new filename by combining the base name, truncated directory path, and timestamp
        int maxLength = strlen(baseName) + strlen(truncatedDirPath) + strlen(timestamp) + 2;
        char* newFileName = malloc(maxLength);
        strcpy(newFileName, baseName);
        strcat(newFileName, "_");
        strcat(newFileName, truncatedDirPath);
        free(truncatedDirPath);
        strcat(newFileName, "_");
        strcat(newFileName, timestamp);
        free(timestamp);

        // Ensure that the new filename does not exceed 255 characters in total length
        if (strlen(newFileName) + strlen(fileType) > 255) {
            printf("Error: New filename '%s' exceeds maximum length of 255 characters\n", newFileName);
            continue;
        }

        // Append the file type as an extension to the new filename
        strcat(newFileName, fileType);

        // Sort the resulting filenames alphabetically and store them in the result array
        result[i] = malloc(strlen(newFileName) + 1);
        strcpy(result[i], newFileName);
        free(newFileName);
    }

    *length = numFiles;
    return result;
}

// Function to replace all occurrences of a substring with another string
char* str_replace(char* s, const char* oldStr, const char* newStr) {
    int i = 0;
    while (*s != '\0') {
        if (strncmp(s, oldStr, strlen(oldStr)) == 0) {
            int j = 0;
            while (newStr[j] != '\0') {
                s++;
                *(s - 1) = newStr[j];
                j++;
            }
            i += strlen(oldStr);
        } else {
            s++;
        }
    }
    return s;
}

// Function to get the base name from a filename
char* basename(char* path) {
    char* p = rindex(path, '/');
    if (p == NULL) {
        p = rindex(path, '\\');
    }
    if (p != NULL) {
        return p + 1;
    } else {
        return path;
    }
}

int main(int argc, char* argv[]) {
    int numFiles;
    char** result = processLogFilenames(argc, argv, &numFiles);

    // Print the processed filenames
    for (int i = 0; i < numFiles; i++) {
        printf("%s\n", result[i]);
    }

    // Free the memory allocated by the function
    for (int i = 0; i < numFiles; i++) {
        free(result[i]);
    }
    free(result);

    return 0;
}
