#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <time.h>

typedef struct {
    char* filename;
    int processed;
} File;

void process_directory(const char* dir_path, FILE** files, size_t* file_count) {
    DIR* dir = opendir(dir_path);
    if (!dir) return; // handle error

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char path[1024];
        sprintf(path, "%s/%s", dir_path, ent->d_name);

        File* file = malloc(sizeof(File));
        file->filename = strdup(path);
        file->processed = 0;
        *file_count += 1;
        **files = file;
        (*files)++;
    }

    closedir(dir);
}

void process_file(char** files, size_t count) {
    for (size_t i = 0; i < count; i++) {
        File* file = files[i];
        char* base_name = strdup(file->filename);
        char* name_parts[] = {strtok(base_name, "."), NULL};
        char* ext = name_parts[1] ? name_parts[1] : "";

        if (strlen(ext) == 0) {
            size_t path_len = 100;
            char path[path_len];
            realpath(file->filename, path);
            strcpy(path + path_len - 4, ".log"); // append .log extension
            free(base_name);
            base_name = strdup(path);
        } else {
            free(base_name);
            base_name = strdup(file->filename);
        }

        char* new_name = malloc(strlen(base_name) + 1); // allocate space for the modified name
        char* p = new_name;
        for (char* c = base_name; *c != '\0'; c++) {
            if (!isalnum(*c)) {
                *(p++) = '_';
                continue;
            }
            *(p++) = *c;
        }
        *p = '\0';

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, 20, "%Y%m%d_%H%M%S", localtime(&now));
        size_t len = strlen(new_name) + 1 + sizeof(timestamp) - 1; // allocate space for the new filename
        char* new_filename = malloc(len); // allocate space for the new filename
        sprintf(new_filename, "%s_%s.%s", new_name, timestamp, ext);

        file->processed = 1;
        free(file->filename);
        file->filename = new_filename;

        free(base_name);
        free(new_name);
    }
}

void sort_files(char** files, size_t count) {
    for (size_t i = 0; i < count; i++) {
        for (size_t j = i + 1; j < count; j++) {
            if (strcmp(files[i]->filename, files[j]->filename) > 0) {
                File* file = files[i];
                files[i] = files[j];
                files[j] = file;
            }
        }
    }
}

int main(int argc, char** argv) {
    int count = 0;
    FILE** files = NULL;

    for (int i = 1; i < argc; i++) {
        File* file = malloc(sizeof(File));
        file->filename = strdup(argv[i]);
        file->processed = 0;
        count++;
        if (!files) {
            files = &file;
        } else {
            *files = file;
            files = &file;
        }
    }

    process_directory(".", &files, &count);

    process_file(files, count);

    sort_files(files, count);

    for (size_t i = 0; i < count; i++) {
        printf("%s\n", files[i]->filename);
        free((char*)files[i]->filename);
        free(files[i]);
    }

    return 0;
}
