#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUNDLES 1000
#define MAX_ITEMS_PER_BUNDLE 10000
#define MAX_MEMORY_IN_USE (MAX_BUNDLES * MAX_ITEMS_PER_BUNDLE * sizeof(struct BundleItem))

typedef struct {
    int key;
    char* value;
} BundleItem;

typedef struct {
    pthread_mutex_t mutex;
    int count;
    BundleItem** items;
} Bundle;

Bundle bundles[MAX_BUNDLES];
int bundle_count = 0;

void load_bundle(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        // Handle error
        return;
    }

    Bundle* current_bundle = &bundles[bundle_count++];
    pthread_mutex_init(&current_bundle->mutex, NULL);
    current_bundle->count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* key_end = strstr(line, ",");
        if (!key_end) {
            // Handle error
            fclose(file);
            return;
        }

        int key = atoi(strtok(line, ","));
        char* value = strtok(NULL, "\n");
        if (value == NULL || strlen(value) >= sizeof(current_bundle->items[0]->value)) {
            // Handle error
            fclose(file);
            return;
        }

        current_bundle->items[current_bundle->count++] = malloc(sizeof(BundleItem));
        (*current_bundle->items[current_bundle->count - 1]).key = key;
        strcpy((*current_bundle->items[current_bundle->count - 1]).value, value);
    }

    pthread_mutex_unlock(&current_bundle->mutex);
    fclose(file);
}

int get_bundle_count() {
    return bundle_count;
}

int generateNfadbCRCIndications(int n) {
    struct NFAPI_CRC_INDICATION_PDU_T* indications = malloc(n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        indications[i].rx_ue_info_tag = rand();
        indications[i].rnti = rand();
        indications[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    // Send data to database server
    DataTableReader* reader = send_data_to_database_server(indications, n);
    free(indications);

