// Load a single resource bundle from a file and return its size
int load_bundle(char *path) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        // File does not exist or is corrupted
        return -1; // Return error code for non-existent file
    }

    int num_items = 0;
    char **items = NULL;

    // Read the file and store its contents in a dynamic array
    while (fscanf(file, "%s", "") != EOF) {
        num_items++;
        if (num_items > max_bundle_size) {
            max_bundle_size = num_items;
        }
    }

    fclose(file);

    // Allocate memory for the bundle and its items
    Bundle *bundle = malloc(sizeof(Bundle));
    bundle->num_items = num_items;
    bundle->items = malloc(num_items * sizeof(char *));
    for (int i = 0; i < num_items; i++) {
        bundle->items[i] = malloc(1024);
    }

    // Populate the bundle with its items
    file = fopen(path, "r");
    int i = 0;
    while (fscanf(file, "%s", "") != EOF) {
        strcpy(bundle->items[i], "");
        i++;
    }
    fclose(file);

    // Add the new bundle to the collection and update the global state
    if (num_bundles >= MAX_BUNDLES) {
        // Discard the least recently used bundle to make space for the new one
        free(bundles[num_bundles - 1].items);
        free(bundles[num_bundles - 1]);
        num_bundles--;
    }

    bundles = realloc(bundles, (num_bundles + 1) * sizeof(Bundle));
    bundles[num_bundles] = *bundle;
    num_bundles++;

    return bundle->num_items;
}

