#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for resource bundle items
typedef struct {
    char key[256];
    char value[256];
} bundle_item_t;

// Define the structure for a single resource bundle
typedef struct {
    int num_items;
    bundle_item_t* items;
} bundle_t;

// Define the global collection of bundles
bundle_t* bundles = NULL;
int num_bundles = 0;

// Define the LRU cache eviction policy
void lru_cache_eviction(bundle_t* evict_me) {
    // Remove the least recently used bundle from the collection
    int i;
    for (i = 0; i < num_bundles; i++) {
        if (bundles[i] == evict_me) {
            memmove(&bundles[i], &bundles[i+1], (num_bundles - i - 1) * sizeof(bundle_t));
            num_bundles--;
            break;
        }
    }
}

// Load a single resource bundle from a file
int load_bundle(const char* path, int max_items) {
    FILE* file = fopen(path, "r");
    if (!file) return -1; // File not found

    char line[256];
    int num_items = 0;
    bundle_item_t* items = NULL;

    while (fgets(line, sizeof(line), file)) {
        // Parse the key-value pair
        char* key_end = strchr(line, ',');
        if (!key_end) break; // Corrupted file

        *key_end = '\0';
        bundle_item_t item;
        strcpy(item.key, line);
        fgets(item.value, sizeof(item.value), file);
        item.value[strcspn(item.value, "\n")] = '\0'; // Remove newline

        if (num_items >= max_items) {
            lru_cache_eviction(&bundles[num_bundles - 1]);
            num_items -= 1;
        }

        items = realloc(items, (num_items + 1) * sizeof(bundle_item_t));
        items[num_items] = item;

        num_items++;
    }

    fclose(file);

    if (!items) return -2; // Corrupted file

    bundle_t new_bundle;
    new_bundle.num_items = num_items;
    new_bundle.items = items;
    bundles = realloc(bundles, (num_bundles + 1) * sizeof(bundle_t));
    bundles[num_bundles++] = new_bundle;

    return num_items;
}

