network_interface* create_network_interface(char* ip, int mtu_size) {
    network_interface* interface = (network_interface*)malloc(sizeof(network_interface));
    if (!interface) {
        return NULL;
    }
    strcpy(interface->ip, ip);
    interface->mtu_size = mtu_size;
    interface->mtu_buffer = malloc(mtu_size);
    if (!interface->mtu_buffer) {
        free(interface);
        return NULL;
    }
    return interface;
}

void destroy_network_interface(network_interface* interface) {
    if (!interface) {
        return;
    }
    free(interface->mtu_buffer);
    free(interface);
}

network_interface** manage_network_interfaces(int* num_interfaces, int initial_size) {
    network_interface** interfaces = (network_interface**)malloc(initial_size * sizeof(network_interface*));
    if (!interfaces) {
        return NULL;
    }
    for (int i = 0; i < initial_size; i++) {
        interfaces[i] = create_network_interface("default_ip", 1500);
    }
    *num_interfaces = initial_size;
    return interfaces;
}

void update_network_interface(network_interface* interface, char* new_ip) {
    if (!interface || !new_ip) {
        return;
    }
    strcpy(interface->ip, new_ip);
}

void release_network_interfaces(network_interface** interfaces, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        destroy_network_interface(interfaces[i]);
    }
    free(interfaces);
}
