import json
import yaml
from functools import wraps
from urllib.request import Request, urlopen, URLError
from urllib.error import HTTPError
from collections import defaultdict
from tempfile import TemporaryFile


def retry(max_attempts=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except (URLError, HTTPError) as e:
                    if attempt >= max_attempts - 1:
                        raise
                    print(f"Retrying due to {e.__class__.__name__}: {e.reason}.")
                    attempt += 1
        return wrapper

    return decorator


def load_json_data(url):
    request = Request(url)
    try:
        response = urlopen(request)
        data = json.loads(response.read().decode())
    except (URLError, HTTPError) as e:
        raise Exception(f"Failed to retrieve JSON data: {e.__class__.__name__}: {e.reason}.")
    return data


def generate_pokemon_weaknesses(pokemon_type):
    pokemon_types_url = "https://api.pokemon-types.com/types"
    weaknesses_data = load_json_data(pokemon_types_url)

    weaknesses = defaultdict(list)
    for type, weakness in weaknesses_data.items():
        if type == pokemon_type:
            weaknesses['type'] = type
            weaknesses['weaknesses'] = [w for w in weakness]

    return yaml.dump(weaknesses, default_flow_style=False)


def update_config(config_file, parameters):
    temp_file = TemporaryFile()
    with open(config_file, 'r') as file:
        config_data = file.read()

    placeholders = re.findall(r'\$\{(\w+)\}', config_data)
    for placeholder in placeholders:
        if placeholder not in parameters:
            raise ValueError(f"Missing configuration parameter: {placeholder}")
        config_data = config_data.replace(f"${{{placeholder}}}", str(parameters[placeholder]))

    temp_file.write(config_data.encode())
    temp_file.seek(0)

    with open('updated_config.yaml', 'w') as file:
        yaml.dump({'config': temp_file.read().decode()}, file, default_flow_style=False)


def main():
    config_file = 'config.yaml'
    parameters = {'environment': 'production', 'database_url': 'localhost:5432'}
    pokemon_type = 'fire'

    try:
        update_config(config_file, parameters)
        with open('updated_config.yaml') as file:
            updated_config = yaml.safe_load(file)

        weaknesses_data = generate_pokemon_weaknesses(pokemon_type)
        updated_config['config']['pokemon'] = {'type': pokemon_type, 'weaknesses': yaml.safe_load(weaknesses_data)}

    except Exception as e:
        print(f"Error occurred: {e.__class__.__name__}: {e}")

    finally:
        temp_file.close()


if __name__ == "__main__":
    main()
