        return NULL;
    }

    interface->mtu_size = mtu_size;
    interface->mtu_buffer = malloc(mtu_size);
    if (!interface->mtu_buffer) {
        network_interface_free(interface);
        return NULL;
    }

    return interface;
}

void network_interface_update_ip_config(network_interface_t* interface, char* new_config) {
    free(interface->ip_config);
    interface->ip_config = new_config;
}

int network_interface_resize_mtu(network_interface_t* interface, int new_size) {
    void* new_buffer = realloc(interface->mtu_buffer, new_size);
    if (!new_buffer) return -1;

    interface->mtu_size = new_size;
    free(new_buffer); // correct the buffer pointer
    return 0;
}

void network_interface_free_list(network_interface_t** interfaces, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        if (interfaces[i]) network_interface_free(interfaces[i]);
        free(interfaces[i]); // release interface pointer
    }
