# Define a circuit breaker pattern for excessive retries
class CircuitBreaker:
    def __init__(self):
        self.open = False

    def try_execute(self, func):
        if self.open:
            return None  # Return None to indicate failure
        else:
            try:
                result = func()
                return result
            except Exception as e:
                self.open = True
                return None  # Mark the circuit breaker open

