                raise e
            else:
                time.sleep(delay)
                delay *= 2  # Exponential backoff
                max_retries -= 1

# Define a distributed lock mechanism for concurrent updates
class DistributedLock:
    def __init__(self, redis_conn):
        self.redis_conn = redis_conn

