void destroy_network_interfaces_list(network_interfaces_list* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->interfaces[i].mtu_buffer);
    }
    free(list->interfaces);
    free(list);
}

network_interface* get_network_interface(network_interfaces_list* list, int index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size) {
        printf("Index out of bounds\n");
        return NULL;
    }
    network_interface* interface = &list->interfaces[index];
    pthread_mutex_unlock(&list->mutex);
    return interface;
}

void update_ip_configuration(network_interfaces_list* list, int index, int new_ip_address, int new_subnet_mask) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size) {
        printf("Index out of bounds\n");
    } else {
        network_interface* interface = &list->interfaces[index];
        interface->ip_address = new_ip_address;
        interface->subnet_mask = new_subnet_mask;
    }
    pthread_mutex_unlock(&list->mutex);
}

void resize_mtu_buffer(network_interfaces_list* list, int index, int new_size) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size) {
        printf("Index out of bounds\n");
    } else {
        network_interface* interface = &list->interfaces[index];
        int* old_mtu_buffer = interface->mtu_buffer;
        int old_size = interface->mtu_size;

        // Deallocate unnecessary portions of the buffer
        if (new_size < old_size) {
            free(old_mtu_buffer + new_size);
        }

        // Reallocate the buffer with the new size
        interface->mtu_buffer = (int*)malloc(new_size * sizeof(int));
        interface->mtu_size = new_size;
    }
    pthread_mutex_unlock(&list->mutex);
}

void read_integer_array(network_interfaces_list* list) {
