void print_usage() {
    printf("Usage: %s [-c <count>] [-s] [-o <output_file>] [--manpage]\n", argv[0]);
    printf("\t-c <count>: Print only the first <count> lines of the input file.\n");
    printf("\t-s: Suppress the printing of line numbers while reading the file.\n");
    printf("\t-o <output_file>: Redirect the output to a specified file instead of standard output.\n");
    printf("\t--manpage: Display detailed usage information and exit.\n");
}

int parse_options(int argc, char **argv) {
    int i = 1;
    option_type option;

    while (i < argc && strlen(argv[i]) == 2 && argv[i][0] == '-') {
        if (!strcmp(argv[i], "--manpage")) {
            print_usage();
            exit(0);
        } else if (!strcmp(argv[i], "-c")) {
            i++;
            count = atoi(argv[i]);
            if (count <= 0) {
                fprintf(stderr, "Invalid count: %s\n", argv[i]);
                return -1;
            }
        } else if (!strcmp(argv[i], "-s")) {
            suppress_line_numbers = 1;
        } else if (!strcmp(argv[i], "-o")) {
            i++;
            output_file = argv[i];
            if (strlen(output_file) > MAX_OUTPUT_FILE_LENGTH) {
                fprintf(stderr, "Output file name too long: %s\n", output_file);
                return -1;
            }
        } else {
            fprintf(stderr, "Invalid option: %s\n", argv[i]);
            return -1;
        }
    }

    return 0;
}

