import os
import envparse
from typing import Dict, Any

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from aioredis import Redis

from functools import wraps
from asyncio import create_task, ensure_future
from aiohttp import ClientSession, TCPConnector

def get_redis_connection() -> Redis:
    redis_url = os.getenv("REDIS_URL")
    return Redis.from_url(redis_url)

async def fetch_weather_data(session: ClientSession) -> Dict[str, Any]:
    try:
        async with session.get("https://weather-api.com/current") as response:
            if response.status == 200:
                return await response.json()
            else:
                # Fallback to default weather data
                return {"temperature": 25.0, "humidity": 60.0}
    except asyncio.CancelledError:
        # Handle cancelled requests
        pass
    except Exception as e:
        print(f"Error fetching weather data: {e}")
        return None

async def get_pokemon_weaknesses(pokemon_type: str) -> Dict[str, Any]:
    weather_data = await fetch_weather_data()
    if not weather_data:
        return {"weakness": ["unknown"]}

    # Calculate weaknesses based on weather data
    weaknesses = {"grass": "fire", "water": "electric"}[pokemon_type]
    return {f"weakness_{i}": weakness for i, weakness in enumerate(weaknesses.split(","))}

async def update_config_file(config_path: str, params: Dict[str, Any]) -> None:
    if not os.access(config_path, os.W_OK):
        # Retry with exponential backoff
        for attempt in range(1, 5):
            try:
                await ensure_future(os.chmod(config_path, stat.S_IRWXU))
                break
            except Exception as e:
                print(f"Error updating config file: {e}")
                await asyncio.sleep(2**attempt)
        else:
            print("Failed to update config file")

    with open(config_path, "r+b") as f:
        content = f.read()
        for key, value in params.items():
            if f"{key}=" in content:
                content = content.replace(f"{key}=", f"{key}={value}")

        f.seek(0)
        f.write(content)

    with open("/etc/config/settings.conf", "a+b") as f:
        # Append new line with encrypted summary
        weaknesses = await get_pokemon_weaknesses("grass")
        cipher = Cipher(algorithms.AES(os.getenv("AES_KEY")), modes.ECB(), backend=default_backend())
        encryptor = cipher.encryptor()
        encrypted_summary = encryptor.update(serialize.dumps(weaknesses).encode()) + encryptor.finalize()
        f.write(b"Summary: " + encrypted_summary)

def main() -> None:
    redis_connection = get_redis_connection()

    @wraps(update_config_file)
    async def retryable_update_config_file(*args, **kwargs):
        for attempt in range(1, 5):
            try:
                await update_config_file(*args, **kwargs)
                break
            except Exception as e:
                print(f"Error updating config file: {e}")
                await asyncio.sleep(2**attempt)
        else:
            print("Failed to update config file")

    create_task(retryable_update_config_file("/etc/config/settings.conf", {"key": "value"}))

if __name__ == "__main__":
    main()
