        cout << "Error: Missing required location or date range." << endl;
        return 1;
    }

    auto start_time = high_resolution_clock::now();

    try {
        // Fetch weather data and display forecasts
        vector<WeatherForecast> forecasts = api.getForecasts(location, date_range, time_interval);

        // Process and output the data
        processAndOutput(forecasts, format);
    } catch (const exception& e) {
        logger.error(e.what());
        return 1;
    }

    auto end_time = high_resolution_clock::now();
    duration<double> processing_time = end_time - start_time;

    cout << "Processing time: " << fixed << setprecision(3) << processing_time.count() << " seconds." << endl;

    return 0;
}

