        return OutputFormat::JSON;
    } else if (format_str == "CSV") {
        return OutputFormat::CSV;
    } else if (format_str == "plain") {
        return OutputFormat::PLAIN;
    }
    // Handle unknown format strings
    return OutputFormat::JSON; // default
