network_interface* init_network_interface(size_t mtu_size) {
    // Allocate memory for the network interface structure
    network_interface* ni = (network_interface*)malloc(sizeof(network_interface));

    // Set default IP configuration
    strcpy(ni->config.ip, "192.168.1.100");
    strcpy(ni->config.netmask, "255.255.255.0");
    strcpy(ni->config.gateway, "192.168.1.1");

