void process_event_stream(char *input_file, char *output_file, char *config_json, int log_level, int alert_threshold) {
    // Parse JSON config
    json_object *config = json_object_from_string(config_json);
    const char *event_type_filter = json_object_get_string(json_object.GetObjectItem(config, "eventType"));
    int severity_level = json_object_get_int(json_object.GetObjectItem(config, "severityLevel"));
    time_t start_timestamp = json_object_get_int(json_object.GetObjectItem(config, "startTimestamp"));
    time_t end_timestamp = json_object_get_int(json_object_GetItem(config, "endTimestamp"));

    // Initialize event aggregator
    json_object *event_aggregator = json_object_new_object();

    // Process input file line by line
    FILE *input_file_fp = fopen(input_file, "r");
    char line[1024];
    while (fscanf(input_file_fp, "%s", line) == 1) {
        // Parse event JSON
        json_object *event_json = json_object_from_string(line);
        const char *event_type = json_object_get_string(json_object.GetObjectItem(event_json, "type"));
        int severity = json_object_get_int(json_objectGetObjectItem(event_json, "severity"));
        time_t timestamp = json_object_get_int(json_objectGetObjectItem(event_json, "timestamp"));

        // Filter and aggregate events
        if (strcmp(event_type, event_type_filter) == 0 && severity >= severity_level && timestamp >= start_timestamp && timestamp <= end_timestamp) {
            // Update event aggregator
            json_object *event_summary = json_object_new_object();
            json_object_object_add(event_summary, "type", json_object_get_string(json_objectGetObjectItem(event_json, "type")));
            json_object_object_add(event_summary, "count", json_object_get_int(event_aggregator, "total_count"));
            json_object_object_add(event_summary, "average_severity", (json_object_get_double(event_aggregator, "total_severity") + severity) / 2);

            // Update aggregator stats
            int total_count = json_object_get_int(event_aggregator, "total_count");
            double total_severity = json_object_get_double(event_aggregator, "total_severity");
            total_count++;
            total_severity += (double)severity;
            json_object_object_add(event_aggregator, "total_count", total_count);
            json_object_object_add(event_aggregator, "total_severity", total_severity);

            // Output event summary
            printf("Event %s: Count=%d, Severity=%.2f\n", event_type, total_count, total_severity / (double)total_count);
        }
    }

    // Close input file
    fclose(input_file_fp);

    // Write output dashboard
    FILE *output_file_fp = fopen(output_file, "w");
    json_object *dashboard_json = json_object_new_object();
    json_object_object_add(dashboard_json, "summary", event_aggregator);
    fwrite(json_object_to_json_string(dashboard_json), 1, strlen(json_object_to_json_string(dashboard_json)), output_file_fp);
    fclose(output_file_fp);

    // Free memory
    json_object_free(event_aggregator);
    json_object_free(config);
}
