def fetch_and_validate_metrics(service_name):
    try:
        metrics = fetch_realtime_metrics(service_name)
        return json.loads(metrics)
    except Exception as e:
        logging.error(f"Failed to fetch metrics for {service_name}: {e}")
        raise

def update_config_file(config_file, params, services):
    with open(config_file, "r+") as file:
        content = file.read()
        for service in services:
            placeholder = f"[{service}]"
            value = str(params.get(service, ""))
            content = content.replace(placeholder, value)
        metrics_block = ""
        for service in services:
            try:
                health_status, cpu_usage, memory_usage = fetch_and_validate_metrics(service)
                metrics_block += json.dumps(generate_metrics(service, health_status, cpu_usage, memory_usage), indent=4) + "\n"
            except Exception as e:
                logging.error(f"Failed to generate metrics for {service}: {e}")
        content += f"[\n{metrics_block}\n]"
        file.seek(0)
        file.write(content)

