UserProfile* create_user_profile(char* username, char* email) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) {
        return NULL;
    }
    profile->username = strdup(username);
    profile->email = strdup(email);
    // Initialize password hash with default size
    profile->password_hash = malloc(16);  // Default password hash size: 16 bytes
    profile->password_size = 16;
    return profile;
}

// Function to update user profile details without reallocating memory
void update_user_profile(UserProfile* profile, char* new_username, char* new_email) {
    if (profile) {
        free(profile->username);
        free(profile->email);
        profile->username = strdup(new_username);
        profile->email = strdup(new_email);
    }
}

// Function to release allocated resources
void destroy_user_profile(UserProfile* profile) {
    if (profile) {
        free(profile->username);
        free(profile->email);
        free(profile->password_hash);
        free(profile);
    }
}

