import subprocess
import os
import sys
import logging

logging.basicConfig(level=logging.INFO)

def install_tool(tool_name):
    if tool_name == 'sed':
        command = f'apt-get install -y sed'
    elif tool_name == 'openssl':
        command = f'yum install -y openssl'
    else:
        raise ValueError(f"Unsupported tool: {tool_name}")

    try:
        subprocess.check_call(command.split())
    except subprocess.CalledProcessError as e:
        logging.error(f"Failed to install {tool_name}: {e}")
        sys.exit(1)

def replace_placeholders(config_file, environment):
    placeholder_values = {
        'dev': {'placeholder1': 'dev_value', 'placeholder2': 'dev_password'},
        'stg': {'placeholder1': 'stg_value', 'placeholder2': 'stg_password'},
        'prod': {'placeholder1': 'prod_value', 'placeholder2': 'prod_password'}
    }

    if environment not in placeholder_values:
        raise ValueError(f"Unsupported environment: {environment}")

    with open(config_file, 'r') as file:
        config_content = file.read()

    for placeholder, value in placeholder_values[environment].items():
        config_content = config_content.replace(f'${{{placeholder}}}', value)

    return config_content

def append_parameter(config_file):
    new_line = 'new_environment_specific_parameter'
    with open(config_file, 'a') as file:
        file.write('\n')
        file.write(new_line)

def generate_config_file(input_file, environment):
    install_tool('sed')

    replaced_config = replace_placeholders(input_file, environment)
    config_content = f'sed -i "s/${{placeholder1}}/${{dev_value }}/g; s/${{placeholder2}}/${{dev_password}}/g" {input_file}'
    subprocess.check_call(config_content.split())

    append_parameter(input_file)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        logging.error("Usage: python script.py <input_config_file> <environment>")
        sys.exit(1)

    input_file = sys.argv[1]
    environment = sys.argv[2]

    try:
        generate_config_file(input_file, environment)
    except Exception as e:
        logging.error(f"Error generating config file: {e}")
        sys.exit(1)
