// C# Class: RandomValueGenerator

using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private Dictionary<string, (int min, int max, bool inclusive)> _rangingDict = new Dictionary<string, (int min, int max, bool inclusive)>();

    public void AddRange(string name, int min, int max, bool inclusive)
    {
        _rangingDict.Add(name, (min, max, inclusive));
    }

    public double GenerateRandomFloat(string rangeName)
    {
        var rng = new Random();
        var minMax = _rangingDict[rangeName];
        return rng.NextDouble() * (minMax.max - minMax.min) + minMax.min;
    }

    public int GenerateRandomInt(string rangeName)
    {
        var rng = new Random();
        var minMax = _rangingDict[rangeName];
        return rng.Next(minMax.min, minMax.max);
    }

    public string Serialize()
    {
        var sb = new StringBuilder();
        foreach (var kvp in _rangingDict)
        {
            sb.AppendLine($"Range {kvp.Key}: [{kvp.Value.min}, {kvp.Value.max}]{(kvp.Value.inclusive ? "" : " exclusive")}");
        }
        return sb.ToString();
    }

    public void MergeRanges(string sourceName, string targetName)
    {
        var srcMinMax = _rangingDict[sourceName];
        var tgtMinMax = _rangingDict[targetName];

        if (srcMinMax.max >= tgtMinMax.min && !tgtMinMax.inclusive)
        {
            // The target range is exclusive and the source range is within it
            // Adjust the target range to include the source range
            tgtMinMax.min = Math.Min(tgtMinMax.min, srcMinMax.min);
            tgtMinMax.max = Math.Max(tgtMinMax.max, srcMinMax.max);
        }
        else if (srcMinMax.min <= tgtMinMax.max && !srcMinMax.inclusive)
        {
            // The source range is exclusive and the target range is within it
            // Adjust the target range to include the source range
            tgtMinMax.min = Math.Min(tgtMinMax.min, srcMinMax.min);
            tgtMinMax.max = Math.Max(tgtMinMax.max, srcMinMax.max);
        }
        else if (srcMinMax.inclusive && tgtMinMax.inclusive)
        {
            // Both ranges are inclusive
            // Merge the source range into the target range
            tgtMinMax.min = Math.Min(tgtMinMax.min, srcMinMax.min);
            tgtMinMax.max = Math.Max(tgtMinMax.max, srcMinMax.max);
        }
        else
        {
            // The ranges do not overlap; create a new range for the source
            _rangingDict.Add(sourceName, (srcMinMax.min, srcMinMax.max, srcMinMax.inclusive));
        }

        _rangingDict.Remove(sourceName);
    }

    public override string ToString()
    {
        return Serialize();
    }
}
