#include <stdio.h>
#include <pthread.h>

#define MAX_POOL_SIZE 1000
#define DEFAULT_SDU_LENGTH 128

typedef struct LTE_PDCP_PDU {
    int SN;
    uint32_t PDCP_SN;
    int STATUS_PDU;
    int SDU_LENGTH;
} LTE_PDCP_PDU;

LTE_PDCP_PDU* lte_pdcp_pdu_array_create(int num_elements) {
    if (num_elements <= 0) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_init(&lock, NULL);

    int* pool = (int*)malloc(sizeof(int) * MAX_POOL_SIZE);
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        pool[i] = i + 1;
    }
    int pool_index = 0;

    LTE_PDCP_PDU** array = (LTE_PDCP_PDU**)malloc(sizeof(LTE_PDCP_PDU*) * num_elements);
    for (int i = 0; i < num_elements; i++) {
        pthread_mutex_lock(&lock);
        if (pool_index >= MAX_POOL_SIZE) {
            free(array);
            free(pool);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        array[i] = (LTE_PDCP_PDU*)malloc(sizeof(LTE_PDCP_PDU));
        array[i]->SN = pool[pool_index]++;
        array[i]->PDCP_SN = 0; // Initialize PDCP_SN
        array[i]->STATUS_PDU = 0; // Initialize STATUS_PDU
        array[i]->SDU_LENGTH = DEFAULT_SDU_LENGTH;
        pthread_mutex_unlock(&lock);
    }

    free(pool);
    return array;
}

void lte_pdcp_pdu_array_free(LTE_PDCP_PDU** array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(array[i]);
    }
    free(array);
}
