```csharp
using System;
using System.Collections.Generic;
using Newtonsoft.Json;

public class AdvancedRandomValueGenerator
{
    private Dictionary<string, RandomValueRange> _ranges = new Dictionary<string, RandomValueRange>();
    private readonly object _lock = new object();
    private int _concurrentOperationsLimit = 10;
    private double _memoryUsageThreshold = 0.8;

    public void AddRange(string name, double min, double max, bool isExclusive)
    {
        _ranges.Add(name, new RandomValueRange(min, max, isExclusive));
    }

    public float GenerateFloat(string rangeName)
    {
        lock (_lock) return _ranges[rangeName].GenerateRandomFloat();
    }

    public int GenerateInt(string rangeName)
    {
        lock (_lock) return _ranges[rangeName].GenerateRandomInt();
    }

    public string SerializeRanges()
    {
        lock (_lock) return JsonConvert.SerializeObject(_ranges);
    }

    public void MergeRanges(string sourceRange, string targetRange)
    {
        lock (_lock)
        {
            RandomValueRange source = _ranges[sourceRange];
            RandomValueRange target = _ranges[targetRange];

            // Handle overlapping ranges
            if (source.Min <= target.Max && source.Max >= target.Min)
            {
                target.Min = Math.Min(source.Min, target.Min);
                target.Max = Math.Max(source.Max, target.Max);
            }
            else if (target.Min <= source.Max && target.Max >= source.Min)
            {
                // Adjust the bounds of the source range
                source.Min = Math.Max(target.Min, source.Min);
                source.Max = Math.Min(target.Max, source.Max);
            }

            _ranges[targetRange] = target;
        }
    }

    public override string ToString()
    {
        lock (_lock) return JsonConvert.SerializeObject(_ranges);
    }

    public void MonitorMemoryUsage(double threshold)
    {
        _memoryUsageThreshold = threshold;
    }

    public void SetConcurrencyLimit(int limit)
    {
        _concurrentOperationsLimit = limit;
    }
}

public class RandomValueRange
{
    private double _min;
    private double _max;
    private bool _isExclusive;

    public RandomValueRange(double min, double max, bool isExclusive)
    {
        _min = min;
        _max = max;
        _isExclusive = isExclusive;
    }

    public float GenerateRandomFloat()
    {
        return (float)(_min + (new System.Random()).NextDouble() * (_max - _min));
    }

    public int GenerateRandomInt()
    {
        return (int)(_min + new System.Random().NextDouble() * (_max - _min) * 10000);
    }
}
