#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int SN;
    int PDCP_SN;
    int STATUS_PDU;
    int SDU_LENGTH;
} LTE_PDCP_PDU;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int sn_pool[1000]; // Initialize a pool of 1000 unique SN values
int sn_index = 0;

LTE_PDCP_PDU* allocate_pdcp_pdu() {
    int sn = -1;
    pthread_mutex_lock(&lock);
    while (sn == -1) {
        if (sn_index >= sizeof(sn_pool) / sizeof(sn_pool[0])) {
            // Reallocate the pool if it's full
            int* new_sn_pool = realloc(sn_pool, 2 * sizeof(int));
            sn_pool = new_sn_pool;
            sn_index = sizeof(sn_pool) / sizeof(sn_pool[0]);
        }
        sn = sn_pool[sn_index++];
    }
    pthread_mutex_unlock(&lock);

    LTE_PDCP_PDU* pdu = (LTE_PDCP_PDU*)malloc(sizeof(LTE_PDCP_PDU));
    pdu->SN = sn;
    pdu->PDCP_SN = 0; // Default PDCP sequence number
    pdu->STATUS_PDU = 0; // Default status PDUs
    pdu->SDU_LENGTH = 1024; // Default SDU length

    return pdu;
}

void deallocate_pdcp_pdu(LTE_PDCP_PDU* pdu) {
    pthread_mutex_lock(&lock);

    int sn = pdu->SN;
    for (int i = 0; i < sn_index; i++) {
        if (sn_pool[i] == sn) {
            // Update the SN index to reuse this SN value
            sn_index = i;
            break;
        }
    }

    free(pdu);
    pthread_mutex_unlock(&lock);
}

// Example usage:
int main() {
    LTE_PDCP_PDU* pdu1 = allocate_pdcp_pdu();
    printf("SN: %d, PDCP_SN: %d, STATUS_PDU: %d, SDU_LENGTH: %d\n", pdu1->SN, pdu1->PDCP_SN, pdu1->STATUS_PDU, pdu1->SDU_LENGTH);

    LTE_PDCP_PDU* pdu2 = allocate_pdcp_pdu();
    printf("SN: %d, PDCP_SN: %d, STATUS_PDU: %d, SDU_LENGTH: %d\n", pdu2->SN, pdu2->PDCP_SN, pdu2->STATUS_PDU, pdu2->SDU_LENGTH);

    deallocate_pdcp_pdu(pdu1);
    deallocate_pdcp_pdu(pdu2);

    return 0;
}
