    printf("NIC %d:\n", nic->id);
    for (int i = 0; i < nic->num_TC; i++) {
        printf("  Channel %d: Desc - %s, Speed - %.2f, Delay - %d\n",
               i, nic->traffic_descriptors[i].desc, nic->traffic_descriptors[i].speed, nic->traffic_descriptors[i].delay);
    }
}

void manage_NIC_array(NIC** nic_array, int* num_nics) {
