    (*nic_array) = realloc((*nic_array), (*num_nics + 1) * sizeof(NIC));
    (*nic_array)[*num_nics] = new_nic;
    (*num_nics)++;

    for (int i = 0; i < *num_nics; i++) {
        log_NIC((*nic_array)[i]);
    }
