    int idle_timeout; // in seconds
} LteNetworkConfig;

LteUeContext** lte_ue_contexts = NULL;
int lte_ue_contexts_count = 0;
LteNetworkConfig network_config;

void init_lte_network_config() {
    network_config.idle_timeout = 300; // default idle timeout of 5 minutes
}

void add_srb(LteUeContext* ue_context, int srb_id) {
    if (ue_context->srbs_count == 0) {
        ue_context->srbs = malloc(sizeof(int));
        *ue_context->srbs = srb_id;
        ue_context->srbs_count = 1;
    } else {
        ue_context->srbs = realloc(ue_context->srbs, (ue_context->srbs_count + 1) * sizeof(int));
        ue_context->srbs[ue_context->srbs_count] = srb_id;
        ue_context->srbs_count++;
    }
}

void remove_srb(LteUeContext* ue_context, int srb_id) {
    for (int i = 0; i < ue_context->srbs_count; i++) {
        if (ue_context->srbs[i] == srb_id) {
            memmove(&ue_context->srbs[i], &ue_context->srbs[i + 1], (ue_context->srbs_count - i - 1) * sizeof(int));
            ue_context->srbs_count--;
            free(ue_context->srbs);
            return;
        }
    }
}

void add_drb(LteUeContext* ue_context, int drb_id) {
    if (ue_context->drbs_count == 0) {
        ue_context->drbs = malloc(sizeof(int));
        *ue_context->drbs = drb_id;
        ue_context->drbs_count = 1;
    } else {
        ue_context->drbs = realloc(ue_context->drbs, (ue_context->drbs_count + 1) * sizeof(int));
        ue_context->drbs[ue_context->drbs_count] = drb_id;
        ue_context->drbs_count++;
    }
}

