    for (int i = 0; i < ue_context->drbs_count; i++) {
        if (ue_context->drbs[i] == drb_id) {
            memmove(&ue_context->drbs[i], &ue_context->drbs[i + 1], (ue_context->drbs_count - i - 1) * sizeof(int));
            ue_context->drbs_count--;
            free(ue_context->drbs);
            return;
        }
