    for (int i = strlen(filename) - 1; i >= 0; i--) {
        if (filename[i] == '.') {
            curr_ext_len = strlen(&filename[i + 1]);
            strncpy(curr_ext, &filename[i + 1], curr_ext_len);
            strcpy(new_ext, "Modified_");
            sprintf(new_ext + strlen("Modified_"), "%d", curr_ext_len);
            break;
        }
    }

    // 2. Determine the length of the current extension and append this length in digits to the end of the new extension
    strcat(base_name, "_");
    strcat(base_name, new_ext);

    // 3. Replace any non-alphanumeric characters in the original filename with underscores in the new filename
    for (int i = 0; i < strlen(base_name); i++) {
        if (!isalnum((unsigned char)base_name[i])) {
            base_name[i] = '_';
        }
    }

    // 4. Append a randomly generated four-digit number to the end of the new filename
    srand(time(NULL));
    int rand_num = (rand() % 10000);
    sprintf(base_name + strlen(base_name), "_%04d", rand_num);

    // 5. Ensure that the new filename does not exceed 128 characters in total length, including the new extension
    if (strlen(base_name) > 124) {
        base_name[123] = '\0';
    }

    // 6. Handle filenames that do not have an extension by appending the new extension directly after the base name
    if (!curr_ext_len) {
        strcat(base_name, "."); 
        strcat(base_name, new_ext);
    }

    // 7. Utilize the Tokio library for asynchronous handling to dynamically load and execute the specified plugin from a directory of plugins
    tokio::runtime::Runtime runtime = tokio::runtime::TokioRuntime::new();
    tokio::spawn(runtime, async_move {
        // 8. Discover and load plugins without prior knowledge of their names or locations, and implement a mechanism to handle plugin loading errors gracefully
        std::vector<std::string> files;
        DIR *dir = opendir(plugin_dir);
        if (dir == NULL) {
            printf("Plugin directory not found!\n");
            return;
        }

        struct dirent *ent = readdir(dir);
        while (ent != NULL) {
            if (!strcmp(ent->d_name, ".")) continue;
            if (!strcmp(ent->d_name, "..")) continue;

            char full_path[256];
            sprintf(full_path, "%s/%s", plugin_dir, ent->d_name);
            files.push_back(full_path);
            ent = readdir(dir);
        }

        closedir(dir);

        // 9. Implement a mechanism to cache loaded plugins to minimize repeated loading and improve performance
        std::unordered_map<std::string, std::unique_ptr<tokio::fs::File>> cached_plugins;
        for (const auto &file : files) {
            if (std::filesystem::is_regular_file(file)) {
                // 10. Ensure that the plugin directory is not modified during plugin loading and execution; implement a read-only mode for the directory to prevent accidental changes
                std::string file_name = file.filename().string();
                tokio::fs::File file_handle;
                try {
                    file_handle.open(file_name, tokio::fs::FileMode::Read | tokio::fs::FileMode::ReadOnly);
                } catch (tokio::fs::Error e) {
                    printf("Failed to open plugin file: %s\n", e.what());
                    continue;
                }

                // 11. Monitor the system's available disk space before loading and executing plugins to avoid running out of space during the process
                struct statvfs statbuf;
                if (statvfs("/", &statbuf) < 0) {
                    printf("Failed to get disk usage!\n");
                    return;
                }

                int free_space = statbuf.f_bsize * statbuf.f_free_blocks / 1024;
                if (free_space < 10240) {
                    printf("Critical low disk space! Free: %d KB\n", free_space);
                    continue;
                }

                // 12. Log detailed information about each plugin loading attempt, including success or failure status, duration, and any error messages
                printf("Loading plugin: %s...\n", file_name.c_str());
                tokio::time::sleep(std::chrono::seconds(1));

                try {
                    // Execute the loaded plugin asynchronously using Tokio
                    tokio::spawn(runtime, async_move {
                        // Your code to execute the plugin goes here...
                    });
                } catch (tokio::fs::Error e) {
                    printf("Failed to load or execute plugin: %s\n", e.what());
                }
            }
        }
    });

    return base_name;
}
