char* modify_filename(char *filename) {
    char *new_filename = (char *)malloc(257 * sizeof(char)); // 255 for filename + 2 for ".txt"
    int num_digits = 0;
    char *ptr = filename;

    while (*ptr != '\0') {
        if (*ptr >= '0' && *ptr <= '9')
            num_digits++;
        ptr++;
    }

    sprintf(new_filename, "%s%d", filename, num_digits);

    if (strchr(filename, '0') || strpbrk(filename, "0123456789") != NULL) {
        strcat(new_filename, ".txt");
    } else {
        strcat(new_filename, filename + strlen(filename));
    }

    return new_filename;
}
