namespace FileModifier {
class FileNameModifier {
public:
    FileNameModifier() : generator(std::mt19937()), dist(0, 255) {}
    ~FileNameModifier() { delete[] modifiedFilename; }

    static std::mt19937& getGenerator() { return generator; }

    char* modifyFileName(const char* filename) {
        int digitCount = countDigits(filename);
        std::string newFileName = filename;
        if (digitCount > 0) {
            newFileName += std::to_string(digitCount);
            size_t dotPos = newFileName.find('.');
            if (dotPos != std::string::npos) {
                newFileName.replace(dotPos, newFileName.size() - dotPos, ".txt");
            }
        }

        int len = 0;
        for (char c : newFileName) {
            if (len >= 255 || c == ' ') break;
            len++;
        }
        modifiedFilename = new char[len + 1];
        std::strncpy(modifiedFilename, newFileName.c_str(), len);
        modifiedFilename[len] = '\0';

        return modifiedFileName;
    }

private:
    int countDigits(const char* filename) {
        int count = 0;
        while (*filename != '\0') {
            if (std::isdigit(*filename)) count++;
            filename++;
        }
        return count;
    }

    static std::mt19937 generator;
    static std::uniform_int_distribution<int> dist;

    char* modifiedFilename;
};
std::mt19937 FileNameModifier::generator;
std::uniform_int_distribution<int> FileNameModifier::dist;
}
