    {
        private readonly object _lock = new object();
        public string IpConfig { get; set; }
        public int MtuSize { get; }
        private readonly byte[] _mtuBuffer;

        public NetworkInterface(int mtuSize)
        {
            MtuSize = mtuSize;
            _mtuBuffer = new byte[mtuSize];
        }

        public void Dispose()
        {
            GC.SuppressFinalize(this);
        }
    }

    public class Range<T> where T : IComparable<T>
    {
        public T Minimum { get; }
        public T Maximum { get; }
        public bool IsInclusive { get; }

        public Range(T minimum, T maximum, bool isInclusive = false)
        {
            Minimum = minimum;
            Maximum = maximum;
            IsInclusive = isInclusive;
        }

        public void Merge(Range<T> otherRange)
        {
            if (Minimum > otherRange.Maximum || Maximum < otherRange.Minimum)
                throw new ArgumentException("Ranges are not overlapping");

            Minimum = Math.Min(Minimum, otherRange.Minimum);
            Maximum = Math.Max(Maximum, otherRange.Maximum);
        }

        public T GenerateRandom()
        {
            Random random = new Random();
            return (T)GenerateRandom(random.NextDouble());
        }

        private object GenerateRandom(double doubleValue)
        {
            if (typeof(T).IsGenericType && typeof(T).GetGenericTypeDefinition() == typeof(Nullable<>))
                return Convert.ChangeType(GetRandom((int)(doubleValue * (Maximum - Minimum) + Minimum)), typeof(T));
            else
                return Convert.ChangeType(Math.Round(GetRandom(doubleValue), (T).GetType().PropertyInfo("Digit").GetValue(null)), typeof(T));
        }

        private double GetRandom(double value)
        {
            if (IsInclusive)
                return value;
            else
                return value + Math.Sign(value) * 1e-9;
        }
    }

    public string SerializeToJson()
    {
        return JsonConvert.SerializeObject(_networkInterfaces);
    }

    public override string ToString()
    {
        return JsonConvert.SerializeObject(new { NetworkInterfaces = _networkInterfaces });
    }
