void Grid::init(int cellSize, int maxRows, int maxCols) {
    this->cellSize = cellSize;
    this->maxRows = maxRows;
    this->maxCols = maxCols;

    // Initialize grid with zeros
    grid.resize(maxRows, std::vector<Point>(maxCols));

    // Initialize hashGrid with empty vectors
    for (int i = 0; i < maxRows / cellSize; i++) {
        for (int j = 0; j < maxCols / cellSize; j++) {
            hashGrid[i].push_back(std::vector<Point>());
        }
    }
}

void Grid::updateGrid(double lat, double lon) {
