    // ...

    // Update the grid and hashGrid
    int row = static_cast<int>(lat / cellSize);
    int col = static_cast<int>(lon / cellSize);
    for (int i = 0; i < maxRows; i++) {
        for (int j = 0; j < maxCols; j++) {
            if (i >= row - row % cellSize && i <= row + cellSize - row % cellSize &&
                j >= col - col % cellSize && j <= col + cellSize - col % cellSize) {
                // Update the grid and hashGrid
                mtx.lock();
                for (int k = 0; k < point.x; k++) {
                    for (int l = 0; l < point.y; l++) {
