void modify_filename_and_execute_plugin(const char* filename, const char* directory) {
    // Step 1: Extract the base name and the current file extension from the input filename.
    char base_name[256];
    char* ptr = strrchr(filename, '.');
    if (ptr != NULL) {
        strcpy(base_name, ptr + 1);
        *ptr = '\0';
    } else {
        strcpy(base_name, filename);
    }

    // Step 2: Determine the length of the current extension and append this length in digits to the end of the new extension.
    int len = strlen(base_name);

    // Step 3: Replace any non-alphanumeric characters in the original filename with underscores in the new filename.
    char* new_filename = (char*)malloc(MAX_FILE_NAME_LENGTH + 1);
    sprintf(new_filename, "%s_%d", base_name, len);

    // Step 4: Append a randomly generated four-digit number to the end of the new filename.
    int random_num = rand() % 10000;
    sprintf(new_filename + strlen(new_filename), "_%04d", random_num);

    // Step 5: Ensure that the new filename does not exceed MAX_FILE_NAME_LENGTH characters in total length, including the new extension.
    char* new_file_ext = (char*)malloc(MAX_FILE_NAME_LENGTH + 1);
    sprintf(new_file_ext, ".%s", base_name);
    if (strlen(new_filename) + strlen(base_name) > MAX_FILE_NAME_LENGTH) {
        free(new_filename);
        free(new_file_ext);
        return;
