use std::fs::{OpenOptions, File};
use std::io::{Read, Write, ErrorKind};
use std::path::Path;
use std::string::FromUtf8Error;
use md5::Md5;

fn process_and_transform_text_file(file_path: &str, apply_rules: bool, rules: &str, input_text: &str) -> String {
    let mut file = match OpenOptions::new().read(true).open(Path::new(file_path)) {
        Ok(file) => file,
        Err(_) => return format!("Error opening file: {}", file_path),
    };

    if !file.path().exists() || file.metadata().unwrap().len() > 1024 * 1024 * 10 { // 10MB limit
        return "File does not exist or exceeds size limit.".to_string();
    }

    let mut transformed_text = String::new();
    let mut line = String::new();

    if let Err(err) = file.read_to_string(&mut line) {
        error!("Error reading file: {}", err);
        return format!("Error reading file: {}", err);
    }

    for line in line.split('\n') {
        transformed_text.push_str(line.trim());
        transformed_text.push('\n');
    }

    if apply_rules {
        // Apply transformation rules
        let mut hash = Md5::new();
        for c in input_text.chars() {
            match apply_rule(&rules, c) {
                Ok(c) => hash.update(c as u8),
                Err(err) => error!("Error applying rule: {}", err),
            }
        }
    } else {
        transformed_text.push_str(input_text);
    }

    // Compute MD5 hash of the transformed text
    let mut result = Md5::new();
    if let Err(err) = result.update(transformed_text.as_bytes()) {
        error!("Error computing hash: {}", err);
        return "Error computing hash.".to_string();
    }
    let mut hex_str = String::new();
    for byte in result.finalize() {
        hex_str.push_str(&format!("{:02x}", byte));
    }

    format!("MD5 Hash: {}", hex_str)
}

fn apply_rule(rules: &str, c: char) -> Result<char, &'static str> {
    // Implement your transformation rule logic here
    // For example:
    if c.is_uppercase() && rules.contains("UPPERCASE") {
        Ok(c.to_lowercase())
    } else {
        Ok(c)
    }
}
