    char* lchan[MAX_LCHAN];

    for (int i = 0; i < max_entities; i++) {
        mac_e_contexts[i]->mac_entity_id = i + 1;
        num_lchan = calculate_num_entities(mac_e_contexts[i]->num_lchan);
        mac_e_contexts[i]->num_lchan = num_lchan;

        for (int j = 0; j < num_lchan; j++) {
            lchan[j] = (char*)malloc(20); // Allocate space for MAC PDU indicators and CE
