    for (int i = 0; i < max_entities; i++) {
        max_lchan = mac_e_contexts[i]->num_lchan;
        for (int j = 0; j < max_lchan; j++) {
            check_valid_mac_pdu_indicators(mac_e_contexts[i]->lchan[j], j);
            generate_random_ce();
        }
    }

    // Handle concurrent access and logging
    handle_concurrent_access();

    return 0;
}

// Function to read configuration file and initialize dynamic array
void read_config_file(MAC_E_CONTEXT*** mac_e_contexts, int* max_entities) {
    FILE* file = fopen("config.ini", "r");
    if (file == NULL) {
        printf("Error: Unable to open configuration file.\n");
        exit(1);
    }

    // Read and parse configuration settings
    int num_entities = 0;
    fscanf(file, "%d", &num_entities);

    *max_entities = num_entities;

    // Allocate memory for the dynamic array
    *mac_e_contexts = (MAC_E_CONTEXT**)malloc(num_entities * sizeof(MAC_E_CONTEXT*));

    for (int i = 0; i < num_entities; i++) {
        (*mac_e_contexts)[i] = (MAC_E_CONTEXT*)malloc(sizeof(MAC_E_CONTEXT));
    }

    fclose(file);
}

// Function to calculate the number of logical channels per entity
int calculate_num_entities(int config_value) {
    int num_lchan;
    if (config_value <= 0 || config_value > 10) {
        printf("Error: Invalid configuration value for LCHAN.\n");
        exit(1);
    }
    num_lchan = config_value;
    return num_lchan;
}

// Function to check valid MAC PDU indicators
int check_valid_mac_pdu_indicators(char** lchan, int index) {
    // Check if the MAC PDU indicator is valid and within the range
    if (index < 0 || index > 10) {
        printf("Error: Invalid MAC PDU indicator for LCHAN %d.\n", index + 1);
        return -1;
    }
    return 0;
}

// Function to generate random MAC Control Elements (CE)
int generate_random_ce() {
    int ce = rand() % 100; // Generate a random CE value
    return ce;
}

// Function to handle concurrent access and logging
int handle_concurrent_access(void) {
    pthread_mutex_lock(&mutex);

    // Perform operations requiring exclusive access
    for (int i = 0; i < max_entities; i++) {
        printf("MAC Entity %d: LCHAN %s, CE value: %d\n", mac_e_contexts[i]->mac_entity_id, mac_e_contexts[i]->lchan[0], generate_random_ce());
    }

    pthread_mutex_unlock(&mutex);

    return 0;
}
