                nic_array[i].tc[j].rx_ue_info_tag = (unsigned char)(rand() % 256);
            }
        }

        // Increment the number of NICs
        num_nics = num_nics_to_allocate;
    } else if (num_nics > 0 && num_nics_to_allocate < 1) {
        // Deallocate memory for the NIC array and reset variables
        free(nic_array);
        nic_array = NULL;
        num_nics = 0;
    }
}

// Function to validate traffic channel configuration
int validate_tc_config(NIC* nic) {
    int i, j;

    // Check if each TC's RNTI values are within the valid range (1-254)
    for (i = 0; i < nic->num_tc; i++) {
        if (nic->tc[i].rnti < 1 || nic->tc[i].rnti > 254) {
            printf("Error: Invalid RNTI value in TC %d.\n", i);
            return -1;
        }
    }

    // Check if each RX UE INFORMATION TAG is unique within the allocated structures
    for (i = 0; i < nic->num_tc; i++) {
        for (j = i + 1; j < nic->num_tc; j++) {
            if (nic->tc[i].rx_ue_info_tag == nic->tc[j].rx_ue_info_tag) {
                printf("Error: Duplicate RX UE INFORMATION TAG in TC %d.\n", i);
                return -1;
            }
        }
    }

    // If no errors are found, the configuration is valid
    return 0;
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    // Example usage: Manage a dynamic array of NIC structures
    manage_nic_array(5);

    // Example usage: Validate traffic channel configuration for an existing NIC
    if (validate_tc_config(&nic_array[2]) < 0) {
        printf("Error: Traffic channel configuration is invalid.\n");
    } else {
        printf("Traffic channel configuration is valid.\n");
    }

    return 0;
}
