using System.Text.RegularExpressions;

public class DynamicFileParser
{
    private readonly Dictionary<string, DynamicRangeCollection> _parsedFiles = new Dictionary<string, DynamicRangeCollection>();
    private object _lockObj = new object();

    public void ParseAndSave(string inputFile, string outputFile, string rules)
    {
        if (!_parsedFiles.TryGetValue(inputFile, out var ranges))
            ranges = new DynamicRangeCollection(_parsedFiles);

        // Process file contents based on given rules
        // ...

        using (var writer = System.IO.File.CreateText(outputFile))
        {
            writer.WriteLine("Processed content: ");
            foreach (var range in ranges)
            {
                writer.WriteLine(range.ToString());
            }
        }
    }

    public void Serialize(string outputFile)
    {
        using (var writer = System.IO.File.CreateText(outputFile))
        {
            writer.WriteLine(JsonSerialize(_parsedFiles));
        }
    }

    private string JsonSerialize(Dictionary<string, DynamicRangeCollection> ranges)
    {
        return JsonConvert.SerializeObject(ranges);
    }
}

public class DynamicRangeCollection
{
    public List<DynamicRange<int>> IntRanges { get; } = new List<DynamicRange<int>>();
    public List<DynamicRange<float>> FloatRanges { get; } = new List<DynamicRange<float>>();

    public DynamicRangeCollection(Dictionary<string, DynamicRangeCollection> parsedFiles)
        : base()
    {
    }
}

public class DynamicRange<T>
{
    public T Min { get; set; }
    public T Max { get; set; }

    public bool IsInclusive { get; set; }

    public void ExpandTo(T min, T max)
    {
        Min = Math.Min(Min, min);
        Max = Math.Max(Max, max);
    }

    public override string ToString()
    {
        return $"{Min}-{Max} ({IsInclusive ? "inclusive" : "exclusive"})";
    }
}

public class RandomGenerator
{
    private readonly Random _random;

    public RandomGenerator()
    {
        _random = new Random();
    }

    public T GetRandomValue<T>(DynamicRange<T> range)
    {
        if (range.IsInclusive)
            return (T)Convert.ChangeType(MathF.Round(_random.NextDouble() * (range.Max - range.Min) + range.Min), typeof(T));
        else
            return (T)Convert.ChangeType(MathF.Round(_random.NextDouble() * (range.Max - range.Min) + range.Min), typeof(T)) >= range.Min && (T)Convert.ChangeType(MathF.Round(_random.NextDouble() * (range.Max - range.Min) + range.Min), typeof(T)) <= range.Max
                ? (T)Convert.ChangeType(MathF.Round(_random.NextDouble() * (range.Max - range.Min) + range.Min), typeof(T))
                : GetRandomValue<T>(new DynamicRange<T>(range.Min, range.Max));
    }
}

public static class FileParser
{
    public static void Main(string[] args)
    {
        if (args.Length < 3)
            return;

        var parser = new DynamicFileParser();
        parser.ParseAndSave(args[0], args[1], args[2]);
    }
}
