**C++ function: Manipulate a forward list of strings**

```cpp
#include <forward_list>
#include <algorithm>

void manipulateForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    bool found = false;
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }
    if (!found) {
        list.insert_after(it, insertion);
    } else {
        list.insert_after(it, 1, target);
        list.insert_after(it, 1, insertion);
    }
}
```

