    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_all(void** arr, int n) {
    for (int i = 0; i < n; ++i) {
        free(arr[i]);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T* list = malloc_or_die(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * N);
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        sprintf(pdu->RX_UE_INFORMATION_TAG, "RX_%05d", i);
        pdu->RNTI = i;
        srand(time(NULL));
        int random_value = rand() % 100;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = random_value;
    }
    return list;
}

void print_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    for (int i = 0; i < N; ++i) {
        printf("RX_UE_INFORMATION_TAG: %s, RNTI: %d, CRCFLAG: %d\n", 
               list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

int verify_list(NFAPI_CRC_INDATION_PDU_T* list, int N) {
    for (int i = 0; i < N; ++i) {
        if (!list[i].RX_UE_INFORMATION_TAG[0] || list[i].RNTI < 0 || list[i].CRCFLAG < 0) {
            return -1;
        }
    }
    return 0;
}

void pause_resume_list(NFAPI_CRC_INDICATION_PDU_T** list, int* N) {
    static int paused = 0;
    if (paused) {
        *N += (*list)->RNTI;
        ++(*N);
    } else {
        *N -= (*list)->RNTI;
        --(*N);
        free(*list);
        *list = malloc_or_die(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (*N));
        paused = 1;
    }
}

int main() {
    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T* list = create_and_populate_list(N);
    print_list(list, N);
    if (verify_list(list, N) != 0) {
        fprintf(stderr, "List verification failed\n");
        exit(EXIT_FAILURE);
    }
    pause_resume_list(&list, &N);
    return 0;
}
