#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE UE context records
typedef struct {
    int ue_id;
    char* nas_message_queue;
    int rrc_connection_state;
} lte_ue_context;

// Define the function to manage the dynamic pool of LTE UE context records
void* manage_lte_ue_contexts(void* arg) {
    // Create a lock for thread safety
    pthread_mutex_t* lock = (pthread_mutex_t*)arg;

    // Initialize the head and tail pointers for the linked list
    lte_ue_context** contexts = NULL;
    int context_count = 0;
    lte_ue_context* current = NULL;
    lte_ue_context* previous = NULL;

    while(1) {
        // Get the command from the main program (e.g., allocate, deallocate, retrieve)
        int command;

        // Handle the commands
        switch(command) {
            case 0: // Allocate a new context
                if(contexts == NULL || current != contexts[context_count - 1]) {
                    // Allocate memory for the new context
                    lte_ue_context* new_context = (lte_ue_context*)malloc(sizeof(lte_ue_context));

                    // Initialize the UE-ID, NAS message queue, and RRC connection state
                    new_context->ue_id = rand();
                    new_context->nas_message_queue = malloc(100);
                    strcpy(new_context->nas_message_queue, "Initial NAS message queue");
                    new_context->rrc_connection_state = 0;

                    // Add the new context to the linked list
                    if(contexts == NULL) {
                        contexts = (lte_ue_context**)malloc(sizeof(lte_ue_context*));
                        current = new_context;
                        previous = new_context;
                    } else {
                        previous->next = new_context;
                        previous = new_context;
                    }

                    // Update the context count and pointers
                    context_count++;
                } else {
                    printf("Context already exists!\n");
                }

            case 1: // Deallocate a specific context by UE-ID
                int ue_id;

                // Get the UE-ID from the main program
                scanf("%d", &ue_id);

                // Find the context with the given UE-ID and deallocate it
                for(int i = 0; i < context_count; i++) {
                    if(contexts[i]->ue_id == ue_id) {
                        free(contexts[i]->nas_message_queue);
                        free(contexts[i]);
                        contexts[i] = contexts[context_count - 1];
                        context_count--;
                        break;
                    }
                }

            case 2: // Retrieve a specific context by UE-ID
                int ue_id;

                // Get the UE-ID from the main program
                scanf("%d", &ue_id);

                // Find the context with the given UE-ID and retrieve its information
                for(int i = 0; i < context_count; i++) {
                    if(contexts[i]->ue_id == ue_id) {
                        printf("UE-ID: %d\n", contexts[i]->ue_id);
                        printf("NAS message queue: %s\n", contexts[i]->nas_message_queue);
                        printf("RRC connection state: %d\n", contexts[i]->rrc_connection_state);
                    }
                }

            case 3: // Update the RRC connection state of a specific context by UE-ID
                int ue_id;
                int new_rrc_connection_state;

                // Get the UE-ID and new RRC connection state from the main program
                scanf("%d %d", &ue_id, &new_rrc_connection_state);

                // Find the context with the given UE-ID and update its RRC connection state
                for(int i = 0; i < context_count; i++) {
                    if(contexts[i]->ue_id == ue_id) {
                        contexts[i]->rrc_connection_state = new_rrc_connection_state;
                    }
                }

            case 4: // Print the list of all UE contexts
                for(int i = 0; i < context_count; i++) {
                    printf("UE-ID: %d\n", contexts[i]->ue_id);
                    printf("NAS message queue: %s\n", contexts[i]->nas_message_queue);
                    printf("RRC connection state: %d\n", contexts[i]->rrc_connection_state);
                }
        }

        // Release the lock
        pthread_mutex_unlock(lock);

        // Sleep for a short period to avoid busy-waiting
        usleep(100000);
    }
}

// Define the main function to start the management of LTE UE context records
int main() {
    // Create the lock for thread safety
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Start the management of LTE UE context records in a separate thread
    pthread_t thread;
    pthread_create(&thread, NULL, manage_lte_ue_contexts, &lock);

    // Main program loop to handle commands and interact with the managed contexts
    while(1) {
        int command;

