#define UE_CONTEXT_POOL_SIZE 1024
#define UE_ID_MAX 1000

typedef struct {
    uint32_t ue_id;
    // Add more fields as needed
    char nas_message_queue[128];
    int rrc_connection_state;
} lte_ue_context;

lte_ue_context *ue_context_pool = NULL;
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = stderr;

void* ue_context_alloc(void) {
    lte_ue_context *new_ctx = (lte_ue_context*)malloc(sizeof(lte_ue_context));
    if (!new_ctx) {
        perror("Context allocation failed");
        return NULL;
    }
    new_ctx->ue_id = -1; // Mark as uninitialized
    return new_ctx;
}

void ue_context_free(void* ctx) {
    free((lte_ue_context*)ctx);
}

int ue_context_init() {
    if (pthread_mutex_init(&ue_context_lock, NULL)) {
        perror("Mutex initialization failed");
        return -1;
    }
    if (!(ue_context_pool = malloc(UE_CONTEXT_POOL_SIZE * sizeof(lte_ue_context)))) {
        perror("Pool allocation failed");
        return -1;
    }
    for (int i = 0; i < UE_CONTEXT_POOL_SIZE; i++) {
        ue_context_free(ue_context_pool + i);
    }
    return 0;
}

void ue_context_deinit() {
    if (!ue_context_pool) return;
    free(ue_context_pool);
    pthread_mutex_destroy(&ue_context_lock);
}

int ue_context_get_by_ue_id(uint32_t ue_id, lte_ue_context **ctx) {
    *ctx = NULL;
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < UE_CONTEXT_POOL_SIZE; i++) {
        if ((ue_context_pool + i)->ue_id == ue_id) {
            *ctx = ue_context_pool + i;
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
    return (*ctx != NULL) ? 0 : -1;
}

int ue_context_update(lte_ue_context* ctx, uint32_t nas_message_queue[128], int rrc_connection_state) {
    if (!ctx) return -1;
    pthread_mutex_lock(&ue_context_lock);
    ctx->nas_message_queue = nas_message_queue;
    ctx->rrc_connection_state = rrc_connection_state;
    pthread_mutex_unlock(&ue_context_lock);
    return 0;
}

void ue_log_error(int err_code, const char* msg) {
    fprintf(log_file, "Error: %s (code %d)\n", msg, err_code);
}
