import re
import concurrent.futures

def process_log_file(filename):
    with open(filename, 'r') as file:
        for line in file:
            if re.match(r'^(error|warning):', line):
                yield line.strip()

def aggregate_metrics(log_files):
    metrics = {'errors': 0, 'warnings': 0}
    for file in log_files:
        with open(file, 'r') as f:
            for line in f:
                match = re.match(r'^(error|warning):', line)
                if match:
                    metric = match.group(1).lower()
                    metrics[metric] += 1
    return metrics

def main():
    log_files = ['log_file1.log', 'log_file2.log', ...]
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = [executor.submit(process_log_file, file) for file in log_files]
        metrics = aggregate_metrics(log_files)
        print(metrics)

if __name__ == '__main__':
    main()
