#include <pthread.h>

typedef struct {
    void (*task)(void*);
} task_t;

typedef struct {
    int max_threads;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    pthread_t *threads;
} thread_pool_t;

thread_pool_t* create_thread_pool(int max_threads) {
    thread_pool_t* pool = (thread_pool_t*)malloc(sizeof(thread_pool_t));
    pool->max_threads = max_threads;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->threads = (pthread_t*)malloc(max_threads * sizeof(pthread_t));
    return pool;
}

void submit_task(thread_pool_t* pool, task_t* task) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->max_threads; i++) {
        if (!pthread_equal(pool->threads[i], pthread_self())) {
            break;
        }
    }
    pthread_create(&pool->threads[i], NULL, task->task, task->arg);
    pthread_mutex_unlock(&pool->lock);
}

void signal_completion(thread_pool_t* pool) {
    pthread_cond_signal(&pool->cond);
}

void join_thread_pool(thread_pool_t* pool) {
    for (int i = 0; i < pool->max_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
    free(pool->threads);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
}

void print_metrics() {
