typedef struct {
    network_interface* interfaces;
    int num_interfaces;
} network_manager;

network_manager* init_network_manager() {
    return (network_manager*)malloc(sizeof(network_manager));
}

void free_network_manager(network_manager* manager) {
    for(int i = 0; i < manager->num_interfaces; i++) {
        free(manager->interfaces[i].mtu_buffer);
    }
    free(manager->interfaces);
    free(manager);
}

int add_interface(network_manager* manager, int ip_address, int mtu_buffer_size) {
    network_interface* new_interface = (network_interface*)malloc(sizeof(network_interface));
    new_interface->ip_address = ip_address;
    new_interface->mtu_buffer_size = mtu_buffer_size;
    new_interface->mtu_buffer = malloc(mtu_buffer_size);

    if(!manager->interfaces) {
        manager->interfaces = (network_interface*)malloc(sizeof(network_interface));
        manager->num_interfaces = 1;
    } else {
        network_interface** temp = (network_interface**)malloc((manager->num_interfaces + 1)*sizeof(network_interface*));
        for(int i = 0; i < manager->num_interfaces; i++) {
            temp[i] = manager->interfaces[i];
        }
        free(manager->interfaces);
        manager->interfaces = temp;
        manager->num_interfaces++;
    }

    if(!manager->interfaces[manager->num_interfaces - 1]) {
        return -1;
    } else {
        manager->interfaces[manager->num_interfaces - 1] = new_interface;
        return 0;
    }
}

int update_ip(network_manager* manager, int interface_index, int new_ip) {
    if(interface_index >= 0 && interface_index < manager->num_interfaces) {
