import subprocess
import os
import sys
import json
import requests
import platform

def install_tool(tool):
    if platform.dist().lower() == "centos":
        install_cmd = f"yum install -y {tool}"
    elif platform.dist().lower() == "ubuntu":
        install_cmd = f"apt-get install -y {tool}"
    else:
        print(f"Unsupported platform: {platform.dist()}. Skipping installation of {tool}.")
        return
    try:
        subprocess.check_call(install_cmd.split())
    except subprocess.CalledProcessError as e:
        print(f"Failed to install {tool}: {e}")

def get_env_value(key):
    env_vars = os.environ
    if key in env_vars:
        return env_vars[key]
    else:
        return None

def generate_config(env, stage):
    # Load configuration template
    with open("config-template.yml", "r") as f:
        config_template = json.load(f)

    # Replace placeholders with environment-specific values
    for service, settings in config_template["services"].items():
        if env in settings:
            for key, value in settings[env].items():
                config_template["services"][service][key] = value

    # Append stage-specific configuration
    if stage:
        config_template["stage"] = stage

    return json.dumps(config_template)

def main():
    if len(sys.argv) > 1:
        env = sys.argv[1]
    else:
        env = get_env_value("ENV")

    if not env:
        print("Please provide an environment value or set the ENV environment variable.")
        sys.exit(1)

    # Install required tools
    install_tool("docker-compose")
    install_tool("jq")

    config = generate_config(env, "development")

    with open(f"config-{env}.yml", "w") as f:
        f.write(config)

if __name__ == "__main__":
    main()
