#include <string.h>

typedef struct {
    char* ip_address;
    int mtu_buffer_size;
} network_interface_t;

network_interface_t* interface_list = NULL;
int num_interfaces = 0;

void init_interfaces(int num) {
    for (int i = 0; i < num; i++) {
        network_interface_t* new_interface = (network_interface_t*)malloc(sizeof(network_interface_t));
        new_interface->ip_address = (char*)malloc(16);
        strcpy(new_interface->ip_address, "192.168.");
        sprintf(new_interface->ip_address + strlen("192.168."), "%d", i);
        new_interface->mtu_buffer_size = 1500;
        if (interface_list != NULL) {
            interface_list = realloc(interface_list, (num_interfaces + 1) * sizeof(network_interface_t));
        } else {
            interface_list = (network_interface_t*)malloc(num * sizeof(network_interface_t));
        }
        interface_list[num_interfaces++] = *new_interface;
    }
}

void update_ip_config(int idx, char* new_ip) {
    if (idx >= 0 && idx < num_interfaces) {
        free(interface_list[idx].ip_address);
        interface_list[idx].ip_address = (char*)malloc(strlen(new_ip) + 1);
        strcpy(interface_list[idx].ip_address, new_ip);
    }
}

void cleanup_interfaces() {
    for (int i = 0; i < num_interfaces; i++) {
        free(interface_list[i].ip_address);
    }
    free(interface_list);
}
