```python
import os
import sys
import subprocess
from threading import Thread
from queue import Queue, LifoQueue
from logging import getLogger, basicConfig

# Set up logging
basicConfig(level='INFO', format='%(asctime)s - %(levelname)s - %(message)s')

class PipelineManager:
    def __init__(self):
        self.environments = {}
        self.dependencies = set()
        self.parallel_jobs = LifoQueue()

    def set_environment(self, env_name):
        if env_name not in self.environments:
            raise ValueError(f"Environment '{env_name}' not found")

        return self.environments[env_name]

    def add_dependency(self, tool):
        self.dependencies.add(tool)

    def install_dependencies(self, env_name):
        for dependency in self.dependencies:
            try:
                # Install dependencies using package manager
                subprocess.run([f"{dependency}-install"], check=True)
            except subprocess.CalledProcessError as e:
                raise ValueError(f"Failed to install {dependency}: {e}")

    def execute_job(self, job_name, env_name):
        if env_name not in self.environments:
            raise ValueError(f"Environment '{env_name}' not found")

        # Create a new thread for the job
        t = Thread(target=self.run_job, args=(job_name,))
        t.start()
        self.parallel_jobs.put(t)

    def run_job(self, job_name):
        try:
            # Run the job using the selected environment
            subprocess.run([f"{self.environments[env_name]['runner']} {job_name}"], check=True)
        except subprocess.CalledProcessError as e:
            raise ValueError(f"Job '{job_name}' failed: {e}")

    def cleanup(self):
        # Clean up parallel jobs
        while not self.parallel_jobs.empty():
            self.parallel_jobs.get().join()

# Example usage
if __name__ == "__main__":
    pm = PipelineManager()
    pm.set_environment("dev")
    pm.add_dependency("jenkins")
    pm.install_dependencies("dev")

    try:
        pm.execute_job("build", "dev")
        pm.execute_job("test", "dev")
    except ValueError as e:
        print(f"Error: {e}")

    pm.cleanup()

