void mac_entity_context_manager(int num_entities, int idle_timeout) {
    MAC_E_CONTEXT *entities = malloc(num_entities * sizeof(MAC_E_CONTEXT));
    if (!entities) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < num_entities; i++) {
        entities[i].mac_id = i + 1;
        entities[i].lchan_count = rand() % 10 + 1;

        entities[i].lchans = malloc(entities[i].lchan_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!entities[i].lchans) {
            printf("Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(entities[j].lchans);
            }
            free(entities);
            return;
        }

        for (int j = 0; j < entities[i].lchan_count; j++) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &entities[i].lchans[j];
            pdu->rx_ue_info_tag = rand();
            pdu->rnti = rand() % 10000;
            if (pdu->rnti < 0 || pdu->rnti > 9999) {
                printf("RNTI out of range.\n");
                for (int k = 0; k <= i; k++) {
                    free(entities[k].lchans);
                }
                free(entities);
                return;
            }
            pdu->crc_ind_rel8_tag = rand();
            pdu->crcflag = rand() % 2;

            if (!pdu->crcflag) {
                printf("CRC flag not set.\n");
                for (int k = 0; k <= i; k++) {
                    free(entities[k].lchans);
                }
                free(entities);
                return;
            }
        }

        // Initialize NMS callback mechanism
        nms_callback(&entities[i], &pdu);

        // Purge inactive entities after idle timeout
        if (idle_timeout > 0) {
            for (int j = i + 1; j < num_entities; j++) {
                if (entities[j].lchan_count == 0) {
                    free(entities[j].lchans);
                    memmove(&entities[j], &entities[i + 1], (num_entities - i - 1) * sizeof(MAC_E_CONTEXT));
                    i--;
                    break;
                }
            }
        }
    }

    // Send notifications to NMS for new entities
    for (int i = 0; i < num_entities; i++) {
        nms_send_notification(&entities[i]);
    }

    free(entities);
}
