// Priority Queue implementation using a linked list
typedef struct {
    NLE* data;
    double priority;
    struct {
        struct node* next;
    } link;
} PriorityQueue;

typedef struct node {
    PriorityQueue* data;
    struct node* next;
} Node;

void enqueue(PriorityQueue** queue, double priority, NLE* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    new_node->data->priority = priority;
    new_node->data->data = data;
    new_node->next = (*queue)->link.next;
    (*queue)->link.next = new_node;
}

NLE* dequeue(PriorityQueue** queue) {
    if ((*queue)->link.next == NULL) {
        printf("Priority Queue is empty.\n");
        return NULL;
    }
    NLE* data = (*queue)->link.next->data->data;
    Node* temp = (*queue)->link.next;
    (*queue)->link.next = temp->next;
    free(temp);
    return data;
}

// Asynchronous processing using threads
void* process_updates(void* arg) {
