void modify_filename(char* filename) {
    char new_filename[255];
    int num_digits = 0;
    for(int i=0;filename[i];i++) {
        if(('0'<=filename[i)&&'9'>=filename[i])) num_digits++;
    }
    sprintf(new_filename,"%s%d.txt",filename,num_digits);
}

int main(int argc,char** argv) {
    int c;
    char* output_file = NULL;
    while ((c = getopt(argc,argv,"hc:o:")) != -1) {
        switch(c) {
            case 'h':
                printf("Usage: %s [-o output_file] [input_file]\n",argv[0]);
                exit(0);
            case 'o':
                output_file = optarg;
                break;
            default:
                abort();
        }
    }
    if(argc<2) {
        fprintf(stderr,"Error: No input file provided.\n");
        printf("Usage: %s [-o output_file] [input_file]\n",argv[0]);
        exit(1);
