LTE_UERadioAccessNetworkProcedureIdentity* initRadioAccessNetworkProcedureIdentityList(int size) {
    LTE_UERadioAccessNetworkProcedureIdentity* head = NULL;
    LTE_UERadioAccessNetworkProcedureIdentity* current = NULL;

    for (int i = 0; i < size; i++) {
        LTE_UERadioAccessNetworkProcedureIdentity* newNode = (LTE_UERadioAccessNetworkProcedureIdentity*)malloc(sizeof(LTE_UERadioAccessNetworkProcedureIdentity));

        // Generate unique RadioAccessNetworkId
        newNode->RadioAccessNetworkId = rand() % 1000;

        // Generate UEIdentityTag and SecurityCapabilityTag dynamically
        char* UEIdentityTag = (char*)malloc(10 * sizeof(char));
        strcpy(UEIdentityTag, "UE_ID_TAG_");
        sprintf(UEIdentityTag + strlen(UEIdentityTag), "%d", newNode->RadioAccessNetworkId);

