        newNode->UEIdentityTag = UEIdentityTag;
        newNode->SecurityCapabilityTag = SecurityCapabilityTag;

        // Add the new node to the list
        if (head == NULL) {
            head = current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

