#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char remote_ip[17], local_ip[17];
    int remote_port, local_port;
    int status; // 0: CLOSED, 1: ESTABLISHED, 2: FIN_WAIT_1
} ConnectionState;

ConnectionState** connection_states = NULL;
int num_connections = 0;

void add_connection_state(int id, const char* remote_ip, int remote_port, const char* local_ip, int local_port) {
    if (remote_port < 0 || remote_port > 65535 || local_port < 0 || local_port > 65535) {
        printf("Invalid port number!\n");
        return;
    }

    if (!validate_ip(remote_ip) || !validate_ip(local_ip)) {
        printf("Invalid IP address format!\n");
        return;
    }

    ConnectionState** new_connections = realloc(connection_states, (num_connections + 1) * sizeof(ConnectionState*));
    if (!new_connections) {
        printf("Memory allocation failed!\n");
        return;
    }
    connection_states = new_connections;

    ConnectionState* new_state = malloc(sizeof(ConnectionState));
    if (!new_state) {
        printf("Memory allocation failed!\n");
        free(new_connections);
        return;
    }

    new_state->id = id;
    strcpy(new_state->remote_ip, remote_ip);
    strcpy(new_state->local_ip, local_ip);
    new_state->remote_port = remote_port;
    new_state->local_port = local_port;

    connection_states[num_connections++] = new_state;
}

int validate_ip(const char* ip) {
    if (strlen(ip) < 7 || strlen(ip) > 15)
        return 0;

    for (int i = 0; i < strlen(ip); i++) {
        if (!isdigit(ip[i]) && ip[i] != '.' && ip[i] != '-')
            return 0;
    }

    int dots = 0;
    for (int i = 0; i < strlen(ip); i++) {
        if (ip[i] == '.') {
            dots++;
            if (dots > 3)
                return 0;
        }
    }

    return 1;
}

void free_connection_states() {
    for (int i = 0; i < num_connections; i++) {
        free(connection_states[i]);
    }
    free(connection_states);
}
