// Define a structure to represent TCP connection state
typedef struct {
    int id;
    char remote_ip[17];
    char local_ip[17];
    int remote_port;
    int local_port;
    int status;
} ConnectionState;

// Define a structure to manage the dynamic array of connection states
typedef struct {
    ConnectionState* states;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConnectionStateArray;

// Function to create a new connection state array
ConnectionStateArray* createStateArray(int initial_capacity) {
    ConnectionStateArray* arr = (ConnectionStateArray*)malloc(sizeof(ConnectionStateArray));
    arr->states = (ConnectionState*)calloc(initial_capacity, sizeof(ConnectionState));
    arr->size = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL);
    pthread_cond_init(&arr->cond, NULL);
    return arr;
}

// Function to add a new connection state to the array
int addConnectionState(ConnectionStateArray* arr, ConnectionState state) {
    pthread_mutex_lock(&arr->mutex);

    // Check if the array needs to be resized
    if (arr->size >= arr->capacity) {
        int new_capacity = arr->capacity * 2;
        ConnectionState* new_states = (ConnectionState*)realloc(arr->states, new_capacity * sizeof(ConnectionState));
        arr->states = new_states;
        arr->capacity = new_capacity;
    }

    // Validate IP addresses and port numbers
    if (!isValidIP(state.remote_ip) || !isValidIP(state.local_ip) || state.remote_port < 0 || state.local_port < 0 || state.remote_port > 65535 || state.local_port > 65535) {
        pthread_mutex_unlock(&arr->mutex);
        return -1; // Invalid input
    }

    // Add the new connection state to the array
    arr->states[arr->size] = state;
    arr->size++;

    pthread_cond_signal(&arr->cond);

    pthread_mutex_unlock(&arr->mutex);
    return 0; // Success
}

// Function to filter connection states based on given criteria
int filterConnectionStates(ConnectionStateArray* arr, int status, char* ip_filter, int port_filter) {
    pthread_mutex_lock(&arr->mutex);

    for (int i = 0; i < arr->size; i++) {
        ConnectionState state = arr->states[i];
        if ((status != 0 && state.status == status) || (ip_filter != NULL && strcmp(state.remote_ip, ip_filter) == 0) || (port_filter != 0 && state.remote_port == port_filter)) {
            printf("ID: %d, Remote IP: %s, Local IP: %s, Remote Port: %d, Local Port: %d, Status: %d\n", state.id, state.remote_ip, state.local_ip, state.remote_port, state.local_port, state.status);
        }
    }

    pthread_mutex_unlock(&arr->mutex);
    return 0; // Success
}

// Function to free the connection state array and its contents
void freeConnectionStateArray(ConnectionStateArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->states[i].remote_ip);
        free(arr->states[i].local_ip);
    }
    free(arr->states);
    pthread_mutex_destroy(&arr->mutex);
    pthread_cond_destroy(&arr->cond);
    free(arr);
}
