            head = new_node;
            cache_head = new_node;
        } else {
            node_t* current = head;
            while(current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }

        // Validate tags
        if(strlen(new_node->data.UEIdentityTag) > 20 || strlen(new_node->data.SecurityCapabilityTag) > 20) {
            printf("Tags not correctly formatted.\n");
            return;
        }
    }
}

void periodic_cleanup() {
    node_t* current = head;
    while(current != NULL) {
        if(cache_size >= 5) {
            node_t* temp = cache_head;
            cache_head = temp->next;
            free(temp);
            cache_size--;
        } else {
            break;
        }
        current = current->next;
