    if (!memory_pool) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        return NULL; // or throw an exception
    }

    // Configure the memory pool for growth
    config.max_size *= 2;
    void *new_memory = realloc(memory_pool, config.max_size);
    if (new_memory) {
        memory_pool = new_memory;
    } else {
        fprintf(stderr, "Failed to allocate grown memory pool\n");
        return NULL; // or throw an exception
    }

    // Initialize and populate the MAC packet array
    MAC_PACKET_T *mac_packets = memory_pool;
    for (i = 0; i < N; i++) {
        mac_packets[i].src_mac_address[0] = (unsigned char)('0' + i % 10);
