typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned char RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct node* next;
};

NFAPI_CRC_INDICATION_PDU_T* createNode() {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(newNode == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    // Initialize structure with random CRCFLAG
    srand(time(NULL));
    newNode->RX_UE_INFORMATION_TAG = rand() % 1000; // Randomly assign value to RX_UE_INFORMATION_TAG
    newNode->RNTI = rand() % 256; // Randomly assign value to RNTI
    newNode->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1

    return newNode;
}

void freeNode(NFAPI_CRC_INDICATION_PDU_T* node) {
    if(node == NULL)
        return;
    free(node);
}

void printList(struct node* head) {
    while(head != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d\n", head->data.RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", head->data.RNTI);
        printf("CRCFLAG: %d\n", head->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        head = head->next;
    }
}

void updateList(struct node* head) {
    while(head != NULL) {
        // Update CRCFLAG based on specific conditions
        if(head->data.RX_UE_INFORMATION_TAG % 2 == 0)
            head->data.CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        else
            head->data.CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        head = head->next;
    }
}

struct node* createList(int N) {
    struct node* head = NULL;
    for(int i=0; i<N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newNode = createNode();
        if(newNode == NULL)
            return NULL;
        // Add new node to the end of the list
        struct node* current = head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = (struct node*)malloc(sizeof(struct node));
        current->next->data = *newNode;
        current->next->next = NULL;
    }
    return head;
}

int main() {
    int N = 5; // Number of nodes in the list
    struct node* head = createList(N);

    if(head == NULL)
        return -1;

    printList(head); // Print the linked list

    updateList(head); // Update CRCFLAG based on specific conditions

    printf("Updated List:\n");
    printList(head); // Print the updated linked list

    while(head != NULL) {
        freeNode(head);
