typedef struct Node {
    NFAPI_RRC_MEASUREMENT_T data;
    struct Node* left;
    struct Node* right;
} Node;

Node* createTree(int N) {
    if (N <= 0)
        return NULL;

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed\n");
        return NULL; // Handle memory allocation failure
    }

    node->data.MEASUREMENT_ID = -1;
    node->data.CELL_ID = -1;
    node->data.RSRP = 0.0;

    node->left = createTree(N / 2);
    node->right = createTree(N / 2);

    return node;
}

void freeTree(Node* root) {
    if (!root)
        return;

    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

Node* addMeasurement(Node* root, NFAPI_RRC_MEASUREMENT_T measurement) {
    if (root == NULL)
        return createTree(1);

    Node* node = root;
    int N = 0;

    while (node) {
        N++;
        if (measurement.MEASUREMENT_ID < node->data.MEASUREMENT_ID) {
            if (!node->left) {
                node->left = createTree(N / 2);
                break;
            }
            node = node->left;
        } else {
            if (!node->right) {
                node->right = createTree(N / 2 - N / 4);
                break;
            }
            node = node->right;
        }
    }

    node->data.MEASUREMENT_ID = measurement.MEASUREMENT_ID;
    node->data.CELL_ID = measurement.CELL_ID;
    node->data.RSRP = measurement.RSRP;

    return root;
}

void updateRSRP(Node* root, double newRSRP) {
    if (root == NULL)
        return;

    Node* node = root;
    while (node) {
        node->data.RSRP = newRSRP;
        node = node->left ? node->left : node->right;
    }
}

void removeOutdatedMeasurements(Node* root, int threshold) {
    if (root == NULL)
        return;

    Node* node = root;
    while (node) {
        if (node->data.RSRP < threshold) {
            // Remove outdated measurement
            free(node);
            node = node->left ? node->left : node->right;
            continue;
        }
        node = node->left ? node->left : node->right;
    }
}

void printTree(Node* root) {
    if (root == NULL)
        return;

    printf("MEASUREMENT_ID: %d, CELL_ID: %d, RSRP: %.2f\n", root->data.MEASUREMENT_ID, root->data.CELL_ID, root->data.RSRP);
    printTree(root->left);
    printTree(root->right);
}
