    double total_packets = 0.0;
    for (int i = 0; i < num_interfaces; i++) {
        total_packets += stats[i].throughput;
    }

    // Calculate weighted averages
    for (int i = 0; i < num_interfaces; i++) {
        stats[i].packet_loss_rate /= total_packets;
        stats[i].throughput /= total_packets;
        stats[i].latency /= total_packets;
    }
}

double calculate_average(NetworkInterfaceStats* stats, int num_interfaces) {
    double total_packets = 0.0;
    for (int i = 0; i < num_interfaces; i++) {
        total_packets += stats[i].throughput;
    }

    return total_packets / num_interfaces;
}
