    public class DynamicFileParser
    {
        private readonly object _lock = new object();
        private List<ParsedContent> _parsedContents = new List<ParsedContent>();

        public void AddParsedContent(ParsedContent content)
        {
            lock (_lock)
            {
                _parsedContents.Add(content);
            }
        }

        public void UpdateParsedContent(int index, ParsedContent newContent)
        {
            lock (_lock)
            {
                if (index < 0 || index >= _parsedContents.Count) return;
                _parsedContents[index] = newContent;
            }
        }

        public void RemoveParsedContent(int index)
        {
            lock (_lock)
            {
                _parsedContents.RemoveAt(index);
            }
        }

        public ParsedContent GetParsedContent(int index)
        {
            lock (_lock)
            {
                if (index < 0 || index >= _parsedContents.Count) return null;
                return _parsedContents[index];
            }
        }

        public void ReleaseResources()
        {
            lock (_lock)
            {
                _parsedContents.Clear();
            }
        }

        public static string ReadAndTransformBinaryFile(string inputFile, string outputFile, string rules)
        {
            using (FileStream fs = new FileStream(inputFile, FileMode.Open))
