public class FileUploader {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final BlockingQueue<FileUploadTask> taskQueue = new LinkedBlockingQueue<>();
    private final int concurrencyLimit = 5; // adjust this value based on system load and requirements
    private final int retryAttempts = 3;
    private final long dynamicFileSizeThreshold = 1000 * 1024 * 1024; // adjust this value based on system load and requirements

    public void startUploadBatch(List<FileUploadTask> tasks) {
        tasks.forEach(task -> taskQueue.add(task));
        try {
            while (!taskQueue.isEmpty()) {
                int concurrentTasks = Math.min(concurrencyLimit, taskQueue.size());
                List<Future<?>> futures = new ArrayList<>();
                for (int i = 0; i < concurrentTasks; i++) {
                    FileUploadTask task = taskQueue.poll();
                    if (task != null) {
                        futures.add(executor.submit(() -> processFileUpload(task)));
                    }
                }
                for (Future<?> future : futures) {
                    try {
                        future.get(); // block until all tasks are completed
                    } catch (ExecutionException e) {
                        // handle exceptions
                    }
                }
            }
        } finally {
            executor.shutdown();
        }
    }

