import csv
import os
from collections import Counter
from email_validator import validate_email, EmailNotCompliantError
import time

class CSVProcessor:
    def __init__(self, directory_path):
        self.directory_path = directory_path
        self.email_counts = {}
        self.total_count = 0
        self.average_length = 0.0
        self.most_common_domain = None

    def process_csv(self):
        for filename in os.listdir(self.directory_path):
            if not filename.endswith('.csv'):
                continue

            with open(os.path.join(self.directory_path, filename), 'r', newline='') as csvfile:
                reader = csv.reader(csvfile)
                header = next(reader)

                chunk_size = 1000
                chunks = [list(reader) for _ in range((len(list(reader)) + chunk_size - 1) // chunk_size)]

                for chunk in chunks:
                    self.process_chunk(chunk)

    def process_chunk(self, chunk):
        for row in chunk:
            email = row[header.index('email')]
            domain = None

            try:
                v = validate_email(email)
                domain = v.domain
            except EmailNotCompliantError:
                continue

            if domain not in self.email_counts:
                self.email_counts[domain] = 1
            else:
                self.email_counts[domain] += 1

            self.total_count += 1
            self.average_length += len(email)

        self.most_common_domain, _ = Counter(self.email_counts).most_common(1)[0]

    def get_metrics(self):
        if not self.total_count:
            return None

        average_length = self.average_length / self.total_count
        return {
            'total_unique_emails': len(self.email_counts),
            'average_email_length': average_length,
            'most_common_domain': self.most_common_domain
        }

    def __str__(self):
        metrics = self.get_metrics()
        if not metrics:
            return "Processing... (no data found)"

        return f"Total unique emails: {metrics['total_unique_emails']}, Average email length: {metrics['average_email_length']:.2f}, Most common domain: {metrics['most_common_domain']}"

if __name__ == "__main__":
    processor = CSVProcessor('/path/to/csv/files')
    start_time = time.time()
    processor.process_csv()
    print(processor)
    print(f"Processing took {(time.time() - start_time):.2f} seconds")
```']

