    char SecurityCapabilityTag[10];
    time_t lastUpdatedTimestamp;
} LTE_UERadioAccessNetworkProcedureIdentity;

// Define structure for doubly linked list node
typedef struct Node {
    LTE_UERadioAccessNetworkProcedureIdentity data;
    struct Node* next;
    struct Node* prev;
} Node;

// Function to create a new doubly linked list node
Node* newNode(LTE_UERadioAccessNetworkProcedureIdentity data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

// Function to initialize the doubly linked list with randomly generated values
void initDoublyLinkedList(Node** headRef, int size) {
    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < size; i++) {
        LTE_UERadioAccessNetworkProcedureIdentity data;
        data.RadioAccessNetworkId = rand() % 100 + 1;  // Randomly generated RadioAccessNetworkId
        sprintf(data.UEIdentityTag, "UE%05d", rand() % 100000);  // Randomly generated UEIdentityTag
        sprintf(data.SecurityCapabilityTag, "SC%05d", rand() % 100000);  // Randomly generated SecurityCapabilityTag
        data.lastUpdatedTimestamp = time(NULL);

        Node* newNode = newNode(data);
        if (i == 0) {
            *headRef = newNode;
        } else {
            Node* lastNode = *headRef;
            while (lastNode->next != NULL) {
                lastNode = lastNode->next;
            }
            lastNode->next = newNode;
            newNode->prev = lastNode;
        }
    }
}

// Function to print the contents of the doubly linked list
void printDoublyLinkedList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RadioAccessNetworkId: %d, UEIdentityTag: %s, SecurityCapabilityTag: %s, lastUpdatedTimestamp: %ld\n",
               current->data.RadioAccessNetworkId,
               current->data.UEIdentityTag,
               current->data.SecurityCapabilityTag,
               (long)current->data.lastUpdatedTimestamp);
        current = current->next;
    }
}

