void network_interface_manager_init(NETWORK_INTERFACE_T** interface_list, size_t initial_capacity) {
    *interface_list = (NETWORK_INTERFACE_T*)malloc(initial_capacity * sizeof(NETWORK_INTERFACE_T));

    if (*interface_list == NULL) {
        printf("Memory allocation failure.\n");
        return;
    }

    for (size_t i = 0; i < initial_capacity; i++) {
        (*interface_list)[i].connections_count = 0;
        (*interface_list)[i].mtu_buffer_size = 1024;
        (*interface_list)[i].mtu_buffer = (char*)malloc((*interface_list)[i].mtu_buffer_size);
    }
}

// Define a function to add a new network interface
void network_interface_manager_add(NETWORK_INTERFACE_T** interface_list, size_t* capacity) {
    if (*capacity < 1) {
        *capacity *= 2;
        NETWORK_INTERFACE_T* new_interfaces = (NETWORK_INTERFACE_T*)realloc(*interface_list, *capacity * sizeof(NETWORK_INTERFACE_T));

        if (new_interfaces == NULL) {
            printf("Memory allocation failure.\n");
            return;
        }

        *interface_list = new_interfaces;
    }
}

// Define a function to add a new network connection
void network_interface_manager_add_connection(NETWORK_INTERFACE_T* interface, NETWORK_CONNECTION_T* connection) {
    if (interface->connections_count < 1) {
        interface->connections = (NETWORK_CONNECTION_T*)malloc(1 * sizeof(NETWORK_CONNECTION_T));

        if (interface->connections == NULL) {
            printf("Memory allocation failure.\n");
            return;
        }

        memcpy(&interface->connections[0], connection, sizeof(NETWORK_CONNECTION_T));
        interface->connections_count = 1;
    } else {
        NETWORK_CONNECTION_T* new_connections = (NETWORK_CONNECTION_T*)realloc(interface->connections, (interface->connections_count + 1) * sizeof(NETWORK_CONNECTION_T));

        if (new_connections == NULL) {
            printf("Memory allocation failure.\n");
            return;
        }

        memcpy(&new_connections[interface->connections_count], connection, sizeof(NETWORK_CONNECTION_T));
        interface->connections = new_connections;
        interface->connections_count++;
    }
}

// Define a function to handle memory deallocation
void network_interface_manager_free(NETWORK_INTERFACE_T* interface) {
    if (interface != NULL) {
        for (size_t i = 0; i < interface->connections_count; i++) {
            free(&((NETWORK_CONNECTION_T*)interface->connections)[i].transport_layer_payload);
        }

        free(interface->mtu_buffer);
        free(interface->connections);
    }
}

// Define a function to handle logging
void network_interface_manager_log(const char* message, int verbosity_level) {
    if (verbosity_level > 0) {
        printf("Network interface manager: %s\n", message);
    }
}
