```c++
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

class Node {
public:
    std::string data;
    Node* next;
    Node* prev;
};

// Function to insert a second string after the first occurrence of the first string argument in a dynamic list of strings
void insertString(Node*& head, const std::string& target, const std::string& new_string) {
    if (head == nullptr)
        return;

    Node* current = head;
    while (current != nullptr) {
        if (current->data == target) {
            Node* newNode = new Node();
            newNode->data = new_string;
            newNode->next = current->next;
            if (newNode->next != nullptr)
                newNode->next->prev = newNode;
            newNode->prev = current;
            current->next = newNode;
            return;
        }
        current = current->next;
    }
}

int main() {
    Node* head = nullptr;

    // Insert nodes into the list
    for (const auto& str : {"apple", "banana", "orange", "grape"}) {
        Node* newNode = new Node();
        newNode->data = str;
        if (head == nullptr) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != nullptr)
                current = current->next;
            current->next = newNode;
            newNode->prev = current;
        }
    }

    // Insert a new string after the first occurrence of "banana"
    insertString(head, "banana", "mango");

    return 0;
}
