# Function to read and process multiple log files concurrently
def process_logs(log_files):
    log_counts = defaultdict(int)
    pattern = r'pattern_to_match'
    for file in log_files:
        with open(file, 'r') as f:
            content = f.read()
            matches = re.findall(pattern, content)
            log_counts[file] = len(matches)

    return log_counts

if __name__ == '__main__':
    logs_dir = '/path/to/logs/'
    log_files = [os.path.join(logs_dir, file) for file in os.listdir(logs_dir)]
    processed_logs = process_logs(log_files)
    print(processed_logs)
