#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int rrc_id;
    int buffer_size;
    char* mac_pdu;
} RRC_CONTEXT_T;

typedef struct {
    int count;
    RRC_CONTEXT_T** contexts;
} UE_CTX_LIST_T;

UE_CTX_LIST_T ue_ctx_list = {0, NULL};

void ue_ctx_init(int buffer_size) {
    if (buffer_size <= 0) {
        fprintf(stderr, "Error: Buffer size must be positive.\n");
        return;
    }

    RRC_CONTEXT_T* context = malloc(sizeof(RRC_CONTEXT_T));
    if (!context) {
        fprintf(stderr, "Error: Failed to allocate memory for UE context.\n");
        return;
    }

    context->rrc_id = 0; // Initialize with default value
    context->buffer_size = buffer_size;
    context->mac_pdu = malloc(context->buffer_size);
    if (!context->mac_pdu) {
        free(context);
        fprintf(stderr, "Error: Failed to allocate memory for MAC PDU.\n");
        return;
    }

    ue_ctx_list.count++;
    ue_ctx_list.contexts = realloc(ue_ctx_list.contexts, sizeof(RRC_CONTEXT_T*) * ue_ctx_list.count);
    if (!ue_ctx_list.contexts) {
        free(context->mac_pdu);
        free(context);
        fprintf(stderr, "Error: Failed to allocate memory for UE context list.\n");
        return;
    }

    ue_ctx_list.contexts[ue_ctx_list.count - 1] = context;
}

void ue_ctx_update(int rrc_id, int buffer_size) {
    if (buffer_size <= 0) {
        fprintf(stderr, "Error: Buffer size must be positive.\n");
        return;
    }

    for (int i = 0; i < ue_ctx_list.count; i++) {
        if (ue_ctx_list.contexts[i]->rrc_id == rrc_id) {
            free(ue_ctx_list.contexts[i]->mac_pdu);
            ue_ctx_list.contexts[i]->buffer_size = buffer_size;
            ue_ctx_list.contexts[i]->mac_pdu = malloc(buffer_size);
            if (!ue_ctx_list.contexts[i]->mac_pdu) {
                fprintf(stderr, "Error: Failed to allocate memory for MAC PDU.\n");
                return;
            }
            break;
        }
    }
}

void ue_ctx_release(int rrc_id) {
    for (int i = 0; i < ue_ctx_list.count; i++) {
        if (ue_ctx_list.contexts[i]->rrc_id == rrc_id) {
            free(ue_ctx_list.contexts[i]->mac_pdu);
            free(ue_ctx_list.contexts[i]);
            memmove(&ue_ctx_list.contexts[i], &ue_ctx_list.contexts[i + 1], sizeof(RRC_CONTEXT_T*) * (ue_ctx_list.count - i - 1));
            ue_ctx_list.count--;
            break;
        }
    }

    if (ue_ctx_list.count == 0) {
        free(ue_ctx_list.contexts);
        ue_ctx_list.contexts = NULL;
        ue_ctx_list.count = 0;
    }
}

int main() {
    // Example usage:
    ue_ctx_init(1024); // Initialize UE context with buffer size 1024
    ue_ctx_update(1, 2048); // Update buffer size for UE context with RRC ID 1 to 2048
    ue_ctx_release(1); // Release resources for UE context with RRC ID 1

    return 0;
}
