```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Thread-safe linked list structure
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

void* alloc_node(void) {
    return malloc(sizeof(Node));
}

void free_node(void* node) {
    free(node);
}

void init_linked_list(LinkedList* ll) {
    ll->head = NULL;
    pthread_mutex_init(&ll->mutex, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*) alloc_node();
    node->data = data;
    node->next = NULL;
    return node;
}

void add_to_linked_list(LinkedList* ll, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!ll->head) {
        ll->head = new_node;
    } else {
        Node* current = ll->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void update_crcflag(LinkedList* ll, int idx, uint8_t crcflag) {
    if (idx < 0 || idx >= ll->head->data.CRCFLAG) {
        // Handle out-of-bounds error
        return;
    }
    Node* current = ll->head;
    for (int i = 0; i <= idx; i++) {
        if (!current->next) {
            break;
        }
        current = current->next;
    }
    current->data.CRCFLAG = crcflag;
}

void iterate_linked_list(LinkedList* ll, void (*callback)(Node*, void*)) {
    Node* current = ll->head;
    while (current) {
        callback(current, NULL);
        current = current->next;
    }
}

int main() {
    LinkedList ll;
    init_linked_list(&ll);

    // Add some nodes to the linked list
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Initialize data here...
        add_to_linked_list(&ll, data);
    }

    // Update CRCFLAG based on conditions
    int idx = 3;
    uint8_t crcflag = 1;
    update_crcflag(&ll, idx, crcflag);

    // Iterate over the linked list and perform some operation
    void (*callback)(Node*, void*) = (void (*)(Node*, void*)) my_callback_func;
    iterate_linked_list(&ll, callback);

    return 0;
}

// Example callback function to demonstrate iteration
void my_callback_func(Node* node, void* arg) {
    printf("Node CRCFLAG: %x\n", node->data.CRCFLAG);
}
