#include <time.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

void validateTagAndRnti(NFAPI_CRC_INDICATION_PDU_T *pdu, FILE *logFile) {
    if (pdu->RX_UE_INFORMATION_TAG > 255 || pdu->RX_UE_INFORMATION_TAG < 0) {
        fprintf(logFile, "Invalid RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
    }
    if (pdu->RNTI > 65535 || pdu->RNTI < 0) {
        fprintf(logFile, "Invalid RNTI: %d\n", pdu->RNTI);
    }
}

void freePDUArray(NFAPI_CRC_INDICATION_PDU_T **pdus, int N) {
    for (int i = 0; i < N; i++) {
        if (pdus[i] != NULL) {
            free(pdus[i]);
        }
    }
    free(pdus);
}

NFAPI_CRC_INDICATION_PDU_T **allocatePDUArray(int N) {
    NFAPI_CRC_INDICATION_PDU_T **pdus = NULL;

    pdus = malloc(N * sizeof(*pdus));
    if (pdus == NULL) {
        return NULL;  // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdus[i] == NULL) {
            // Handle memory allocation failure
            freePDUArray(pdus, i);
            return NULL;
        }

        // Randomly set CRCFLAG for each structure
        pdus[i]->RX_UE_INFORMATION_TAG = rand() % 256;
        pdus[i]->RNTI = rand() % 65536;
    }

    return pdus;
}

int main(int argc, char *argv[]) {
    int N;
    FILE *logFile = fopen("log.txt", "w");
    srand(time(NULL));  // Seed random number generator

    printf("Enter the number of structures: ");
    scanf("%d", &N);

    NFAPI_CRC_INDICATION_PDU_T **pdus = allocatePDUArray(N);
    if (pdus == NULL) {
        fclose(logFile);  // Close log file
        return 1;  // Error occurred during allocation
    }

    for (int i = 0; i < N; i++) {
        validateTagAndRnti(pdus[i], logFile);
    }

    freePDUArray(pdus, N);
    fclose(logFile);  // Close log file

    return 0;
}
