#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // MAC_RLC_AMP entity
} MAC_CONTEXT;

typedef struct {
    // channel specific data
} MAC_TRANSPORT_CHANNEL;

struct mac_context_list {
    MAC_CONTEXT* ctx;
    int size;
    int capacity;
    pthread_mutex_t lock;
};

MAC_CONTEXT_LIST* mac_context_list_init(int initial_capacity) {
    MAC_CONTEXT_LIST* list = malloc(sizeof(MAC_CONTEXT_LIST));
    list->ctx = calloc(initial_capacity, sizeof(MAC_CONTEXT));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void mac_context_list_add(MAC_CONTEXT_LIST* list, MAC_TRANSPORT_CHANNEL* channel) {
    if (list->size >= list->capacity) {
        // resize the array
        list->ctx = realloc(list->ctx, (list->capacity * 2 + 1) * sizeof(MAC_CONTEXT));
        list->capacity *= 2;
    }
    list->ctx[list->size].channel = channel;
    list->size++;
}

void mac_context_list_update(MAC_CONTEXT_LIST* list, int index, MAC_TRANSPORT_CHANNEL* new_channel) {
    pthread_mutex_lock(&list->lock);
    if (index < list->size) {
        list->ctx[index].channel = new_channel;
    }
    pthread_mutex_unlock(&list->lock);
}

void mac_context_list_free(MAC_CONTEXT_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->ctx[i].channel);
    }
    free(list->ctx);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
