SessionContext* sessionContextCreate() {
    SessionContext* ctx = (SessionContext*)malloc(sizeof(SessionContext));
    ctx->rrc = NULL;
    ctx->size = 0;
    ctx->channels = NULL;
    pthread_mutex_init(&ctx->lock, NULL);
    return ctx;
}

void sessionContextAddTransportChannel(SessionContext* ctx, TransportChannelStructure* channel) {
    pthread_mutex_lock(&ctx->lock);
    ctx->channels = (TransportChannelStructure**)realloc(ctx->channels, (ctx->size + 1) * sizeof(TransportChannelStructure*));
    ctx->channels[ctx->size] = channel;
    ctx->size++;
    pthread_mutex_unlock(&ctx->lock);
}

void sessionContextUpdateTransportChannel(SessionContext* ctx, int index, TransportChannelStructure* newChannel) {
    pthread_mutex_lock(&ctx->lock);
    if (index < ctx->size) {
        ctx->channels[index] = newChannel;
    }
    pthread_mutex_unlock(&ctx->lock);
}

void sessionContextRemoveTransportChannel(SessionContext* ctx, int index) {
    pthread_mutex_lock(&ctx->lock);
    for (int i = index; i < ctx->size - 1; i++) {
        ctx->channels[i] = ctx->channels[i + 1];
    }
    free(ctx->channels[ctx->size - 1]);
    ctx->size--;
    pthread_mutex_unlock(&ctx->lock);
}

