// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    enum { CRCFLAG_SET, CRCFLAG_NOT_SET } CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a structure with valid values
void initStructure(NFAPI_CRC_INDICATION_PDU_T* pStruct) {
    srand(time(NULL));
    pStruct->RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Ensure value falls within valid range
    pStruct->RNTI = rand() % 100 + 1; // Ensure value falls within valid range
    pStruct->CRCFLAG = (rand() % 2 == 0) ? CRCFLAG_SET : CRCFLAG_NOT_SET;
}

// Function to validate a structure's values
void validateStructure(NFAPI_CRC_INDICATION_PDU_T* pStruct, char* logMessage) {
    if (!(pStruct->RX_UE_INFORMATION_TAG >= 1 && pStruct->RX_UE_INFORMATION_TAG <= 1000)) {
        printf("%s: RX_UE_INFORMATION_TAG out of range.\n", logMessage);
    }
    if (!(pStruct->RNTI >= 1 && pStruct->RNTI <= 100)) {
        printf("%s: RNTI out of range.\n", logMessage);
    }
}

// Function to dynamically allocate memory for the array
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure
        printf("Failed to allocate memory.\n");
        return NULL;
    }
    return ptr;
}

// Function to release allocated memory
void releaseMemory(void* ptr) {
    free(ptr);
}

// Thread-safe wrapper for the main function
void* threadSafeAllocateAndPopulate(void* args) {
    int N = *(int*)args;
    NFAPI_CRC_INDICATION_PDU_T** pArray = (NFAPI_CRC_INDICATION_PDU_T**)allocateMemory(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (pArray == NULL) {
        // Handle allocation failure
        printf("Failed to allocate memory.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pArray[i] = (NFAPI_CRC_INDICATION_PDU_T*)allocateMemory(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (pArray[i] == NULL) {
            // Handle allocation failure
            printf("Failed to allocate memory.\n");
            for (int j = 0; j < i; j++) {
                releaseMemory(pArray[j]);
            }
            releaseMemory(pArray);
            return NULL;
        }

        initStructure((NFAPI_CRC_INDICATION_PDU_T*)pArray[i]);
        validateStructure((NFAPI_CRC_INDICATION_PDU_T*)pArray[i], "Thread");
    }

    // Perform further processing here

    for (int i = 0; i < N; i++) {
        releaseMemory(pArray[i]);
    }

    releaseMemory(pArray);

    return NULL;
}

// External logging system
void logEvent(const char* message) {
    // Implement asynchronous logging mechanism here
    printf("%s\n", message);
}

int main() {
    int N = 0; // User input

    pthread_t thread;
    pthread_create(&thread, NULL, threadSafeAllocateAndPopulate, &N);

    pthread_join(thread, NULL);

    return 0;
}
