#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateNfadbCRCIndications(int numIndications, int* rntiValues, int transactionSize, int retryCount) {
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numIndications; i++) {
        indications[i].RNTI = rntiValues[i];
        indications[i].CRCFLAG = rand() % 256;
    }

    // Send data to database server
    int batchSize = transactionSize;
    int numTransactions = (numIndications + batchSize - 1) / batchSize;
    for (int i = 0; i < numTransactions; i++) {
        int start = i * batchSize;
        int end = (i == numTransactions - 1) ? numIndications : (i + 1) * batchSize;

        // Validate CRC indications
        bool isValid = true;
        for (int j = start; j < end; j++) {
            if (indications[j].CRCFLAG > 128) {
                printf("Invalid CRC flag: %d\n", indications[j].CRCFLAG);
                isValid = false;
                break;
            }
        }

        // Send batch to database server
        if (!isValid) {
            printf("Batch failed validation, skipping...\n");
        } else {
            printf("Sending batch... (%d - %d)\n", start, end - 1);

            // Simulate sending data to database server
            time_t startTime = time(NULL);
            for (int j = start; j < end; j++) {
                // Send indication to database server
                printf("Indication: RNTI=%d, CRCFLAG=%d\n", indications[j].RNTI, indications[j].CRCFLAG);

                // Simulate potential network failure
                if (rand() % 100 > 50) {
                    printf("Network failure, retrying...\n");

                    int retries = 0;
                    while (retries < retryCount && rand() % 100 > 50) {
                        printf("Retrying... (%d)\n", retries);
                        // Simulate retry
                        time_t startTime = time(NULL);
                        for (int k = start; k < end; k++) {
                            // Send indication to database server
                            printf("Indication: RNTI=%d, CRCFLAG=%d\n", indications[k].RNTI, indications[k].CRCFLAG);
                        }
                        retries++;
                    }

                    if (retries >= retryCount) {
                        printf("Failed after %d retries.\n", retries);
                    } else {
                        printf("Success after %d retries.\n", retries);
                    }
                }
            }

            // Log metrics
            time_t endTime = time(NULL);
            double processingTime = difftime(endTime, startTime);
            int successRate = (end - start) / batchSize * 100;
            printf("Batch processed in %.2f seconds, %d%% successful.\n", processingTime, successRate);
        }
    }

    free(indications);
}

int main() {
    int numIndications = 10;
    int* rntiValues = (int*)malloc(numIndications * sizeof(int));
    for (int i = 0; i < numIndications; i++) {
        rntiValues[i] = i;
    }

    generateNfadbCRCIndications(numIndications, rntiValues, 5, 3);

    free(rntiValues);
    return 0;
}
