#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct SessionContext {
    RRCConnectionEntity* rrc_connection;
    LinkedList* transport_channels;
} SessionContext;

int initializeSessionContext(struct SessionContext* session, char* password, Connection* connection, callbackFunction callback) {
    if (password == NULL || *password == '\0' ||
        connection->title == NULL || 
        callback == NULL) {
        return -1; // invalid input
    }

    pthread_mutex_init(&session->mutex, NULL); // init mutex

    session->rrc_connection = malloc(sizeof(RRCConnectionEntity));
    if (session->rrc_connection == NULL) {
        free(session);
        return -2; // memory allocation failed
    }

    session->transport_channels = LinkedList_create();
    if (session->transport_channels == NULL) {
        free(session->rrc_connection);
        free(session);
        return -3; // linked list creation failed
    }

    return 0; // success
}

void addTransportChannel(SessionContext* session, TransportChannelStructure* channel) {
    pthread_mutex_lock(&session->mutex); // lock for thread safety

    LinkedList_addTail(session->transport_channels, channel);

    pthread_mutex_unlock(&session->mutex); // unlock
}

void updateTransportChannel(SessionContext* session, int index, TransportChannelStructure* new_channel) {
    pthread_mutex_lock(&session->mutex); // lock for thread safety

    if (index >= 0 && index < LinkedList_size(session->transport_channels)) {
        LinkedList_setItemAt(session->transport_channels, index, new_channel);
    }

    pthread_mutex_unlock(&session->mutex); // unlock
}

void cleanUpSessionContext(SessionContext* session) {
    pthread_mutex_lock(&session->mutex); // lock for thread safety

    free(session->rrc_connection);
    LinkedList_free(session->transport_channels);

    free(session);

    pthread_mutex_unlock(&session->mutex); // unlock
}
