std::vector<std::string> insertAfter(const std::vector<std::string>& list, const std::string& target, const std::string& newString) {
    std::vector<std::string> result = list;
    auto it = std::find(result.begin(), result.end(), target);
    if (it != result.end()) {
        result.insert(it + 1, newString);
    } else {
        result.push_back(newString);
    }
    return result;
}
