import os
import concurrent.futures
import logging

class Logger:
    def __init__(self):
        self.log_file = "log.txt"
        self.logger = logging.getLogger("logger")
        self.logger.setLevel(logging.INFO)
        formatter = logging.Formatter("%(asctime)s - %(name)s - %(levelname)s - %(message)s")
        file_handler = logging.FileHandler(self.log_file, mode="w")
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def log_info(self, message):
        self.logger.info(message)

logger = Logger()

def process_log_files(log_files):
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = []
        for log_file in log_files:
            future = executor.submit(process_log_file, log_file)
            futures.append(future)
        results = [future.result() for future in futures]
        return results

def process_log_file(log_file):
    try:
        with open(log_file, "r") as file:
            log_entries = [line.strip() for line in file.readlines()]
            # Process log entries
            logger.log_info(f"Processed {log_file}")
            return log_entries
    except Exception as e:
        logger.log_error(f"Error processing {log_file}: {str(e)}")
        return []

def aggregate_metrics(metrics):
    aggregated_metrics = {}
    for metric in metrics:
        for key, value in metric.items():
            if key not in aggregated_metrics:
                aggregated_metrics[key] = 0
            aggregated_metrics[key] += value
    return aggregated_metrics

metrics = process_log_files(["log1.txt", "log2.txt"])
aggregated_metrics = aggregate_metrics(metrics)
print(aggregated_metrics)
