#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_THREADS 10
#define MAX_TASKS 100

typedef struct {
    void* (*task)(void*);
} task_t;

typedef struct {
    int id;
    void* data;
} task_data_t;

task_data_t tasks[MAX_TASKS];
int num_tasks = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* thread_func(void* arg) {
    task_data_t* task_data = (task_data_t*)arg;
    // Process task
    printf("Thread %d processing task %d\n", task_data->id, task_data->id);
    return NULL;
}

int create_thread_pool(int max_threads) {
    pthread_t threads[MAX_THREADS];
    int num_threads = 0;
    for (int i = 0; i < MAX_THREADS && i < max_threads; i++) {
        if (pthread_create(&threads[i], NULL, thread_func, &tasks[num_tasks++]) != 0) {
            printf("Error creating thread %d\n", i);
            return -1;
        }
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}

void submit_task(int task_id, void* data) {
    task_data_t* task_data = &tasks[task_id];
    task_data->id = task_id;
    task_data->data = data;
    pthread_mutex_lock(&mutex);
    num_tasks++;
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize thread pool with 5 threads
    create_thread_pool(5);

    // Submit tasks
    for (int i = 0; i < MAX_TASKS; i++) {
        submit_task(i, "Task data");
    }

    return 0;
}
