Bundle* load_bundle(const char* path) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        return NULL; // File not found
    }

    int size = 0;
    char line[MAX_BUNDLE_SIZE];
    while (fgets(line, sizeof(line), file)) {
        size++;
    }
    rewind(file);

    Bundle* bundle = malloc(sizeof(Bundle));
    bundle->size = size;
    bundle->items = malloc(size * sizeof(BundleItem));

    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        char* key = strtok(line, ",");
        char* value = strtok(NULL, "\n");
        BundleItem* item = malloc(sizeof(BundleItem));
        item->key = strdup(key);
        item->value = strdup(value);
        bundle->items[i] = item;
        i++;
    }
    fclose(file);

    return bundle;
}

