#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

void process_filename(char *filename) {
    int digit_count = 0;
    char *token = strtok(filename, "."); // Separate filename and extension
    while (token && *token) { // Check if token is not NULL and has characters
        for (int i = 0; *token; ++i, ++token) {
            if (isdigit(*token)) {
                digit_count++;
                break;
            }
        }
        token = strtok(NULL, "."); // Get the next token or null if none
    }

    char new_filename[256]; // Ensure filename does not exceed 255 characters
    int len = strlen(token);
    if (len > 200) { // Handle edge cases where filenames are too long
        printf("Error: Filename %s exceeds maximum length.\n", filename);
        return;
    }
    strcpy(new_filename, token);

    char *dot_pos = strrchr(new_filename, '.'); // Find the file extension
    if (dot_pos && digit_count) { // Replace extension with "txt" if there are digits
        memmove(dot_pos, ".txt", 5);
    }

    printf("Processed filename: %s\n", new_filename);
}

void parse_args(int argc, char **argv) {
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--help")) { // Print usage information
            printf("Usage: %s [-c] [-o output_file] [input_file]\n", argv[0]);
            return;
        } else if (!strcmp(argv[i], "-c")) {
            process_filename(argv[++i]); // Process filename command-line argument
        } else if (strncmp(argv[i], "-o ", 3)) { // Handle -o option for output file
            printf("Output file: %s\n", argv[i]);
        }
    }

    if (argc < 2) { // Print usage information if no input file is provided
        parse_args(0, NULL);
        exit(1);
    }

    FILE *input_file = fopen(argv[1], "r"); // Open the input file
    if (!input_file) {
        printf("Error: Unable to open input file %s.\n", argv[1]);
        return;
    }
    int line_count = 0;
    char buffer[1024]; // Read and process input file line by line
    while (fgets(buffer, sizeof(buffer), input_file)) {
        line_count++;
    }
    fclose(input_file);

    printf("Number of lines: %d\n", line_count);
}

int main(int argc, char **argv) {
    parse_args(argc, argv);
    return 0;
}
