#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_LINE 1024

typedef struct {
    int count;
    int line_number;
} options;

void print_usage();
void process_file(const char *file, const options *ops);
void process_directory(const char *dir, const options *ops);

int main(int argc, char **argv) {
    options ops = {0};
    int optind = 1; // Start from the first non-option argument

    while (optind < argc) {
        if (!strcmp(argv[optind], "-c")) {
            ops.count = atoi(argv[++optind]);
        } else if (!strcmp(argv[optind], "-s")) {
            ops.line_number = 0;
        } else if (!strcmp(argv[optind], "-o")) {
            ops.output_file = argv[++optind];
        } else if (!strcmp(argv[optind], "--manpage")) {
            print_usage();
            return 0;
        }
        optind++;
    }

    if (argc < 2) {
        print_usage();
        return 1;
    }

    if (strlen(argv[1]) == 4 && !strcmp(argv[1] + 1, ".txt")) { // Check for directory path
        process_directory(argv[1], &ops);
    } else {
        process_file(argv[1], &ops);
    }

    return 0;
}

void print_usage() {
    printf("Usage: program [options] <input_file>\n");
    printf("Options:\n");
    printf("-c <count>   Process only the first <count> lines\n");
    printf("-s           Suppress line numbers\n");
    printf("-o <file>    Redirect output to specified file\n");
    printf("--manpage     Display detailed usage information and exit\n");
}

void process_file(const char *file, const options *ops) {
    FILE *f = fopen(file, "r");
    if (f == NULL) {
        perror("Error opening the file");
        return;
    }

    char line[MAX_LINE];
    clock_t start_time = clock();
    int lines_processed = 0;

    while (fgets(line, sizeof(line), f)) {
        if (!ops->line_number++) {
            // Process only the first <count> lines
            if (++lines_processed > ops->count) {
                break;
            }
        }

        printf("%s", line);
    }

    fclose(f);

    clock_t end_time = clock();
    double processing_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("\nProcessed %d lines in %.2f seconds\n", ops->count, processing_time);
}

void process_directory(const char *dir, const options *ops) {
    DIR *dp = opendir(dir);
    if (dp == NULL) {
        perror("Error opening the directory");
        return;
    }

    struct dirent *ent;
    int files_processed = 0;

    clock_t start_time = clock();

    while ((ent = readdir(dp)) != NULL) {
        char file_path[PATH_MAX];
        sprintf(file_path, "%s/%s", dir, ent->d_name);

        if (stat(file_path, &st) == -1 || !S_ISREG(st.st_mode)) {
            // Skip non-regular files
            continue;
        }

        FILE *f = fopen(file_path, "r");
        if (f == NULL) {
            perror("Error opening the file");
            continue;
        }

        char line[MAX_LINE];
        int lines_processed = 0;

        while (fgets(line, sizeof(line), f)) {
            // Process each file separately
            printf("%s", line);
        }

        fclose(f);

        files_processed++;
    }

    closedir(dp);

    clock_t end_time = clock();
    double processing_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("\nProcessed %d files in %.2f seconds\n", files_processed, processing_time);
}
