#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_BUNDLE_SIZE 1024
#define MAX_NUMBER_OF_BUNDLES 100

typedef struct {
    int rnti;
    char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char* filepath;
    int count;
} RESOURCE_BUNDLE_T;

RESOURCE_BUNDLE_T bundles[MAX_NUMBER_OF_BUNDLES];
int bundle_count = 0;

int load_resource_bundle(const char* filepath) {
    FILE* file = fopen(filepath, "r");
    if (file == NULL) {
        return -1; // Error: File not found or corrupted
    }

    int line_count = 0;
    while (fgets(line, MAX_BUNDLE_SIZE, file)) {
        line[strcspn(line, "\n")] = 0; // Remove newline character

        // Parse key-value pair
        char* token = strtok(line, ",");
        if (token == NULL) {
            return -2; // Error: Corrupted bundle file
        }

        int rnti = atoi(token);
        char crcflag = line[3]; // Assuming CRC flag is the 4th character

        // Allocate memory for new bundle item
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            return -3; // Error: Out of memory
        }

        pdu->rnti = rnti;
        pdu->crcflag = crcflag;

        // Add bundle item to current bundle
        bundles[bundle_count].count++;
        bundles[bundle_count].filepath = filepath;

        free(pdu); // Free allocated memory

        line_count++;
    }

    fclose(file);
    return line_count; // Return the number of items in the bundle
}

void populateNfapiPduList(int N) {
    int rnti_values[100]; // Assume RNTI values are stored in an external configuration file
    FILE* config_file = fopen("rnti_config.txt", "r");
    if (config_file == NULL) {
        perror("Error reading RNTI configuration file");
        return;
    }

    int rnti_index = 0;
    while (!feof(config_file)) {
        fscanf(config_file, "%d\n", &rnti_values[rnti_index]);
        rnti_index++;

        if (rnti_index >= N) {
            break;
