// Struct to represent word frequencies
typedef struct {
    int count;
    char *word;
} WordFrequency;

// Function to scan directory recursively and process files
void process_directory(char *directory, FILE *output_file, int verbose) {
    DIR *dp = opendir(directory);
    if (dp == NULL) {
        // Handle error opening directory
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip current and parent directories
        }

        char filepath[256];
        sprintf(filepath, "%s/%s", directory, entry->d_name);

        struct stat sb;
        if (stat(filepath, &sb) != 0) {
            // Handle error checking file status
            perror("Failed to check file status");
            continue;
        }

        if (S_ISDIR(sb.st_mode)) {
            process_directory(filepath, output_file, verbose);
        } else if (strcmp(entry->d_name, ".txt") == 0) {
            FILE *file = fopen(filepath, "r");
            if (file == NULL) {
                // Handle error opening file
                perror("Failed to open file");
                continue;
            }

            int line_count = 0;
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), file)) {
                line_count++;
            }
            fclose(file);

            FILE *stats_file = fopen("word_stats.txt", "w");
            if (stats_file == NULL) {
                // Handle error opening stats file
                perror("Failed to open stats file");
                return;
            }

            int word_count = 0;
            WordFrequency *word_freqs = malloc(sizeof(WordFrequency));
            while (fgets(buffer, sizeof(buffer), file)) {
                char *token = strtok(buffer, " ");
                while (token != NULL) {
                    token = strtok(NULL, " ");

                    bool found = false;
                    for (int i = 0; i < word_freqs->count; i++) {
                        if (strcmp(word_freqs[i].word, token) == 0) {
                            word_freqs[i].count++;
                            found = true;
                            break;
                        }
                    }

                    if (!found) {
                        word_freqs[word_freqs->count].count = 1;
                        word_freqs[word_freqs->count].word = strdup(token);
                        word_freqs->count++;
                    }
                    word_count++;

                }
            }
            fclose(file);

            fprintf(stats_file, "Total words: %d\n", word_count);
            fprintf(stats_file, "Unique words: %d\n", word_freqs->count);
            fprintf(stats_file, "Average word length per file: %.2f\n", (double)word_count / line_count);

            for (int i = 0; i < word_freqs->count; i++) {
                fprintf(stats_file, "%s: %d\n", word_freqs[i].word, word_freqs[i].count);
                free(word_freqs[i].word);
            }
            free(word_freqs);

            fclose(stats_file);
        }
    }

    closedir(dp);
}

int main(int argc, char **argv) {
    int verbose = 0;
    char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            // Display usage information
            printf("Usage: %s [-v|--verbose] [-o|--output-file FILE] [-c|--count-only] [-s|--stats] DIRECTORY\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output-file") == 0) {
            output_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count-only") == 0) {
            // Only count files, lines, and words without generating word frequency summaries
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--stats") == 0) {
            // Provide detailed statistics on total words, unique words, and average word length per file
        }
    }

    process_directory(argv[argc - 1], output_file ? fopen(output_file, "w") : NULL, verbose);

    return 0;
}
