        // Accept new connections and process requests...
        listen_fd = accept(listen_fd, (struct sockaddr *)&client_addr, &client_len);
        if (listen_fd < 0) {
            perror("Error accepting connection");
            continue;
        }
        client_fd = fork();
        if (client_fd < 0) {
            perror("Error forking process");
            close(listen_fd);
            continue;
        }

        // Handle the accepted request...
        if (client_fd == 0) { // Child process
            process_http_request(listen_fd);
            close(listen_fd); // Close the client socket
            exit(0);
        } else { // Parent process
            close(client_fd); // Close the child process
        }
    }

    return 0;
}

