void load_bundle(const char *path) {
    // Load the bundle and its items
    FILE *file = fopen(path, "r");
    if (!file) {
        // Handle file not found or corrupted error
        return;
    }

    Bundle *bundle = (Bundle *)malloc(sizeof(Bundle));
    bundle->name = strdup(path);
    bundle->items_count = 0;
    bundle->items = NULL;

