    fclose(file);

    // Add the bundle to the global collection
    pthread_mutex_lock(&mutex);
    BundleList *list = &bundles;
    list->count++;
    if (list->count > MAX_BUNDLES) {
        // Discard the least recently used bundle to make space for the new one
        free(list->bundles[list->count - 2]->name);
        free(list->bundles[list->count - 2]->items);
        free(list->bundles[--list->count]);
    }
    bundle->next = list->bundles;
    list->bundles = bundle;
    pthread_mutex_unlock(&mutex);

    // Log the load success
    if (log_file) {
        fprintf(log_file, "Bundle '%s' loaded successfully.\n", path);
