    for (int i = 0; i < bundles.count; i++) {
        Bundle *bundle = bundles.bundles[i];
        if (!matches(pattern, bundle->name)) {
            // Remove the bundle from the collection
            free(bundle->name);
            free(bundle->items);
            free(bundle);
            bundles.bundles[i] = bundles.bundles[--bundles.count];
            i--;
        }
    }
    pthread_mutex_unlock(&mutex);

    return;
}

void track_dependencies(const char *bundle_name) {
