function extractBibleBookNames(text, filterLessCommon = true, languages = ['en', 'es']) {
  const bibleApiUrl = 'https://api.bible.org/books';
  const cache = {};

  function getBooks(language) {
    if (!cache[language]) {
      try {
        const response = await fetch(`${bibleApiUrl}/${language}`);
        const books = await response.json();
        cache[language] = books;
      } catch (error) {
        console.error('Error fetching Bible books:', error);
      }
    }
    return cache[language];
  }

  function processText(text, language) {
    const books = getBooks(language).filter(book => book.type === 'OT');
    const bookNames = {};

    for (const book of books) {
      if (!text.toLowerCase().includes(` ${book.name} `)) continue;

      const wordCount = (text.match(new RegExp(` ${book.name} `, 'g')) || []).length;
      if (!bookNames[book.name]) bookNames[book.name] = 0;
      bookNames[book.name] += wordCount;
    }

    return bookNames;
  }

  async function extractBookNames(texts, filterLessCommon) {
    const languageDetector = await import('detec-tor');
    const detectedLanguages = texts.map(languageDetector.detect);

    const results = [];
    for (const text of texts) {
      const language = detectedLanguages.find((lang) => lang.confidence > 0.5);

      if (!language) continue;

      const bookNames = processText(text, language);
      if (filterLessCommon && Object.values(bookNames).every(count => count < 5)) continue;

      results.push({ ...bookNames });
    }

    return results;
  }

  async function extractBookNamesBatch(texts) {
    const promises = texts.map(() => Promise.resolve());
    for (const text of texts) {
      promises[promises.length - 1] = extractBookNames([text]);
    }
    return await Promise.all(promises);
  }

  async function processTextBatch(texts, filterLessCommon, languages) {
    try {
      const results = await extractBookNamesBatch(texts);

      const finalResults = [];
      for (const result of results) {
        for (const bookName in result) {
          let exists = false;
          for (let i = 0; i < finalResults.length; i++) {
            if (Object.keys(finalResults[i]).some(key => key === bookName)) {
              exists = true;
              break;
            }
          }
          if (!exists) finalResults.push({ [bookName]: result[bookName] });
        }
      }

      return finalResults;
    } catch (error) {
      console.error('Error processing texts:', error);
      return [];
    }
  }

  async function main(texts, filterLessCommon = true) {
    try {
      const results = await processTextBatch(texts, filterLessCommon);
      return results;
    } catch (error) {
      console.error('Error processing texts:', error);
      return [];
    }
  }

  module.exports = { extractBibleBookNames: main };
