import re
import requests
from collections import defaultdict
from functools import lru_cache
from datetime import timedelta
from itertools import groupby
from operator import itemgetter

class LogProcessor:
    def __init__(self):
        self.api_url = "https://api.example.com/queries"
        self.cache_file = "local_queries.json"
        self.language_map = {"en": "English", "fr": "French", "de": "German"}
        self.query_cache = {}

    @lru_cache(maxsize=128)
    def fetch_queries(self, lang):
        if lang not in self.query_cache:
            response = requests.get(f"{self.api_url}/{lang}")
            if response.status_code == 200:
                queries = response.json()
                with open(self.cache_file, "w") as f:
                    json.dump({q["id"]: q["name"] for q in queries}, f)
                self.query_cache[lang] = {int(q["id"]): q["name"] for q in queries}
            else:
                raise Exception("Failed to fetch queries")
        return self.query_cache.get(lang, {})

    @lru_cache(maxsize=128)
    def process_log(self, log_file):
        query_count = defaultdict(int)
        error_counts = defaultdict(dict)
        lang = None
        for line in log_file:
            if re.match(r"^(en|fr|de):", line):
                lang = re.match(r"^(en|fr|de):(.*)$", line).group(2).strip()
            elif re.match(r"\[(\d+)\] (.*)\(", line):
                query_id, error_message = re.match(r"\[(\d+)\] (.*)\((.*)\)", line).groups()
                query_id = int(query_id)
                if lang and (query_id in self.fetch_queries(lang) or query_id == 0):
                    query_count[query_id] += 1
                    for keyword in re.findall(r"(\w+)", error_message):
                        if keyword:
                            error_counts[query_id].setdefault(keyword, 0)
                            error_counts[query_id][keyword] += 1
        return {"queries": dict(query_count), "errors": {k: dict(v) for k, v in error_counts.items()}}

    def process_logs(self, log_files):
        result = {}
        for log_file in log_files:
            try:
                log_data = self.process_log(log_file)
                if not all(k in result["queries"] for k in log_data["queries"].keys()):
                    result["queries"] = {k: v + log_data["queries"][k] for k, v in result.get("queries", {}).items()}
                    for query_id, count in log_data["queries"].items():
                        if query_id not in (0,) and query_id < 15:
                            del result["queries"][query_id]
                else:
                    for query_id, count in log_data["queries"].items():
                        if query_id not in result["queries"]:
                            result["queries"][query_id] = count
            except Exception as e:
                print(f"Error processing {log_file}: {str(e)}")
        return result

    def update_cache(self):
        for lang, _ in self.language_map.items():
            try:
                response = requests.get(f"{self.api_url}/{lang}")
                if response.status_code == 200:
                    queries = response.json()
                    with open(self.cache_file, "w") as f:
                        json.dump({q["id"]: q["name"] for q in queries}, f)
                else:
                    raise Exception("Failed to update cache")
            except Exception as e:
                print(f"Error updating cache: {str(e)}")

    def generate_report(self, result):
        query_counts = sorted(result["queries"].items(), key=itemgetter(1), reverse=True)
        error_counts = {}
        for query_id, count in result["queries"].items():
            if query_id not in (0,):
                for keyword, freq in result["errors"][query_id].items():
                    error_counts.setdefault(keyword, 0)
                    error_counts[keyword] += freq
        report = f"Most frequent queries: {', '.join(str(k) + ' (' + str(v) + ')' for k, v in query_counts)}"
        for keyword, freq in sorted(error_counts.items(), key=itemgetter(1), reverse=True):
            report += f"\nError '{keyword}': {freq}"
        return report

    def process(self, log_files):
        try:
            result = self.process_logs(log_files)
            if len(result["queries"]) > 0:
                print(self.generate_report(result))
                self.update_cache()
            else:
                print("No queries found")
        except Exception as e:
            print(f"Error: {str(e)}")

    def main(self):
        log_files = ["log1.log", "log2.log", ...]  # add your log files here
        self.process(log_files)

if __name__ == "__main__":
    LogProcessor().main()
