import re
import logging
import requests
from cryptography.hazmat.primitives.ciphers import CipherContext
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend

def process_logs(log_files, password, filter_less_common_queries=False):
    # Initialize AES-256-CBC cipher with given password
    iv = bytes([0x00] * 16)
    key = derive_key(password, backend=default_backend())
    cipher = CipherContext(CipherContext.ENCRYPT, key, backend=default_backend(), iv=iv)

    # Initialize cache dictionary and query support API client
    cache = {}
    api_client = requests.Session()

    # Process each log file
    for log_file in log_files:
        with open(log_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        # Extract error messages and queries from log entries
        query_map = {}
        error_type_freq = {}
        for line in lines:
            match = re.search(r'(\w+) (\w+)', line.decode('utf-8'))
            if match:
                query, error_message = match.groups()
                if error_message not in error_type_freq:
                    error_type_freq[error_message] = 1
                else:
                    error_type_freq[error_message] += 1

                if query not in query_map:
                    query_map[query] = 0
                query_map[query] += 1

        # Filter out less common queries (if enabled)
        if filter_less_common_queries and any(count < 15 for count in query_map.values()):
            filtered_query_map = {query: count for query, count in query_map.items() if count >= 15}
        else:
            filtered_query_map = query_map

        # Update cache with new supported queries from the API
        for query, _ in filtered_query_map.items():
            if query not in cache:
                response = api_client.get(f'api/queries/{query}')
                if response.status_code == 200:
                    cache[query] = response.json()
                else:
                    # Handle API failure (retry up to three times)
                    for attempt in range(1, 4):
                        try:
                            response = api_client.get(f'api/queries/{query}', timeout=10)
                            if response.status_code == 200:
                                cache[query] = response.json()
                                break
                        except requests.exceptions.RequestException as e:
                            logging.warning(f"Failed to retrieve query {query} (attempt {attempt}/{3}): {e}")

        # Generate a detailed report summarizing the most frequent queries and errors
        report = {
            'most_common_queries': dict(sorted(filtered_query_map.items(), key=lambda item: item[1], reverse=True)),
            'error_type_freq': error_type_freq,
            'query_distribution': {}
        }
        for query, count in filtered_query_map.items():
            if query not in report['query_distribution']:
                report['query_distribution'][query] = 0
            report['query_distribution'][query] += 1

        return cipher, cache, report

def derive_key(password, backend=default_backend()):
    key = hashes.sha1_256(password.encode('utf-8'), backend=backend)
    return CipherContext(key).get_key()
