#define BER_QUALITY_FACTOR_THRESHOLD 1e-6

typedef struct {
    int TX_POWER_LEVEL;
    int RX_SINR;
    double BER_QUALITY_FACTOR;
    time_t timestamp;
} PHY_STATS_RECORD_T;

void* phy_stats_array_init(int N) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int sn_pool[MAX_N];
    int current_sn = 0;

    PHY_STATS_RECORD_T** array = (PHY_STATS_RECORD_T**)malloc(N * sizeof(PHY_STATS_RECORD_T*));
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        array[i] = (PHY_STATS_RECORD_T*)malloc(sizeof(PHY_STATS_RECORD_T));
        array[i]->SN = current_sn++;
        array[i]->PDCP_SN = -1;
        array[i]->STATUS_PDU = 0;
        array[i]->SDU_LENGTH = 100; // Default value
        pthread_mutex_unlock(&mutex);
    }

    return (void*)array;
}

void phy_stats_array_validate(PHY_STATS_RECORD_T** array, int N) {
    for (int i = 0; i < N; i++) {
        if (array[i]->TX_POWER_LEVEL < MIN_TX_POWER || array[i]->TX_POWER_LEVEL > MAX_TX_POWER) {
            // Log error message
            pthread_mutex_lock(&mutex);
            printf("Invalid TX power level at index %d: %d\n", i, array[i]->TX_POWER_LEVEL);
            pthread_mutex_unlock(&mutex);
        }

        if (array[i]->RX_SINR < RX_SINR_THRESHOLD || array[i]->BER_QUALITY_FACTOR > BER_QUALITY_FACTOR_THRESHOLD) {
            // Log error message
            pthread_mutex_lock(&mutex);
            printf("Invalid RX SINR or BER quality factor at index %d: %d, %.9e\n", i, array[i]->RX_SINR, array[i]->BER_QUALITY_FACTOR);
            pthread_mutex_unlock(&mutex);
        }
    }
}

void phy_stats_array_free(PHY_STATS_RECORD_T** array, int N) {
    for (int i = 0; i < N; i++) {
        free(array[i]);
    }
    free(array);
}
