    table->size = 0;
    table->buckets = (item**)malloc(sizeof(item*) * capacity);
}

int hash(hash_table* table, const char* key) {
    return strlen(key) % table->size;
}

void add_item(hash_table* table, item* item) {
    int index = hash(table, item->key);
    item->expiration += time(NULL) + 3600; // expire after TTL seconds
    if (table->buckets[index] == NULL) {
        table->buckets[index] = item;
    } else {
        item** temp = (item**)malloc(sizeof(item*) * (table->size * 2));
        for (int i = 0; i < table->size; i++) {
            temp[i] = table->buckets[i];
        }
        free(table->buckets);
        table->buckets = temp;
    }
}

void sort_items(hash_table* table) {
    item* items[table->size];
    int count = 0;
    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i] != NULL) {
            items[count++] = table->buckets[i];
        }
    }
    qsort(items, count, sizeof(item), item_compare);
    for (int i = 0; i < count; i++) {
        table->buckets[i] = items[i];
    }
}

void free_cache(hash_table* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]->value);
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
}

int item_compare(const void* a, const void* b) {
    item* item1 = *(item*)a;
    item* item2 = *(item*)b;
    return item2->expiration - item1->expiration;
}
