#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CACHE_SIZE 1000
#define LOG_BUFFER_SIZE 1024

typedef struct {
    char* key;
    long expiration_timestamp;
    void* value;
} item;

typedef struct _hash_table {
    int size;
    item** buckets;
    pthread_mutex_t mutex;
} hash_table;

void* allocate(const size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Allocation failure\n");
        exit(1);
    }
    return ptr;
}

int is_power_of_two(int num) {
    return (num && !(num & (num - 1)));
}

void resize(hash_table* table, int new_size) {
    hash_table* temp = allocate(sizeof(hash_table));
    temp->size = new_size;
    temp->buckets = allocate(new_size * sizeof(item*));

    for (int i = 0; i < new_size; i++) {
        temp->buckets[i] = NULL;
    }

    pthread_mutex_init(&temp->mutex, NULL);

    // Migrate items
    for (int i = 0; i < table->size; i++) {
        item* curr_item = table->buckets[i];
        while (curr_item) {
            item* next = curr_item->next;
            int index = curr_item->key % new_size;
            curr_item->next = temp->buckets[index];
            temp->buckets[index] = curr_item;
            curr_item = next;
        }
    }

    // Clear old table
    for (int i = 0; i < table->size; i++) {
        item* curr_item = table->buckets[i];
        while (curr_item) {
            item* next = curr_item->next;
            free(curr_item);
            curr_item = next;
        }
    }

    // Swap tables
    hash_table* temp_ptr = table;
    table = temp;
    temp = temp_ptr;

    // Clean up old table's resources
    free(temp->buckets);
    free(temp);

    pthread_mutex_destroy(&table->mutex);
}

int hash(item* item, int size) {
    return (item->key % size);
}

void cache_insert(hash_table* table, item* new_item) {
    pthread_mutex_lock(&table->mutex);

    // Handle resizing if necessary
    if (table->size * 2 <= MAX_CACHE_SIZE && is_power_of_two(table->size)) {
        resize(table, table->size * 2);
    }

    int index = hash(new_item, table->size);
    new_item->next = table->buckets[index];
    table->buckets[index] = new_item;

    pthread_mutex_unlock(&table->mutex);

    // Log the insertion
    char log_message[LOG_BUFFER_SIZE];
    sprintf(log_message, "Inserted item with key %s and expiration timestamp %ld\n", new_item->key, new_item->expiration_timestamp);
    fprintf(stderr, "%s", log_message);
}

void cache_evict(hash_table* table) {
    pthread_mutex_lock(&table->mutex);

    // Find the least-recently-used (LRU) item
    int min_expiration = LONG_MAX;
    item* lru_item = NULL;

    for (int i = 0; i < table->size; i++) {
        item* curr_item = table->buckets[i];
        while (curr_item) {
            if (curr_item->expiration_timestamp < min_expiration) {
                min_expiration = curr_item->expiration_timestamp;
                lru_item = curr_item;
            }
            curr_item = curr_item->next;
        }
    }

    // Evict the LRU item
    if (lru_item) {
        table->buckets[hash(lru_item, table->size)] = lru_item->next;
        free(lru_item);
    }

    pthread_mutex_unlock(&table->mutex);

    // Log the eviction
    char log_message[LOG_BUFFER_SIZE];
    sprintf(log_message, "Evicted item with key %s and expiration timestamp %ld\n", lru_item ? lru_item->key : "(unknown)", min_expiration);
    fprintf(stderr, "%s", log_message);
}

void cache_free(hash_table* table) {
    pthread_mutex_lock(&table->mutex);

    for (int i = 0; i < table->size; i++) {
        item* curr_item = table->buckets[i];
        while (curr_item) {
            item* next = curr_item->next;
            free(curr_item);
            curr_item = next;
        }
    }

    pthread_mutex_unlock(&table->mutex);

    // Clean up the hash table's resources
    free(table->buckets);
    free(table);
}

int main() {
    hash_table* cache = allocate(sizeof(hash_table));
    cache->size = 16;

    // Initialize items and insert them into the cache
    item* items[] = {
        {"key1", time(NULL) + 60, allocate(10)},
        {"key2", time(NULL) + 30, allocate(20)},
        {"key3", time(NULL) + 120, allocate(30)}
    };

    for (int i = 0; i < sizeof(items) / sizeof(*items); i++) {
        items[i]->expiration_timestamp += 3600; // Set TTL to 1 hour
        cache_insert(cache, items[i]);
    }

    return 0;
}
