typedef struct {
    char* key;
    long expiration_timestamp;
    void* value;
    time_t last_accessed;
} item;

typedef struct {
    int size;
    int capacity;
    item** items;
    pthread_mutex_t lock;
} hash_table;

void init_hash_table(hash_table* table, int capacity) {
    table->size = 0;
    table->capacity = capacity;
    table->items = (item**)malloc(sizeof(item*) * capacity);
    pthread_mutex_init(&table->lock, NULL);
}

int resize_hash_table(hash_table* table, int new_capacity) {
    item** new_items = (item**)realloc(table->items, sizeof(item*) * new_capacity);
    if (!new_items)
        return -1;
    table->capacity = new_capacity;
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_init(&table->lock, NULL);
    return 0;
}

void insert_item(hash_table* table, item* item) {
    int hash_value = item->expiration_timestamp % table->capacity;
    pthread_mutex_lock(&table->lock);
    if (table->items[hash_value]) {
        // Resize the table if it's full
        if (table->size == table->capacity) {
            resize_hash_table(table, table->capacity * 2);
            hash_value = item->expiration_timestamp % table->capacity;
        }
    }
    table->items[hash_value] = item;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

item* find_item(hash_table* table, char* key) {
    int i;
    for (i = 0; i < table->size; i++) {
        if (strcmp(table->items[i]->key, key) == 0)
            return table->items[i];
    }
    return NULL;
}

void sort_items(hash_table* table) {
    item* temp;
    int i, j;
    for (i = 0; i < table->size - 1; i++) {
        for (j = 0; j < table->size - i - 1; j++) {
            if (table->items[j]->expiration_timestamp < table->items[j + 1]->expiration_timestamp) {
                temp = table->items[j];
                table->items[j] = table->items[j + 1];
                table->items[j + 1] = temp;
            }
        }
    }
}

void free_hash_table(hash_table* table) {
    int i;
    for (i = 0; i < table->size; i++) {
        if (table->items[i]->value)
            free(table->items[i]->value);
        free(table->items[i]);
    }
    free(table->items);
    pthread_mutex_destroy(&table->lock);
}

void log_cache_event(hash_table* table, char* event) {
    // Implement logging mechanism
}

