void init_sessions_and_activity_logs() {
    int i, j;

    // Allocate memory for sessions array
    Session** temp_sessions = (Session**)malloc(max_sessions * sizeof(Session));
    if (!temp_sessions) {
        printf("Memory allocation failed for session array.\n");
        return;
    }

    // Initialize sessions array
    for (i = 0; i < max_sessions; i++) {
        temp_sessions[i].id = i;
        temp_sessions[i].start_timestamp = time(NULL);
        temp_sessions[i].end_timestamp = time(NULL);
    }

    // Sort the sessions based on their start timestamps in ascending order
    for (i = 1; i < max_sessions; i++) {
        Session key = temp_sessions[i];
        int j;
        for (j = i - 1; j >= 0 && temp_sessions[j].start_timestamp > key.start_timestamp; j--) {
            temp_sessions[j + 1] = temp_sessions[j];
        }
        temp_sessions[j + 1] = key;
    }

    // Assign sessions array to the global variable
    sessions = temp_sessions;

    // Allocate memory for activity logs array
    ActivityLog** temp_activity_logs = (ActivityLog*)malloc(max_activity_logs * sizeof(ActivityLog));
    if (!temp_activity_logs) {
        printf("Memory allocation failed for activity log array.\n");
        return;
    }

    // Initialize activity logs array
    for (i = 0; i < max_activity_logs; i++) {
        temp_activity_logs[i].session = &sessions[i];
        temp_activity_logs[i].num_events = 0;
        temp_activity_logs[i].events = NULL;
    }

    // Assign activity logs array to the global variable
    activity_logs = temp_activity_logs;
}

void free_sessions_and_activity_logs() {
    int i;

    // Free sessions array
    for (i = 0; i < num_sessions; i++) {
        free(sessions[i].events);
    }
    free(sessions);

    // Free activity logs array
    for (i = 0; i < num_activity_logs; i++) {
        free(activity_logs[i].events);
    }
    free(activity_logs);
}

int main() {
    init_sessions_and_activity_logs();
    free_sessions_and_activity_logs();

    return 0;
}
