#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char identifier[10];
    time_t timestamp;
} record;

typedef struct {
    record* ptr;
    int count;
    double average_timestamp;
} summary;

record** initialize_data_structures(int max_records, int max_summaries) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(sizeof(long) * max_records);
    int* keys = (int*)malloc(sizeof(int) * max_records);
    record* records = (record*)malloc(sizeof(record) * max_records);
    summary* summaries = (summary*)malloc(sizeof(summary) * max_summaries);

    // Initialize arrays
    for (int i = 0; i < max_records; i++) {
        offsets[i] = i;
        keys[i] = rand() % 100 + 1;
        records[i].value = rand() % 100 + 1;
        strcpy(records[i].identifier, "Record");
        time_t now = time(NULL);
        records[i].timestamp = now;

        // Sort records
        for (int j = 0; j < i; j++) {
            if (records[j].value > records[i].value) {
                record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }

    return &records;
}

void add_record(record** records, int* max_records, summary* summaries, int* max_summaries) {
    // Check if the array is full
    if (*max_records >= *max_summaries) {
        printf("Array full. Cannot add more records.\n");
        return;
    }

    // Create a new record
    record* new_record = (record*)malloc(sizeof(record));
    new_record->value = rand() % 100 + 1;
    strcpy(new_record->identifier, "Record");
    time_t now = time(NULL);
    new_record->timestamp = now;

    // Insert the record into the array
    for (int i = 0; i < *max_records; i++) {
        if (records[i]->value > new_record->value) {
            int j;
            for (j = *max_records - 1; j >= i; j--) {
                records[j + 1] = records[j];
            }
            break;
        }
    }

    // Update the summary
    for (int i = 0; i < *max_summaries; i++) {
        if (summaries[i].ptr == NULL || summaries[i].count == 0) {
            summaries[i].ptr = new_record;
            summaries[i].count = 1;
            summaries[i].average_timestamp = (double)new_record->timestamp / 1.0;
            break;
        } else if (abs((int)(summaries[i].ptr->timestamp - new_record->timestamp)) < 10) {
            summaries[i].count++;
            summaries[i].average_timestamp += ((double)new_record->timestamp - (double)summaries[i].ptr->timestamp) / (double)summaries[i].count;
        }
    }

    // Update the maximum number of records and summaries
    (*max_records)++;
}

void remove_record(record** records, int* max_records) {
    if (*max_records > 0) {
        *max_records--;
    }
}

void free_data_structures(record** records, int* max_records, summary* summaries, int* max_summaries) {
    for (int i = 0; i < *max_summaries; i++) {
        free(summaries[i].ptr);
    }

    free(records);
    free(summaries);

    printf("Data structures freed.\n");
}

int main() {
    // Initialize data structures
    record** records;
    int max_records = 10;
    int max_summaries = 5;

    records = initialize_data_structures(max_records, max_summaries);

    // Add records
    for (int i = 0; i < 20; i++) {
        add_record(&records, &max_records, &summaries[max_summaries], &max_summaries);
    }

    // Remove a record
    remove_record(&records, &max_records);

    // Free data structures
    free_data_structures(records, &max_records, summaries, &max_summaries);

    return 0;
}
