#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct item {
    char* key;
    long expiration_timestamp;
    void* value;
    long last_accessed;
} Item;

typedef struct hash_table {
    int size;
    int capacity;
    Item** items;
    pthread_mutex_t mutex;
} HashTable;

void init_hash_table(HashTable* table, int capacity) {
    table->size = 0;
    table->capacity = capacity;
    table->items = (Item**)malloc(sizeof(Item*) * capacity);
    for(int i = 0; i < capacity; i++) {
        table->items[i] = NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
}

void free_hash_table(HashTable* table) {
    for(int i = 0; i < table->capacity; i++) {
        if(table->items[i] != NULL) {
            free(table->items[i]->key);
            free(table->items[i]->value);
            free(table->items[i]);
        }
    }
    free(table->items);
    pthread_mutex_destroy(&table->mutex);
}

int hash_item(const char* key, int capacity) {
    unsigned long hash = 0;
    const char* p = (const char*)key;
    while(*p != '\0') {
        hash = (*p++ ^ (unsigned long)hash) * 1103515245 + 12345;
    }
    return (int)(hash % capacity);
}

void insert_item(HashTable* table, Item* item) {
    int index = hash_item(item->key, table->capacity);
    pthread_mutex_lock(&table->mutex);
    if(table->items[index] == NULL || strcmp(item->key, ((Item*)table->items[index])->key) < 0) {
        table->items[index] = item;
        table->size++;
    }
    else {
        Item* current_item = table->items[index];
        while(current_item != NULL && strcmp(item->key, current_item->key) >= 0) {
            if(current_item->expiration_timestamp <= time(NULL)) {
                pthread_mutex_unlock(&table->mutex);
                free_hash_table(table);
                exit(1);
            }
            Item* temp = current_item;
            current_item = ((Item*)current_item)->next;
            free(temp->key);
            free(temp->value);
            free(temp);
        }
        if(current_item == NULL) {
            table->items[index] = item;
        }
        else {
            item->next = current_item;
            table->items[index] = item;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

void evict_least_recently_used(HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    for(int i = 0; i < table->capacity; i++) {
        if(table->items[i] != NULL) {
            Item* current_item = table->items[i];
            while(current_item != NULL && ((Item*)current_item)->expiration_timestamp <= time(NULL)) {
                Item* temp = current_item;
                current_item = ((Item*)current_item)->next;
                free(temp->key);
                free(temp->value);
                free(temp);
            }
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

void* get_value(void* item) {
    return ((Item*)item)->value;
}

int main() {
    // Initialize the cache
    HashTable table;
    init_hash_table(&table, 1024);

    // Insert items into the cache
    Item* item1 = (Item*)malloc(sizeof(Item));
    item1->key = strdup("item1");
    item1->expiration_timestamp = time(NULL) + 60;
    item1->value = NULL;
    item1->last_accessed = time(NULL);
    insert_item(&table, item1);

    // Evict the least recently used items
    evict_least_recently_used(&table);

    return 0;
}

