#include <time.h>

typedef struct {
    int session_id;
    time_t start_timestamp;
    time_t end_timestamp;
} Session;

typedef struct {
    Session* session;
    char** events;
    int event_count;
} ActivityLog;

void initialize_session_collection(int max_sessions, int max_events_per_session) {
    // Initialize session array
    Session* sessions = (Session*)malloc(max_sessions * sizeof(Session));
    if (!sessions) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize activity log array
    ActivityLog* activity_logs = (ActivityLog*)malloc(max_sessions * sizeof(ActivityLog));
    if (!activity_logs) {
        free(sessions);
        printf("Memory allocation failed.\n");
        return;
    }

    // Sort sessions by start timestamp in ascending order
    qsort(sessions, max_sessions, sizeof(Session), compare_session_start_timestamp);

    // Initialize session IDs and activity logs
    for (int i = 0; i < max_sessions; i++) {
        sessions[i].session_id = i;
        activity_logs[i].session = &sessions[i];
        activity_logs[i].event_count = 0;
    }
}

// Compare function for qsort to sort sessions by start timestamp in ascending order
int compare_session_start_timestamp(const void* a, const void* b) {
    Session* session_a = (Session*)a;
    Session* session_b = (Session*)b;

    if (session_a->start_timestamp < session_b->start_timestamp)
        return -1;
    else if (session_a->start_timestamp > session_b->start_timestamp)
        return 1;
    else
        return 0;
}

// Function to insert a new session into the sorted array
void insert_new_session(Session* new_session, Session** sessions, int* max_sessions) {
    int i = *max_sessions - 1;

    // Find the correct position for the new session in the sorted array
    while (i >= 0 && new_session->start_timestamp < sessions[i]->start_timestamp)
        i--;

    if (i + 1 > *max_sessions) {
        // Resize the array if necessary
        Session* new_sessions = (Session*)realloc(sessions, (*max_sessions + 10) * sizeof(Session));
        ActivityLog* new_activity_logs = (ActivityLog*)realloc(activity_logs, (*max_sessions + 10) * sizeof(ActivityLog));
        sessions = &new_sessions;
        activity_logs = &new_activity_logs;
    }

    // Shift existing sessions to the right
    for (int j = *max_sessions; i < j; j--)
        sessions[j] = sessions[i];
    sessions[i + 1] = new_session;
    *max_sessions += 10;

    return;
}

// Function to free all allocated memory upon completion of the function
void finalize_session_collection(Session* sessions, ActivityLog* activity_logs) {
    // Free session array
    free(sessions);

    // Free activity log array
    for (int i = 0; i < *max_sessions; i++) {
        free(activity_logs[i].events);
        free(&activity_logs[i]);
    }
    free(activity_logs);

    return;
}
