summary* create_summary(record** records, size_t num_records) {
    summary* summaries = (summary*)malloc(sizeof(summary));
    summaries->records = (record**)malloc(num_records * sizeof(record*));
    for (size_t i = 0; i < num_records; i++) {
        summaries->records[i] = records[i];
    }
    summaries->num_records = num_records;
    return summaries;
}

void sort_records(record** records, size_t num_records) {
    qsort(records, num_records, sizeof(record*), record_cmp);
}

int record_cmp(const void* a, const void* b) {
    const record* r1 = *(record**)a;
    const record* r2 = *(record**)b;
    return r1->value - r2->value;
}

void clean_up(summary* summaries, record** records) {
    // Free memory
    for (size_t i = 0; i < summaries->num_records; i++) {
        free(summaries->records[i]);
    }
    free(summaries);
    for (size_t i = 0; i < summaries->num_records; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int max_limit;
    int* offsets = NULL;
    int* keys = NULL;

    // Initialize arrays
    init_arrays(max_limit, &offsets, &keys);

    record** records = (record**)malloc(max_limit * sizeof(record*));
    for (size_t i = 0; i < max_limit; i++) {
        records[i] = (record*)malloc(sizeof(record));
        // Randomly assign each record's integer value within a specified range
        records[i]->value = rand() % 100;
        strcpy(records[i]->id, "Record_");
    }

    summary* summaries = create_summary(records, max_limit);

    sort_records(records, max_limit);

    // Clean up resources
    clean_up(summaries, records);

    return 0;
}
