#include <dirent.h>

typedef struct {
    char* name;
    struct stat statbuf;
    unsigned long size;
} file_record;

int main(int argc, char** argv) {
    int verbose = 0;
    char* output_file = NULL;
    char* input_dir = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-v] [-o file] directory\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strncmp(argv[i], "-o ", 3) == 0) {
            output_file = &argv[i][2];
        } else if (input_dir == NULL) {
            input_dir = argv[i];
        }
    }

    if (input_dir == NULL) {
        printf("No input directory provided.\n");
        return 1;
    }

    DIR* dir = opendir(input_dir);
    if (dir == NULL) {
        perror("opendir");
        return 2;
    }

    int file_count = 0;
    int dir_count = 0;

    struct dirent** files_and_dirs;
    size_t files_and_dirs_len = scandir(input_dir, &files_and_dirs, NULL, NULL);
    if (files_and_dirs_len == -1) {
        perror("scandir");
        closedir(dir);
        return 3;
    }

    for (size_t i = 0; i < files_and_dirs_len; i++) {
        file_record* file_rec = malloc(sizeof(file_record));
        file_rec->name = files_and_dirs[i]->d_name;
        file_rec->statbuf.st_size = files_and_dirs[i]->d_type == DT_REG || files_and_dirs[i]->d_type == DT_DIR ? 0 : (unsigned long)files_and_dirs[i]->d_stat.st_size;

        struct stat statbuf;
        if (fstatat(dirfd(dir), files_and_dirs[i]->d_name, &statbuf, AT_SYMLINK_NOFOLLOW) != 0) {
            perror("fstatat");
            free(file_rec);
            continue;
        }

        file_rec->statbuf = statbuf;

        if (S_ISDIR(files_and_dirs[i]->d_stat.st_mode)) {
            dir_count++;
        } else {
            file_count++;
        }
    }

    closedir(dir);

    unsigned long* sizes = malloc(sizeof(unsigned long) * (file_count + 1));
    char** names = malloc(sizeof(char*) * (file_count + 2));

    size_t idx = 0;
    for (size_t i = 0; i < files_and_dirs_len; i++) {
        if (files_and_dirs[i]->d_type == DT_REG || files_and_dirs[i]->d_type == DT_DIR) {
            file_record* file_rec = malloc(sizeof(file_record));
            file_rec->name = files_and_dirs[i]->d_name;
            file_rec->statbuf.st_size = (unsigned long)files_and_dirs[i]->d_stat.st_size;

            if (fstatat(dirfd(dir), files_and_dirs[i]->d_name, &file_rec->statbuf, AT_SYMLINK_NOFOLLOW) != 0) {
                perror("fstatat");
                free(file_rec);
                continue;
            }

            sizes[idx] = file_rec->statbuf.st_size;
            names[idx] = file_rec->name;

            idx++;
        }
    }

    for (size_t i = 0; i < idx; i++) {
        printf("%s, %lu\n", names[i], sizes[i]);
    }

    free(sizes);
    free(names);

    return 0;
}']

