#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int data;
    struct Node* next;
} Node;

Node* create_node(int data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void free_list(Node* head) {
    while(head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int get_largest(int** arr, int size) {
    int max = (*arr)[0];
    for (int i = 1; i < size; i++) {
        if ((*arr)[i] > max)
            max = (*arr)[i];
    }
    return max;
}

void read_and_validate_input(Node** head_ref, FILE* input_file) {
    int c;
    Node* current_node = NULL;
    while ((c = fgetc(input_file)) != EOF) {
        if (c == '\n') {
            if (*head_ref == NULL)
                *head_ref = create_node(0);
            else
                current_node->next = create_node(c - '0');
            current_node = current_node->next;
        }
    }
}

void print_largest(Node* head) {
    Node* temp = head;
    int max = temp->data;
    while(temp != NULL) {
        if (temp->data > max)
            max = temp->data;
        temp = temp->next;
    }
    printf("Largest number is: %d\n", max);
}

int main() {
    Node* head = NULL;
    FILE* input_file = stdin;

    read_and_validate_input(&head, input_file);

    if (ferror(input_file)) {
        fprintf(stderr, "Error reading from standard input.\n");
        return 1;
    }

    int* arr = NULL;
    int size = 0;
    Node* current = head;
    while(current != NULL) {
        size++;
        current = current->next;
    }
    arr = (int*)malloc(sizeof(int)*size);
    int i = 0;
    current = head;
    while(current != NULL) {
        arr[i] = current->data;
        i++;
        current = current->next;
    }

    int max_val = get_largest(&arr, size);

    printf("Largest number is: %d\n", max_val);

    free_list(head);
    free(arr);

    return 0;
}

