#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char* name;
    char* email;
    int age;
} User;

User* user_new() {
    User* user = (User*)malloc(sizeof(User));
    user->name = NULL;
    user->email = NULL;
    user->age = 0;
    return user;
}

void user_free(User** user) {
    if (*user != NULL) {
        free((*user)->name);
        free((*user)->email);
        free(*user);
        *user = NULL;
    }
}

int main() {
    json_object* root;
    FILE* file = fopen("input.json", "r");
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char* buffer = (char*)malloc(sizeof(char) * (size + 1));
    fread(buffer, sizeof(char), size, file);
    fclose(file);

    buffer[size] = '\0';
    root = json_decode(buffer);
    free(buffer);

    if (root == NULL || json_object_object_get(root, "users") == NULL) {
        printf("No valid users provided.\n");
        return 1;
    }

    User* users[json_object_array_length(json_object_object_get(root, "users"))];
    for (int i = 0; i < json_object_array_length(json_object_object_get(root, "users")); i++) {
        User* user = user_new();
        users[i] = user;

        json_object* user_obj = json_object_object_get(json_object_object_get(root, "users"), json_object_array_get_idx(json_object_object_get(root, "users"), i));
        user->name = strdup(json_object_get_string(user_obj, "name"));
        user->email = strdup(json_object_get_string(user_obj, "email"));
        user->age = (int)json_object_get_number(user_obj, "age");

        user_free(&user);
    }

    int max_age = 0;
    User* oldest_user = NULL;

    for (int i = 0; i < json_object_array_length(json_object_object_get(root, "users")); i++) {
        if (users[i]->age > max_age) {
            max_age = users[i]->age;
            oldest_user = users[i];
        }
    }

    printf("The user with the highest age is: %s, %d years old.\n", oldest_user->name, oldest_user->age);

    return 0;
}
