#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void createStateList(int* states, int numStates, int maxStateValue) {
    // Create new state list dynamically
    int** newStateList = (int**)malloc(numStates * sizeof(int*));
    for (int i = 0; i < numStates; i++) {
        newStateList[i] = (int*)malloc(sizeof(int));
        *newStateList[i] = rand() % maxStateValue;
    }

    // Sort the states
    int temp;
    for (int i = 0; i < numStates - 1; i++) {
        for (int j = 0; j < numStates - i - 1; j++) {
            if (*newStateList[j] > *newStateList[j + 1]) {
                temp = *newStateList[j];
                *newStateList[j] = *newStateList[j + 1];
                *newStateList[j + 1] = temp;
            }
        }
    }

    // Log the state list
    for (int i = 0; i < numStates; i++) {
        printf("State %d: %d\n", i, *newStateList[i]);
    }

    // Release allocated memory
    for (int i = 0; i < numStates; i++) {
        free(newStateList[i]);
    }
    free(newStateList);
}

void createNFAPI_CRC_INDICATION_PDU_T_Array(int N) {
    // Dynamically allocate memory for array of structures
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Populate structures
        array[i]->RX_UE_INFORMATION_TAG = rand() % 256;
        array[i]->RNTI = rand() % 256;
        array[i]->CRCFLAG = (rand() & 1) ? 1 : 0;

        // Validate tags and RNTIs
        if (array[i]->RX_UE_INFORMATION_TAG < 0 || array[i]->RX_UE_INFORMATION_TAG > 255 ||
            array[i]->RNTI < 0 || array[i]->RNTI > 255) {
            printf("Invalid tag or RNTI: %d, %d\n", array[i]->RX_UE_INFORMATION_TAG, array[i]->RNTI);
        }
    }

    // Log the structures
    for (int i = 0; i < N; i++) {
        printf("Structure %d: RX_UE_INFORMATION_TAG = %d, RNTI = %d, CRCFLAG = %d\n", i, array[i]->RX_UE_INFORMATION_TAG, array[i]->RNTI, array[i]->CRCFLAG);
    }

    // Release allocated memory
    for (int i = 0; i < N; i++) {
        free(array[i]);
    }
    free(array);
}
