#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure definitions
typedef struct {
    int value;
    char *id;
} Record;

typedef struct {
    Record **records;
    int count;
} Summary;

// Function to manage dynamic collection of records
Summary *manageRecords(int *offsets, int *keys, Record **records, int n) {
    // Initialize summary array
    Summary *summaries = (Summary *)malloc(sizeof(Summary) * (n / 10 + 1));
    if (!summaries) return NULL;

    // Initialize record pointers in summaries
    for (int i = 0; i < sizeof(Summary) / sizeof(Summary[0]); i++) {
        summaries[i].records = (Record **)malloc(sizeof(Record *) * 10);
        if (!summaries[i].records) return NULL;
    }

    // Initialize record array
    Record **recArr = (Record **)malloc(sizeof(Record *) * n);
    if (!recArr) return NULL;

    // Initialize summary count
    int summaryCount = 0;

    // Loop through records and assign to summaries
    for (int i = 0; i < n; i++) {
        Record *record = records[i];
        int key = keys[i];
        int offset = offsets[i];

        // Find or create a summary for this record
        Summary *summary;
        for (int j = 0; j <= summaryCount; j++) {
            if (j == summaryCount || key > summaries[j].count) {
                summary = &summaries[j];
                break;
            }
        }

        // Add record to summary
        summary->records[summary->count] = record;
        summary->count++;

        // Reallocate summary array if necessary
        if (summary->count == sizeof(Summary) / sizeof(Summary[0])) {
            Summary *temp = summaries;
            int newSize = sizeof(Summary) * 2;
            summaries = (Summary *)realloc(summaries, newSize);
            temp = NULL;
        }
    }

    // Sort records
    Record **sortedRecArr = (Record **)malloc(sizeof(Record *) * n);
    if (!sortedRecArr) return NULL;

    for (int i = 0; i < n; i++) {
        sortedRecArr[i] = recArr[i];
    }

    qsort(sortedRecArr, n, sizeof(Record *), recordCompare);

    // Return summary and sorted records
    Summary *retSummaries;
    Record **retRecords;

    // Allocate memory for return values
    retSummaries = (Summary *)malloc(sizeof(Summary) * summaryCount);
    retRecords = (Record **)malloc(sizeof(Record *) * n);

    // Copy summaries and records to return array
    int j = 0;
    for (int i = 0; i < summaryCount; i++) {
        retSummaries[i] = summaries[i];
        for (int k = 0; k < summaries[i].count; k++) {
            retRecords[j++] = summaries[i].records[k];
        }
    }

    return retSummaries;
}

// Compare function for qsort
int recordCompare(const void *a, const void *b) {
    Record **ra = (Record **)a;
    Record **rb = (Record **)b;

    if ((*ra)->value < (*rb)->value)
        return -1;
    else if ((*ra)->value > (*rb)->value)
        return 1;
    else
        return 0;
}

// Clean up function to deallocate memory
void cleanUp(Summary *summaries, Record **records) {
    // Free summaries and their records
    for (int i = 0; i < sizeof(Summary) / sizeof(Summary[0]); i++) {
        if (summaries[i].count > 0) {
            for (int j = 0; j < summaries[i].count; j++) {
                free(summaries[i].records[j]);
            }
            free(summaries[i].records);
        }
    }

    // Free records
    for (int i = 0; i < sizeof(Summary) / sizeof(Summary[0]); i++) {
        if (summaries[i].count > 0) {
            for (int j = 0; j < summaries[i].count; j++) {
                free(recArr[j]);
            }
        }
    }

    // Free memory
    free(summaries);
    free(recArr);

    return;
}

int main() {
    int offsets[] = {1, 2, 3};
    int keys[] = {10, 20, 30};
    Record *records[] = {(Record){.value=5, .id="record1"}, (Record){.value=15, .id="record2"}, (Record){.value=25, .id="record3"}};

    Summary *summaries = manageRecords(offsets, keys, records, 3);

    // Print summaries and sorted records
    for (int i = 0; i < sizeof(Summary) / sizeof(Summary[0]); i++) {
        printf("Summary %d: ", i);
        for (int j = 0; j < summaries[i].count; j++) {
            printf("%s, ", summaries[i].records[j]->id);
        }
        printf("\n");
    }

    cleanUp(summaries, records);

    return 0;
}

