#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    int size;
    int capacity;
    time_t last_accessed[T];
    int T;
} NFAPI_CRC_INDICATION_PDU_T_Array;

void nfapi_crc_indication_pdu_array_init(NFAPI_CRC_INDICATION_PDU_T_Array* array, int capacity, int T) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size = 0;
    array->capacity = capacity;
    for (int i = 0; i < capacity; i++) {
        array->last_accessed[i] = time(NULL);
    }
    array->T = T;
}

void nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_T_Array* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    array->array[array->size] = pdu;
    array->last_accessed[array->size] = time(NULL);
    array->size++;
}

void nfapi_crc_indication_pdu_array_update(NFAPI_CRC_INDICATION_PDU_T_Array* array, int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (index < 0 || index >= array->size) return;
    array->array[index] = pdu;
    array->last_accessed[index] = time(NULL);
}

int nfapi_crc_indication_pdu_array_get_size(NFAPI_CRC_INDICATION_PDU_T_Array* array) {
    return array->size;
}

void nfapi_crc_indication_pdu_array_clean_up(NFAPI_CRC_INDICATION_PDU_T_Array* array) {
    for (int i = 0; i < array->size; i++) {
        if (time(NULL) - array->last_accessed[i] > array->T) {
            memmove(&array->array[i], &array->array[i + 1], (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
        }
    }
}

void nfapi_crc_indication_pdu_array_serialize_binary(const NFAPI_CRC_INDICATION_PDU_T_Array* array, FILE* file) {
    fwrite(&array->size, sizeof(int), 1, file);
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

NFAPI_CRC_INDICATION_PDU_T_Array* nfapi_crc_indication_pdu_array_deserialize_binary(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T_Array* array = (NFAPI_CRC_INDICATION_PDU_T_Array*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_Array));
    fread(&array->size, sizeof(int), 1, file);
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    return array;
}

void nfapi_crc_indication_pdu_array_serialize_json(const NFAPI_CRC_INDICATION_PDU_T_Array* array, FILE* file) {
    fprintf(file, "{\"size\": %d, \"array\": [", array->size);
    for (int i = 0; i < array->size; i++) {
        fprintf(file, "{\"RX_UE_INFORMATION_TAG\": %hu, \"RNTI\": %u, \"CRC_INDICATION_REL8_TAG\": %u, \"CRCFLAG\": %u},",
            array->array[i].RX_UE_INFORMATION_TAG, array->array[i].RNTI, array->array[i].CRC_INDICATION_REL8_TAG, array->array[i].CRCFLAG);
    }
    fprintf(file, "]}");
}

NFAPI_CRC_INDICATION_PDU_T_Array* nfapi_crc_indication_pdu_array_deserialize_json(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T_Array* array = (NFAPI_CRC_INDICATION_PDU_T_Array*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_Array));
    char line[256];
    int size = 0;
    while (fgets(line, sizeof(line), file)) {
        if (strstarts(line, "{\"size\": ")) {
            size = atoi(strsep(&line, ":") + 1);
            break;
        }
    }
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        fgets(line, sizeof(line), file);
