            &array->array[i].RX_UE_INFORMATION_TAG, &array->array[i].RNTI, &array->array[i].CRC_INDICATION_REL8_TAG, &array->array[i].CRCFLAG);
    }
    return array;
}

void nfapi_crc_indication_pdu_array_serialize_text(const NFAPI_CRC_INDICATION_PDU_T_Array* array, FILE* file) {
