#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Array to store NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* dynamic_array = NULL;
int array_size = 0;
int num_elements = 0;
int T = 10; // default threshold in seconds
int S = 30; // default age limit in seconds

// Function to add new elements
void add_element(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = rand();
    new_element->CRCFLAG = (rand() % 2);
    if (num_elements == array_size) {
        // Resize the array
        NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dynamic_array, (array_size + 10) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_array != NULL) {
            dynamic_array = temp_array;
            array_size += 10;
        } else {
            printf("Array reallocation failed!\n");
            return;
        }
    }
    if (num_elements < array_size) {
        // Update the last element
        dynamic_array[num_elements].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        dynamic_array[num_elements].RNTI = RNTI;
        num_elements++;
    } else {
        // Update the first unused element
        for (int i = 0; i < array_size; i++) {
            if (dynamic_array[i]->RX_UE_INFORMATION_TAG == -1) {
                dynamic_array[i]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                dynamic_array[i]->RNTI = RNTI;
                break;
            }
        }
    }
}

// Function to update existing elements
void update_element(int index, int new_RX_UE_INFORMATION_TAG, int new_RNTI) {
    if (index < 0 || index >= num_elements) {
        printf("Invalid element index!\n");
        return;
    }
    dynamic_array[index]->RX_UE_INFORMATION_TAG = new_RX_UE_INFORMATION_TAG;
    dynamic_array[index]->RNTI = new_RNTI;
}

// Function to get the count of elements
int get_num_elements() {
    return num_elements;
}

// Function to periodically clean up unused memory
void periodic_cleanup(int current_time) {
    for (int i = 0; i < array_size; i++) {
        if (current_time - dynamic_array[i]->RX_UE_INFORMATION_TAG > T) {
            // Mark the element for potential cleanup
            dynamic_array[i]->RX_UE_INFORMATION_TAG = -1;
        }
    }
}

// Function to serialize and deserialize the array
void serialize_array(const char* file_path, int format) {
    if (format == 0) { // binary format
        FILE* file = fopen(file_path, "wb");
        fwrite(&num_elements, sizeof(int), 1, file);
        for (int i = 0; i < num_elements; i++) {
            fwrite(&dynamic_array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        }
        fclose(file);
    } else { // JSON format
        FILE* file = fopen(file_path, "w");
        fprintf(file, "{\n");
        for (int i = 0; i < num_elements; i++) {
            fprintf(file, "\"RX_UE_INFORMATION_TAG\": %d,\n\"RNTI\": %d,\n\"CRC_INDICATION_REL8_TAG\": %d,\n\"CRCFLAG\": %d", dynamic_array[i].RX_UE_INFORMATION_TAG, dynamic_array[i].RNTI, dynamic_array[i].CRC_INDICATION_REL8_TAG, dynamic_array[i].CRCFLAG);
            if (i < num_elements - 1) {
                fprintf(file, "\n");
            } else {
                fprintf(file, "}\n");
            }
        }
        fclose(file);
    }
}

// Function to deserialize and serialize the array
void deserialize_array(const char* file_path, int format) {
    FILE* file = fopen(file_path, "rb");
    if (file != NULL) {
