typedef struct {
    int REQUEST_ID;
    int STATUS_CODE;
    char *RESPONSE_BODY;
} HTTP_RESPONSE_RECORD_T;

// Configurable threshold (T) in seconds
#define CLEANUP_THRESHOLD 60

// Configurable age limit (S) in seconds
#define AGE_LIMIT 300

typedef struct {
    HTTP_RESPONSE_RECORD_T *records;
    int size;
    int capacity;
} HTTP_RESPONSE_LIST_T;

HTTP_RESPONSE_LIST_T *http_response_list_new(int initial_capacity) {
    HTTP_RESPONSE_LIST_T *list = malloc(sizeof(HTTP_RESPONSE_LIST_T));
    list->size = 0;
    list->capacity = initial_capacity;
    list->records = malloc(initial_capacity * sizeof(HTTP_RESPONSE_RECORD_T));
    return list;
}

void http_response_list_free(HTTP_RESPONSE_LIST_T *list) {
    for (int i = 0; i < list->size; i++) {
        free(list->records[i].RESPONSE_BODY);
    }
    free(list->records);
    free(list);
}

// Add a new record to the list
void http_response_list_add(HTTP_RESPONSE_LIST_T *list, int request_id, int status_code, char *response_body) {
    if (list->size >= list->capacity) {
        // Dynamically resize the underlying storage
        list->capacity *= 2;
        list->records = realloc(list->records, list->capacity * sizeof(HTTP_RESPONSE_RECORD_T));
    }
    list->records[list->size].REQUEST_ID = request_id;
    list->records[list->size].STATUS_CODE = status_code;
    list->records[list->size].RESPONSE_BODY = strdup(response_body);
    list->size++;
}

// Update an existing record in the list
void http_response_list_update(HTTP_RESPONSE_LIST_T *list, int request_id, int new_status_code) {
    for (int i = 0; i < list->size; i++) {
        if (list->records[i].REQUEST_ID == request_id) {
            list->records[i].STATUS_CODE = new_status_code;
            return;
        }
    }
}

// Retrieve a record from the list by ID
HTTP_RESPONSE_RECORD_T *http_response_list_get(HTTP_RESPONSE_LIST_T *list, int request_id) {
    for (int i = 0; i < list->size; i++) {
        if (list->records[i].REQUEST_ID == request_id) {
            return &list->records[i];
        }
    }
    return NULL;
}

// Get the count of elements in the list
int http_response_list_count(HTTP_RESPONSE_LIST_T *list) {
    return list->size;
}

// Periodic memory management (clean up unused records)
void http_response_list_cleanup(HTTP_RESPONSE_LIST_T *list, time_t current_time) {
    for (int i = 0; i < list->size; i++) {
        if (current_time - list->records[i].REQUEST_ID > CLEANUP_THRESHOLD) {
            // Remove the record from the list
            memmove(&list->records[i], &list->records[i + 1], (list->size - i - 1) * sizeof(HTTP_RESPONSE_RECORD_T));
            list->size--;
        }
    }
}

// Serialize the list to a file in binary format
void http_response_list_serialize_binary(HTTP_RESPONSE_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        // Handle error
    } else {
        fwrite(&list->size, sizeof(int), 1, file);
        for (int i = 0; i < list->size; i++) {
            fwrite(&list->records[i], sizeof(HTTP_RESPONSE_RECORD_T), 1, file);
        }
        fclose(file);
    }
}

// Serialize the list to a file in JSON format
void http_response_list_serialize_json(HTTP_RESPONSE_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        // Handle error
    } else {
        fprintf(file, "[");
        for (int i = 0; i < list->size; i++) {
            fprintf(file, "{\"request_id\": %d, \"status_code\": %d, \"response_body\": \"%s\"}", list->records[i].REQUEST_ID, list->records[i].STATUS_CODE, list->records[i].RESPONSE_BODY);
            if (i < list->size - 1) {
                fprintf(file, ",");
        }
    }
    fprintf(file, "]");
    fclose(file);
}

// Deserialize the list from a file in binary format
HTTP_RESPONSE_LIST_T *http_response_list_deserialize_binary(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
    } else {
        HTTP_RESPONSE_LIST_T *list = malloc(sizeof(HTTP_RESPONSE_LIST_T));
        fread(&list->size, sizeof(int), 1, file);
        list->records = malloc(list->size * sizeof(HTTP_RESPONSE_RECORD_T));
        for (int i = 0; i < list->size; i++) {
            fread(&list->records[i], sizeof(HTTP_RESPONSE_RECORD_T), 1, file);
