#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of sessions
#define MAX_SESSIONS 1000

// Structure representing a session
typedef struct {
    int id;
    time_t start_timestamp;
    time_t end_timestamp;
} Session;

// Structure representing an activity log
typedef struct {
    Session* session;
    char** events;
    int event_count;
} ActivityLog;

// Function to manage and initialize sessions and their activity logs
ActivityLog* init_sessions(int max_events_per_session) {
    // Initialize the maximum number of sessions
    int max_sessions = MAX_SESSIONS;

    // Allocate memory for the array of 'session' structures
    Session* sessions = (Session*)malloc(max_sessions * sizeof(Session));

    // Check if memory allocation was successful
    if (!sessions) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each session with a unique ID and timestamps
    for (int i = 0; i < max_sessions; i++) {
        sessions[i].id = i + 1;
        sessions[i].start_timestamp = time(NULL);
        sessions[i].end_timestamp = time(NULL);
    }

    // Sort the sessions based on their start timestamps in ascending order
    qsort(sessions, max_sessions, sizeof(Session), session_compare);

    // Initialize the array of 'activity_log' structures
    ActivityLog* activity_logs = (ActivityLog*)malloc(max_sessions * sizeof(ActivityLog));

    for (int i = 0; i < max_sessions; i++) {
        activity_logs[i].session = &sessions[i];
        activity_logs[i].events = NULL;
        activity_logs[i].event_count = 0;
    }

    return activity_logs;
}

// Function to compare two sessions based on their start timestamps
int session_compare(const void* a, const void* b) {
    Session* sa = (Session*)a;
    Session* sb = (Session*)b;

    if (sa->start_timestamp < sb->start_timestamp)
        return -1;
    else if (sa->start_timestamp > sb->start_timestamp)
        return 1;
    else
        return 0;
}

// Function to add a new event to an existing session's activity log
void add_event(ActivityLog* activity_log, const char* event) {
    // Check if the activity log exists
    if (!activity_log || !activity_log->session)
        return;

    // Create a new event and append it to the activity log
    char** new_events = (char**)realloc(activity_log->events, (activity_log->event_count + 1) * sizeof(char*));
    new_events[activity_log->event_count] = strdup(event);
    activity_log->events = new_events;
    activity_log->event_count++;
}

// Function to remove an existing event from a session's activity log
void remove_event(ActivityLog* activity_log, int event_index) {
    // Check if the activity log exists and has at least one event
    if (!activity_log || !activity_log->events || activity_log->event_count <= 0)
        return;

    // Shift all events after the removed event down by one position
    for (int i = event_index; i < activity_log->event_count - 1; i++) {
        char** temp = activity_log->events;
        activity_log->events = realloc(activity_log->events, (activity_log->event_count) * sizeof(char*));
        activity_log->events[i] = temp[i + 1];
    }

    // Free the memory of the removed event
    free(activity_log->events[activity_index]);

    // Update the event count and reallocate memory if necessary
    activity_log->event_count--;
}

// Function to update an existing session's end timestamp
void update_session_end_timestamp(Session* session, time_t new_end_timestamp) {
    // Check if the session exists
    if (!session)
        return;

    session->end_timestamp = new_end_timestamp;
}

// Function to free all allocated memory upon function completion
void finalize_sessions(ActivityLog* activity_logs) {
    // Free the array of 'activity_log' structures
    for (int i = 0; i < max_sessions; i++) {
        ActivityLog* current_activity_log = &activity_logs[i];
        if (current_activity_log->session)
            free(current_activity_log->session);
        if (current_activity_log->events) {
            for (int j = 0; j < current_activity_log->event_count; j++) {
                free(current_activity_log->events[j]);
            }
            free(current_activity_log->events);
        }
    }

    // Free the array of 'session' structures
    if (activity_logs)
        free(activity_logs);

    // Print a message indicating successful memory deallocation
    printf("Memory deallocated successfully.\n");
}
