void* manage_sessions(int load) {
    // Initialize arrays
    int num_sessions = 0;
    Session** sessions = (Session**)malloc(sizeof(Session*) * load);
    char** usernames = (char**)calloc(load, sizeof(char));
    ActivityLog* activity_log = (ActivityLog*)malloc(sizeof(ActivityLog) * load);

    // Initialize ranges for session timestamps based on server load
    int min_timestamp = 0;
    int max_timestamp = 10000;
    if (load > 500) {
        min_timestamp = 10000;
        max_timestamp = 200000;
    }

    // Initialize activity log
    for (int i = 0; i < load; i++) {
        activity_log[i].user_id = -1;
        activity_log[i].active_sessions = 0;
        activity_log[i].last_seen_timestamp = 0;
    }

    // Manage sessions
    return NULL;
}

// Function to filter and retrieve active sessions for a given user
Session* get_active_sessions(int user_id, Session** sessions, int num_sessions) {
    // Initialize hash table for fast lookups
    int* users = (int*)calloc(num_sessions, sizeof(int));
    for (int i = 0; i < num_sessions; i++) {
        users[i] = -1;
    }

    // Filter and retrieve active sessions
    Session* result = NULL;
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]->state == 1 && users[sessions[i]->id] != user_id) {
            users[sessions[i]->id] = user_id;
            result = (Session*)realloc(result, sizeof(Session) * (result ? result->size : 0) + 1);
            result[result->size].id = sessions[i]->id;
            result[result->size].username = sessions[i]->username;
            result[result->size].timestamp = sessions[i]->timestamp;
            result[result->size].state = sessions[i]->state;
            result->size++;
        }
    }

    // Clean up resources
    free(users);
    return result;
}

// Function to clean up resources when the function completes
void cleanup(void* session_data) {
    // Free memory allocated for sessions, usernames, and activity log
    Session** sessions = (Session**)session_data;
    char** usernames = ((ActivityLog*)session_data)->usernames;
    ActivityLog* activity_log = (ActivityLog*)session_data;

    // Free each element in the arrays
    for (int i = 0; i < num_sessions; i++) {
        free(sessions[i]);
    }
    free(sessions);
    free(usernames);
    free(activity_log);

    return;
}
