    memory_pool.memory_blocks = NULL;
    memory_pool.block_size = sizeof(LTE_UERadioAccessNetworkProcedureIdentity);
    memory_pool.num_blocks = 0;

    // Allocate memory for the new node using the custom memory pool
    void *memory_block = memory_pool_allocate(&memory_pool, memory_pool.block_size);

    if (memory_block == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    LTE_UERadioAccessNetworkProcedureIdentity* new_node = memory_block;

    // Initialize node data
    new_node->RadioAccessNetworkId = RadioAccessNetworkId;
    strcpy(new_node->AccessStratumInformationTags, AccessStratumInformationTags);

    return new_node;
}

// Function to add a new node to the linked list while maintaining thread safety and avoiding duplicate IDs
void add_node(LTE_UERadioAccessNetworkProcedureIdentity** list, int* size, LTE_UERadioAccessNetworkProcedureIdentity* new_node) {
    // Check for duplicate ID
    for (int i = 0; i < *size; i++) {
        if ((*list)[i]->RadioAccessNetworkId == new_node->RadioAccessNetworkId) {
            // Handle duplicate ID
            return;
        }
    }

    // Insert the new node at the end of the list
    (*list) = realloc((*list), sizeof(LTE_UERadioAccessNetworkProcedureIdentity*) * (*size + 1));
    (*list)[*size] = new_node;
    (*size)++;
}

// Function to remove a node from the linked list while maintaining thread safety
void remove_node(LTE_UERadioAccessNetworkProcedureIdentity** list, int* size) {
    // Check if there are nodes in the list
    if (*size == 0) {
        return; // List is empty
    }

    // Shift all nodes down by one position to fill the gap left by removed node
    for (int i = *size - 1; i > 0; i--) {
        (*list)[i] = (*list)[i-1];
    }

    // Free memory of removed node
    free((*list)[0]);

    (*list) = realloc((*list), sizeof(LTE_UERadioAccessNetworkProcedureIdentity*) * (*size - 1));
    (*size)--;

    // Rebalance the linked list if necessary (e.g., after removal)
