#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the maximum number of states in the list
#define MAX_STATES 1000

// Define the structure for storing state information
typedef struct {
    int state_id;
    int value;
} State_t;

// Define the function to create and manage a state list
void fsa_state_list(int N, int max_states) {
    // Initialize variables
    int i;
    State_t *state_list = NULL;
    srand(time(NULL));

    // Allocate memory for the state list
    if (!(state_list = (State_t *)malloc(sizeof(State_t) * max_states))) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize and sort the states in ascending order
    for (i = 0; i < max_states; i++) {
        state_list[i].state_id = i;
        state_list[i].value = rand() % 100 + 1;
    }
    qsort(state_list, max_states, sizeof(State_t), compare);

    // Print the sorted states
    for (i = 0; i < max_states; i++) {
        printf("State %d: Value=%d\n", state_list[i].state_id, state_list[i].value);
    }

    // Deallocate memory when done
    free(state_list);
}

// Define the function to compare states
int compare(const void *a, const void *b) {
    State_t *sta = (State_t *)a;
    State_t *stb = (State_t *)b;

    return (sta->value - stb->value);
}
