// Thread-safe hash table
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    LTE_UERadioAccessNetworkProcedureIdentity** table;
} HashTable;

// Initialize the hash table with a given capacity and populate it with randomly generated structures
HashTable* initHashTable(size_t capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = (LTE_UERadioAccessNetworkProcedureIdentity**)calloc(capacity, sizeof(LTE_UERadioAccessNetworkProcedureIdentity*));

    for (size_t i = 0; i < capacity; i++) {
        LTE_UERadioAccessNetworkProcedureIdentity* item = (LTE_UERadioAccessNetworkProcedureIdentity*)malloc(sizeof(LTE_UERadioAccessNetworkProcedureIdentity));
        item->radioAccessNetworkId = rand() % 100;
        for (int j = 0; j < 5; j++) {
            char buffer[10];
            sprintf(buffer, "Tag_%d", j);
            item->accessStratumInformationTags[j] = (char*)malloc(strlen(buffer) + 1);
            strcpy(item->accessStratumInformationTags[j], buffer);
        }
        ht->table[i] = item;
    }

    return ht;
}

// Thread-safe function to add an item to the hash table
void addItem(HashTable* ht, LTE_UERadioAccessNetworkProcedureIdentity* item) {
    pthread_mutex_lock(&ht->lock);

    // Validate tags and add the item to the hash table
    for (int j = 0; j < 5; j++) {
        if (!strcmp(item->accessStratumInformationTags[j], "")) {
            free(item);
            pthread_mutex_unlock(&ht->lock);
            return;
        }
    }

    size_t index = rand() % ht->capacity;
    ht->table[index] = item;
    ht->size++;

    pthread_mutex_unlock(&ht->lock);
}

// Thread-safe function to get an item from the hash table
LTE_UERadioAccessNetworkProcedureIdentity* getItem(HashTable* ht, int radioAccessNetworkId) {
    pthread_mutex_lock(&ht->lock);

    size_t index = rand() % ht->capacity;
    while (index < ht->size && !ht->table[index]->radioAccessNetworkId == radioAccessNetworkId) {
        index = (index + 1) % ht->capacity;
    }

    LTE_UERadioAccessNetworkProcedureIdentity* item = ht->table[index];
    pthread_mutex_unlock(&ht->lock);

    return item;
}

// Thread-safe function to periodically clean up unused structures in the hash table
void cleanUpHashTable(HashTable* ht, int threshold) {
    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->capacity; i++) {
        if (!ht->table[i]) {
            free(ht->table[i]);
            ht->size--;
        }
    }

    pthread_mutex_unlock(&ht->lock);
}

// Thread-safe function to periodically evict least recently used (LRU) cache entries
void lruEviction(HashTable* ht, int threshold) {
    pthread_mutex_lock(&ht->lock);

    for (int i = 0; i < threshold; i++) {
        size_t index = rand() % ht->size;
        free(ht->table[index]);
        ht->size--;
    }

    pthread_mutex_unlock(&ht->lock);
}

// Thread-safe function to dynamically add or remove instances of the hash table based on current traffic patterns
void autoScaleHashTable(HashTable* ht, int threshold) {
    pthread_mutex_lock(&ht->lock);

    if (ht->size > threshold) {
        // Add instance(s)
    } else if (ht->size < threshold) {
        // Remove instance(s)
    }

    pthread_mutex_unlock(&ht->lock);
}

