    float memory_consumption;
    time_t maintenance_date[MAX_MAINTENANCE_EVENTS];
    int num_maintenance_events;
} Device;

typedef struct {
    Device* devices;
    int size;
    FILE* log_file;
} Inventory;

Inventory* init_inventory() {
    Inventory* inventory = (Inventory*)malloc(sizeof(Inventory));
    if (!inventory) return NULL;
    inventory->devices = (Device*)calloc(MAX_DEVICES, sizeof(Device));
    if (!inventory->devices) {
        free(inventory);
        return NULL;
    }
    inventory->size = 0;
    inventory->log_file = fopen("device_inventory.log", "w");
    if (!inventory->log_file) {
        free(inventory->devices);
        free(inventory);
        return NULL;
    }
    return inventory;
}

void add_device(Inventory* inventory, Device device) {
    // Check for duplicate serial numbers
    int found = 0;
    for (int i = 0; i < inventory->size; i++) {
        if (strcmp(device.serial_number, inventory->devices[i].serial_number) == 0) {
            found = 1;
            break;
        }
    }
    if (found) {
        fprintf(inventory->log_file, "Error: Duplicate serial number detected. Aborting.\n");
        return;
    }

    // Check for valid device specifications
    if (!device.model || !device.firmware_version || strlen(device.serial_number) > 19) {
        fprintf(inventory->log_file, "Error: Invalid device specification. Aborting.\n");
        return;
    }

    inventory->devices[inventory->size] = device;
    inventory->size++;
}

void search_device(Inventory* inventory, const char* model, const char* firmware_version) {
    for (int i = 0; i < inventory->size; i++) {
        if (!strcmp(inventory->devices[i].model, model) && !strcmp(inventory->devices[i].firmware_version, firmware_version)) {
            printf("Device found with ID %d\n", inventory->devices[i].id);
            return;
        }
    }
    fprintf(inventory->log_file, "Error: Device not found.\n");
}

void free_inventory(Inventory* inventory) {
    for (int i = 0; i < inventory->size; i++) {
        free(inventory->devices[i].maintenance_date);
    }
    free(inventory->devices);
    fclose(inventory->log_file);
    free(inventory);
}
