    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % value_range;
        records[i].identifier = malloc(strlen("record") + 1);
        strcpy(records[i].identifier, "record");
        records[i].timestamp = time(NULL); // Record creation timestamp

        if (!records[i].identifier) {
            printf("Memory allocation failed for record identifier.\n");
            free(records[i].identifier);
