#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent network traffic events
typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    enum { TCP, UDP, ICMP } protocol;
    time_t timestamp;
    uint32_t packet_size;
} Event;

// Define a structure to represent the event queue
typedef struct {
    Event* events; // Array of events
    size_t capacity; // Maximum number of events in the queue
    size_t count; // Current number of events in the queue
    pthread_mutex_t mutex; // Mutex for thread-safe operations
    pthread_cond_t cond; // Condition variable for notification
} EventQueue;

// Initialize memory for the event queue and handle errors
EventQueue* init_event_queue(size_t capacity) {
    EventQueue* queue = (EventQueue*)malloc(sizeof(EventQueue));
    if (!queue) return NULL;

    queue->events = (Event*)calloc(capacity, sizeof(Event));
    if (!queue->events) {
        free(queue);
        return NULL;
    }

    queue->capacity = capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

// Insert a new event into the event queue while maintaining chronological order
void insert_event(EventQueue* queue, Event event) {
    if (pthread_mutex_lock(&queue->mutex)) return; // Handle lock errors

    // Check if there's enough space to insert the new event
    if (queue->count == queue->capacity) {
        // Resize the array and move existing events forward
        size_t new_capacity = queue->capacity * 2;
        Event* new_events = (Event*)realloc(queue->events, new_capacity * sizeof(Event));
        if (!new_events) return; // Handle memory allocation errors

        queue->events = new_events;
        queue->capacity = new_capacity;
    }

    // Insert the new event at the end of the array
    size_t i = queue->count++;
    while (i--) {
        Event temp = queue->events[i];
        queue->events[i+1] = temp;
    }
    queue->events[0] = event; // Update the timestamp and move forward

    pthread_cond_signal(&queue->cond); // Notify waiting threads
    pthread_mutex_unlock(&queue->mutex);
}

