    uint8_t crcflag;
} NFAPI_RX_INDICATION_T;

NFAPI_RX_INDICATION_PDU_T* generate_indications(size_t n) {
    NFAPI_RX_INDICATION_PDU_T* indications = (NFAPI_RX_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_RX_INDICATION_PDU_T));

    // Generate random tags
    NFAPITag* tags = (NFAPITag*)malloc(n * sizeof(NFAPITag));
    for (size_t i = 0; i < n; ++i) {
        tags[i].data = (uint8_t*)malloc(10); // Assume a fixed-size tag data
        srand(time(NULL)); // Initialize the random seed
        size_t length = rand() % 5 + 1;
        for (size_t j = 0; j < length; ++j) {
            tags[i].data[j] = (uint8_t)(rand() & 0xFF);
        }
        tags[i].length = length;
    }

    // Generate random indications
    for (size_t i = 0; i < n; ++i) {
        NFAPI_RX_INDICATION_T indication;
        indication.tag = tags[i];
        srand(time(NULL)); // Initialize the random seed
        indication.crcflag = (uint8_t)(rand() & 0xFF);

        indications[i].header.size = sizeof(NFAPI_RX_INDICATION_PDU_T);
        indications[i].header.type = NFAPI_RX_INDICATION;
        indications[i].data = (void*)&indication;
        indications[i].length = sizeof(indication) + tags[i].length;
    }

    // Clean up
    for (size_t i = 0; i < n; ++i) {
        free(tags[i].data);
    }
    free(tags);
    return indications;
}
