    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_list(int max_buffer_size, int max_batch_size, int* crc_list, int* rnti_count) {
    srand(time(NULL));

    int i, j, k, l, m, n;
    int crcflag = rand() % 2; // Randomly set CRCFLAG
    int rnti[100]; // Array to store unique RNTIs

    for (n = 0; n < *rnti_count; n++) {
        rnti[n] = -1; // Initialize array with -1, indicating no RNTI yet assigned
    }

    j = 0;
    k = 0;

    while (j < *rnti_count) {
        l = rand() % max_batch_size + 1; // Randomly generate batch size

        for (m = 0; m < l; m++) {
            if (k >= max_buffer_size) break; // Check if buffer is full

            i = rand() % *rnti_count;

            while (rnti[i] != -1) { // Check if RNTI is already assigned
                i = rand() % *rnti_count;
            }

            rnti[rnti_count - 1 - j] = i; // Assign unique RNTI to current PDU

            crc_list[k].RX_UE_INFORMATION_TAG = k + 1;
            crc_list[k].RNTI = i;
            crc_list[k].CRC_INDICATION_REL8_TAG = (k % 2) ? rand() % 1000 : 1234;
            crc_list[k].CRCFLAG = crcflag; // Set CRCFLAG consistently for the same RNTI

            k++;

            if (k >= max_buffer_size) break; // Check if buffer is full
        }

        j += l;
    }

    *rnti_count = n + 1; // Update actual RNTI count

    return 0;
}
