import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.zip.ZipException;

public class ThemeCacheManager {

    private static final Logger LOGGER = Logger.getLogger(ThemeCacheManager.class.getName());

    public void manageThemeCache(Bitmap themeBitmap, String defaultThemeDir) {
        if (themeBitmap != null && !themeBitmap.isRecycled()) {
            themeBitmap.recycle();
            themeBitmap = null;
        }

        try {
            // Check configuration file for default theme directory
            File configFile = new File(Environment.getExternalStorageDirectory(), "config.txt");
            String configDefaultDir = readFile(configFile);
            if (configDefaultDir == null || configDefaultDir.isEmpty()) {
                configDefaultDir = System.getProperty("default.theme.dir", "/sdcard/themes/default");
                setDefaultThemeDir(configFile, configDefaultDir);
            }

            // Parse PNG file
            File pngFile = new File(new File(defaultThemeDir), "theme.png");
            if (!pngFile.exists() || !isValidPNG(pngFile)) {
                // Handle corrupted or invalid PNG file gracefully
                LOGGER.log(Level.WARNING, "Invalid theme PNG file. Using default theme instead.");
                return;
            }

            Bitmap parsedBitmap = BitmapFactory.decodeStream(new FileInputStream(pngFile));
            if (parsedBitmap == null) {
                // Handle failed parsing gracefully
                LOGGER.log(Level.SEVERE, "Failed to parse theme PNG file.", new IOException("Failed to read PNG file"));
                return;
            }

            // Cache the parsed PNG file
            File cacheDir = new File(defaultThemeDir, "cache");
            if (!cacheDir.exists()) {
                Files.createDirectory(Paths.get(cacheDir.getAbsolutePath()));
            }
            String cachedFile = getUniqueCacheName();
            File cachedPNG = new File(cacheDir, cachedFile);
            try (InputStream in = new FileInputStream(pngFile); OutputStream out = new FileOutputStream(cachedPNG)) {
                IOUtils.copy(in, out);
            } catch (IOException e) {
                // Handle failed caching gracefully
                LOGGER.log(Level.SEVERE, "Failed to cache theme PNG file.", e);
                return;
            }

            // Periodically clean up old files based on retention policy
            int retentionDays = 30; // Default retention period
            File[] cachedFiles = cacheDir.listFiles();
            for (File file : cachedFiles) {
                if (file.isFile() && file.lastModified() < System.currentTimeMillis() - retentionDays * 24 * 60 * 60 * 1000) {
                    file.delete();
                }
            }

            LOGGER.log(Level.INFO, "Theme cache successfully updated.");
        } catch (IOException | ZipException e) {
            // Handle exceptions gracefully
            LOGGER.log(Level.SEVERE, "Failed to manage theme cache.", e);
        }
    }

    private String readFile(File file) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            return reader.readLine();
        }
    }

    private void setDefaultThemeDir(File configFile, String defaultDir) throws IOException {
        try (PrintWriter writer = new PrintWriter(configFile)) {
