```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    int protocol;
    time_t timestamp;
    size_t packet_size;
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventCollection;

EventCollection* event_collection_create(size_t initial_capacity) {
    EventCollection* collection = (EventCollection*)malloc(sizeof(EventCollection));
    collection->events = (Event*)calloc(initial_capacity, sizeof(Event));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void event_collection_insert(EventCollection* collection, Event* event) {
    if (collection->size == collection->capacity) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return;
    }
    pthread_mutex_lock(&collection->lock);
    memcpy(&collection->events[collection->size], event, sizeof(Event));
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

void event_collection_delete(EventCollection* collection, size_t index) {
    if (index >= collection->size) {
        printf("Index out of bounds\n");
        return;
    }
    pthread_mutex_lock(&collection->lock);
    memmove(&collection->events[index], &collection->events[index + 1], (collection->size - index - 1) * sizeof(Event));
    collection->size--;
    pthread_mutex_unlock(&collection->lock);
}

Event* event_collection_get(EventCollection* collection, size_t index) {
    if (index >= collection->size) {
        printf("Index out of bounds\n");
        return NULL;
    }
    pthread_mutex_lock(&collection->lock);
    Event* event = &collection->events[index];
    pthread_mutex_unlock(&collection->lock);
    return event;
}

void event_collection_free(EventCollection* collection) {
    free(collection->events);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
