// Define constants for session data types
#define SESSION_ID_TYPE int
#define TIMESTAMP_TYPE time_t
#define ACTIVITY_STATUS_TYPE char*

// Define structure to represent a user session
typedef struct {
    SESSION_ID_TYPE id;
    TIMESTAMP_TYPE start_time;
    TIMESTAMP_TYPE expire_time;
    TIMESTAMP_TYPE last_active;
    ACTIVITY_STATUS_TYPE status;
} Session;

// Define the session database and its corresponding lock
Session* sessions = NULL;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new session entry
void create_session(SESSION_ID_TYPE id, TIMESTAMP_TYPE start_time, TIMESTAMP_TYPE expire_time) {
    Session* new_session = (Session*)malloc(sizeof(Session));
    if (!new_session) {
        printf("Memory allocation failed.\n");
        return;
    }
    new_session->id = id;
    new_session->start_time = start_time;
    new_session->expire_time = expire_time;
    new_session->last_active = start_time;
    new_session->status = "active";
}

// Function to update a session's activity status
void update_session_status(SESSION_ID_TYPE id, TIMESTAMP_TYPE last_active) {
    pthread_mutex_lock(&session_lock);
    Session* current_session = sessions;
    while (current_session && current_session->id != id)
        current_session = current_session + 1;
    if (current_session) {
        current_session->last_active = last_active;
        if (current_session->expire_time <= current_session->last_active)
            current_session->status = "inactive";
        else
            current_session->status = "active";
    }
    pthread_mutex_unlock(&session_lock);
}

// Function to delete a session entry based on the given ID
void delete_session(SESSION_ID_TYPE id) {
    pthread_mutex_lock(&session_lock);
    Session* current_session = sessions;
    Session* previous_session = NULL;
    while (current_session && current_session->id != id)
        if (!previous_session)
            previous_session = current_session;
        else
            current_session++;
    if (current_session) {
        if (previous_session)
            *(previous_session + 1) = *current_session;
        else
            sessions = current_session + 1;
        free(current_session);
    }
    pthread_mutex_unlock(&session_lock);
}

// Function to query a session entry based on the given ID
Session* query_session(SESSION_ID_TYPE id) {
    Session* current_session = sessions;
    while (current_session && current_session->id != id)
        current_session++;
    return current_session;
}

// Function to update expired sessions and send notifications asynchronously
void update_expired_sessions() {
    pthread_mutex_lock(&session_lock);
    Session* current_session = sessions;
    while (current_session) {
        if (current_session->expire_time <= current_session->last_active) {
            // Send notification here
            printf("Session %d has expired.\n", current_session->id);
            delete_session(current_session->id);
        }
        else
            current_session++;
    }
    pthread_mutex_unlock(&session_lock);
}

