import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class ThemeCache {
    private static final int DEFAULT_CACHE_SIZE = 100;
    private static final String DEFAULT_THEME_DIR = "default_theme";
    private Map<String, Bitmap> themeCache;
    private ExecutorService executor;
    private Logger logger;

    public ThemeCache() {
        themeCache = new ConcurrentHashMap<>();
        executor = Executors.newCachedThreadPool();
        logger = LoggerFactory.getLogger(ThemeCache.class);
    }

    public void initialize(String defaultThemeDir) {
        if (defaultThemeDir == null || !themeCache.containsKey(defaultThemeDir)) {
            defaultThemeDir = DEFAULT_THEME_DIR;
            themeCache.putIfAbsent(defaultThemeDir, loadDefaultTheme());
        }
    }

    public Bitmap getThemeBitmap(String themeName) {
        return themeCache.computeIfAbsent(themeName, this::loadTheme);
    }

    private Bitmap loadTheme(String themeName) {
        String themePath = getThemePath(themeName);
        try (InputStream is = new FileInputStream(themePath)) {
            return BitmapFactory.decodeStream(is);
        } catch (IOException e) {
            logger.error("Failed to load theme bitmap: {}", e.getMessage());
            return null;
        }
    }

    private String getThemePath(String themeName) {
        // Implement your own directory structure and file naming convention
        return "path/to/themes/" + themeName + ".png";
    }

    public void updateThemePreference(String oldTheme, String newTheme) {
        Bitmap oldBitmap = themeCache.remove(oldTheme);
        if (oldBitmap != null) {
            executor.submit(() -> {
                try (OutputStream os = new FileOutputStream(getThemePath(oldTheme))) {
                    bitmap.compress(Bitmap.CompressFormat.PNG, 100, os);
                } catch (IOException e) {
                    logger.error("Failed to save old theme bitmap: {}", e.getMessage());
                }
            });
        }
    }

    public void monitorCacheUsage() {
        // Implement your own cache usage monitoring and cleanup logic
        ScheduledExecutorService scheduledExecutor = Executors.newSingleThreadScheduledExecutor();
        scheduledExecutor.schedule(() -> {
            try (Iterator<String> iterator = themeCache.keySet().iterator()) {
                while (iterator.hasNext()) {
                    String themeName = iterator.next();
                    Bitmap bitmap = themeCache.get(themeName);
                    if (!bitmap.isInUse()) {
                        themeCache.remove(themeName);
                        logger.info("Cleaned up unused theme: {}", themeName);
                    }
                }
            } catch (Exception e) {
                logger.error("Error monitoring cache usage: {}", e.getMessage());
            }
        }, 1, TimeUnit.HOURS, TimeUnit.NANOSECONDS);

    }

    public void shutdown() {
        executor.shutdown();
        scheduledExecutor.shutdown();
    }
}
