#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array[MAX_ARRAY_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile = NULL;

void initArray(int size) {
    for (int i = 0; i < size; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }

        // Initialize structure fields
        array[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        array[i]->RNTI = rand() % 100;
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 100;
        array[i]->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1

        if (logFile != NULL) {
            fprintf(logFile, "Structure initialized: RX_UE_INFORMATION_TAG = %d, RNTI = %d, CRC_INDICATION_REL8_TAG = %d, CRCFLAG = %d\n", array[i]->RX_UE_INFORMATION_TAG, array[i]->RNTI, array[i]->CRC_INDICATION_REL8_TAG, array[i]->CRCFLAG);
        }
    }
}

void* threadFunc(void* arg) {
    int size = (int)arg;

    // Critical section: Access and modify the shared array
    pthread_mutex_lock(&mutex);
    initArray(size);
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    // Optional logging setup
    logFile = fopen("log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(1);
    }

    int numThreads = 5; // Number of threads to create

    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; i++) {
        int size = rand() % MAX_ARRAY_SIZE + 1;
        if (pthread_create(&threads[i], NULL, threadFunc, (void*)size) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            exit(1);
        }
    }

    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    fclose(logFile);

    return 0;
}

