#include <string.h>
#include <pthread.h>

// Define the structure for LTE_PHY_TEST_MESSAGE_T
typedef struct {
    int phy_test_message_type;
    int test_id;
    int result_status;
} LTE_PHY_TEST_MESSAGE_T;

// Define the structure for the list and its properties
typedef struct {
    LTE_PHY_TEST_MESSAGE_T* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} LTE_PHY_TEST_MESSAGE_LIST_T;

// Function to initialize the list
LTE_PHY_TEST_MESSAGE_LIST_T* lte_phy_test_message_list_init() {
    LTE_PHY_TEST_MESSAGE_LIST_T* list = (LTE_PHY_TEST_MESSAGE_LIST_T*)malloc(sizeof(LTE_PHY_TEST_MESSAGE_LIST_T));
    if (!list) return NULL;

    list->messages = NULL;
    list->capacity = 1;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    return list;
}

// Function to add a new message to the list
int lte_phy_test_message_list_add(LTE_PHY_TEST_MESSAGE_LIST_T* list, LTE_PHY_TEST_MESSAGE_T* message) {
    if (!list || !message) return -1;

    pthread_mutex_lock(&list->lock);

    // Reorganize memory pool periodically for better performance and memory efficiency
    if (list->count >= list->capacity * 0.75) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_TEST_MESSAGE_T** new_messages = (LTE_PHY_TEST_MESSAGE_T**)realloc(list->messages, sizeof(LTE_PHY_TEST_MESSAGE_T*) * new_capacity);
        if (!new_messages) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->capacity = new_capacity;
        list->messages = new_messages;
    }

    // Check for memory allocation failure
    LTE_PHY_TEST_MESSAGE_T** messages = (LTE_PHY_TEST_MESSAGE_T**)realloc(list->messages, sizeof(LTE_PHY_TEST_MESSAGE_T*) * (list->count + 1));
    if (!messages) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->messages = messages;

    // Update the count and memory pool
    list->messages[list->count] = message;
    ++list->count;

    pthread_cond_signal(&list->cond);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to get the number of elements in the list
size_t lte_phy_test_message_list_size(LTE_PHY_TEST_MESSAGE_LIST_T* list) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);

    size_t count = list->count;

    pthread_mutex_unlock(&list->lock);

    return count;
}

// Function to free the resources allocated for the list
void lte_phy_test_message_list_free(LTE_PHY_TEST_MESSAGE_LIST_T* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    // Free memory pool
    for (size_t i = 0; i < list->count; ++i)
        free(list->messages[i]);

    free(list->messages);

    pthread_cond_destroy(&list->cond);
    pthread_mutex_unlock(&list->lock);
}
