#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define EVENT_ATTRS 10
#define TEMPROXY 500 // temporal proximity in milliseconds

typedef struct {
    int priority;
    char* attributes[EVENT_ATTRS];
} EventRecord;

EventRecord** events = NULL;
int event_count = 0;
int max_events = MAX_EVENTS;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("event_log.txt", "a");

void merge_adjacent_events(int start, int end) {
    for (int i = start; i < end - 1; i++) {
        if ((events[i]->priority <= events[i + 1]->priority) && 
            (abs(events[i]->priority - events[i + 1]->priority) < TEMPROXY)) {
            EventRecord* merged_event = (EventRecord*)malloc(sizeof(EventRecord));
            memcpy(merged_event, &events[i], sizeof(EventRecord));
            for (int j = i; j < end; j++) {
                if (events[j]->priority > events[i]->priority) {
                    memcpy(&merged_event->attributes[EVENT_ATTRS - 1], 
                           &events[j]->attributes[0], 
                           EVENT_ATTRS * sizeof(char*));
                    break;
                }
            }
            // remove duplicate event
            for (int j = i; j < end; j++) {
                free(events[j]);
                events[j] = NULL;
            }
            events[i] = merged_event;
            event_count--;
        }
    }
}

void prune_obsolete_events() {
    int prune_start = 0;
    for (int i = 0; i < event_count; i++) {
        if (events[i]->priority > events[i + 1]->priority) {
            prune_start = i + 1;
            break;
        }
    }
    // log pruning operation
    fprintf(log_file, "Pruned %d events.\n", event_count - prune_start);
    for (int i = event_count; i >= prune_start; i--) {
        free(events[i]);
        events[i] = NULL;
    }
    event_count -= (event_count - prune_start);
}

void* process_events(void*) {
    while (1) {
        // check and merge adjacent events
        int start, end;
        for (start = 0; start < event_count; start++) {
            for (end = start + 1; end < event_count && 
                 (events[start]->priority == events[end]->priority); 
                 end++);
            merge_adjacent_events(start, end);
        }
        // check and prune obsolete events
        prune_obsolete_events();
    }
}

void event_log(const char* message) {
    fprintf(log_file, "%s\n", message);
}

int add_event(EventRecord* new_event) {
    pthread_mutex_lock(&mutex);
    if (event_count >= max_events) {
        max_events *= 2;
        events = realloc(events, max_events * sizeof(EventRecord*));
    }
    events[event_count] = new_event;
    event_count++;
    pthread_mutex_unlock(&mutex);
    return event_count - 1; // return the index of newly added event
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_events, NULL);

    // add and manage events
    EventRecord* new_event = (EventRecord*)malloc(sizeof(EventRecord));
    new_event->priority = 5;
    new_event->attributes[0] = "Attribute1";
    new_event->attributes[1] = "Attribute2";
    int event_index = add_event(new_event);
    printf("Added event at index %d.\n", event_index);

    // free allocated memory
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < event_count; i++) {
        free(events[i]);
    }
    free(events);
    events = NULL;
    event_count = 0;
    max_events = MAX_EVENTS;
    pthread_mutex_unlock(&mutex);

    return 0;
}

