// Define the structure for event records
typedef struct {
    int priority;
    char* type;
    void* attributes;
} EventRecord;

// Define the structure for the event storage system
typedef struct {
    EventRecord* events;
    int size;
    int capacity;
    pthread_mutex_t mutex; // Mutex for thread-safe operations
} EventStorage;

// Function to initialize the event storage system
EventStorage* init_event_storage(int initial_capacity) {
    EventStorage* es = (EventStorage*)malloc(sizeof(EventStorage));
    es->events = (EventRecord*)malloc(initial_capacity * sizeof(EventRecord));
    es->size = 0;
    es->capacity = initial_capacity;
    pthread_mutex_init(&es->mutex, NULL);
    return es;
}

// Function to add a new event record
void add_event(EventStorage* es, int priority, const char* type, void* attributes) {
    pthread_mutex_lock(&es->mutex);

    if (es->size >= es->capacity) {
        // Dynamically resize the event storage if full
        es->events = (EventRecord*)realloc(es->events, (es->capacity * 2) * sizeof(EventRecord));
        es->capacity *= 2;
    }

    EventRecord* new_event = &es->events[es->size++];
    new_event->priority = priority;
    new_event->type = strdup(type);
    new_event->attributes = attributes;

    pthread_mutex_unlock(&es->mutex);
}

// Function to remove an event record
void remove_event(EventStorage* es, int index) {
    pthread_mutex_lock(&es->mutex);

    if (index < 0 || index >= es->size) {
        // Handle invalid index
    } else {
        EventRecord* last_event = &es->events[--es->size];
        memmove(&es->events[index], &es->events[index + 1], (es->size - index) * sizeof(EventRecord));
        free(last_event->type);
        free(last_event->attributes);
        free(last_event);
    }

    pthread_mutex_unlock(&es->mutex);
}

