int nrbpf_collection_insert(NRBPF_COLLECTION_T* collection, NRBPF_PACKET_T packet) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->packets->size) {
        // Reallocation of memory required
        int new_size = collection->size * 2 + 1;
        NRBPF_PACKET_T* new_packets = (NRBPF_PACKET_T*)realloc(collection->packets, new_size * sizeof(NRBPF_PACKET_T));
        if (!new_packets) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // memory allocation failed
        }
        collection->packets = new_packets;
    }
    NRBPF_PACKET_T* packet_ptr = &collection->packets[collection->size];
    *packet_ptr = packet;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
    return 0; // successful insertion
}

// Function to sort the packets in ascending order based on integer values
void nrbpf_collection_sort(NRBPF_COLLECTION_T* collection) {
    qsort(collection->packets, collection->size, sizeof(NRBPF_PACKET_T), (int (*)(const void*, const void*))compare_packets);
}

// Comparison function for sorting packets
int compare_packets(const void* a, const void* b) {
    NRBPF_PACKET_T packet1 = *(NRBPF_PACKET_T*)a;
    NRBPF_PACKET_T packet2 = *(NRBPF_PACKET_T*)b;
    if (packet1.ue_context_info.integer_value < packet2.ue_context_info.integer_value) {
        return -1; // a comes before b
    } else if (packet1.ue_context_info.integer_value > packet2.ue_context_info.integer_value) {
        return 1; // a comes after b
    } else {
        return 0; // a and b have equal integer values, maintaining stability in the sort
    }
}

// Function to verify the integrity of the populated packets using a checksum or similar technique
void nrbpf_collection_verify(NRBPF_COLLECTION_T* collection) {
