    double TRANSMISSION_POWER;
} LTE_RRC_CTR_TX_INFO_T;

// Define the linked list structure
typedef struct {
    LTE_RRC_CRT_TX_INFO_T* head;
    LTE_RRC_CRT_TX_INFO_T* tail;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new node with random transmission power
LTE_RRC_CRT_TX_INFO_T* create_node(int CELL_ID, int MME_ID, int PHY_LAYER_STATUS) {
    LTE_RRC_CRT_TX_INFO_T* node = (LTE_RRC_CRT_TX_INFO_T*)malloc(sizeof(LTE_RRC_CRT_TX_INFO_T));
    if (node != NULL) {
        node->CELL_ID = CELL_ID;
        node->MME_ID = MME_ID;
        node->PHY_LAYER_STATUS = PHY_LAYER_STATUS;
        node->TRANSMISSION_POWER = (double)rand() / RAND_MAX;
    }
    return node;
}

// Function to initialize the linked list
void init_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to add a new element to the end of the list
void add_element(LinkedList* list, LTE_RRC_CRT_TX_INFO_T* node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to remove an element from the list
void remove_element(LinkedList* list, LTE_RRC_CRT_TX_INFO_T* node) {
    pthread_mutex_lock(&list->lock);

    if (node == list->head) {
        list->head = node->next;
    }

    if (node == list->tail) {
        list->tail = node->prev;
    }

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free all allocated memory
void free_list(LinkedList* list) {
    LTE_RRC_CRT_TX_INFO_T* current = list->head;
    LTE_RRC_CRT_TX_INFO_T* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
}
