#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SESSIONS 1000
#define SESSION_ID_LENGTH 20
#define ACTIVITY_LOG_LENGTH 500

typedef struct {
    int session_id;
    char start_timestamp[SESSION_ID_LENGTH];
    char activity_log[ACTIVITY_LOG_LENGTH];
} Session;

Session* sessions = NULL;
int num_sessions = 0;
int max_sessions = MAX_SESSIONS;

void initialize_sessions() {
    if (num_sessions > max_sessions) {
        // Dynamic resizing
        max_sessions *= 2;
        sessions = (Session*) realloc(sessions, sizeof(Session) * max_sessions);
    }
}

Session* get_session(int session_id) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            return &sessions[i];
        }
    }
    return NULL;
}

void add_session(Session new_session) {
    initialize_sessions();
    sessions[num_sessions] = new_session;
    num_sessions++;
}

void update_session(int session_id, Session updated_session) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            sessions[i] = updated_session;
            return;
        }
    }
}

void remove_session(int session_id) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            // Shift the remaining sessions down
            memmove(&sessions[i], &sessions[i + 1], sizeof(Session) * (num_sessions - i - 1));
            num_sessions--;
            return;
        }
    }
}

void sort_sessions() {
    qsort(sessions, num_sessions, sizeof(Session), compare_sessions);
}

int compare_sessions(const void* a, const void* b) {
    Session* sa = (Session*) a;
    Session* sb = (Session*) b;

    // Sort by start timestamp
    return strcmp(sa->start_timestamp, sb->start_timestamp);
}

void handle_error() {
    fprintf(stderr, "Error: %s\n", strerror(errno));
    exit(1);
}
