// Lock for synchronization
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Hash table to store NFAPI_CRC_INDICATION_PDU_T instances
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
} NFAPI_CRC_INDICATION_PDU_T_HT;

