void insert_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&lock);

    if (nfaPI_CRC_INDICATION_PDU_HT.size >= nfaPI_CRC_INDICATION_PDU_HT.capacity) {
        // Re-allocate the array with double size
        NFAPI_CRC_INDICATION_PDU_HT* old = &nfaPI_CRC_INDICATION_PDU_HT;
        int new_capacity = old->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_HT* new_array = (NFAPI_CRC_INDICATION_PDU_HT*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_HT));
        new_array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_array->size = 0;
        new_array->capacity = new_capacity;

        if (old->data) {
            // Copy the elements from old to new
            for (int i = 0; i < old->size; i++) {
                new_array->data[i] = old->data[i];
            }

            free(old->data);
        }

        free(old);
        *old = *new_array;
    }

    // Check for duplicate RNTI
    int found = 0;
    for (int i = 0; i < nfaPI_CRC_INDICATION_PDU_HT.size; i++) {
        if ((nfaPI_CRC_INDICATION_PDU_HT.data[i].RNTI == new_element->RNTI) &&
            (nfaPI_CRC_INDICATION_PDU_HT.data[i].RX_UE_INFORMATION_TAG == new_element->RX_UE_INFORMATION_TAG)) {
            found = 1;
            break;
        }
    }

    if (!found) {
        // Insert new element
        nfaPI_CRC_INDICATION_PDU_HT.data[nfaPI_CRC_INDICATION_PDU_HT.size] = *new_element;
        (nfaPI_CRC_INDICATION_PDU_HT.tag_count)++;
        nfaPI_CRC_INDICATION_PDU_HT.size++;
    } else {
        // Update count for existing element
        (nfaPI_CRC_INDICATION_PDU_HT.data[found].tag_count)++;
    }

    pthread_mutex_unlock(&lock);
}

void* get_NFAPI_CRC_INDICATION_PDU_T(int RNTI, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < nfaPI_CRC_INDICATION_PDU_HT.size; i++) {
        if ((nfaPI_CRC_INDICATION_PDU_HT.data[i].RNTI == RNTI) &&
            (nfaPI_CRC_INDICATION_PDU_HT.data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG)) {
            pthread_mutex_unlock(&lock);
            return &nfaPI_CRC_INDICATION_PDU_HT.data[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void validate_NFAPI_CRC_INDICATION_PDU_HT() {
