    if (!data) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }
    data->capacity = capacity;
    data->readings = (SensorReading*)calloc(capacity, sizeof(SensorReading));
    if (!data->readings) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(data);
        return NULL;
    }
    data->num_readings = 0;
    pthread_mutex_init(&data->lock, NULL);
    return data;
}

// Function to process and aggregate sensor data
void processAndAggregateSensorData(SensorData* data, int num_new_readings, double** measurement_values) {
    pthread_mutex_lock(&data->lock); // Lock for thread-safe access

    // Add new readings to the collection
    if (data->num_readings + num_new_readings > data->capacity) {
        size_t new_capacity = data->capacity * 2;
        SensorReading* new_readings = (SensorReading*)realloc(data->readings, new_capacity * sizeof(SensorReading));
        if (!new_readings) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            pthread_mutex_unlock(&data->lock);
            return;
        }
        data->capacity = new_capacity;
        data->readings = new_readings;
    }
    memcpy(data->readings + data->num_readings, measurement_values[0], num_new_readings * sizeof(SensorReading));

    // Aggregate and process the sensor readings
    pthread_mutex_unlock(&data->lock); // Unlock for thread-safe access

    // ... (aggregate and process logic goes here)
