#define LRU_LIST_SIZE 1000

typedef struct {
    char remote_ip[16];
    uint16_t remote_port;
    char local_ip[16];
    uint16_t local_port;
    uint32_t bytes_sent;
    uint32_t bytes_received;
    uint32_t last_activity_timestamp;
} TCP_CONNECTION_STATS_T;

typedef struct {
    TCP_CONNECTION_STATS_T stats;
    struct list_node* next;
} LRU_LIST_NODE_T;

typedef struct {
    LRU_LIST_NODE_T* head;
    LRU_LIST_NODE_T* tail;
    pthread_mutex_t lock;
} LRU_LIST_T;

void lru_list_init(LRU_LIST_T* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
}

void lru_list_free(LRU_LIST_T* list) {
    LRU_LIST_NODE_T* current = list->head;
    LRU_LIST_NODE_T* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void lru_list_insert(LRU_LIST_T* list, TCP_CONNECTION_STATS_T* stats) {
    LRU_LIST_NODE_T* new_node = (LRU_LIST_NODE_T*)malloc(sizeof(LRU_LIST_NODE_T));
    new_node->stats = *stats;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

TCP_CONNECTION_STATS_T* lru_list_remove(LRU_LIST_T* list) {
    TCP_CONNECTION_STATS_T* stats = NULL;
    LRU_LIST_NODE_T* current = list->head;

    pthread_mutex_lock(&list->lock);
    if (current != NULL) {
        stats = &current->stats;
        list->head = current->next;
        free(current);
        if (list->head == NULL)
            list->tail = NULL;
    }
    pthread_mutex_unlock(&list->lock);

    return stats;
}

void hash_table_init(void** hash_table, int size) {
    *hash_table = (TCP_CONNECTION_STATS_T**)malloc(size * sizeof(TCP_CONNECTION_STATS_T*));
    for (int i = 0; i < size; i++) {
        (*hash_table)[i] = NULL;
    }
}

void hash_table_free(void** hash_table, int size) {
    for (int i = 0; i < size; i++) {
        free((*hash_table)[i]);
    }
    free(*hash_table);
}

TCP_CONNECTION_STATS_T* hash_table_insert(void** hash_table, int size, TCP_CONNECTION_STATS_T* stats) {
    int index = stats->remote_port % size;
    pthread_mutex_lock(&((*hash_table)[index]->lock));
    if ((*hash_table)[index] == NULL) {
        (*hash_table)[index] = (TCP_CONNECTION_STATS_T*)malloc(sizeof(TCP_CONNECTION_STATS_T));
        memcpy(*hash_table, &stats, sizeof(TCP_CONNECTION_STATS_T));
    } else {
        memcpy(*hash_table[index], stats, sizeof(TCP_CONNECTION_STATS_T));
    }
    pthread_mutex_unlock(&((*hash_table)[index]->lock));

    return *hash_table[index];
}

TCP_CONNECTION_STATS_T* hash_table_remove(void** hash_table, int size, TCP_CONNECTION_STATS_T* stats) {
    int index = stats->remote_port % size;
    pthread_mutex_lock(&((*hash_table)[index]->lock));
    free(*hash_table[index]);
    (*hash_table)[index] = NULL;
