```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define ENTRY_SIZE 64
#define LRU_TIMEOUT 300 // seconds

typedef struct {
    int SESSION_ID;
    char USERNAME[16];
    time_t LOGIN_TIME;
    time_t LOGOUT_TIME;
    time_t ACTIVE_TIME;
    char LAST_ACCESS_IP[20];
} USER_SESSION_INFO_T;

struct node {
    USER_SESSION_INFO_T entry;
    struct node* prev;
    struct node* next;
};

typedef struct node NODE_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NODE_T* head = NULL;
NODE_T* tail = NULL;
int entries_count = 0;

void init_list() {
    head = NULL;
    tail = NULL;
    entries_count = 0;
}

NODE_T* create_node(USER_SESSION_INFO_T entry) {
    NODE_T* new_node = (NODE_T*)malloc(sizeof(NODE_T));
    if (!new_node) {
        printf("Memory allocation failed for a new node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->entry = entry;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void free_list() {
    NODE_T* current = head;
    NODE_T* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
}

void insert_node(USER_SESSION_INFO_T entry) {
    pthread_mutex_lock(&lock);

    if (!head) {
        head = create_node(entry);
        tail = head;
    } else {
        NODE_T* new_node = create_node(entry);
        new_node->next = NULL;

        if (entries_count == 0 || entry.ACTIVE_TIME > head->entry.ACTIVE_TIME) {
            new_node->prev = NULL;
            head->prev = new_node;
            head = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    entries_count++;

    pthread_mutex_unlock(&lock);
}

void delete_node(int SESSION_ID) {
    pthread_mutex_lock(&lock);

    NODE_T* current = head;
    while (current) {
        if (current->entry.SESSION_ID == SESSION_ID) {
            if (current == head) {
                head = current->next;
                if (!head) {
                    tail = NULL;
                } else {
                    head->prev = NULL;
                }
            } else if (current == tail) {
                tail = current->prev;
                tail->next = NULL;
            } else {
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }

            free(current);
            entries_count--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void* iterate_list(void* arg) {
    NODE_T* current = head;

    while (current) {
        // process node entry
        printf("Iteration: SESSION_ID=%d, USERNAME=%s, ACTIVE_TIME=%ld\n", 
               current->entry.SESSION_ID, current->entry.USERNAME, current->entry.ACTIVE_TIME);
        current = current->next;
    }

    return NULL;
}

void evict_lru() {
    pthread_mutex_lock(&lock);

    if (entries_count > 0) {
        NODE_T* lru_node = head;

        while (lru_node && lru_node->next) {
            if (lru_node->entry.ACTIVE_TIME < lru_node->next->entry.ACTIVE_TIME) {
                lru_node = lru_node->next;
            } else {
                NODE_T* to_evict = lru_node;
                lru_node = lru_node->next;

                if (to_evict == head) {
                    head = to_evict->next;
                    if (!head) {
                        tail = NULL;
                    } else {
                        head->prev = NULL;
                    }
                } else if (to_evict == tail) {
                    tail = to_evict->prev;
                    tail->next = NULL;
                } else {
                    to_evict->prev->next = to_evict->next;
                    to_evict->next->prev = to_evict->prev;
                }

                free(to_evict);
                entries_count--;
            }
        }
    }

    pthread_mutex_unlock(&lock);
}

void check_timeout() {
    pthread_mutex_lock(&lock);

    NODE_T* current = head;

    while (current) {
        if ((time(NULL) - current->entry.ACTIVE_TIME) > LRU_TIMEOUT) {
            delete_node(current->entry.SESSION_ID);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
