typedef struct {
    int timestamp;
    int sensor_id;
    double raw_measurement;
} SensorReading;

SensorReading* readings = NULL;
int num_readings = 0;
sem_t read_write_lock;

void processAndAggregateSensorData(int new_timestamp, int new_sensor_id, double new_raw_measurement) {
    SensorReading new_reading = {new_timestamp, new_sensor_id, new_raw_measurement};

    sem_wait(&read_write_lock);
    // Critical section starts here
    if (num_readings >= MAX_READINGS) {
        printf("Error: Maximum number of readings reached!\n");
        exit(1);
    }

    readings[num_readings++] = new_reading;
    // Critical section ends here
    sem_post(&read_write_lock);

    // Check for anomalies in the data
    if (new_raw_measurement > 100.0) {
        printf("Anomaly detected: Raw measurement %f is too high!\n", new_raw_measurement);
    }
}

int main() {
    pthread_t threads[MAX_READINGS];
    int thread_id = 0;

    sem_init(&read_write_lock, 0, 1);

    for (int i = 0; i < MAX_READINGS; i++) {
        SensorReading temp_reading;
        // Simulate sensor data
        temp_reading.timestamp = i + 1;
        temp_reading.sensor_id = i % 2 ? 1 : 0;
        temp_reading.raw_measurement = (double)i / 100.0;

        pthread_create(&threads[thread_id], NULL, processAndAggregateSensorData, &temp_reading);
        thread_id++;
    }

    for (int i = 0; i < MAX_READINGS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&read_write_lock);

    return 0;
}
