    int key;
    int value;
} record;

record* create_records(int n, int *keys, long *offsets) {
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        records[i].key = keys[i];
        records[i].value = rand() % 100;
    }
    return records;
}

typedef struct {
    int size;
    record** buckets;
} hashmap;

hashmap* create_hashmap(int size) {
    hashmap* hm = (hashmap*)malloc(sizeof(hashmap));
    if (!hm) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    hm->size = 1000; // Initial size
    hm->buckets = (record**)malloc(hm->size * sizeof(record*));
    for (int i = 0; i < hm->size; i++) {
        hm->buckets[i] = NULL;
    }
    return hm;
}

void insert_record(hashmap* hm, int key, record* rec) {
    int index = key % hm->size;
    if (!hm->buckets[index]) {
        hm->buckets[index] = (record*)malloc(sizeof(record));
        hm->buckets[index]->key = key;
        hm->buckets[index]->value = rec->value;
    } else {
        record* current = hm->buckets[index];
        while (current) {
            if (current->key == key) {
                free(current);
                current = NULL;
                break;
            }
            current = current->next;
        }
        if (!current) {
            record* new_rec = (record*)malloc(sizeof(record));
            new_rec->key = key;
            new_rec->value = rec->value;
            new_rec->next = hm->buckets[index];
            hm->buckets[index] = new_rec;
        }
    }
}

void print_hashmap(hashmap* hm) {
    for (int i = 0; i < hm->size; i++) {
        if (hm->buckets[i]) {
            record* current = hm->buckets[i];
            while (current) {
                printf("Key: %d, Value: %d\n", current->key, current->value);
                current = current->next;
            }
        }
    }
}

void init_hashmap(hashmap* hm, int n, int *keys, long *offsets) {
    for (int i = 0; i < n; i++) {
        record* rec = create_records(1, &keys[i], &offsets[i]);
        insert_record(hm, keys[i], rec);
    }
}

void free_hashmap(hashmap* hm) {
    for (int i = 0; i < hm->size; i++) {
        if (hm->buckets[i]) {
            record* current = hm->buckets[i];
            while (current) {
                record* temp = current;
                current = current->next;
                free(temp);
            }
        }
    }
    free(hm->buckets);
    free(hm);
}

int main() {
    int n = 100; // Number of records
    int *keys = malloc(n * sizeof(int));
    long *offsets = malloc(n * sizeof(long));
    srand(time(NULL)); // Seed random number generator

    hashmap* hm = create_hashmap(10); // Create a hashmap with initial size 10

    for (int i = 0; i < n; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand() * 1000 + i; // Generate random offset values
    }

    init_hashmap(hm, n, keys, offsets); // Initialize the hashmap

    print_hashmap(hm); // Print the contents of the hashmap

    free_hashmap(hm); // Free the memory allocated for the hashmap

    return 0;
}
