    // Initialize memory pool
    void* memory_pool = malloc(config->initial_size);
    if (!memory_pool) {
        printf("Error: Unable to allocate initial memory block.\n");
        return NULL;
    }

    // Initialize connections array
    NETWORK_CONNECTION_T** connections = (NETWORK CONNECTION_T**)malloc(config->initial_size * sizeof(NETWORK_CONNECTION_T*));
