#define MAX_REQUESTS 1000
#define MAX_METHODS 10
#define MAX_URLS 20
#define BODY_SIZE_RANGE 1024

typedef enum {
    GET,
    POST,
    PUT,
    DELETE,
    HEAD,
    OPTIONS,
    CONNECT,
    PATCH,
    HTTP_INVALID
} http_method_t;

typedef struct {
    char method;
    char *url;
    char *header;
    size_t body_size;
} http_request_t;

http_request_t **requests = NULL;
int request_count = 0;

void log_event(const char *event, int level) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    printf("[%02d:%02d] [Thread ID: %lu] [Level: %d] %s\n", tm.tm_hour, tm.tm_min, (long unsigned)pthread_self(), level, event);
}

void initialize_request(http_request_t *request, int request_index) {
    static char valid_methods[] = {"GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "CONNECT", "PATCH"};
    static int num_methods = sizeof(valid_methods) / sizeof(char *);

    for (int i = 0; i < num_methods; ++i) {
        request->method = valid_methods[i][0];
        if (rand() % 10 > 5) {
            break;
        }
    }

    char *url_schemes[] = {"http://", "https://"};
    static int num_url_schemes = sizeof(url_schemes) / sizeof(char *);

    for (int i = 0; i < num_url_schemes; ++i) {
        request->url = malloc(strlen(url_schemes[i]) + strlen("example.com") + strlen("/path/to/resource"));
        strcpy(request->url, url_schemes[i]);
        strcat(strcat(request->url, "example.com"), "/path/to/resource");
    }

    char *valid_headers[] = {"Content-Type: text/plain", "Accept-Language: en-US"};
    static int num_headers = sizeof(valid_headers) / sizeof(char *);

    for (int i = 0; i < num_headers; ++i) {
        request->header = malloc(strlen(valid_headers[i]) + 1);
        strcpy(request->header, valid_headers[i]);
    }

    request->body_size = rand() % BODY_SIZE_RANGE;
}

void validate_request(http_request_t *request) {
    static char *invalid_methods[] = {"FOO", "BAR"};
    static int num_invalid_methods = sizeof(invalid_methods) / sizeof(char *);

    for (int i = 0; i < num_invalid_methods; ++i) {
        if (strcmp(request->method, invalid_methods[i]) == 0) {
            log_event("Invalid HTTP method: ", ERROR);
            break;
        }
    }

    static char *invalid_urls[] = {"http://example.com/path/to/does/not/exist"};
    static int num_invalid_urls = sizeof(invalid_urls) / sizeof(char *);

    for (int i = 0; i < num_invalid_urls; ++i) {
        if (strncmp(request->url, "http://example.com", strlen("http://example.com")) == 0) {
            log_event("Malformed URL: ", ERROR);
            break;
        }
    }
}

void free_request(http_request_t *request) {
    free(request->url);
    free(request->header);
}

int allocate_requests(int num_requests) {
    int i;
    http_request_t **new_requests = malloc(num_requests * sizeof(http_request_t *));
    for (i = 0; i < num_requests; ++i) {
        new_requests[i] = malloc(sizeof(http_request_t));
        initialize_request(new_requests[i], i);
    }
    free(requests);
    requests = new_requests;
    request_count = num_requests;
    return 1;
}

void deallocate_requests() {
    for (int i = 0; i < request_count; ++i) {
        free_request(requests[i]);
    }
    free(requests);
    request_count = 0;
}
