int create_crc_indication_pdu_array(int n, NFAPI_CRC_INDICATION_PDU_T** pdu_array) {
    if (n <= 0) {
        *pdu_array = NULL;
        return 0; // Successful allocation
    }

    *pdu_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_array == NULL) {
        printf("Error: Memory allocation failed.\n");
        return -1; // Memory allocation failure
    }

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < n; i++) {
        (*pdu_array)[i].RX_UE_INFORMATION_TAG = i % 256;
        (*pdu_array)[i].RNTI = rand() % 65536;

        if ((*pdu_array)[i].RNTI > (n - 1)) {
            // Ensure no two RNTI values are the same
            (*pdu_array)[i].RX_UE_INFORMATION_TAG++;
        }

        (*pdu_array)[i].CRC_INDICATION_REL8_TAG[0] = rand() % 256;
        (*pdu_array)[i].CRC_INDICATION_REL8_TAG[1] = (rand() % 2) ? 0x01 : 0x00; // Randomly set CRCFLAG
    }

    return n; // Successful allocation and population
}

