#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 1000
#define MAX_MTU_SIZE 1500

typedef struct {
    int rnti;
    char rx_ue_info_tag[20];
    int crcflag;
    int crc_indication_rel8_tag;
} network_interface_t;

network_interface_t *interfaces = NULL;
int num_interfaces = 0;
pthread_mutex_t interfaces_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && size > 0) {
        ptr = valloc(size);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int init_interfaces(int rnti_value) {
    interfaces = (network_interface_t*)my_malloc(MAX_INTERFACES * sizeof(network_interface_t));
    if (interfaces == NULL) {
        return -1;
    }
    num_interfaces = 0;
    for (int i = 0; i < MAX_INTERFACES; i++) {
        interfaces[i].rnti = rnti_value;
    }
    return 0;
}

void add_interface(int rnti, char* rx_ue_info_tag, int crcflag, int crc_indication_rel8_tag) {
    pthread_mutex_lock(&interfaces_lock);
    if (num_interfaces >= MAX_INTERFACES) {
        printf("Error: Maximum number of interfaces reached.\n");
        return;
    }
    interfaces[num_interfaces].rnti = rnti;
    strcpy(interfaces[num_interfaces].rx_ue_info_tag, rx_ue_info_tag);
    interfaces[num_interfaces].crcflag = crcflag;
    interfaces[num_interfaces].crc_indication_rel8_tag = crc_indication_rel8_tag;
    num_interfaces++;
    pthread_mutex_unlock(&interfaces_lock);
}

void update_mtu(int index, int new_size) {
    if (index >= 0 && index < num_interfaces) {
        pthread_mutex_lock(&interfaces_lock);
        if (new_size > MAX_MTU_SIZE) {
            printf("Error: MTU size exceeds maximum limit.\n");
        } else {
            interfaces[index].crc_indication_rel8_tag = new_size;
        }
        pthread_mutex_unlock(&interfaces_lock);
    } else {
        printf("Error: Invalid index for MTU update.\n");
    }
}

void log_change(char* log_level, char* message) {
    pthread_mutex_lock(&log_lock);
    if (log_file == NULL) {
        printf("%s: %s\n", log_level, message);
    } else {
        fprintf(log_file, "%s: %s\n", log_level, message);
    }
    pthread_mutex_unlock(&log_lock);
}

int main() {
    int rnti_value = 12345;
    init_interfaces(rnti_value);

    // Test add_interface function
    add_interface(11111, "abc", 1, 0xdeadbeef);
    add_interface(22222, "def", 2, 0xdeadbabe);

    // Update MTU size for the first interface
    update_mtu(0, 1472);

    // Log a message
    log_change("INFO", "Network configuration updated.");

    return 0;
}

