async function asyncReduce(arr, initialValue, callback) {
  // ...
  try {
    const result = await asyncReduce(numbers, initialValue, callback);
    console[logLevel](`Final result: ${result}`);
  } catch (error) {
    console.error('Error:', error);
  }
}
