async function reduceArray(numbers, initial, callback) {
  const config = {
    concurrency: 5,
    cacheTTL: 30000,
    apiTimeout: 2000,
    retries: 3,
  };

  try {
    let accumulated = initial;
    for await (const num of numbers) {
      if (!config.concurrency--) {
        throw new Error('Concurrency limit reached');
      }
      const result = await callback(accumulated, num);
      accumulated = result;
    }
    return accumulated;

  } catch (error) {
    console.error(error.message || 'Error during reduction');
    return undefined;
  }
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initial = 0;
const callback = async (acc, num) => acc + num;

async function fetchData(id) {
  // Simulate API call
  await new Promise((resolve) =>
    setTimeout(() => resolve({ data: `Data for ${id}` }), 1000)
  );
}

reduceArray(numbers, initial, async (acc, num) => {
  if (num % 2 === 0) {
    const data = await fetchData(num);
    return acc + data.data.length;
  }
  return acc + num;
});
