async function robustReduce(arr, initValue, callback, config = {}) {
  const { retries = 3, cacheExpiration = 3600, errorHandler } = config;
  let cachedResult = null;

  if (cacheExpiration > 0 && window.localStorage.getItem('robustReduceCache')) {
    try {
      const cachedData = JSON.parse(window.localStorage.getItem('robustReduceCache'));
      if (!cachedData || Date.now() - cachedData.timestamp > cacheExpiration * 1000) {
        throw new Error('Invalid cache data');
      }
      return cachedResult = callback(initValue, arr[0], { context: 'cache' });
    } catch (error) {
      console.error(error);
      // Try to recover from invalid cache data
      await setTimeout(() => null, 500); // Wait for a bit before retrying
    }
  }

  try {
    for await (const num of arr) {
      let result = callback(cachedResult || initValue, num, { context: 'normal' });
      if (!result && errorHandler) {
        throw new Error('Error during reduction');
      }
      cachedResult = result;
    }
  } catch (error) {
    if (retries > 0 && errorHandler) {
      try {
        await errorHandler(error);
      } catch (newError) {
        // Rethrow the original error if the retry handler fails
        throw newError;
      }
    } else {
      throw error;
    }
  } finally {
    if (cachedResult && cacheExpiration > 0) {
      window.localStorage.setItem('robustReduceCache', JSON.stringify({ result: cachedResult, timestamp: Date.now() }));
    }
  }

  return cachedResult;
}
