import json
import redis
from collections import OrderedDict
from functools import lru_cache
from threading import Lock, Thread
from queue import Queue

class ProfileCache:
    def __init__(self, host='localhost', port=6379, db=0):
        self.redis = redis.Redis(host=host, port=port, db=db)
        self.cache = OrderedDict()
        self.lock = Lock()

    @lru_cache(maxsize=None)
    def get(self, profile_id):
        return json.loads(self.redis.get(profile_id).decode('utf-8')) if self.redis.exists(profile_id) else None

    def set(self, profile_id, data):
        with self.lock:
            self.cache[profile_id] = data
            self.redis.set(profile_id, json.dumps(data).encode('utf-8'))

    def update(self, profile_id, key, value):
        current_data = self.get(profile_id)
        if current_data is not None:
            current_data[key] = value
            self.set(profile_id, current_data)

    def delete(self, profile_id):
        with self.lock:
            self.cache.pop(profile_id, None)
            self.redis.delete(profile_id)

class ProfileProcessor:
    def __init__(self, cache, api_url, concurrency=5):
        self.cache = cache
        self.api_queue = Queue()
        self.concurrent_tasks = concurrency

        self.tasks = []
        for _ in range(concurrency):
            t = Thread(target=self.process_api_request)
            t.daemon = True
            t.start()

    def enqueue_api_request(self, profile_id):
        self.api_queue.put(profile_id)

    def process_api_request(self):
        while True:
            profile_id = self.api_queue.get()
            try:
                api_data = requests.get(f'{api_url}/{profile_id}').json()
                if api_data is not None:
                    self.cache.set(profile_id, api_data)
            except Exception as e:
                logging.error(f'Failed to retrieve data for {profile_id}: {str(e)}')
            finally:
                self.api_queue.task_done()

    def start(self):
        while True:
            self.tasks = [self.api_queue.get() for _ in range(self.concurrent_tasks)]
            if not all([t.is_alive() for t in self.tasks]):
                break
        self.api_queue.join()
