    // Initialize the timestamp for logging
    time_t start_time = time(NULL);

    for (int i = 0; i < 100; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!structure) {
            deallocate_memory(array, 100 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            return 1;
        }

        // Set the CRCFLAG randomly
        struct timespec spec;
        clock_gettime(CLOCK_REALTIME, &spec);
        int random_number = (int)(spec.tv_nsec % RAND_MAX);

        structure->RX_UE_INFORMATION_TAG = i;
        structure->RNTI = i + 1000; // Ensure uniqueness of RNTI values across different network slices
        structure->CRC_INDICATION_REL8_TAG = i * 2; // Randomly set CRC_INDICATION_REL8_TAG value

        int j = rand_r(&random_number) % 5;
        if (j > 1)
            structure->CRCFLAG = 0; // Randomly set CRCFLAG to 0 or 1
        else
            structure->CRCFLAG = 1;

