    }

    // Reuse previously allocated memory whenever possible
    for (int i = 0; i < 100; i++) {
        if (!array[i]) continue;

        // Switch between different network slices dynamically
        array[i]->RX_UE_INFORMATION_TAG += 10;
        array[i]->RNTI++;
    }

    // Periodically clean up unused memory using a garbage collection mechanism
    for (int i = 0; i < 100; i++) {
        if (!array[i]) continue;

        deallocate_memory(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    deallocate_memory(array, 100 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    printf("Memory deallocated successfully.\n");

    return 0;
}
