use log::{info, warn};
use parking_lot::RwLock;
use std::{
    collections::{HashMap, VecDeque},
    error::Error,
    sync::atomic::{AtomicUsize, Ordering},
};

struct DataPipelineBuilder {
    stages: Vec<RwLock<Box<dyn FnMut(&mut Vecdeque) + '_>>>,
    memory_pool: Arc<MemoryPool>,
}

impl DataPipelineBuilder {
    fn new(memory_pool: Arc<MemoryPool>) -> Self {
        DataPipelineBuilder {
            stages: vec![],
            memory_pool,
        }
    }

    fn add_stage(mut self, stage: impl FnMut(&mut Vecdeque) + '_)
    -> Result<Self, Box<dyn Error>>
    {
        let mut stage_box = Box::new(stage);
        self.stages.push(RwLock::new(stage_box));
        Ok(self)
    }

    fn build_pipeline(self) -> DataPipeline {
        DataPipeline { stages: self.stages, memory_pool: self.memory_pool }
    }
}

struct MemoryPool {
    capacity: usize,
    buffer: VecDeque<u8>,
}

impl MemoryPool {
    fn new(capacity: usize) -> Self {
        MemoryPool { capacity, buffer: VecDeque::with_capacity(capacity) }
    }

    fn allocate(&self) -> Result<usize, Box<dyn Error>> {
        if self.buffer.len() >= self.capacity {
            warn!("Memory pool is full. Cannot allocate memory.");
            return Err("Memory allocation failure".into());
        }
        let len = self.buffer.capacity() - self.buffer.len();
        Ok(len)
    }

    fn deallocate(&self, len: usize) {
        if self.buffer.len() + len > self.capacity {
            warn!("Cannot deallocate. Memory pool is full.");
        } else {
            self.buffer.truncate(self.buffer.len() + len);
        }
    }
}

struct DataPipeline {
    stages: Vec<RwLock<Box<dyn FnMut(&mut Vecdeque) + '_>>>,
    memory_pool: Arc<MemoryPool>,
}

impl DataPipeline {
    fn process(&self, data: &mut Vecdeque) -> Result<(), Box<dyn Error>> {
        for stage in self.stages.iter() {
            let mut stage_box = stage.write();
            stage_box(data);
        }
        Ok(())
    }
}
