void init_mac_entities(MAC_E_CONTEXT** mac_entities, int num_entities) {
    // Create an array to hold the MAC entities
    *mac_entities = (MAC_E_CONTEXT*)malloc(num_entities * sizeof(MAC_E_CONTEXT));

    for (int i = 0; i < num_entities; i++) {
        (*mac_entities)[i].LCHAN_COUNT = (rand() % 10) + 1;
        (*mac_entities)[i].LCHAN_INDICATORS = (int*)malloc((*mac_entities)[i].LCHAN_COUNT * sizeof(int));
        (*mac_entities)[i].LCHAN_CONTROL_ELEMENTS = (char**)malloc((*mac_entities)[i].LCHAN_COUNT * sizeof(char*));

        for (int j = 0; j < (*mac_entities)[i].LCHAN_COUNT; j++) {
            // Initialize MAC PDU indicators and random MAC Control Elements
            (*mac_entities)[i].LCHAN_INDICATORS[j] = rand() % 10;
            (*mac_entities)[i].LCHAN_CONTROL_ELEMENTS[j] = (char*)malloc(20);
            sprintf((*mac_entities)[i].LCHAN_CONTROL_ELEMENTS[j], "CE_%d", j);
        }
    }
}

// Free an array of MAC Entity Contexts
void free_mac_entities(MAC_E_CONTEXT* mac_entities, int num_entities) {
    for (int i = 0; i < num_entities; i++) {
        if ((*mac_entities)[i].LCHAN_COUNT > 0) {
            for (int j = 0; j < (*mac_entities)[i].LCHAN_COUNT; j++) {
                free((*mac_entities)[i].LCHAN_CONTROL_ELEMENTS[j]);
                (*mac_entities)[i].LCHAN_CONTROL_ELEMENTS[j] = NULL;
            }
        }

        if ((*mac_entities)[i].LCHAN_INDICATORS != NULL) {
            free((*mac_entities)[i].LCHAN_INDICATORS);
            (*mac_entities)[i].LCHAN_INDICATORS = NULL;
        }
    }

    free(mac_entities);
}

