// Custom memory management functions
void* my_malloc(size_t size);
void my_free(void* ptr);

typedef struct {
    int key;
    long offset;
} record;

record* new_record(int key, long offset) {
    record* rec = (record*)my_malloc(sizeof(record));
    rec->key = key;
    rec->offset = offset;
    return rec;
}

// Linked list node
typedef struct Node {
    record* data;
    struct Node* next;
} Node;

Node* new_node(Node* next, record* data) {
    Node* node = (Node*)my_malloc(sizeof(Node));
    node->data = data;
    node->next = next;
    return node;
}

// Linked list
typedef struct LinkedList {
    Node* head;
    Node* tail;
} LinkedList;

LinkedList new_linked_list() {
    LinkedList ll = { NULL, NULL };
    return ll;
}

void add_record(LinkedList* list, record* data) {
    Node* node = (Node*)my_malloc(sizeof(Node));
    node->data = data;
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
}

record* find_record_by_key(LinkedList* list, int key) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data->key == key) {
            return current->data;
        }
        current = current->next;
    }
    return NULL; // not found
}

// Serialization
void serialize_record(record* rec, FILE* file) {
    fwrite(&rec->key, sizeof(int), 1, file);
    fwrite(&rec->offset, sizeof(long), 1, file);
}

void serialize_linked_list(LinkedList* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        serialize_record(current->data, file);
        current = current->next;
    }
}

// Deserialization
record* deserialize_record(FILE* file) {
    record* rec = (record*)my_malloc(sizeof(record));
    fread(&rec->key, sizeof(int), 1, file);
    fread(&rec->offset, sizeof(long), 1, file);
    return rec;
}

void deserialize_linked_list(LinkedList* list, FILE* file) {
    Node* current = NULL;
    while (1) {
        record* rec = deserialize_record(file);
        if (rec == NULL) break; // end of file
        add_record(list, rec);
    }
}

int main() {
    LinkedList list = new_linked_list();
    // Add records to the linked list
    // ...

    FILE* file = fopen("data.bin", "wb");
    serialize_linked_list(&list, file);
    fclose(file);

    file = fopen("data.bin", "rb");
    deserialize_linked_list(&list, file);
    fclose(file);

    return 0;
}
