#include <string.h>
#include <time.h>
#include <pthread.h>

#define N_MAX 10000
#define LOG_LEVEL 1
#define CRCFLAG_MIN 0x01
#define CRCFLAG_MAX 0xFF
#define RNTI_MAX 0xFFFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int pool_size = 10000;
NFAPI_CRC_INDICATION_PDU_T* pool = NULL;

void* create_pool(size_t size) {
    void* ptr = valloc(size);
    if (ptr == MAP_FAILED) {
        return NULL;
    }
    return ptr;
}

void init_pool() {
    pool_size *= 2;
    pthread_mutex_lock(&lock);
    pool = realloc(pool, pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int N) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    int i, j;
    for (i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* p = pool + i;
