// Define the structure for a log entry
typedef struct {
    long timestamp;
    char eventType[256];
    int severityLevel;
} LogEntry;

// Define the structure to store processed logs
typedef struct {
    LogEntry* entries;
    size_t count;
} LogSet;

// Function to process log entries and store them in a structured data structure
LogSet* processLogs(char** logs, size_t numLogs) {
    LogSet* logSet = (LogSet*)malloc(sizeof(LogSet));
    logSet->entries = NULL;
    logSet->count = 0;

    for(size_t i = 0; i < numLogs; i++) {
        char* log = logs[i];
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));

        // Parse the log and store it in the structure
        sscanf(log, "%ld %s %d", &entry->timestamp, entry->eventType, &entry->severityLevel);

        if(strncmp(entry->eventType, "ERROR", 5) == 0 || strncmp(entry->eventType, "WARNING", 8) == 0) {
            // Handle errors and warnings
            printf("Error or warning log: %s\n", log);
        } else {
            entry->next = logSet->entries;
            logSet->entries = entry;
            logSet->count++;
        }
    }

    return logSet;
}

// Function to find the most frequently occurring event type and its total count
void printMostFrequentEventType(LogSet* logSet) {
    if(logSet->count == 0) {
        printf("No valid logs provided.\n");
        return;
    }

    // Initialize variables to store the most frequent event type and its count
    char mostFrequentEventType[256] = "";
    int mostFrequentCount = 0;

    // Iterate over the processed log entries
    for(size_t i = 0; i < logSet->count; i++) {
        LogEntry* entry = logSet->entries + i;
        size_t eventTypeLength = strlen(entry->eventType);

        // Check if the current event type is more frequent than the previous one
        if(strncmp(entry->eventType, mostFrequentEventType, eventTypeLength) < 0) {
            strcpy(mostFrequentEventType, entry->eventType);
            mostFrequentCount = 1;
        } else if(strncmp(entry->eventType, mostFrequentEventType, eventTypeLength) == 0) {
            mostFrequentCount++;
        }
    }

    printf("Most frequent event type: %s\nTotal count: %d\n", mostFrequentEventType, mostFrequentCount);
}

int main() {
    // Example usage
    char** logs = (char**)malloc(5 * sizeof(char*));
    for(size_t i = 0; i < 5; i++) {
        char log[1024] = "1634523456789 ERROR System failure\n";
        logs[i] = log;
    }
    LogSet* logSet = processLogs(logs, 5);
    printMostFrequentEventType(logSet);

    return 0;
}
