#define VALIDATION_FAILURE_THRESHOLD 0.1

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int total_allocations = 0;
int validation_failures = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_init_structures(int n, float probability_threshold) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!structures) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    total_allocations += n;

    for (int i = 0; i < n; i++) {
        structures[i].rx_ue_info = ...; // Initialize RX_UE_INFORMATION_TAG
        structures[i].rnti = ...; // Initialize RNTI
        structures[i].crc_indication_rel8_tag = ...; // Initialize CRC_INDICATION_REL8_TAG

        if (rand() / (float)RAND_MAX < probability_threshold) {
            structures[i].crc_flag = 1;
        } else {
            structures[i].crc_flag = 0;
        }
    }

    for (int i = 0; i < n; i++) {
        // Validate CRC value
        if (structures[i].crc_indication_rel8_tag.crc_value != calculate_crc(structures[i].data)) {
            validation_failures++;
            log_error("Invalid CRC value in structure %d", i);

            // Free all allocated memory
            for (int j = 0; j < i; j++) {
                free(&structures[j]);
            }

            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);

    // Log successful allocation and validation
    log_info("Allocated %d structures successfully", n);

    // Monitor memory usage and structure health
    if (total_allocations > MAX_ALLOCATIONS) {
        release_unused_structures();
    }

    return structures;
}

void release_unused_structures() {
    pthread_mutex_lock(&lock);

    for (int i = total_allocations - 1; i >= 0; i--) {
        // Check structure usage and release if unused
        // ...
    }

    pthread_mutex_unlock(&lock);
}

void monitor_health() {
    pthread_mutex_lock(&lock);

    float allocation_rate = (float)total_allocations / (clock() / CLOCKS_PER_SEC);
    float validation_failure_rate = (float)validation_failures / total_allocations;

    if (allocation_rate > MONITORING_THRESHOLD || validation_failure_rate > VALIDATION_FAILURE_THRESHOLD) {
        // Log alert and trigger reconfiguration if necessary
        log_alert("Memory usage or validation failure rate exceeded threshold");
    }

    pthread_mutex_unlock(&lock);
}

void adjust_probability_threshold(float new_threshold) {
    pthread_mutex_lock(&lock);

