#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>

#define MAX_NFAP 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* xmalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

int compare(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* q = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return p->RNTI - q->RNTI;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* nfaps = xmalloc(MAX_NFAP * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < MAX_NFAP; i++) {
        nfaps[i].RX_UE_INFORMATION_TAG = rand();
        nfaps[i].RNTI = rand();
        if (i > 0) {
            while (binary_search(nfaps, i-1, &nfaps[i]) == -1)
                nfaps[i].RNTI++;
        }
        nfaps[i].CRC_INDICATION_REL8_TAG = rand();
        nfaps[i].CRCFLAG = rand() % 2;
    }

    qsort(nfaps, MAX_NFAP, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);

    free(nfaps);
    return 0;
}

int binary_search(NFAPI_CRC_INDICATION_PDU_T* arr, int n, NFAPI_CRC_INDICATION_PDU_T* key) {
    int low = 0;
    int high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (arr[mid].RNTI < key->RNTI)
            low = mid + 1;
        else if (arr[mid].RNTI > key->RNTI)
            high = mid - 1;
        else
            return mid;
    }
    return -1;
}
