void pdu_manager_init(size_t initial_capacity) {
    pdu_manager.capacity = initial_capacity;
    pdu_manager.pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    pthread_mutex_init(&pdu_manager.mutex, NULL);
