    for (size_t i = 0; i < pdu_manager.capacity; ++i) {
        if (!pdu_manager.pdus[i].RX_UE_INFORMATION_TAG || !pdu_manager.pdus[i].RNTI || !pdu_manager.pdus[i].CRC_INDICATION_REL8_TAG) {
            pdu_manager.pdus[i] = *pdu;
            pdu->CRCFLAG = set_CRCFLAG_probabilistically();
            return;
        }
    }
    pthread_mutex_unlock(&pdu_manager.mutex);
