        if (!is_pdu_valid(pdu_manager.pdus[i])) {
            memmove(&pdu_manager.pdus[i], &pdu_manager.pdus[i + 1], (pdu_manager.capacity - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu_manager.capacity--;
        } else {
            ++i;
        }
