int loadResourceBundle(const char *filename, int maxItems) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // File not found
    }

    int itemCount = 0;
    NFAPI_CRC_INDICATION_PDU_T *pduArray = malloc(maxItems * sizeof(NFAPI_CRC_INDATION_PDU_T));
    char line[1024];

    while (fgets(line, sizeof(line), file)) {
        if (strlen(line) > 1 && line[strlen(line) - 1] == '\n') { // Remove trailing newline
            line[strlen(line) - 1] = '\0';
        }

        const char *keyValPair = strtok(line, ",");
        if (keyValPair != NULL) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = (uint8_t)atoi(strtok(NULL, ","));
            pdu.RNTI = (uint16_t)atoi(strtok(NULL, ","));

            // Generate random CRCFLAG
            srand(time(NULL));
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (uint8_t)(rand() % 256);

            if (itemCount < maxItems) {
                pduArray[itemCount] = pdu;
                itemCount++;
            } else {
                fclose(file);
                free(pduArray);
                return -2; // Max items reached
            }
        }
    }

    fclose(file);
    return itemCount;
}

