    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_indication_pdu_t_list = NULL;
sem_t *semaphore;

int load_nfa_pi_crc_indication_pdu_t_list(const char* file_path, int max_concurrent_loads) {
    int items_loaded = 0;
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        return -1; // Error opening file
    }

    sem_init(semaphore, 1, 0); // Initialize semaphore

    while (fscanf(file, "%s=%d,%x\n", ...) != EOF) {
        NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_indication_pdu_t = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfa_pi_crc_indication_pdu_t == NULL) {
            // Error allocating memory
            return -2;
        }

        // Initialize structure fields

        sem_wait(semaphore); // Acquire semaphore
        nfa_pi_crc_indication_pdu_t_list = realloc(nfa_pi_crc_indication_pdu_t_list, (items_loaded + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfa_pi_crc_indication_pdu_t_list == NULL) {
            // Error allocating memory
            return -2;
        }
        nfa_pi_crc_indication_pdu_t_list[items_loaded] = *nfa_pi_crc_indication_pdu_t;
        sem_post(semaphore); // Release semaphore

        items_loaded++;
    }

    fclose(file);

    if (items_loaded > max_concurrent_loads) {
        return -3; // Exceeded maximum concurrent loads
    }

    return items_loaded;
}

void free_nfa_pi_crc_indication_pdu_t_list() {
    for (int i = 0; i < items_loaded; i++) {
        free(&nfa_pi_crc_indication_pdu_t_list[i]);
    }
    free(nfa_pi_crc_indication_pdu_t_list);
    sem_destroy(semaphore); // Destroy semaphore
}

int main(int argc, char *argv[]) {
    int max_concurrent_loads = 50;
    const char* file_path = "resourcebundle.txt";

    int items_loaded = load_nfa_pi_crc_indication_pdu_t_list(file_path, max_concurrent_loads);

    if (items_loaded < 0) {
        // Handle error
    } else {
        printf("Loaded %d NFAPI_CRC_INDICATION_PDU_T structures\n", items_loaded);
    }

    free_nfa_pi_crc_indication_pdu_t_list();

    return 0;
}

