#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
    struct Record* prev;
} Record;

typedef struct Node {
    Record* records;
    pthread_mutex_t mutex;
} Node;

Node* head = NULL;
Node* tail = NULL;

void insertRecord(Node* node, int key, long offset) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->next = NULL;
    newRecord->prev = node->records;
    if(node->records != NULL) {
        node->records->next = newRecord;
    } else {
        node->records = newRecord;
    }
    node->records = newRecord;
}

void deleteRecord(Node* node, int key) {
    Record* current = node->records;
    Record* previous = NULL;

    while(current != NULL) {
        if(current->key == key) {
            if(previous == NULL) {
                node->records = current->next;
            } else {
                previous->next = current->next;
                if(current->next != NULL) {
                    current->next->prev = previous;
                }
            }

            free(current);
            return;
        }

        previous = current;
        current = current->next;
    }
}

Record* findRecord(Node* node, int key) {
    Record* current = node->records;

    while(current != NULL) {
        if(current->key == key) {
            return current;
        }

        current = current->next;
    }

    return NULL;
}

void serializeRecords(FILE* file, Node* node) {
    fwrite(&node->records->key, sizeof(int), 1, file);
    fwrite(&node->records->offset, sizeof(long), 1, file);

    Record* current = node->records;
    while(current != NULL) {
        fwrite(&current->next, sizeof(Record*), 1, file);
        current = current->next;
    }
}

void deserializeRecords(FILE* file, Node* node) {
    if(node == NULL) return;

    Record* newRecord = (Record*)malloc(sizeof(Record));
    fseek(file, 0, SEEK_SET);
    fread(&newRecord->key, sizeof(int), 1, file);
    fread(&newRecord->offset, sizeof(long), 1, file);

    node->records = newRecord;
    Record* current = newRecord;
    while(fread(&current->next, sizeof(Record*), 1, file) == 1) {
        Record* nextRecord = (Record*)malloc(sizeof(Record));
        fseek(file, sizeof(long), SEEK_CUR);
        fread(&nextRecord->key, sizeof(int), 1, file);
        fread(&nextRecord->offset, sizeof(long), 1, file);
        current->next = nextRecord;
        current = nextRecord;
    }
}

void printRecords(Node* node) {
    Record* current = node->records;

    while(current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
}
