int mac_context_array_init(MAC_CONTEXT_T ***array, size_t *size) {
    *array = (MAC_CONTEXT_T **)malloc(sizeof(MAC_CONTEXT_T *) * 10);
    if (*array == NULL) return -1; // Memory allocation failed
    memset(*array, 0, sizeof(MAC_CONTEXT_T *) * 10);
    *size = 10;
    return 0; // Success
}

void mac_context_array_free(MAC_CONTEXT_T **array, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (array[i] != NULL)
            free(array[i]);
    }
    free(array);
}

int mac_context_array_add(MAC_CONTEXT_T ***array, size_t *size, MAC_CONTEXT_T *ctx) {
    if (*size == 10) { // Dynamic allocation threshold
        *array = (MAC_CONTEXT_T **)realloc(*array, sizeof(MAC_CONTEXT_T *) * 20);
        if (*array == NULL) return -1; // Memory allocation failed
        memset(&((*array)[*size]), 0, sizeof(MAC_CONTEXT_T *));
        (*size)++;
    }
    array[(*size)-1] = (MAC_CONTEXT_T *)malloc(sizeof(MAC_CONTEXT_T));
    if (array[(*size)-1] == NULL) return -1; // Memory allocation failed
    memcpy(array[(*size)-1], ctx, sizeof(MAC_CONTEXT_T));
    return 0; // Success
}

int main() {
    MAC_CONTEXT_T ***mac_ctx_array;
    size_t mac_ctx_size;

    if (mac_context_array_init(&mac_ctx_array, &mac_ctx_size) < 0)
        printf("Initialization failed: %s\n", "Memory allocation error");

    for (size_t i = 0; i < 5; i++) {
        MAC_CONTEXT_T ctx;
        // Initialize ctx
        if (mac_context_array_add(&mac_ctx_array, &mac_ctx_size, &ctx) < 0)
            printf("Addition failed: %s\n", "Memory allocation error");
    }

    mac_context_array_free(mac_ctx_array, mac_ctx_size);
    return 0;
}
