}

std::vector<NFAPI_CRC_INDICATION_PDU_T*> generateUniqueRNTIArray(int numElements, int maxRNTI) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> nfaPiArray;

    for (int i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = new NFAPI_CRC_INDICATION_PDU_T();

        // Generate random values
        p->RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti = rand() % maxRNTI;

        while (std::find_if(nfaPiArray.begin(), nfaPiArray.end(),
                [rnti](NFAPI_CRC_INDICATION_PDU_T* q) { return q->RNTI == rnti; }) != nfaPiArray.end()) {
            rnti = rand() % maxRNTI;
