        if (i >= allocatedSize) {
            int newSize = allocatedSize + 1024;
            NFAPI_CRC_INDICATION_PDU_T* newPool = realloc(memPool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);
            if (newPool == NULL) {
