#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGE_SIZE 1024
#define MAX_SEVERITY_LEVELS 4

typedef enum {
    DEBUG = 1,
    INFO,
    WARNING,
    ERROR
} severity_level;

typedef struct {
    int fd;
    severity_level level;
    char message[MAX_MESSAGE_SIZE];
} log_message_t;

log_message_t *message_queue;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
int queue_size = 0;
FILE *output_files[MAX_SEVERITY_LEVELS];

void init_log_system() {
    for (int i = 0; i < MAX_SEVERITY_LEVELS; i++) {
        output_files[i] = fopen("log_file.txt", "a");
        if (!output_files[i]) {
            printf("Error opening log file.\n");
            exit(1);
        }
    }
}

void log_message(log_message_t *message) {
    pthread_mutex_lock(&queue_lock);
    message_queue[queue_size++] = *message;
    pthread_mutex_unlock(&queue_lock);

    if (message->level == DEBUG || message->level == INFO) {
        fwrite(message->message, sizeof(char), strlen(message->message), output_files[0]);
    } else if (message->level == WARNING || message->level == ERROR) {
        fwrite(message->message, sizeof(char), strlen(message->message), output_files[1]);
    }
}

void rotate_log_files() {
    for (int i = 0; i < MAX_SEVERITY_LEVELS; i++) {
        fseek(output_files[i], 0, SEEK_END);
        int file_size = ftell(output_files[i]);
        if (file_size > 1024 * 1024) { // Rotate log files when they reach 1MB
            fclose(output_files[i]);
            sprintf("log_file_%d.txt", i);
            output_files[i] = fopen("log_file.txt", "w");
        }
    }
}

void* log_thread(void* arg) {
    while (true) {
        pthread_mutex_lock(&queue_lock);
        if (queue_size > 0) {
            log_message(&message_queue[0]);
            memmove(message_queue, message_queue + 1, sizeof(log_message_t) * (queue_size - 1));
            queue_size--;
        }
        pthread_mutex_unlock(&queue_lock);

        // Remote logging and file rotation
        for (int i = 0; i < MAX_SEVERITY_LEVELS; i++) {
            if (output_files[i]) {
                fwrite("remote log", sizeof(char), strlen("remote log"), output_files[i]);
                fclose(output_files[i]);
            }
        }

        rotate_log_files();
    }
}

void start_log_thread() {
    pthread_t thread;
    pthread_create(&thread, NULL, log_thread, NULL);
}

int main() {
    init_log_system();
    start_log_thread();

    // Example usage
    log_message_t message1 = {0};
    message1.fd = 0;
    message1.level = DEBUG;
    strcpy(message1.message, "This is a debug message");

    log_message(&message1);

    return 0;
}

