int checksum = 0;

void *allocate_record() {
    return malloc(sizeof(NRBPF_PACKET_T));
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(&records[i]);
    }
    free(records);
}

void insert_record(NRBPF_PACKET_T *record) {
    LOCK_MUTEX
    records[record_count++] = *record;
    UNLOCK_MUTEX

    checksum += record->ue_context_info + (int)record->sinr;
}

void verify_records() {
    int sum = 0;
    for (int i = 0; i < record_count; i++) {
        sum += records[i].ue_context_info + (int)records[i].sinr;
    }
    if (sum != checksum) {
        printf("Records corrupted!\n");
    }
}

void sort_records() {
    qsort(records, record_count, sizeof(NRBPF_PACKET_T), compare);
}

int compare(const void *a, const void *b) {
    NRBPF_PACKET_T *ra = *(NRBPF_PACKET_T **)a;
    NRBPF_PACKET_T *rb = *(NRBPF_PACKET_T **)b;

    if (ra->ue_context_info < rb->ue_context_info)
        return -1;
    else if (ra->ue_context_info > rb->ue_context_info)
        return 1;
    else
        return 0;
}

void print_records() {
