void generateNfaPduList(NFAPI_CRC_INDICATION_PDU_T** pduList, int* size) {
    // Memory pool management
    int blockSize = 1024;
    char* memoryPool = (char*)malloc(blockSize);
    void* blockHead = memoryPool;
    void* blockTail = memoryPool + blockSize;

    for (int i = 0; i < *size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize structure
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = rand() % 2;

        // Update memory pool pointers
        blockHead += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (blockHead + sizeof(NFAPI_CRC_INDICATION_PDU_T) > blockTail) {
            blockTail = (void*)((char*)blockTail - blockSize + sizeof(NFAPI_CRC_INDICATION_PDU_T));
            blockHead = memoryPool;
        }
    }

    // Initialize dynamic array
    *pduList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < *size; i++) {
        (*pduList)[i] = pdu;
    }

    // Free memory pool
    free(memoryPool);
}

