#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "logging.h"
#include "memory_pool.h"

#define MAX_STRUCTURE_COUNT 100000
#define RING_BUFFER_SIZE 256

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    uint32_t size;
    uint32_t capacity;
} memory_pool_t;

void* allocate_structure(memory_pool_t* pool) {
    if (pool->size >= pool->capacity) {
        // Reallocate the ring buffer
        void* new_buffer = realloc(pool, sizeof(structures), RING_BUFFER_SIZE * 2);
        if (!new_buffer) return NULL;
        pool->capacity *= 2;
    }
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void deallocate_structure(void* structure) {
    free(structure);
}

int create_structures(int N, memory_pool_t* pool, FILE* log_file) {
    for (int i = 0; i < N; i++) {
        void* structure = allocate_structure(pool);
        if (!structure) break;

        // Initialize the structure with valid data
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->RX_UE_INFORMATION_TAG = ...;
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->RNTI = ...;
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->CRC_INDICATION_REL8_TAG.crcFlag = rand() % 2;

        // Log the allocation
        logging_log(log_file, LOGGING_VERBOSE, "Allocated structure %p\n", structure);

        // Add the structure to the pool
        pool->structures[pool->size++] = (NFAPI_CRC_INDICATION_PDU_T*)structure;
    }

    return 0;
}

int pause_allocation(memory_pool_t* pool) {
    if (!pool->size) return 0;

    // Save the current state
    int paused_size = pool->size;
    pool->size = 0;

    // Set a flag to indicate that allocation is paused
    pool->paused = 1;

    logging_log(log_file, LOGGING_VERBOSE, "Allocation paused\n");

    return paused_size;
}

int resume_allocation(memory_pool_t* pool) {
    if (!pool->size || !pool->paused) return 0;

    // Restore the saved state
    pool->size = paused_size;
    pool->paused = 0;

    logging_log(log_file, LOGGING_VERBOSE, "Allocation resumed\n");

    return 0;
}

int main() {
    FILE* log_file = fopen("log.txt", "w");
    memory_pool_t pool;
    pool.size = 0;
    pool.capacity = RING_BUFFER_SIZE;
    pool.structures = NULL;

    // Simulate high-load conditions
    int N = 100000;
    create_structures(N, &pool, log_file);

    // Test pause-resume operations
    int paused_size = pause_allocation(&pool);
    for (int i = 0; i < paused_size / 2; i++) {
        deallocate_structure(pool.structures[paused_size - i - 1]);
    }
    resume_allocation(&pool);

    // Simulate continuous allocation and freeing
    for (int i = 0; i < N * 10; i++) {
        void* structure = allocate_structure(&pool);
        if (!structure) break;

        // Initialize the structure with valid data
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->RX_UE_INFORMATION_TAG = ...;
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->RNTI = ...;
        ((NFAPI_CRC_INDICATION_PDU_T*)structure)->CRC_INDICATION_REL8_TAG.crcFlag = rand() % 2;

        // Log the allocation
        logging_log(log_file, LOGGING_VERBOSE, "Allocated structure %p\n", structure);

        deallocate_structure(structure);
    }

    return 0;
}
