#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char* id;
    time_t timestamp;
} item;

int load_data(item*** data, FILE** file) {
    // Read number of items from file
    int num_items = 0;
    if (fread(&num_items, sizeof(int), 1, *file) != 1) {
        printf("Error reading number of items\n");
        return -1;
    }

    // Allocate memory for arrays
    (*data) = (item**)malloc(num_items * sizeof(item*));
    char** ids = (char**)malloc(num_items * sizeof(char*));
    double* values = (double*)malloc(num_items * sizeof(double));

    // Read data from file
    for (int i = 0; i < num_items; i++) {
        if (fread(&((*data)[i]->timestamp), sizeof(time_t), 1, *file) != 1) {
            printf("Error reading timestamp\n");
            return -1;
        }
        if (fread(&values[i], sizeof(double), 1, *file) != 1) {
            printf("Error reading value\n");
            return -1;
        }
        int id_len = 0;
        if (fread(&id_len, sizeof(int), 1, *file) != 1) {
            printf("Error reading identifier length\n");
            return -1;
        }
        ids[i] = (char*)malloc(id_len + 1);
        if (fread(ids[i], id_len + 1, 1, *file) != 1) {
            printf("Error reading identifier\n");
            return -1;
        }
        ((*data)[i]->id) = ids[i];
    }

    // Read strings
    char* str = (char*)malloc(1024);
    for (int i = 0; i < num_items; i++) {
        if (fread(str, 1024, 1, *file) != 1) {
            printf("Error reading string\n");
            return -1;
        }
        int str_len = strlen(str);
        (*data)[i]->value = values[i];
    }

    // Free memory
    for (int i = 0; i < num_items; i++) {
        free(ids[i]);
    }
    free(ids);
    free(values);

    return 0;
}

int save_data(item* data, FILE* file) {
    // Write number of items to file
    int num_items = 0;
    for (int i = 0; i < num_items; i++) {
        if (fwrite(&data[i].timestamp, sizeof(time_t), 1, file) != 1) {
            printf("Error writing timestamp\n");
            return -1;
        }
        if (fwrite(&data[i].value, sizeof(double), 1, file) != 1) {
            printf("Error writing value\n");
            return -1;
        }
        int id_len = strlen(data[i].id);
        if (fwrite(&id_len, sizeof(int), 1, file) != 1) {
            printf("Error writing identifier length\n");
            return -1;
        }
        if (fwrite(data[i].id, id_len + 1, 1, file) != 1) {
            printf("Error writing identifier\n");
            return -1;
        }
    }

    return 0;
}

int main() {
    item* data = NULL;
    FILE* file = fopen("data.bin", "wb+");
    if (file == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    // Allocate memory for arrays
    int num_items = 10,000;
    data = (item*)malloc(num_items * sizeof(item));

    // Initialize arrays
    for (int i = 0; i < num_items; i++) {
        data[i].timestamp = time(NULL);
        data[i].value = (double)i;
        char* id = (char*)malloc(10);
        sprintf(id, "id_%d", i);
        data[i].id = id;
    }

    // Save data to file
    if (save_data(data, file) == -1) {
        printf("Error saving data\n");
        return -1;
    }

    // Load data from file
    item** loaded_data = NULL;
    FILE* loaded_file = fopen("data.bin", "rb+");
    if (loaded_file == NULL || load_data(&loaded_data, &loaded_file) == -1) {
        printf("Error loading data\n");
        return -1;
    }

    // Verify integrity of loaded data
    for (int i = 0; i < num_items; i++) {
        printf("Timestamp: %ld, Value: %f, ID: %s\n", loaded_data[i]->timestamp, loaded_data[i]->value, loaded_data[i]->id);
    }

    // Free memory
    for (int i = 0; i < num_items; i++) {
        free(loaded_data[i]->id);
    }
    free(loaded_data);

    return 0;
}
