#include <string.h>

typedef struct {
    float temp;
    char id[10];
} SensorData;

typedef struct {
    float dev;
    char desc[20];
} StatusRecord;

typedef struct {
    int entries;
    StatusRecord** records;
} LogStruct;

SensorData* sensor_data = NULL;
StatusRecord* status_records = NULL;
LogStruct* log = NULL;

void initialize() {
    FILE *file = fopen("temperature_data.txt", "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    float max_temp = 0.0f, min_temp = 100.0f;
    int count = 0, record_size = sizeof(SensorData);
    sensor_data = (SensorData*)malloc(record_size * 10);

    while (fscanf(file, "%f %s", &sensor_data[count].temp, sensor_data[count].id) == 2 && count < 10) {
        if (sensor_data[count].temp > max_temp)
            max_temp = sensor_data[count].temp;
        if (sensor_data[count].temp < min_temp)
            min_temp = sensor_data[count].temp;
        count++;
    }

    fclose(file);

    status_records = (StatusRecord*)malloc(sizeof(StatusRecord) * count);
    log = (LogStruct*)malloc(sizeof(LogStruct));

    for (int i = 0; i < count; i++) {
        status_records[i].dev = sensor_data[i].temp - min_temp;
        strcpy(status_records[i].desc, sensor_data[i].id);
    }

    qsort(status_records, count, sizeof(StatusRecord), compStatusRecords);
}

int compStatusRecords(const void *a, const void *b) {
    StatusRecord* sa = (StatusRecord*)a;
    StatusRecord* sb = (StatusRecord*)b;
    return (sb->dev - sa->dev);
}

SensorData* getReading(char* id) {
    for (int i = 0; i < 10; i++) {
        if (!strcmp(sensor_data[i].id, id)) {
            SensorData* reading = (SensorData*)malloc(sizeof(SensorData));
            *reading = sensor_data[i];
            return reading;
        }
    }
    return NULL;
}

void freeMemory() {
    free(sensor_data);
    free(status_records);
    free(log);
}
