#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* description;
    long offset;
} record;

record* manageMemory(int n, int minValue, int maxValue) {
    if (n <= 0 || minValue >= maxValue) {
        return NULL; // Error: Invalid input
    }

    // Allocate memory for offsets and keys
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));

    // Check for memory allocation failure
    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate memory for records
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;

        // Allocate memory for description and initialize to NULL
        char* desc = (char*)malloc(32 * sizeof(char));
        if (!desc) {
            free(offsets);
            free(keys);
            for (int j = i; j >= 0; j--) {
                free(records[j].description);
            }
            return NULL;
        }

        // Set description and set offset to corresponding element in offsets array
        records[i].description = desc;
        records[i].offset = &offsets[i];

        // Check for memory allocation failure
        if (!records[i].description) {
            free(offsets);
            free(keys);
            for (int j = i; j >= 0; j--) {
                free(records[j].description);
            }
            return NULL;
        }
    }

    // Free allocated resources on error
    return records;
}
