['Here's the C code for managing memory allocation and initialization for multiple data structures:

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    int value;
    char* description;
    long* offset;
} record;

record* allocateRecords(int n, int minValue, int maxValue, char* logBuffer) {
    // Calculate total memory required for arrays and record structures
    size_t totalMemory = (n * sizeof(long)) + (n * sizeof(record));

    // Get available system memory
    size_t systemMemory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    size_t maxTotalMemory = systemMemory / 2; // Limit to 50% of available memory

    if (totalMemory > maxTotalMemory) {
        // Log error and terminate
        sprintf(logBuffer, "Insufficient system memory: %zu bytes needed, but only %zu bytes available.\n", totalMemory, maxTotalMemory);
        return NULL;
    }

    // Allocate memory for arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));

    if (!offsets || !keys) {
        sprintf(logBuffer, "Error allocating arrays: %p and %p\n", offsets, keys);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize array elements
    for (int i = 0; i < n; i++) {
        offsets[i] = i * (maxValue - minValue) + minValue;
        keys[i] = i % maxValue;
    }

    // Allocate memory for record structures and initialize pointers to 'offsets' array
    record* records = (record*)malloc(n * sizeof(record));
    for (int i = 0; i < n; i++) {
        records[i].value = offsets[i];
        records[i].description = NULL;
        records[i].offset = &offsets[i];
    }

    // Set descriptions for each record
    static const char* descriptions[] = {"Record description 1", "Record description 2", ...}; // Static array of strings
    for (int i = 0; i < n; i++) {
        records[i].description = descriptions[records[i].value % sizeof(descriptions) / sizeof(descriptions[0])];
    }

    return records;
}

void freeRecords(record* records, int n) {
    // Free allocated memory
    for (int i = 0; i < n; i++) {
        if (records[i].description)
            free(records[i].description);
        if (records[i].offset)
            free((void*)records[i].offset); // Correctly align 'offset' pointer
    }

    free(records);
}
