#define MAX_SENSORS 10
#define MAX_READINGS 1000
#define LOG_BUFFER_SIZE 1024

typedef struct status {
    float temp_dev;
    char desc[20];
} status_t;

typedef struct log_entry {
    status_t* status;
    int count;
} log_entry_t;

log_entry_t log[MAX_SENSORS];

void* read_temp_data(void* arg) {
    int sensor_id = *(int*)arg;
    FILE* file = fopen(get_sensor_file_name(sensor_id), "r");

    if (!file) {
        perror("Error reading temperature data from file");
        return NULL;
    }

    float temps[MAX_READINGS];
    char ids[MAX_READINGS][20];
    status_t statuses[MAX_READINGS];

    int i = 0;
    while (fscanf(file, "%s %f\n", ids[i], &temps[i]) == 2) {
        if (i >= MAX_READINGS - 1) break;
        if (check_temp_range(temps[i])) continue; // filter out invalid data
        statuses[i].temp_dev = temps[i] - get_average_temp(sensor_id);
        strcpy(statuses[i].desc, ids[i]);
        i++;
    }

    fclose(file);

    // sort temperatures by deviation in descending order
    quicksort_temps(0, i-1, statuses);

    log[sensor_id].status = (status_t*)malloc(i * sizeof(status_t));
    memcpy(log[sensor_id].status, statuses, i * sizeof(status_t));
    log[sensor_id].count = i;

    return NULL;
}

int main() {
    pthread_t threads[MAX_SENSORS];

    for (int i = 0; i < MAX_SENSORS; i++) {
        int* arg = malloc(sizeof(int));
        *arg = i;
        pthread_create(&threads[i], NULL, read_temp_data, arg);
    }

    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_join(threads[i], NULL);
    }

    // retrieve a specific temperature reading
    status_t* temp_reading = get_temp_reading(5);

    // update or modify existing records
    update_temp_reading(3, 25.1);

    // free allocated memory when done
    free_temp_data();

    return 0;
}

void quicksort_temps(int low, int high, status_t* temps) {
    if (low >= high) return;

    int pivot_index = partition_temps(low, high, temps);
    quicksort_temps(low, pivot_index - 1, temps);
    quicksort_temps(pivot_index + 1, high, temps);
}

int partition_temps(int low, int high, status_t* temps) {
    float pivot = temps[low].temp_dev;
    int i = low + 1;
    int j = high;

    while (i <= j) {
        while (i <= j && temps[i].temp_dev < pivot) i++;
        while (i <= j && temps[j].temp_dev > pivot) j--;

        if (i <= j) {
            float temp = temps[i].temp_dev;
            temps[i-1] = temps[i];
            temps[i] = temps[j];
            i++;
            j--;
        }
    }

    temps[low] = temps[i-1];
    return i - 1;
}
