typedef struct {
    double value;
    const char* id;
} item;

item* collection = NULL;
int capacity = 0;
int count = 0;

void init_collection(int max_capacity) {
    if (collection != NULL) free_collection();
    capacity = max_capacity;
    collection = (item*)malloc(capacity * sizeof(item));
}

void add_item(double value, const char* id) {
    if (count >= capacity) {
        // Resize the collection
        capacity *= 2;
        item* new_collection = (item*)realloc(collection, capacity * sizeof(item));
        collection = new_collection;
    }
    item* temp = &collection[count++];
    temp->value = value;
    temp->id = id;
}

item* find_item(const char* id) {
    for (int i = 0; i < count; i++) {
        if (strcmp(collection[i].id, id) == 0) {
            return &collection[i];
        }
    }
    return NULL;
}

void update_item(const char* id, double value) {
    item* found = find_item(id);
    if (found != NULL) {
        found->value = value;
    }
}

void sort_collection() {
    item temp;
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (collection[i].value > collection[j].value) {
                temp = collection[i];
                collection[i] = collection[j];
