#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_CAPACITY 10000
#define SORT_ORDER_ASCENDING 0
#define SORT_ORDER_DESCENDING 1

typedef struct {
    double value;
    const char *identifier;
} item_t;

item_t **collection = NULL;
int collection_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_collection() {
    collection = (item_t **)malloc(sizeof(item_t *) * MAX_CAPACITY);
}

bool add_item(const char *identifier, double value) {
    pthread_mutex_lock(&mutex);

    item_t *new_item = (item_t *)malloc(sizeof(item_t));
    new_item->value = value;
    new_item->identifier = strdup(identifier);

    if (collection_size == MAX_CAPACITY) {
        // Handle memory allocation failure
        free(new_item);
        pthread_mutex_unlock(&mutex);
        return false;
    }

    collection[collection_size] = new_item;
    collection_size++;

    pthread_mutex_unlock(&mutex);
    return true;
}

item_t *get_item(const char *identifier) {
    for (int i = 0; i < collection_size; i++) {
        if (strcmp(collection[i]->identifier, identifier) == 0) {
            return collection[i];
        }
    }
    return NULL;
}

bool update_item(const char *identifier, double value) {
    item_t *item = get_item(identifier);
    if (!item) {
        return false;
    }

    item->value = value;

    return true;
}

void sort_collection(int order) {
    for (int i = 0; i < collection_size - 1; i++) {
        int j = i + 1;
        while (j > i && ((order == SORT_ORDER_ASCENDING && collection[i]->value > collection[j]->value) || (order == SORT_ORDER_DESCENDING && collection[i]->value < collection[j]->value))) {
            item_t *temp = collection[i];
            collection[i] = collection[j];
            collection[j] = temp;
            j--;
        }
    }
}

bool search_items(double min_value, double max_value) {
    for (int i = 0; i < collection_size; i++) {
        if (collection[i]->value >= min_value && collection[i]->value <= max_value) {
            // Process or return the matching item
            printf("Found item: %s - %.2f\n", collection[i]->identifier, collection[i]->value);
        }
    }
    return true;
}

void destroy_collection() {
    for (int i = 0; i < collection_size; i++) {
        free(collection[i]->identifier);
        free(collection[i]);
    }
    free(collection);
    collection = NULL;
    collection_size = 0;
}
