typedef struct {
    offset_t key;
    value_t value;
    timestamp_t timestamp;
    metadata_t metadata;
} record_t;

void my_func(size_t max_memory, int (*callback)(record_t), uint32_t *seed) {
    // Allocate and initialize arrays
    size_t num_records = (max_memory / sizeof(record_t)) + 1;
    offset_t *keys = malloc(num_records * sizeof(offset_t));
    key_t *key_array = malloc(num_records * sizeof(key_t));

    // Initialize keys
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = i;
    }

    // Initialize record structures
    record_t *records = malloc(num_records * sizeof(record_t));
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].value = rand_r(seed) % 100 + 1;
        records[i].timestamp = time(NULL);
        records[i].metadata.frequency = 0;
        records[i].metadata.last_accessed = time(NULL);

        // Call callback function for each record
        if (callback) {
            (*callback)(records[i]);
        }
    }

    free(keys);
    free(key_array);

    // Free allocated memory
    free(records);
}

int main() {
    size_t max_memory = 1024 * 1024; // 1MB
    int callback(record_t r) {
        printf("Record key: %llu, value: %d, timestamp: %lu\n", r.key, r.value, r.timestamp);
        return 0;
    }
    uint32_t seed = time(NULL);

    my_func(max_memory, callback, &seed);

    return 0;
}
