#define MAX_CAPACITY 10000
#define MEMORY_POOL_SIZE 1000

typedef struct {
    double value;
    const char* identifier;
} item;

item* dynamicCollection = NULL;
int collectionSize = 0;
int maxCapacity = MAX_CAPACITY;
int memoryPoolIndex = 0;

void* allocateMemory(size_t size) {
    void* mem = NULL;
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (!dynamicCollection[i].identifier) {
            mem = &dynamicCollection[i];
            break;
        }
    }
    return mem;
}

item* addItem(double value, const char* identifier) {
    item* newItem = allocateMemory(sizeof(item));
    if (newItem) {
        memcpy(newItem, &item{value, identifier}, sizeof(item));
        dynamicCollection[collectionSize++] = *newItem;
        return newItem;
    }
    return NULL;
}

item* getItem(const char* identifier) {
    for (int i = 0; i < collectionSize; i++) {
        if (!strcmp(dynamicCollection[i].identifier, identifier)) {
            return &dynamicCollection[i];
        }
    }
    return NULL;
}

void updateItem(item* itemToUpdate, double value) {
    itemToUpdate->value = value;
}

void sortCollection() {
    qsort(dynamicCollection, collectionSize, sizeof(item), (int (*)(const void*, const void*))cmpItems);
}

int cmpItems(const void* a, const void* b) {
    item* iA = (item*)a;
    item* iB = (item*)b;
    return (iA->value < iB->value ? -1 : iA->value > iB->value ? 1 : 0);
}

int searchItems(double min, double max) {
    int count = 0;
    for (int i = 0; i < collectionSize; i++) {
        if (min <= dynamicCollection[i].value && dynamicCollection[i].value <= max) {
            count++;
        }
    }
    return count;
}

void printUsage() {
    printf("Usage: ./dynamic_collection [options]\n");
    printf("Options:\n");
