    static struct option long_options[] = {
        {"manpage", 0, 0, 's'},
        {"output-file", 1, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "+cs:o:", long_options, NULL)) != -1) {
