typedef struct {
    int key;
    char* identifier;
} record;

typedef struct {
    record** records;
    int count;
} summary;

void init_records(int num_records, int min_key, int max_key, record*** records) {
    // Allocate memory for the array of record pointers
    *records = (record**)malloc(num_records * sizeof(record*));

    // Initialize each record with a random integer value and identifier
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (record*)malloc(sizeof(record));
        (*records)[i]->key = min_key + rand() % (max_key - min_key + 1);
        // Allocate memory for the identifier string
        char buffer[10];
        sprintf(buffer, "Record_%d", i);
        (*records)[i]->identifier = (char*)malloc(strlen(buffer) + 1);
        strcpy((*records)[i]->identifier, buffer);
    }
}

void init_summaries(int num_records, summary** summaries) {
    // Allocate memory for the array of summary pointers
    *summaries = (summary*)malloc(num_records / 100 + 1 * sizeof(summary));

    // Initialize each summary with a count and null records pointer
    for (int i = 0; i < num_records / 100 + 1; i++) {
        (*summaries)[i].records = NULL;
        (*summaries)[i].count = 0;
    }
}

void sort_records(int num_records, record*** records) {
    // Use a simple insertion sort algorithm for efficient sorting
    for (int i = 1; i < num_records; i++) {
        record temp = (*records)[i];
        int j = i - 1;
        while (j >= 0 && temp.key < (*records)[j]->key) {
            (*records)[j + 1] = (*records)[j];
            j--;
        }
        (*records)[j + 1] = &temp;
    }
}

void free_resources(int num_records, record*** records, summary** summaries) {
    // Free each record's memory
    for (int i = 0; i < num_records; i++) {
        free((*records)[i]->identifier);
        free((*records)[i]);
    }

    // Free the array of records and the array of summaries
    for (int i = 0; i < num_records / 100 + 1; i++) {
        if ((*summaries)[i].records) {
            for (int j = 0; j < (*summaries)[i].count; j++) {
                free((*(*summaries)[i].records)[j]);
            }
            free((*summmaries)[i].records);
        }
    }

    // Free the arrays themselves
    free(*summaries);
    free(*records);
}

int main() {
    int num_records = 1000; // Adjust this value as needed
    int min_key = 1;
    int max_key = 1000;

    record** records = NULL;
    summary* summaries = NULL;

    init_records(num_records, min_key, max_key, &records);
    init_summaries(num_records, &summaries);

    sort_records(num_records, &records);

    free_resources(num_records, &records, &summaries);

    return 0;
}
