#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 100
#define SUMMARY_BUFFER_SIZE 1024

typedef struct {
    int value;
    char* identifier;
} record;

typedef struct {
    record* records;
    int count;
} summary;

void initialize_database(int max_records, int max_summary_buffer_size) {
    // Allocate memory for and initialize an array of long integers representing offsets.
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i;
    }

    // Allocate memory for and initialize an array of int integers serving as keys, ensuring that no two keys are identical.
    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % 100;
        if (i > 0 && !is_key_unique(key, &keys[i - 1])) {
            char buffer[16];
            sprintf(buffer, ":%d", i);
            key += atoi(buffer);
        }
        keys[i] = key;
    }

    // Allocate memory for and initialize an array of record structures.
    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    for (int i = 0; i < MAX_RECORDS; i++) {
        int value = rand() % 10000;
        char buffer[11];
        sprintf(buffer, "%c%.9s", 'A' + (rand() % 26), random_string());
        records[i].value = value;
        records[i].identifier = strndup(buffer, 10);
    }

    // Allocate memory for and initialize an array of summary structures.
    summary* summaries = (summary*)malloc(MAX_RECORDS * sizeof(summary));
    int summary_index = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (i % 10 == 9) { // Group records by every 10th entry
            summaries[summary_index].records = &records[i - 9];
            summaries[summary_index].count = i - 8;
            summary_index++;
        }
    }

    // Sort the records based on their int values in ascending order.
    record temp;
    for (int i = 0; i < MAX_RECORDS; i++) {
        for (int j = i + 1; j < MAX_RECORDS; j++) {
            if (records[i].value > records[j].value) {
                temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }

    // Free all allocated memory.
    free(offsets);
    for (int i = 0; i < summary_index; i++) {
        free(summaries[i].records->identifier);
        free(summaries[i].records);
    }
    free(records);
    free(summaries);
}

// Helper function to check if a key is unique.
bool is_key_unique(int key, int* previous_keys) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (previous_keys[i] == key) return false;
    }
    return true;
}

// Helper function to generate a random alphanumeric string.
char* random_string() {
    char buffer[11];
    for (int i = 0; i < 10; i++) {
        buffer[i] = 'A' + rand() % 26;
    }
