void create_buffer(BUFFER_INFO_T* buffer_info) {
    buffer_info->pdus = (PACKET_DATA_UNIT_T**)malloc(buffer_info->num_entries * sizeof(PACKET_DATA_UNIT_T*));
}

int add_pdu_to_buffer(BUFFER_INFO_T* buffer_info, PACKET_DATA_UNIT_T* pdu) {
    // Dynamic buffer resizing using realloc
    if (buffer_info->pdus == NULL || buffer_info->num_entries <= 0) {
        create_buffer(buffer_info);
    }

    // Check for buffer overflow condition
    if (buffer_info->num_entries * sizeof(PACKET_DATA_UNIT_T*) >= buffer_info->frame_size) {
        printf("Buffer overflow detected! Packet dropped.\n");
        return -1;
    }

    // Add PDU to the buffer
    buffer_info->pdus[buffer_info->num_entries++] = pdu;

    return 0;
}

PACKET_DATA_UNIT_T* get_pdu_from_buffer(BUFFER_INFO_T* buffer_info, int index) {
    if (index < 0 || index >= buffer_info->num_entries) {
        printf("Packet not found! Returning NULL.\n");
        return NULL;
    }

    return buffer_info->pdus[index];
}

