void *buffer_manager(void *arg) {
    // Initialize buffer and packet indices
    int packets_written = 0;
    int current_packet_index = 0;
    PACKET_DATA_UNIT_T *packet_buffer = (PACKET_DATA_UNIT_T *)malloc(MAX_PACKETS * sizeof(PACKET_DATA_UNIT_T));

    pthread_mutex_t write_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t new_packet_available = PTHREAD_COND_INITIALIZER;

    while (1) {
        // Wait for a new packet to be written
        pthread_mutex_lock(&write_lock);
        pthread_cond_wait(&new_packet_available, &write_lock);

        // Write the new packet into the buffer
        if (packets_written < MAX_PACKETS) {
            packet_buffer[current_packet_index].packet_data = ((char *)arg) + packets_written * FRAME_SIZE;
            current_packet_index++;
            packets_written++;
        } else {
            // Handle buffer overflow condition
            printf("Buffer overflow! Packet dropped.\n");
            break;
        }

        // Signal that a new packet is available
        pthread_cond_signal(&new_packet_available);
    }

    free(packet_buffer);
}

