    if (!buffer) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    currentCapacity = frameSize;
    maxCapacity = frameSize;

    // Function to add new PDUs
    void addPDU(PACKET_DATA_UNIT_T pdu) {
        if (currentCapacity >= maxCapacity) {
            // Resize the buffer
            int newSize = maxCapacity * 2 + frameSize;
            PACKET_DATA_UNIT_T *newBuffer = (PACKET_DATA_UNIT_T *)realloc(buffer, newSize * sizeof(PACKET_DATA_UNIT_T));

            if (!newBuffer) {
                printf("Error: Memory reallocation failed\n");
                return;
            }

            buffer = newBuffer;
            maxCapacity = newSize;
        }

        // Add the PDU to the end of the buffer
        memcpy(&buffer[currentCapacity], &pdu, frameSize);
        currentCapacity++;
    }

    // Function to retrieve packets within the buffer
    void getPacket(int index) {
        if (index >= 0 && index < currentCapacity) {
            // Retrieve and process the packet at the given index
            PACKET_DATA_UNIT_T pdu = buffer[index];
            printf("Received PDU: %d\n", pdu);
        } else {
            printf("Error: Packet not found or out of bounds\n");
        }
    }

    // Function to recover from errors and graceful degradation in case of resource exhaustion
    void recover() {
        if (currentCapacity > maxCapacity / 2) {
            // Reduce the buffer size to avoid excessive fragmentation
            int newSize = maxCapacity / 2 + frameSize;
            PACKET_DATA_UNIT_T *newBuffer = (PACKET_DATA_UNIT_T *)realloc(buffer, newSize * sizeof(PACKET_DATA_UNIT_T));

            if (!newBuffer) {
                printf("Error: Memory reallocation failed\n");
                return;
            }

            buffer = newBuffer;
            currentCapacity = maxCapacity / 2;
        }
    }

    // Function to integrate with existing network stack protocols
    void processPacket(int index, int protocol) {
        if (index >= 0 && index < currentCapacity) {
            // Process the packet based on the given protocol
            PACKET_DATA_UNIT_T pdu = buffer[index];
            printf("Processing PDU for protocol %d: %d\n", protocol, pdu);
        } else {
            printf("Error: Packet not found or out of bounds\n");
        }
    }

    // Function to display buffer statistics and packet loss rates
    void displayStats() {
        printf("Buffer utilization: %.2f%%\n", (double)currentCapacity / maxCapacity * 100);
        printf("Packet loss rate: %.2f%%\n", (double)(maxCapacity - currentCapacity) / maxCapacity * 100);
    }

