        // Add PDUs and retrieve packets
        addPDU({TRANSPORT_FORMAT_AND_MIMO_PARAMS, PHY_TRANSPORT_BLOCK_INFO_T});
        getPacket(0);

        // Recover from errors and graceful degradation
        recover();

        // Process packets based on protocol
        processPacket(1, 1);
        processPacket(2, 2);

        // Display buffer statistics and packet loss rates
        displayStats();

        return 0;
    }
