// Structure to manage the list of data transfer records
typedef struct {
    DATA_TRANSFER_RECORD* elements;
    int size;
    int capacity;
    pthread_mutex_t mutex; // Mutex for thread-safe operations
    pthread_cond_t cond; // Condition variable for waiting on resizing
    int num_elements; // Number of elements currently stored in the list
} LIST_OF_DATA_TRANSFER_RECORDS;

// Function to initialize and manage a dynamically allocated list of DATA_TRANSFER_RECORD structures
LIST_OF_DATA_TRANSFER_RECORDS* init_list_of_data_transfer_records() {
    LIST_OF_DATA_TRANSFER_RECORDS* list = (LIST_OF_DATA_TRANSFER_RECORDS*)malloc(sizeof(LIST_OF_DATA_TRANSFER_RECORDS));
    if (!list) {
        return NULL; // Handle memory allocation failure gracefully
    }

    list->size = 0;
    list->capacity = 10; // Initial capacity for the list
    list->elements = (DATA_TRANSFER_RECORD*)malloc(list->capacity * sizeof(DATA_TRANSFER_RECORD));
    if (!list->elements) {
        free(list);
        return NULL; // Handle memory allocation failure gracefully
    }

    pthread_mutex_init(&list->mutex, NULL); // Initialize mutex for thread-safe operations
    pthread_cond_init(&list->cond, NULL); // Initialize condition variable for waiting on resizing

    list->num_elements = 0;

    return list;
}

// Function to add a new data transfer record to the list while maintaining thread safety
int add_data_transfer_record(LIST_OF_DATA_TRANSFER_RECORDS* list, DATA_TRANSFER_RECORD* record) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread-safe operations

    if (list->num_elements == list->size) {
        // Resize the list if it's full
        int new_capacity = list->capacity * 2; // Double the current capacity
        DATA_TRANSFER_RECORD* new_elements = (DATA_TRANSFER_RECORD*)realloc(list->elements, new_capacity * sizeof(DATA_TRANSFER_RECORD));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex); // Unlock mutex in case of memory allocation failure
            return -1; // Handle memory allocation failure gracefully
        }

        list->capacity = new_capacity;
        list->elements = new_elements;
    }

    memcpy(&list->elements[list->num_elements], record, sizeof(DATA_TRANSFER_RECORD)); // Add the new data transfer record to the list
    list->num_elements++;

    pthread_cond_signal(&list->cond); // Signal condition variable for waiting threads

    pthread_mutex_unlock(&list->mutex); // Unlock mutex after adding the new data transfer record

    return 0; // Successful addition of the data transfer record
}

// Function to get a specific data transfer record from the list while maintaining thread safety
DATA_TRANSFER_RECORD* get_data_transfer_record(LIST_OF_DATA_TRANSFER_RECORDS* list, int index) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread-safe operations

    if (index < 0 || index >= list->num_elements) {
        pthread_mutex_unlock(&list->mutex); // Unlock mutex in case of invalid index
        return NULL; // Handle invalid index gracefully
    }

    DATA_TRANSFER_RECORD* record = &list->elements[index];

    pthread_mutex_unlock(&list->mutex); // Unlock mutex after retrieving the data transfer record

    return record;
}

// Function to free the resources allocated for the list while maintaining thread safety
void free_list_of_data_transfer_records(LIST_OF_DATA_TRANSFER_RECORDS* list) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread-safe operations

    if (list) {
        free(list->elements); // Free memory allocated for data transfer records
        pthread_cond_destroy(&list->cond); // Destroy condition variable
        pthread_mutex_unlock(&list->mutex); // Unlock mutex after freeing resources
        free(list); // Free the list structure itself
    }
}

