typedef struct {
    int session_id;
    char user_name[32];
    time_t login_time;
    time_t last_active_time;
} USER_SESSION;

typedef struct {
    USER_SESSION* table;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int active_sessions;
} HASH_TABLE;

void* hash_table_create(size_t initial_capacity) {
    HASH_TABLE* table = (HASH_TABLE*)malloc(sizeof(HASH_TABLE));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->table = (USER_SESSION*)calloc(initial_capacity, sizeof(USER_SESSION));
    if (!table->table) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->mutex, NULL);
    pthread_cond_init(&table->cond, NULL);
    table->active_sessions = 0;

    return table;
}

void hash_table_destroy(HASH_TABLE* table) {
    if (!table) return;

    free(table->table);
    pthread_mutex_destroy(&table->mutex);
    pthread_cond_destroy(&table->cond);
    free(table);
}

int hash_table_insert(HASH_TABLE* table, USER_SESSION* session) {
    int index = session->session_id % table->capacity;
    if (table->table[index].session_id != 0) {
        return -1; // collision detected
    }

    pthread_mutex_lock(&table->mutex);
    table->table[index] = *session;
    table->active_sessions++;
    pthread_cond_signal(&table->cond);
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

USER_SESSION* hash_table_lookup(HASH_TABLE* table, int session_id) {
    int index = session_id % table->capacity;
    pthread_mutex_lock(&table->mutex);
    USER_SESSION* result = &table->table[index];
    pthread_mutex_unlock(&table->mutex);

    return result;
}

void hash_table_reorganize(HASH_TABLE* table) {
    size_t new_capacity = table->capacity * 2;
    HASH_TABLE* new_table = (HASH_TABLE*)hash_table_create(new_capacity);

    if (!new_table) return;

    pthread_mutex_lock(&table->mutex);
    USER_SESSION* temp = table->table;
    table->table = new_table->table;
    new_table->table = temp;
    table->capacity = new_capacity;
    pthread_mutex_unlock(&table->mutex);

    hash_table_destroy(new_table);
}

