enum {
    SUCCESS,
    MEMORY_ERROR,
    FILE_READ_ERROR,
    CONTEXT_UPDATE_FAILURE
};

LteUeContext* lte_ue_context_pool[CONTEXT_RECORDS_MAX];
pthread_mutex_t context_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("ue_context.log", "a");

// Function to manage LTE UE contexts
int ue_context_mgmt(int ue_id, const char* nas_message_queue, enum LteUeContextState rrc_connection_state) {
    int idx = -1;
    pthread_mutex_lock(&context_lock);

    // Search for existing context by UE-ID
    for (int i = 0; i < CONTEXT_RECORDS_MAX; i++) {
        if (!lte_ue_context_pool[i].ue_id) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        // Allocate new context record
        LteUeContext* new_ctx = (LteUeContext*) malloc(sizeof(LteUeContext));
        if (!new_ctx) {
            pthread_mutex_unlock(&context_lock);
            return MEMORY_ERROR;
        }
        lte_ue_context_pool[idx] = new_ctx;
    }

    // Update context record
    lte_ue_context_pool[idx]->ue_id = ue_id;
    lte_ue_context_pool[idx]->nas_message_queue = strdup(nas_message_queue);
    lte_ue_context_pool[idx]->rrc_connection_state = rrc_connection_state;

    pthread_mutex_unlock(&context_lock);

    if (fputs("Updated UE context: ", log_file) == EOF || fputc('\n', log_file) == EOF) {
        fclose(log_file);
        return FILE_READ_ERROR;
    }

    return SUCCESS;
}

// Function to read and process the text file
int process_text_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return FILE_READ_ERROR;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        int last_field_idx = 0;
        for (int i = strlen(line) - 1; i >= 0; i--) {
            if (line[i] == ',') {
                last_field_idx = i + 1;
                break;
            }
        }

        double avg_last_two_fields = (atof(&line[last_field_idx]) + atof(&line[0])) / 2.0;

        printf("%s,%.2lf\n", line, avg_last_field);

        // Allocate memory dynamically for the line and free it after use
        char* line_copy = (char*) malloc(strlen(line) + 1);
        strcpy(line_copy, line);
        free(line);
    }

    fclose(file);
    return SUCCESS;
}

int main() {
    if (process_text_file("ue_contexts.txt") != SUCCESS) {
        printf("Error processing text file.\n");
    }

    // Test the UE context management function
    if (ue_context_mgmt(123, "some nas message queue", CONNECTED) != SUCCESS) {
        printf("Error updating UE context.\n");
    }

    return 0;
}
