    char *output_file;
    int verbose;
} CommandLineOptions;

// Define a struct to hold file processing information
typedef struct {
    FILE *file;
    int line_number;
    time_t start_time;
    time_t end_time;
} FileProcessingInfo;

// Function to parse command line arguments
void parseCommandLineArgs(int argc, char **argv, CommandLineOptions *options) {
    // Initialize options with default values
    options->count = 0;
    options->suppress_line_numbers = 0;
    options->output_file = NULL;
    options->verbose = 0;

    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0) {
            options->count = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-s") == 0) {
            options->suppress_line_numbers = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            options->output_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "--manpage") == 0) {
            printf("Usage: file_processing_tool [options] <input_file>\n");
            printf("Options:\n");
            printf("  -c <count>: Print only the first <count> lines of the input file.\n");
            printf("  -s: Suppress the printing of line numbers while reading the file.\n");
            printf("  -o <output_file>: Redirect the output to a specified file instead of standard output.\n");
            printf("  --manpage: Display detailed usage information and exit.\n");
            return;
        }
    }

    // Check if an input file was specified
    if (i >= argc) {
        fprintf(stderr, "Error: No input file specified.\n");
        return;
    }

    options->input_file = argv[i];
}

// Function to process a single file
void processFile(FileProcessingInfo *file_info, CommandLineOptions *options) {
    // Open the file for reading and writing (if output file is specified)
    if (!file_info->file) {
        file_info->file = fopen(file_info->input_file, "r");
        if (!file_info->file) {
            fprintf(stderr, "Error: Unable to open input file '%s' for reading.\n", file_info->input_file);
            return;
        }
    }

    // Read the file line by line and perform operations based on options
    int i = 0;
    while (fgets(file_info->line_buffer, sizeof(file_info->line_buffer), file_info->file)) {
        // Track processing time
        if (file_info->start_time == 0) {
            file_info->start_time = time(NULL);
        }

        // Perform operations based on options
        if (options->count > 0 && i < options->count) {
            printf("%s", file_info->line_buffer);
        } else if (!options->suppress_line_numbers) {
            printf("[%d] %s", i + 1, file_info->line_buffer);
        }

        // Update line number and processing time
        i++;
        file_info->end_time = time(NULL);

        // Check for end of file
        if (feof(file_info->file)) {
            break;
        }
    }

    // Close the file
    fclose(file_info->file);

    // Print processing statistics
    printf("Processing time: %ld seconds\n", file_info->end_time - file_info->start_time);
}

// Function to process multiple files in batch mode
void processBatchFiles(int argc, char **argv, CommandLineOptions *options) {
    // Initialize batch processing information
    int batch_file_count = 0;
    FILE *batch_file = NULL;

    // Process each input file sequentially
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-") == 0) {
            // Process the current batch file
            processFile(&batch_file_info, options);

            // Reset batch processing information
            batch_file_count = 0;
            fclose(batch_file);
            batch_file = NULL;

            // Check for end of batch files
            if (i + 1 >= argc) {
                break;
            }
        } else {
            // Open the current input file for reading and writing (if output file is specified)
            FILE *file = fopen(argv[i], "r");
            if (!file) {
                fprintf(stderr, "Error: Unable to open input file '%s' for reading.\n", argv[i]);
                return;
            }

            // Add the file to the batch
            batch_file_info.file = file;
            batch_file_count++;

            // Open the batch file for writing (if output file is specified)
            if (!batch_file) {
                batch_file = fopen(options->output_file, "w");
                if (!batch_file) {
                    fprintf(stderr, "Error: Unable to open output file '%s' for writing.\n", options->output_file);
                    return;
                }
            }

            // Process the input file line by line
            while (fgets(line_buffer, sizeof(line_buffer), file)) {
                // Track processing time
                if (start_time == 0) {
                    start_time = time(NULL);
                }

                // Perform operations based on options
                if (options->count > 0 && i < options->count) {
                    printf("%s", line_buffer);
                } else if (!options->suppress_line_numbers) {
                    printf("[%d] %s", i + 1, line_buffer);
                }

                // Update line number and processing time
                i++;
                end_time = time(NULL);

                // Check for end of file
                if (feof(file)) {
                    break;
                }
            }

            // Close the input file and reset line number
            fclose(file);
            i = 0;

            // Check for end of batch files
            if (i + 1 >= argc) {
                break;
            }
        }
    }

    // Process the last batch file
    processFile(&batch_file_info, options);

    // Generate summary report
    printf("Total lines processed: %d\n", total_lines_processed);
    printf("Average processing time per file: %ld seconds\n", average_processing_time_per_file);
}

// Function to generate a summary report in the specified format (e.g., JSON, CSV)
void generateSummaryReport(int batch_file_count, int total_lines_processed, double average_processing_time_per_file) {
    // Determine the output format
    char *output_format = getenv("OUTPUT_FORMAT");
    if (!output_format || strcmp(output_format, "JSON") == 0) {
        // Generate JSON report
        printf("{\n");
        printf("  \"total_lines_processed\": %d,\n", total_lines_processed);
        printf("  \"average_processing_time_per_file\": %.2f\n", average_processing_time_per_file);
        printf("}\n");
    } else if (strcmp(output_format, "CSV") == 0) {
        // Generate CSV report
        printf("%d,%f\n", total_lines_processed, average_processing_time_per_file);
    }
}

int main(int argc, char **argv) {
    CommandLineOptions options;
    parseCommandLineArgs(argc, argv, &options);

    if (options.input_file) {
        FileProcessingInfo file_info;
        processFile(&file_info, &options);
    } else {
        processBatchFiles(argc, argv, &options);
    }

    return 0;
}
