// Function prototypes
void generateNfaPduList(int argc, char **argv);

int main(int argc, char **argv) {
    // Parse command line arguments
    int count = -1;
    char *inputDir = NULL;
    int suppressLineNumbers = 0;
    int redirectOutput = 0;
    int manpage = 0;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-c")) {
            count = atoi(argv[i + 1]);
            i++;
        } else if (!strcmp(argv[i], "-s")) {
            suppressLineNumbers = 1;
        } else if (!strcmp(argv[i], "-o")) {
            redirectOutput = 1;
        } else if (!strcmp(argv[i], "--manpage")) {
            manpage = 1;
        } else if (inputDir == NULL) {
            inputDir = argv[i];
        }
    }

    // Call the function to generate NFA PDU list
    generateNfaPduList(argc, argv);

    return 0;
}

void generateNfaPduList(int argc, char **argv) {
    // Initialize variables
    int numFilesProcessed = 0;
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    // Process files in the specified directories
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-c")) {
            continue;
        } else if (!strcmp(argv[i], "-s") || !strcmp(argv[i], "-o") || !strcmp(argv[i], "--manpage")) {
            continue;
        }

        // Open the file
        int fd = open(argv[i], O_RDONLY);
        if (fd < 0) {
            printf("Error opening file: %s\n", argv[i]);
            return;
        }

        // Read and process lines in the file
        char line[1024];
        while (read(fd, line, 1023) > 0) {
            numFilesProcessed++;
            // Process the line here

            if (numFilesProcessed % 60 == 0) {
                clock_gettime(CLOCK_REALTIME, &end_time);
                double elapsed_time = (double)(end_time.tv_nsec - start_time.tv_nsec) / 1000000000;
                printf("Lines processed per minute: %f\n", numFilesProcessed / elapsed_time);
                clock_gettime(CLOCK_REALTIME, &start_time);
            }
        }

        close(fd);
    }

    // Close the file
    if (inputDir != NULL) {
        int fd = open(inputDir, O_RDONLY);
        if (fd < 0) {
            printf("Error opening input directory: %s\n", inputDir);
            return;
        }

        close(fd);
    }

    clock_gettime(CLOCK_REALTIME, &end_time);
    double elapsed_time = (double)(end_time.tv_nsec - start_time.tv_nsec) / 1000000000;
    printf("Total processing time: %f seconds\n", elapsed_time);

    return;
}
