typedef struct {
    pthread_mutex_t lock;
    int num_records;
    NFAPI_CRC_INDICATION_PDU_T* records;
} LTE_UeContextRecordPool;

void lte_ue_context_record_pool_init(LTE_UeContextRecordPool* pool, int n) {
    pool->num_records = 0;
    pool->records = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&pool->lock, NULL);
}

void lte_ue_context_record_pool_free(LTE_UeContextRecordPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
}

int lte_ue_context_record_pool_add(LTE_UeContextRecordPool* pool, int n) {
    NFAPI_CRC_INDICATION_PDU_T* new_records = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->records, (n + pool->num_records) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_records)
        return -1; // allocation failure
    memset(&new_records[pool->num_records], 0, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&pool->lock);
    pool->records = new_records;
    pool->num_records += n;
    pthread_mutex_unlock(&pool->lock);
    return 0; // success
}

void lte_ue_context_record_pool_update(LTE_UeContextRecordPool* pool, int ue_id) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->num_records; i++) {
        if (pool->records[i].rx_ue_info_tag == ue_id) {
            // update UE context record
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void lte_ue_context_record_pool_destroy(LTE_UeContextRecordPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
}
