// Function prototypes
void print_usage();
int parse_args(int argc, char *argv[], FILE **input_file, int *line_count, int *suppress_lines, char **output_file);
void process_file(FILE *input_file, int line_count, int suppress_lines, char *output_file);
void log_processing_time(double processing_time);

int main(int argc, char *argv[]) {
    // Initialize variables
    FILE *input_file = NULL;
    int line_count = 0;
    int suppress_lines = 0;
    char *output_file = NULL;

    // Parse command-line arguments
    if (!parse_args(argc, argv, &input_file, &line_count, &suppress_lines, &output_file)) {
        return 1; // Exit with error code
    }

    // Process input file
    process_file(input_file, line_count, suppress_lines, output_file);

    // Log processing time
    double processing_time = clock() - (double)clock();
    log_processing_time(processing_time / CLOCKS_PER_SEC);

    return 0;
}

// Function to print usage information
void print_usage() {
    printf("Usage: program [-c <count>] [-s] [-o <output_file>] [--manpage]\n");
    printf("[-c <count>]: Print only the first <count> lines of the input file.\n");
    printf("[-s]: Suppress the printing of line numbers while reading the file.\n");
    printf("[-o <output_file>]: Redirect the output to a specified file instead of standard output.\n");
    printf("--manpage: Display detailed usage information and exit.\n");
}

// Function to parse command-line arguments
int parse_args(int argc, char *argv[], FILE **input_file, int *line_count, int *suppress_lines, char **output_file) {
    // Initialize variables
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0) {
            line_count = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-s") == 0) {
            *suppress_lines = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            *output_file = argv[++i];
        } else if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return 0; // Exit with error code
        }
    }

    // Check for input file
    if (argc <= i) {
        printf("Error: No input file specified.\n");
        print_usage();
        return -1;
    }

    *input_file = fopen(argv[i], "r");
    if (*input_file == NULL) {
        printf("Error: Cannot open input file '%s'.\n", argv[i]);
        print_usage();
        return -1;
    }

    return 1; // Successful parsing
}

// Function to process the input file
void process_file(FILE *input_file, int line_count, int suppress_lines, char *output_file) {
    FILE *temp_output = stdout;

    if (output_file != NULL) {
        temp_output = fopen(output_file, "w");
        if (temp_output == NULL) {
            printf("Error: Cannot open output file '%s'.\n", output_file);
            return;
        }
    }

    // Initialize variables
    int line_number = 0;
    char line[1024];
    regex_t pattern;

    while (fgets(line, sizeof(line), input_file)) {
        if (!suppress_lines) {
            printf("%d: %s", ++line_number, line);
        } else {
            printf("%s", line);
        }

        // Check for regex filtering
        if (regcomp(&pattern, "your_pattern_here", REG_EXTENDED) == 0) {
            regmatch_t match;
            regexec(&pattern, line, sizeof(line), &match, 0);
            if (!regmatch_error() && (line[match.rm_so] != '\0' || line[match.rm_eo] != '\0')) {
                printf("%s", line);
            }
        }

        if (output_file != NULL) {
            fprintf(temp_output, "%s", line);
        } else {
            printf("%s", line);
