#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_id;
    // NAS message queue
    // RRC connection state
    // extended metadata (last active time and signal strength)
} lte_ue_context;

// LRU cache size
#define LRU_CACHE_SIZE 100

// Structure for the dynamic pool of LTE UE context records
typedef struct {
    pthread_mutex_t lock;
    int size;
    int capacity;
    lte_ue_context* contexts;
    // LRU cache (least recently used)
    int lru_head;
    int lru_tail;
} lte_ue_pool;

// Initialize the dynamic pool with a given initial capacity
lte_ue_pool* lte_ue_pool_init(int initial_capacity) {
    lte_ue_pool* pool = (lte_ue_pool*)malloc(sizeof(lte_ue_pool));
    if (!pool) return NULL;

    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->contexts = (lte_ue_context*)calloc(initial_capacity, sizeof(lte_ue_context));
    if (!pool->contexts) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    // Initialize LRU cache
    pool->lru_head = 0;
    pool->lru_tail = 0;

    return pool;
}

// Allocate a new UE context and add it to the dynamic pool
lte_ue_context* lte_ue_pool_alloc(lte_ue_pool* pool) {
    if (pool->size >= pool->capacity) {
        // Reallocate with double capacity
        int new_capacity = pool->capacity * 2;
        lte_ue_context* new_contexts = (lte_ue_context*)realloc(pool->contexts, new_capacity * sizeof(lte_ue_context));
        if (!new_contexts) return NULL;

        pthread_mutex_unlock(&pool->lock);

        // Update pool's state
        pool->capacity = new_capacity;
        pool->contexts = new_contexts;

        pthread_mutex_lock(&pool->lock);
    }

    lte_ue_context* context = &pool->contexts[pool->size++];
    return context;
}

// Deallocate a UE context from the dynamic pool (LRU cache eviction)
void lte_ue_pool_free(lte_ue_pool* pool) {
    if (pool->lru_tail == 0) {
        // No contexts in LRU cache, just decrement size
        --pool->size;
    } else {
        // Evict the least recently used context from LRU cache
        int lru_index = pool->lru_head;
        pool->lru_head = (pool->lru_head + 1) % pool->capacity;

        // Update the size and free the evicted context
        --pool->size;
        if (lru_index < pool->size) {
            memmove(&pool->contexts[lru_index], &pool->contexts[lru_tail], sizeof(lte_ue_context));
            pool->lru_tail = lru_index;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Retrieve a UE context from the dynamic pool by its ID
lte_ue_context* lte_ue_pool_get(lte_ue_pool* pool, uint32_t ue_id) {
    // Find the context with matching UE-ID in LRU cache
    for (int i = 0; i < pool->size; i++) {
        if (pool->contexts[i].ue_id == ue_id) {
            // Update LRU cache
            if (i < pool->lru_tail)
                pool->lru_head = i;
            else
                pool->lru_tail = i;

            return &pool->contexts[i];
        }
    }

    return NULL; // UE context not found in the pool
}

// Retrieve a UE context from the dynamic pool by its ID (concurrent access)
void* lte_ue_pool_get_concurrent(lte_ue_pool* pool, uint32_t ue_id) {
    pthread_mutex_lock(&pool->lock);

    lte_ue_context* context = lte_ue_pool_get(pool, ue_id);
    if (!context) {
        // Log UE not found
        // ...
    }

    pthread_mutex_unlock(&pool->lock);
    return context;
}

// Main function to manage the dynamic pool of LTE UE contexts
int main() {
    // Initialize the dynamic pool with an initial capacity
    lte_ue_pool* pool = lte_ue_pool_init(LRU_CACHE_SIZE);

    if (!pool) {
        // Log allocation failure
        // ...
    }

    // Use the pool for context management
    while (1) {
        // Allocate a new UE context and add it to the pool
        lte_ue_context* context = lte_ue_pool_alloc(pool);
        if (!context) {
            // Log allocation failure
            // ...
        }

        // Deallocate an existing UE context from the pool (LRU cache eviction)
        lte_ue_pool_free(pool);

        // Retrieve a UE context by its ID
        lte_ue_context* retrieved_context = lte_ue_pool_get(pool, 12345);
        if (!retrieved_context) {
            // Log UE not found
            // ...
        }
    }

    return 0;
}

