typedef struct {
    int key;
    char id[20];
} Record;

Record* createRecord(int key, const char* id) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    record->key = key;
    strcpy(record->id, id);
    return record;
}

int main() {
    // Define maximum number of records and value range
    int maxRecords = 1000;
    int minValue = 1;
    int maxValue = 100;

    // Initialize offset array for 'long' values and key array for 'int' values
    long* offsets = (long*)malloc(maxRecords * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed.\n");
        return 1;
    }
    int* keys = (int*)malloc(maxRecords * sizeof(int));

    // Initialize summary array with pointers to records and number of records each summary covers
    Record** summaries = (Record**)malloc((maxRecords / 10) * sizeof(Record*));
    if (!summaries) {
        printf("Memory allocation failed.\n");
        free(offsets);
        return 1;
    }
    int numSummaries = maxRecords / 10;

    // Initialize record count
    int recordCount = 0;

    // Generate random records and store them in arrays
    for (int i = 0; i < maxRecords; i++) {
        Record* record = createRecord(rand() % (maxValue - minValue + 1) + minValue, "record");
        if (!record) {
            printf("Memory allocation failed.\n");
            return 1;
        }
        offsets[i] = (long)record;
        keys[i] = record->key;

        // Add records to summaries
        int summaryIndex = i / 10;
        if (summaryIndex >= numSummaries) {
            // Handle overflow
            printf("Record count exceeds maximum.\n");
            return 1;
        }
        Record* currentSummary = &summaries[summaryIndex];
        currentSummary->key = record->key;
        currentSummary->id = "record";
        if (currentSummary == NULL) {
            // Handle null pointer dereference
            printf("Invalid summary record.\n");
            return 1;
        }
    }

    // Sort records by their integer values in ascending order
    for (int i = 0; i < maxRecords - 1; i++) {
        for (int j = i + 1; j < maxRecords; j++) {
            if (keys[i] > keys[j]) {
                int tempKey = keys[i];
                long tempOffset = offsets[i];
                Record* tempRecord = createRecord(tempKey, "record");
                if (!tempRecord) {
                    printf("Memory allocation failed.\n");
                    return 1;
                }
                offsets[i] = offsets[j];
                keys[i] = keys[j];
                offsets[j] = tempOffset;
                keys[j] = tempKey;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < numSummaries; i++) {
        free(summaries[i]);
    }
    free(summaries);
    free(offsets);
    free(keys);

    return 0;
}
