#define MAX_SENSOR_DATA 100
#define MAX_SENSOR_IDENTIFIER_LENGTH 32

typedef struct {
    char sensor_identifier[MAX_SENSOR_IDENTIFIER_LENGTH];
    int time_stamp;
    double sensor_reading;
} SENSOR_DATA_PDU_T;

SENSOR_DATA_PDU_T* processStreamingSensorData(int batch_size, int max_batch_size) {
    // Initialize the data array and allocate memory
    SENSOR_DATA_PDU_T* sensor_data = (SENSOR_DATA_PDU_T*)malloc(batch_size * sizeof(SENSOR_DATA_PDU_T));

    // Initialize the rate limiter
    int token_bucket = 0;
    int tokens_per_second = 100;
    int bucket_size = 10000; // Tokens per second times seconds until refill

    for (int i = 0; i < batch_size; i++) {
        if (token_bucket >= bucket_size) {
            token_bucket -= bucket_size;
        } else {
            if (rand() % tokens_per_second == 0) {
                continue; // Rate limit exceeded, skip this sensor data
            }
        }

        // Generate random sensor data
        sprintf(sensor_data[i].sensor_identifier, "Sensor_%d", i);
        sensor_data[i].time_stamp = rand();
        sensor_data[i].sensor_reading = (double)rand() / RAND_MAX;

        token_bucket++;
    }

    return sensor_data;
}

void* processBatch(void* arg) {
    // Get the batch size and max batch size
    int* batch_size_ptr = (int*)arg;
    int batch_size = *batch_size_ptr;
    int max_batch_size = 100; // Default max batch size

    // Process the batch of sensor data
    SENSOR_DATA_PDU_T* sensor_data = processStreamingSensorData(batch_size, max_batch_size);

    // Validate the integrity of the data processing pipeline
    if (sensor_data == NULL) {
        printf("Error: Data processing failed.\n");
        return NULL;
    }

    // Process the sensor data
    for (int i = 0; i < batch_size; i++) {
        printf("%s - %d - %.2f\n", sensor_data[i].sensor_identifier, sensor_data[i].time_stamp, sensor_data[i].sensor_reading);
    }

    free(sensor_data);

    return NULL;
}

int main() {
    // Create a thread pool to process batches of sensor data
    pthread_t thread_pool[10];
    int batch_size = 5; // Default batch size

    for (int i = 0; i < 5; i++) {
        pthread_create(&thread_pool[i], NULL, processBatch, &batch_size);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    return 0;
}
