// Define the structure
typedef struct {
    int rnti;
    char name[20];
    int age;
} user_t;

// Define the function to process JSON data
void process_json_data(const json_object* root) {
    // Initialize the list of users
    user_t** users = NULL;
    size_t num_users = 0;

    // Process each element in the JSON array
    json_object* elements = json_object_object_get(root, "users");
    if (elements != NULL) {
        size_t i;
        for (i = 0; i < json_object_array_size(elements); i++) {
            json_object* user_obj = json_object_array_get(elements, i);
            if (user_obj != NULL) {
                user_t* user = malloc(sizeof(user_t));
                if (user != NULL) {
                    user->rnti = json_object_get_int_val(json_object_object_get(user_obj, "rnti"));
                    strcpy(user->name, json_object_get_string_val(json_object_object_get(user_obj, "name")));
                    user->age = json_object_get_int_val(json_object_object_get(user_obj, "age"));

                    // Add the user to the list
                    users = realloc(users, (num_users + 1) * sizeof(user_t*));
                    users[num_users++] = user;
                }
            }
        }
    }

    // Print the user with the highest age
    if (num_users > 0) {
        size_t max_age_index = 0;
        for (i = 1; i < num_users; i++) {
            if (users[i]->age > users[max_age_index]->age) {
                max_age_index = i;
            }
        }
        printf("The user with the highest age is: %s, age %d\n", users[max_age_index]->name, users[max_age_index]->age);
    } else {
        printf("No valid users provided.\n");
    }

    // Free the memory
    for (i = 0; i < num_users; i++) {
        free(users[i]);
    }
    free(users);
}

int main() {
    // Process JSON data
    json_object* root = json_object_from_file("data.json");
    if (root != NULL) {
        process_json_data(root);
        json_object_put(root);
    }

    return 0;
}
