    // Initialize the memory pool
    size_t pool_size = 100;
    NFAPI_CRC_INDICATION_PDU_T* pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the NIC and MAC_E_CONTEXT arrays
    int nic_count = 10;
    int mac_e_context_count = 20;
    int* nics = (int*)malloc(nic_count * sizeof(int));
    int** mac_e_contexts = (int**)malloc(mac_e_context_count * sizeof(int*));

    // Initialize the CRC indication PDU list
    *pdu_list = pool;

    // Generate the NIC and MAC_E_CONTEXT arrays
    for (int i = 0; i < nic_count; i++) {
        nics[i] = i;
    }

    for (int i = 0; i < mac_e_context_count; i++) {
        mac_e_contexts[i] = (int*)malloc(10 * sizeof(int));
        for (int j = 0; j < 10; j++) {
            mac_e_contexts[i][j] = j;
        }
    }

    // Generate the CRC indication PDU list
    int pdu_count = nic_count * mac_e_context_count;
    NFAPI_CRC_INDICATION_PDU_T* pdus = *pdu_list;
    for (int i = 0; i < pdu_count; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i % 100;
        pdus[i].RNTI = i % 256;
        pdus[i].CRC_INDICATION_REL8_TAG = i % 65536;
        pdus[i].CRCFLAG = rand() % 2;

        // Add the NIC and MAC_E_CONTEXT arrays to the CRC indication PDU
        pdus[i].nic_count = nic_count;
        pdus[i].mac_e_contexts = mac_e_contexts;

        // Log some metrics
        printf("Generated PDU: %d, NIC Count: %d, Mac E Context Count: %d\n", i, nic_count, mac_e_context_count);
    }

    // Deallocate the memory pool
    for (int i = 0; i < mac_e_context_count; i++) {
        free(mac_e_contexts[i]);
    }
    free(mac_e_contexts);

    *list_size = pdu_count;
}

int main() {
    int list_size;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;

