#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct {
    uint32_t cell_id;
    uint16_t tsi;
    struct {
        uint32_t rx_success;
        uint32_t rx_failure;
        uint32_t rx_timeout;
        uint32_t rx_packet_loss;
    } phy_rx_stats;
} PHY_STATS_RECORD;

typedef enum { CSV, JSON } export_format;

// Global variable to store the dynamic array
PHY_STATS_RECORD **stats_array = NULL;
size_t stats_array_size = 0;
pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new record to the array
int add_stats_record(uint32_t cell_id, uint16_t tsi, const PHY_RX_STATS *rx_stats) {
    pthread_mutex_lock(&stats_mutex);
    if (stats_array_size >= sizeof(PHY_STATS_RECORD) * 1024) { // resize threshold
        stats_array = realloc(stats_array, sizeof(PHY_STATS_RECORD *) * (stats_array_size + 1));
        stats_array[stats_array_size] = malloc(sizeof(PHY_STATS_RECORD));
        stats_array_size++;
    }
    PHY_STATS_RECORD *new_record = stats_array[stats_array_size - 1];
    new_record->cell_id = cell_id;
    new_record->tsi = tsi;
    memcpy(&new_record->phy_rx_stats, rx_stats, sizeof(PHY_RX_STATS));
    pthread_mutex_unlock(&stats_mutex);
    return stats_array_size - 1; // return the index of the newly added record
}

// Function to update an existing record in the array
int update_stats_record(int idx, const PHY_RX_STATS *rx_stats) {
    pthread_mutex_lock(&stats_mutex);
    if (idx < 0 || idx >= stats_array_size) {
        pthread_mutex_unlock(&stats_mutex);
        return -1; // invalid index
    }
    stats_array[idx]->phy_rx_stats = *rx_stats;
    pthread_mutex_unlock(&stats_mutex);
    return 0;
}

// Function to get the count of elements in the array
size_t get_stats_count() {
    return stats_array_size;
}

// Function to periodically clean up old records based on a configured time threshold
void cleanup_stats_records(int timeout) {
    pthread_mutex_lock(&stats_mutex);
    for (int i = 0; i < stats_array_size; i++) {
        if ((time(NULL) - stats_array[i]->phy_rx_stats.rx_success) > timeout) {
            free(stats_array[i]);
            memmove(stats_array + i, stats_array + i + 1, sizeof(PHY_STATS_RECORD *) * (stats_array_size - i - 1));
            stats_array_size--;
        }
    }
    pthread_mutex_unlock(&stats_mutex);
}

// Function to export the current state of the statistics to a file
int export_stats_to_file(export_format format) {
    FILE *fp = fopen("stats_data.csv", "w"); // default CSV format
    if (fp == NULL) return -1;
    for (int i = 0; i < stats_array_size; i++) {
        fprintf(fp, "%u,%hu,%.16f,%.16f,%.16f\n",
            stats_array[i]->cell_id,
            stats_array[i]->tsi,
            (double)stats_array[i]->phy_rx_stats.rx_success / (stats_array[i]->phy_rx_stats.rx_failure + 1.0),
            (double)stats_array[i]->phy_rx_stats.rx_timeout / (stats_array[i]->phy_rx_stats.rx_packet_loss + 1.0)
        );
    }
    fclose(fp);
    return 0;
}

// Configuration interface to adjust the size of the dynamic array
int set_stats_array_size(size_t new_size) {
    stats_array = realloc(stats_array, sizeof(PHY_STATS_RECORD *) * new_size);
    stats_array_size = new_size;
    return 0;
}
