                // Process lines based on the command-line arguments
                // ...

                // Update rolling statistics
                linesProcessed++;
                time_t currentTime = time(NULL);
                if (difftime(currentTime, startTime) >= 60.0f) {
                    int minutesProcessed = linesProcessed / 60;
                    minuteCount += minutesProcessed;
                    linesProcessed %= 60;
                    printf("Lines processed per minute: %d\n", minutesProcessed);
                    startTime = currentTime;
                }
            }

            fclose(file);
        }
        closedir(dirp);
    }

    // Print final statistics
    int totalMinutesProcessed = minuteCount + (linesProcessed / 60.0f);
    printf("Total lines processed: %d\n", linesProcessed);
    printf("Total minutes processed: %d\n", totalMinutesProcessed);

    return 0;
}
