typedef struct {
    int UE_ID;
    int SRBs[10]; // Array to hold 10 SRBs and DRBs each
    int DRBs[10];
    char Network_Config[256]; // Array to hold network configuration details
} LTE_UE_Context;

// Structure definition for UE Context List
typedef struct {
    LTE_UE_Context* contexts;
    int size;
    pthread_mutex_t lock; // Mutex for thread-safe access
} LTE_UE_Context_List;

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU_T(int n) {
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
