        result[i].RX_UE_INFORMATION_TAG = rand();
        result[i].RNTI = rand();
        strcpy(result[i].CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
    }
    return result;
}

// Function to initialize a list of LTE UE Contexts
LTE_UE_Context_List* init_LTE_UE_Context_List(int n) {
    LTE_UE_Context_List* result = (LTE_UE_Context_List*)malloc(sizeof(LTE_UE_Context_List));
    result->contexts = (LTE_UE_Context*)malloc(n * sizeof(LTE_UE_Context));
    for (int i = 0; i < n; i++) {
        // Initialize UE ID, SRBs and DRBs with default values
        result->contexts[i].UE_ID = i;
        memset(result->contexts[i].SRBs, 0, sizeof(int) * 10);
        memset(result->contexts[i].DRBs, 0, sizeof(int) * 10);
        strcpy(result->contexts[i].Network_Config, "Default Network Configuration");
    }
    result->size = n;
    pthread_mutex_init(&result->lock, NULL); // Initialize mutex
    return result;
}

// Function to add SRB and DRB to a UE Context
void add_SRBS_DRBs(LTE_UE_Context* context, int SRB, int DRB) {
    // Add SRB and DRB to the context's arrays
    for (int i = 0; i < 10; i++) {
        if (context->SRBs[i] == 0) {
            context->SRBs[i] = SRB;
            return;
        }
    }
    for (int i = 0; i < 10; i++) {
        if (context->DRBs[i] == 0) {
            context->DRBs[i] = DRB;
            return;
        }
    }
}

// Function to remove SRB and DRB from a UE Context
void remove_SRBS_DRBs(LTE_UE_Context* context, int SRB, int DRB) {
    // Find the SRB and DRB in the context's arrays
    for (int i = 0; i < 10; i++) {
        if (context->SRBs[i] == SRB) {
            context->SRBs[i] = 0;
            return;
        }
    }
    for (int i = 0; i < 10; i++) {
        if (context->DRBs[i] == DRB) {
            context->DRBs[i] = 0;
            return;
        }
    }
}

// Function to update SRB and DRB in a UE Context
void update_SRBS_DRBs(LTE_UE_Context* context, int oldSRB, int newSRB, int oldDRB, int newDRB) {
    // Find the old SRB and DRB in the context's arrays
    for (int i = 0; i < 10; i++) {
        if (context->SRBs[i] == oldSRB) {
            context->SRBs[i] = newSRB;
            return;
        }
    }
    for (int i = 0; i < 10; i++) {
        if (context->DRBs[i] == oldDRB) {
            context->DRBs[i] = newDRB;
            return;
        }
    }
}

// Function to handle context expiration based on idle timeout settings
void expire_contexts(LTE_UE_Context_List* ue_context_list, int idle_timeout) {
    // Iterate over the UE contexts and check if they are expired
    for (int i = 0; i < ue_context_list->size; i++) {
        LTE_UE_Context* context = &ue_context_list->contexts[i];
        // Check if the context has been idle for longer than the timeout
        if (context->idle_time > idle_timeout) {
            // Remove the expired context from the list
            memmove(&ue_context_list->contexts[i], &ue_context_list->contexts[i + 1], sizeof(LTE_UE_Context) * (ue_context_list->size - i));
            ue_context_list->size--;
        }
    }
}

// Function to export UE Context data to a standardized format
void export_ue_contexts(LTE_UE_Context_List* ue_context_list, char* output_file) {
    // Open the output file for writing
    FILE* output = fopen(output_file, "w");
    if (output == NULL) {
        printf("Failed to open output file\n");
        return;
    }
    // Write the UE contexts to the output file in a standardized format
    for (int i = 0; i < ue_context_list->size; i++) {
        LTE_UE_Context* context = &ue_context_list->contexts[i];
        fprintf(output, "UE ID: %d\n", context->UE_ID);
        for (int j = 0; j < 10; j++) {
            if (context->SRBs[j] != 0) {
                fprintf(output, "SRB: %d\n", context->SRBs[j]);
            }
            if (context->DRBs[j] != 0) {
                fprintf(output, "DRB: %d\n", context->DRBs[j]);
            }
        }
    }
    fclose(output);
}

int main() {
    // Initialize the UE context list with a size of 10,000
    LTE_UE_Context_List* ue_context_list = init_LTE_UE_Context_List(10000);

    // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = generate_NFAPI_CRC_INDICATION_PDU_T(10);

    // Add, remove, and update SRBs and DRBs in the UE contexts
    for (int i = 0; i < ue_context_list->size; i++) {
        LTE_UE_Context* context = &ue_context_list->contexts[i];
        add_SRBS_DRBs(context, 1, 2);
        remove_SRBS_DRBs(context, 1, 0);
        update_SRBS_DRBs(context, 3, 4, 5, 6);

        // Check if the context has expired and handle expiration
        if (context->idle_time > 10) {
            expire_contexts(ue_context_list, 10);
        }
    }

    // Export the UE contexts to a standardized format
    export_ue_contexts(ue_context_list, "output.txt");

    return 0;
}
