    LIST(GTPV2_CONTEXT_PG) p_gw_contexts;
    SESSION_MGMT_T session_mgmt;
} GTPV2_CONTEXT_T;

typedef struct {
    pthread_mutex_t mutex;
    LIST(GTPV2_CONTEXT_T) ue_contexts;
    CACHED_LIST(GTPV2_MESSAGE_T) gtpv2_messages;
    SESSION_TIMEOUT_T session_timeout;
    LOGGING_T logging;
} GTPV2_MANAGEMENT_T;

GTPV2_MANAGEMENT_T *gtpv2_management = NULL;

void gtpv2_init() {
    gtpv2_management = malloc(sizeof(GTPV2_MANAGEMENT_T));
    pthread_mutex_init(&gtpv2_management->mutex, NULL);
    INIT_LIST_HEAD(&gtpv2_management->ue_contexts);
    INIT_CACHED_LIST_HEAD(&gtpv2_management->gtpv2_messages);
    gtpv2_management->session_timeout = DEFAULT_SESSION_TIMEOUT;
    LOGGING_INIT();
}

void gtpv2_add_ue_context(GTPV2_CONTEXT_T *context) {
    pthread_mutex_lock(&gtpv2_management->mutex);
    list_add(&gtpv2_management->ue_contexts, &context->list);
    pthread_mutex_unlock(&gtpv2_management->mutex);
    LOGGING_ADD_CONTEXT(context);
}

void gtpv2_remove_ue_context(uint32_t ue_id) {
    pthread_mutex_lock(&gtpv2_management->mutex);
    LIST_FOREACH(GTPV2_CONTEXT_T, &gtpv2_management->ue_contexts, it) {
        if (it->ue_id == ue_id) {
            list_del(&gtpv2_management->ue_contexts, &it->list);
            break;
        }
    }
    pthread_mutex_unlock(&gtpv2_management->mutex);
    LOGGING_REMOVE_CONTEXT(ue_id);
}

void gtpv2_update_ue_context(GTPV2_CONTEXT_T *context) {
    pthread_mutex_lock(&gtpv2_management->mutex);
    LIST_FOREACH(GTPV2_CONTEXT_T, &gtpv2_management->ue_contexts, it) {
        if (it->ue_id == context->ue_id) {
            // update UE context
            break;
        }
    }
    pthread_mutex_unlock(&gtpv2_management->mutex);
    LOGGING_UPDATE_CONTEXT(context);
}

void gtpv2_expire_ue_context(uint32_t ue_id, uint32_t timestamp) {
    pthread_mutex_lock(&gtpv2_management->mutex);
    LIST_FOREACH(GTPV2_CONTEXT_T, &gtpv2_management->ue_contexts, it) {
        if (it->ue_id == ue_id && it->session_mgmt.timestamp + it->session_mgmt.timeout < timestamp) {
            // expire UE context
            break;
        }
    }
    pthread_mutex_unlock(&gtpv2_management->mutex);
    LOGGING_EXPIRE_CONTEXT(ue_id);
}

void gtpv2_export_ue_contexts() {
    // export GTPv2 Context data to a standardized format
}

void gtpv2_free() {
    pthread_mutex_lock(&gtpv2_management->mutex);
    LIST_FOREACH(GTPV2_CONTEXT_T, &gtpv2_management->ue_contexts, it) {
        free(it);
    }
    free(gtpv2_management);
    LOGGING_DESTROY();
}

int main() {
    gtpv2_init();
    // use gtpv2 management functions
    gtpv2_free();
    return 0;
}
