    uint32_t ue_id;
    GTPV2_MESSAGE_T message;
    SGW_CONTEXT_T sgw_contexts[MAX_SGW_CONTEXTS];
    PGWC_CONTEXT_T pgwc_contexts[MAX_PGWC_CONTEXTS];
} UE_GTPV2_CONTEXT_T;

// Thread-safe context management
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
UE_GTPV2_CONTEXT_T *gtpv2_contexts[MAX_UE_CONTEXTS];

void init_ue_gtpv2_context(UE_GTPV2_CONTEXT_T *context) {
    context->ue_id = (uint32_t)rand();
    context->message = (GTPV2_MESSAGE_T){.header = ({.msg_type = rand() % 2;})};
}

void update_sgw_context(SGW_CONTEXT_T *sgw_context, uint8_t type) {
    sgw_context->type = type;
}

void update_pgwc_context(PGWC_CONTEXT_T *pgwc_context, uint8_t type) {
    pgwc_context->type = type;
}

void add_ue_gtpv2_context(UE_GTPV2_CONTEXT_T *context) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!gtpv2_contexts[i]) {
            gtpv2_contexts[i] = context;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void remove_ue_gtpv2_context(UE_GTPV2_CONTEXT_T *context) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (gtpv2_contexts[i] == context) {
            gtpv2_contexts[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void export_ue_gtpv2_context(UE_GTPV2_CONTEXT_T *context, FILE *file) {
    // Export UE ID and GTPv2 message
    fprintf(file, "UE_ID: %u\n", context->ue_id);
    fprintf(file, "GTPV2_MESSAGE:\n");
    fwrite(&context->message, sizeof(GTPV2_MESSAGE_T), 1, file);

    // Export S-GW and P-GW contexts
    for (int i = 0; i < MAX_SGW_CONTEXTS; i++) {
        if (context->sgw_contexts[i].type != 0) {
            fprintf(file, "SGW_CONTEXT:\n");
            fwrite(&context->sgw_contexts[i], sizeof(SGW_CONTEXT_T), 1, file);
        }
    }

    for (int i = 0; i < MAX_PGWC_CONTEXTS; i++) {
        if (context->pgwc_contexts[i].type != 0) {
            fprintf(file, "PGWC_CONTEXT:\n");
            fwrite(&context->pgwc_contexts[i], sizeof(PGWC_CONTEXT_T), 1, file);
        }
    }
}

// Memory pool for dynamic allocations
void *malloc(size_t size) {
    // Implement memory pool logic here
}

int main() {
    srand(time(NULL));
    UE_GTPV2_CONTEXT_T context;
    init_ue_gtpv2_context(&context);

    // Add UE GTPv2 context to the list
    add_ue_gtpv2_context(&context);

    // Update S-GW and P-GW contexts
    update_sgw_context(context.sgw_contexts[0], 1);
    update_pgwc_context(context.pgwc_contexts[0], 2);

    // Export UE GTPv2 context to a file
    FILE *file = fopen("context.txt", "wb");
    export_ue_gtpv2_context(&context, file);
    fclose(file);

    return 0;
}

