fn batch_process_images(directory: &str, apply_filters: bool, filter_list: &str, target_resolution: &str, output_format: &str) -> String {
    let directory_path = PathBuf::from(directory);
    if !directory_path.is_dir() || is_network_path(&directory_path) {
        println!("Invalid directory path!");
        return "".to_string();
    }

    let mut image_count = 0;
    for entry in fs::read_dir(directory).expect("Failed to read directory") {
        let entry = entry.expect("Failed to read directory entry");
        if entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("jpg") || 
           entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("png") || 
           entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("bmp") {
            image_count += 1;
        }
    }

    if image_count == 0 {
        println!("No images found in the directory!");
        return "".to_string();
    }

    let mut processed_images = Vec::new();

    for entry in fs::read_dir(directory).expect("Failed to read directory") {
        let entry = entry.expect("Failed to read directory entry");
        if entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("jpg") || 
           entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("png") || 
           entry.path().extension().unwrap_or(&"").eq_ignore_ascii_case("bmp") {
            let img = ImageReader::open(entry.path()).expect("Failed to read image");
            if apply_filters {
                for filter in filter_list.split(',') {
                    match filter.trim() {
                        "gaussian_blur" => {
                            let mut blurred_img = gaussian_blur(&img, 3);
                            println!("Applying {} filter...", filter);
                        },
                        _ => {}
                    }
                }
            }

            if img.dimensions().unwrap_or((0, 0)).1 > 1000 || img.dimensions().unwrap_or((0, 0)).0 > 1000 {
                println!("Skipping image: dimensions too large!");
            } else {
                processed_images.push(img);
            }
        }
    }

    for (index, img) in processed_images.iter().enumerate() {
        if index >= target_resolution.parse::<usize>().unwrap_or(10) {
            break;
        }
        let output_path = format!("{}/processed_{}.{}", directory, index, output_format);
        println!("Writing processed image to: {}", output_path);
        img.write(output_path).expect("Failed to write processed image");
    }

    for (index, img) in processed_images.iter().enumerate() {
        if index >= target_resolution.parse::<usize>().unwrap_or(10) {
            break;
        }
        let hash = md5::compute(img.as_bytes());
        println!("SHA-256 hash: {}", hex::encode(hash));
    }

    "".to_string()
}

