// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_array(int n, const char* src_file) {
    // Initialize array and pointers
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
    int* rnti_array = NULL;
    char** tag_array = NULL;

    // Fetch necessary tags from the external data source (src_file)
    FILE* file = fopen(src_file, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file '%s'\n", src_file);
        return NULL;
    }
    int num_tags = 0;
    fscanf(file, "%d", &num_tags);
    fclose(file);

    // Allocate memory for the arrays
    pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    rnti_array = (int*)malloc(n * sizeof(int));
    tag_array = (char**)calloc(n, sizeof(char*));

    // Initialize and populate the arrays
    for (int i = 0; i < n; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i;
        rnti_array[i] = i;
        sprintf(tag_array[i], "TAG_%02d", i);
        pdu_array[i].CRCFLAG = rand() % 2;

        // Ensure efficient memory allocation and deallocation
        if (pdu_array == NULL || rnti_array == NULL || tag_array == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(pdu_array);
            free(rnti_array);
            for (int j = 0; j < i; j++) {
                free(tag_array[j]);
            }
            free(tag_array);
            return NULL;
        }
    }

    // Deallocate memory
    free(rnti_array);
    for (int i = 0; i < n; i++) {
        free(tag_array[i]);
    }
    free(tag_array);

    return pdu_array;
}

// Example usage:
int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = generate_crc_indication_pdu_array(10, "tags.txt");

    if (pdu_array) {
        for (int i = 0; i < 10; i++) {
            printf("RX_UE_INFORMATION_TAG: %d\nRNTI: %d\nCRC_INDICATION_REL8_TAG: %s\nCRCFLAG: %d\n", pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG, pdu_array[i].CRCFLAG);
        }
    } else {
        fprintf(stderr, "Failed to generate PDU array\n");
    }

    return 0;
}
