#include <time.h>

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char* TRANSPORT_LAYER_INFORMATION;
} NFAPI_CRC_INDICATION_PDU_T;

// Define memory pooling strategy
#define MEMORY_POOL_SIZE 1000
NFAPI_CRC_INDICATION_PDU_T* memoryPool = NULL;

void generateNfaPduList(int numPDUs, int poolSize) {
    // Initialize time and random number generators
    srand(time(NULL));

    // Set default memory pool size if not provided
    if (poolSize <= 0) {
        poolSize = MEMORY_POOL_SIZE;
    }

    // Allocate memory for the memory pool
    memoryPool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(poolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize memory pool indices
    int poolIndex = 0;

    // Loop to generate PDUs
    for (int i = 0; i < numPDUs; i++) {
        // Allocate memory for a new PDU
        NFAPI_CRC_INDICATION_PDU_T* pdu = &memoryPool[poolIndex++];

        // Set unique RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();

        // Randomly set CRCFLAG
        int crcFlag = rand() % 2;
        if (crcFlag) {
            pdu->CRCFLAG = 1; // Set CRC flag
        } else {
            pdu->CRCFLAG = 0; // Clear CRC flag
        }

        // Calculate checksum for TRANSPORT_LAYER_INFORMATION field
        char* transportLayerInfo = (char*)malloc(256); // Assume maximum length is 256 characters
        sprintf(transportLayerInfo, "Transport Layer Information: %d %d", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);

        // Set TRANSPORT_LAYER_INFORMATION field
        pdu->TRANSPORT_LAYER_INFORMATION = transportLayerInfo;

        // Verify checksum upon retrieval
        int calculatedChecksum = 0;
        for (int j = 0; j < strlen(transportLayerInfo); j++) {
            calculatedChecksum += transportLayerInfo[j];
        }

        if (calculatedChecksum != pdu->TRANSPORT_LAYER_INFORMATION_CHECKSUM) {
            printf("Error: Checksum mismatch in TRANSPORT_LAYER_INFORMATION field.\n");
        }
    }

    // Deallocate memory pool
    free(memoryPool);
}

int main() {
    int numPDUs = 100;
    generateNfaPduList(numPDUs, MEMORY_POOL_SIZE);
    return 0;
}
