**Task 2: Reading Integers from Standard Input and Storing Them in a Dynamically Allocated Array or Singly Linked List**

```c
#include <stdio.h>
#include <stdlib.h>

// Structure for singly linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* create_node(int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;  // Out-of-memory condition
    node->value = value;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if (!node) return;  // Nothing to free
    free(node);
}

// Function to read integers from standard input and store them in a dynamically allocated array or singly linked list
int read_integers(int max_elements, int max_bytes_per_batch) {
    Node* head = NULL;
    Node** nodes = (Node**)malloc(max_elements * sizeof(Node*));
    if (!nodes) return -1;  // Out-of-memory condition

    int current_batch = 0;
    int bytes_used = 0;

    while (fscanf(stdin, "%d", &nodes[current_batch]->value) == 1 && bytes_used < max_bytes_per_batch) {
        current_batch++;
        if (current_batch >= max_elements || bytes_used > max_bytes_per_batch) break;
        nodes[current_batch] = create_node(nodes[current_batch - 1]->value);
    }

    // Find the largest integer in the array
    int max_value = nodes[0]->value;
    for (int i = 1; i < current_batch; i++) {
        if (nodes[i]->value > max_value) max_value = nodes[i]->value;
    }

    printf("Largest integer: %d\n", max_value);

    // Free dynamically allocated memory
    for (int i = 0; i < current_batch; i++) {
        free_node(nodes[i]);
    }
    free(nodes);

    return 0;  // Success
}

int main() {
    read_integers(1000000, 1024);  // Read up to 1 million integers with a maximum of 1024 bytes per batch
    return 0;
}
