void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void compilePacketSequence(int num_segments) {
    // Memory pooling strategy
    int num_blocks = 1000; // adjust based on performance requirements
    void** block_heads = (void**)my_malloc(num_blocks * sizeof(void*));

    for (int i = 0; i < num_blocks; i++) {
        block_heads[i] = my_malloc(sizeof(PACKET_SEGMENT_T) * 32);
    }

    PACKET_SEGMENT_T** packet_segments = NULL;
    int total_packets = 0;

    // Iterate over the sequence of packets
    for (int i = 0; i < num_segments; i++) {
        // Dynamic allocation based on memory availability
        int block_idx = total_packets % num_blocks;
        PACKET_SEGMENT_T* segment = block_heads[block_idx] + total_packets % 32;

        // Populate packet structure with random data
        srand(time(NULL) + i);
        segment->segment_id = rand() % 1000;
        strncpy(segment->target_address, "192.168.1.", 12); // adjust based on system interface
        segment->payload_data = (unsigned int)rand();

        total_packets++;
    }

    // Release memory blocks when done
    for (int i = 0; i < num_blocks; i++) {
        free(block_heads[i]);
    }
    free(block_heads);

    printf("Compiled packet sequence with %d segments.\n", total_packets);
}
