public class DeserializeByteArray {
    private static final Logger logger = Logger.getLogger(DeserializeByteArray.class.getName());

    public Object deserialize(byte[] byteArray) throws Exception {
        ObjectInputStream inputStream = null;
        try {
            inputStream = new ObjectInputStream(new ByteArrayInputStream(byteArray));
            return inputStream.readObject();
        } catch (StreamCorruptedException e) {
            throw new RuntimeException("Failed to deserialize byte array due to corruption", e);
        } catch (ClassNotFoundException e) {
            logger.warning("Class not found during deserialization. Returning null.");
            return null;
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
    }
}
