    if (*contexts == NULL) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize mutexes for concurrent access control
    pthread_mutex_init(&((*contexts)[0].event_list_mutex), NULL);

    while (1) {
        // Reallocate memory as needed to accommodate growing array size
        if (current_size == max_size) {
            lte_ue_context* new_array = (lte_ue_context*)realloc(*contexts, (max_size * 2) * sizeof(lte_ue_context));
            if (new_array == NULL) {
