typedef struct {
    int ms_id;
    enum { RRC_IDLE, RRC_CONNECTED, RRC_REESTABLISHING } rrc_state;
    pthread_mutex_t event_mutex;
    int num_events;
    struct {
        int timer_id;
        void (*callback)(int);
    } events[1000];
} MSContext;

MSContext* ms_contexts = NULL;
int num_ms_contexts = 0;
pthread_mutex_t context_mutex;

void init_ms_contexts() {
    if (ms_contexts) return; // Already initialized
    pthread_mutex_init(&context_mutex, NULL);
    ms_contexts = malloc(1000 * sizeof(MSContext));
}

void free_ms_contexts() {
    if (!ms_contexts) return; // Not initialized
    for (int i = 0; i < num_ms_contexts; i++) {
        pthread_mutex_destroy(&ms_contexts[i].event_mutex);
    }
    free(ms_contexts);
}

MSContext* get_ms_context(int ms_id) {
    pthread_mutex_lock(&context_mutex);
    for (int i = 0; i < num_ms_contexts; i++) {
        if (ms_contexts[i].ms_id == ms_id) {
            pthread_mutex_unlock(&context_mutex);
            return &ms_contexts[i];
        }
    }
    pthread_mutex_unlock(&context_mutex);
    return NULL;
}

void add_event(int ms_id, int timer_id, void (*callback)(int)) {
    pthread_mutex_lock(&get_ms_context(ms_id)->event_mutex);
    get_ms_context(ms_id)->events[get_ms_context(ms_id)->num_events].timer_id = timer_id;
    get_ms_context(ms_id)->events[get_ms_context(ms_id)->num_events].callback = callback;
    get_ms_context(ms_id)->num_events++;
    pthread_mutex_unlock(&get_ms_context(ms_id)->event_mutex);
}

void reconfigure(int ms_id) {
    MSContext* context = get_ms_context(ms_id);
    if (!context) return; // Not found
    pthread_mutex_lock(&context->event_mutex);
    // Validate RRC message integrity and handle reconfiguration requests
    pthread_mutex_unlock(&context->event_mutex);
}

void update_timer_event(int ms_id, int timer_id, void (*callback)(int)) {
    MSContext* context = get_ms_context(ms_id);
    if (!context) return; // Not found
    pthread_mutex_lock(&context->event_mutex);
    for (int i = 0; i < context->num_events; i++) {
        if (context->events[i].timer_id == timer_id) {
            context->events[i].callback = callback;
            break;
        }
    }
    pthread_mutex_unlock(&context->event_mutex);
}
