        pdu_array[i].RNTI = rand() % 100;
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
    return pdu_array;
}

void* initialize_records(int n, int max_records) {
    record_t* records = (record_t*)malloc(max_records * sizeof(record_t));
    for (int i = 0; i < min(n, max_records); i++) {
        records[i].key = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].identifier = malloc(strlen("Record ") + 10);
        sprintf(records[i].identifier, "Record %d", i);
    }
    return records;
}

void* initialize_summaries(int n, int max_records) {
    summary_t* summaries = (summary_t*)malloc(n * sizeof(summary_t));
    for (int i = 0; i < n; i++) {
        summaries[i].start_index = i * MAX_RECORDS / n;
        summaries[i].end_index = ((i + 1) * MAX_RECORDS / n - 1);
        summaries[i].num_records = MIN_VALUE;
        summaries[i].records = (record_t**)malloc(max_records * sizeof(record_t*));
    }
    return summaries;
