// Function to dynamically allocate memory for and initialize multiple data structures
void* dynamic_memory_allocation(size_t size, int num_elements) {
    void* ptr;

    // Allocate memory for 'num_elements' number of elements
    ptr = malloc(num_elements * size);

    if (!ptr) {
        printf("Error: Unable to allocate memory.\n");
        return NULL;
    }

    // Initialize the allocated memory with default values
    if (size > 0 && num_elements > 0) {
        memset(ptr, 0, num_elements * size);
    }

    return ptr;
