    while (fscanf(f, "%d\n", &num) == 1) {
        (*count)++;
        if ((array = realloc(array, sizeof(Node*) * (*count))) == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        array[*count - 1] = (Node*)malloc(sizeof(Node));
        array[*count - 1]->offset = num;
    }
    fclose(f);
    return array;
}

void print_largest_offset(Node* array, int count) {
    long max = array[0].offset;
    for (int i = 1; i < count; i++) {
        if (array[i].offset > max)
            max = array[i].offset;
    }
    printf("The largest offset is %ld.\n", max);
}

