            for (j = 1; j < len; j++) {
                if (ints[j] > maxVal) {
                    maxVal = ints[j];
                }
            }

            *maxVals++ = maxVal;
        } else {
            fclose(file);
            return;
        }

        free(ints);
    }

    fclose(file);
}

