// Define a structure to hold interface configuration data
typedef struct {
    LTE_ENB_API_STRUCT_T* config;
    int count;
} InterfaceConfig;

// Function to dynamically manage the array of LTE_ENB_API_STRUCTS_T structures
void populate_LTE_ENB_API_ARRAY(char* configFile, int* numInterfaces) {
    FILE* configfile = fopen(configFile, "r");
    if (configfile == NULL) {
        printf("Failed to open configuration file!\n");
        return;
    }

    // Initialize the array of LTE_ENB_API_STRUCTS_T structures
    InterfaceConfig* interfaces = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));
    interfaces->count = 0;

    // Read configuration data from file or database
    char line[256];
    while (fgets(line, sizeof(line), configfile)) {
        // Parse the line and extract interface ID, IP address, and subnet mask
        int id;
        char ipAddr[16], subnetMask[16];

        sscanf(line, "%d %s %s", &id, ipAddr, subnetMask);

        // Allocate memory for a new LTE_ENB_API_STRUCT_T structure
        LTE_ENB_API_STRUCT_T* config = (LTE_ENB_API_STRUCT_T*)malloc(sizeof(LTE_ENB_API_STRUCT_T));
        if (config == NULL) {
            printf("Out of memory!\n");
            fclose(configfile);
            return;
        }

        // Initialize the new structure with unique values
        config->interface_id = id;
        strcpy(config->ip_address, ipAddr);
        strcpy(config->subnet_mask, subnetMask);

        // Add the new structure to the array
        interfaces->count++;
        (interfaces->config) = realloc(interfaces->config, sizeof(LTE_ENB_API_STRUCT_T*) * interfaces->count);
        interfaces->config[interfaces->count - 1] = config;
    }

    fclose(configfile);

    // Update the numInterfaces variable with the actual number of interfaces
    *numInterfaces = interfaces->count;

    free(interfaces->config);
    free(interfaces);
}

int main() {
    int numInterfaces = 0;
    populate_LTE_ENB_API_ARRAY("config.txt", &numInterfaces);
    printf("Number of interfaces: %d\n", numInterfaces);
    return 0;
}
