                serverConfig->server_id = atoi(token);
            } else if (i == 1) {
                serverConfig->server_ip = strdup(token);
            } else if (i == 2) {
                serverConfig->port_number = atoi(token);
            } else if (i == 3) {
                serverConfig->secret_key = strdup(token);
