typedef struct {
    int value;
    char id[16];
} record;

typedef struct {
    record** records;
    int num_records;
} summary;

void init_and_sort(int max_num_records, int max_offset_size, int min_key_range, int max_key_range) {
    // Define maximum number of records
    int max_records = (max_num_records > 0 ? max_num_records : 100);

    // Initialize arrays
    long* offsets = (long*)malloc(max_records * sizeof(long));
    int* keys = (int*)malloc(max_records * sizeof(int));
    record* records = (record*)malloc(max_records * sizeof(record));
    summary** summaries = (summary**)malloc((max_num_records / 10) * sizeof(summary));

    // Initialize random number generator
    srand(time(NULL));

    // Populate offset array and key array with unique values within specified range
    for (int i = 0; i < max_records; i++) {
        offsets[i] = rand() % (max_offset_size - 1);
        keys[i] = rand() % ((max_key_range - min_key_range) + 1) + min_key_range;
    }

    // Initialize record array with random values and unique IDs
    for (int i = 0; i < max_records; i++) {
        records[i].value = rand() % (max_num_records - 1);
        sprintf(records[i].id, "record-%d", i);
    }

    // Initialize summary array
    int num_summaries = (max_num_records / 10) + 1;
    for (int i = 0; i < num_summaries; i++) {
        summaries[i] = (summary*)malloc(sizeof(summary));
        summaries[i]->num_records = rand() % ((max_records - 1) / 10) + 1;
        summaries[i]->records = (record**)malloc(summaries[i]->num_records * sizeof(record*));

        // Link records to summary
        for (int j = 0; j < summaries[i]->num_records; j++) {
            summaries[i]->records[j] = &records[(i * 10) + j];
        }
    }

    // Sort record array and verify sorting correctness using binary search
    qsort(records, max_records, sizeof(record), compare_records);
    int target_value = rand() % (max_num_records - 1);
    if (binary_search(records, max_records, &target_value)) {
        printf("Target value found: %d\n", target_value);
    } else {
        printf("Target value not found.\n");
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < num_summaries; i++) {
        free(summaries[i]->records);
        free(summaries[i]);
    }
    free(records);

    return;
}

// Compare function for qsort
int compare_records(const void* a, const void* b) {
    record* rec1 = (record*)a;
    record* rec2 = (record*)b;

    if (rec1->value < rec2->value)
        return -1;
    else if (rec1->value > rec2->value)
        return 1;
    else
        return 0;
}

// Binary search function
int binary_search(record* records, int size, int* target_value) {
    record target = { *target_value, "" };
    int low = 0;
    int high = size - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if (records[mid].value == target.value)
            return 1;
        else if (records[mid].value < target.value)
            low = mid + 1;
        else
            high = mid - 1;
    }

    return 0;
}
