} record;

typedef struct {
    record *records;
    int num_records;
} summary;

void init_arrays(item **items, int ***keys, double ***values, item ***struct_items, record ***records, summary ***summaries, int max_records) {
    // Dynamically allocate memory for arrays
    *items = (item *)malloc(sizeof(item) * 4);
    *keys = (int **)malloc(sizeof(int) * 4);
    *values = (double **)malloc(sizeof(double) * 4);
    *struct_items = (item **)malloc(sizeof(item) * 4);
    *records = (record *)malloc(sizeof(record) * max_records);
    *summaries = (summary *)malloc(sizeof(summary));

    // Initialize arrays
    for (int i = 0; i < 4; i++) {
        (*keys)[i] = (int *)malloc(sizeof(int));
        (*values)[i] = (double *)malloc(sizeof(double));
        (*struct_items)[i] = (item *)malloc(sizeof(item));

        // Initialize struct item
        (*struct_items)[i]->value = (double)(rand() / (RAND_MAX / FLOATING_POINT_RANGE));
        (*struct_items)[i]->id = (char *)malloc(strlen("unique_id") + 1);
        strcpy((*struct_items)[i]->id, "unique_id");
        (*struct_items)[i]->timestamp = time(NULL);

        // Initialize record
        (*records)[i].id = rand() % INTEGER_RANGE;
        (*records)[i].str_id = (char *)malloc(strlen("record_id") + 1);
        strcpy((*records)[i].str_id, "record_id");

        // Initialize summary
        (*summaries)->num_records = i;
    }
}

void sort_records(record **records, int num_records) {
    // Sort records based on their integer values in ascending order
    qsort(*records, num_records, sizeof(record), (int (*)(const void *, const void *))record_compare);
}

int record_compare(const void *a, const void *b) {
    // Compare two records based on their integer values
    record *r1 = (record *)a;
    record *r2 = (record *)b;
    return r1->id - r2->id;
}

void free_arrays(item **items, int ***keys, double ***values, item ***struct_items, record ***records, summary ***summaries) {
    // Free allocated memory
    for (int i = 0; i < 4; i++) {
        free((*keys)[i]);
        free((*values)[i]);
        free((*struct_items)[i]->id);
        free((*struct_items)[i]);
    }
    free(*items);
    free(*keys);
    free(*values);
    free(*struct_items);
    free(*records);
    free(*summaries);
}
