// Function to load events from file
void loadEvents(Event** events, int* eventCount) {
    // Open the file in binary read mode
    FILE* file = fopen("events.bin", "rb");

    if (file == NULL) return; // Return if unable to open the file

    // Read the total number of events and the array size
    fread(eventCount, sizeof(int), 1, file);
    int eventArraySize = *eventCount;

    // Dynamically allocate memory for the events array
    *events = (Event*)malloc(eventArraySize * sizeof(Event));

    // Read each event from the file and store it in the array
    for (int i = 0; i < eventArraySize; i++) {
        fread(&((*events)[i].message), sizeof(char*), 1, file);
        fread(&((*events)[i].timestamp), sizeof(time_t), 1, file);
        fread(&((*events)[i].priority), sizeof(int), 1, file);
    }

    fclose(file);
}

// Function to save events to file
void saveEvents(Event** events, int eventCount) {
    // Open the file in binary write mode
    FILE* file = fopen("events.bin", "wb");

    if (file == NULL) return; // Return if unable to open the file

    // Write the total number of events and the array size
    fwrite(&eventCount, sizeof(int), 1, file);

    // Write each event to the file
    for (int i = 0; i < eventCount; i++) {
        fwrite(&((*events)[i].message), sizeof(char*), 1, file);
        fwrite(&((*events)[i].timestamp), sizeof(time_t), 1, file);
        fwrite(&((*events)[i].priority), sizeof(int), 1, file);
