#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for a user profile
typedef struct {
    char name[256];
    char email[256];
    time_t dob;
    int numActivities;
    struct activity *activities;
} UserProfile;

// Define a structure to represent a user group
typedef struct {
    UserProfile **users;
    int userCount;
    int maxUsers;
} UserGroup;

// Define a structure for an activity log entry
typedef struct {
    char description[256];
    time_t timestamp;
    char type[16]; // e.g., exercise, social, learning
} ActivityLogEntry;

// Function to initialize and manage memory for user profiles in a group
UserGroup* initUserGroup(int maxUsers) {
    UserGroup *group = (UserGroup*)malloc(sizeof(UserGroup));
    if (!group) return NULL;

    group->users = (UserProfile**)calloc(maxUsers, sizeof(UserProfile*));
    if (!group->users) {
        free(group);
        return NULL;
    }

    group->userCount = 0;
    group->maxUsers = maxUsers;
    return group;
}

// Function to add a new user profile to the group
void addUser(UserGroup *group, char* name, char* email, time_t dob) {
    UserProfile *profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) return; // Allocation failure

    strcpy(profile->name, name);
    strcpy(profile->email, email);
    profile->dob = dob;
    profile->numActivities = 0;

    group->users[group->userCount++] = profile;

    // Ensure uniqueness of user names and emails within the group
    for (int i = 0; i < group->userCount; i++) {
        if (strcmp(profile->name, group->users[i]->name) == 0 || 
            strcmp(profile->email, group->users[i]->email) == 0) {
            free(profile);
            return;
        }
    }
}

// Function to sort user profiles by date of birth
void sortByDob(UserGroup *group) {
    UserProfile **temp = (UserProfile**)malloc(group->userCount * sizeof(UserProfile*));

    for (int i = 0; i < group->userCount; i++) 
        temp[i] = group->users[i];

    qsort(temp, group->userCount, sizeof(UserProfile*), sortByDobComparator);

    int j;
    for (j = 0; j < group->userCount; j++) 
        group->users[j] = temp[j];

    free(temp);
}

// Comparator function for qsort
int sortByDobComparator(const void *a, const void *b) {
    UserProfile *p1 = *(UserProfile**)a;
    UserProfile *p2 = *(UserProfile**)b;
    return (int)(p1->dob - p2->dob);
}

// Function to free all allocated memory
void freeUserGroup(UserGroup *group) {
    for (int i = 0; i < group->userCount; i++) 
        free(group->users[i]);

    free(group->users);
    free(group);
}
