#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define THRESHOLD 1000.0
#define MIN_INT 1
#define MAX_INT 100

typedef struct record {
    int id;
    char* name;
    double value;
} Record;

typedef struct summary {
    Record* record;
    int count;
    time_t timestamp;
} Summary;

Record* records = NULL;
int num_records = 0;

// Function to manage dynamic collection of records
void manage_records() {
    // Allocate memory for records and summaries
    if ((records = malloc(sizeof(Record) * MAX_RECORDS)) == NULL) {
        printf("Error allocating memory.\n");
        return;
    }

    Summary* summaries = (Summary*)malloc(sizeof(Summary) * (MAX_RECORDS / 2 + 1));

    // Initialize records and summaries
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].id = (rand() % (MAX_INT - MIN_INT + 1)) + MIN_INT;
        records[i].name = malloc(16);
        strcpy(records[i].name, "Record ");
        itoa(records[i].id, &records[i].name[7], 10);
        records[i].value = (double)rand() / RAND_MAX * THRESHOLD;
    }

    for (int i = 0; i < MAX_RECORDS / 2 + 1; i++) {
        summaries[i].record = NULL;
        summaries[i].count = 0;
        summaries[i].timestamp = time(NULL);
    }

    // Sort records in ascending order
    qsort(records, num_records, sizeof(Record), compare_records);

    // Log allocation and deallocation events
    FILE* log_file = fopen("memory.log", "a");
    if (log_file != NULL) {
        for (int i = 0; i < num_records; i++) {
            fprintf(log_file, "Record allocated at %s.\n", ctime(&summaries[i].timestamp));
        }
        fclose(log_file);
    }

    // Serialize records to disk periodically
    while (num_records > 10) {
        for (int i = 0; i < num_records; i++) {
            if ((records[i].id % 2 == 1 && (rand() % 2 == 0)) ||
                (records[i].id % 2 == 0 && (rand() % 2 != 0))) {
                // Serialize record to disk
                FILE* file = fopen("record.ser", "wb");
                if (file != NULL) {
                    fwrite(&records[i], sizeof(Record), 1, file);
                    fclose(file);
                }
            }
        }
    }

    // Free allocated memory when function completes
    for (int i = 0; i < num_records; i++) {
        free(records[i].name);
    }
    free(summaries);

    return;
}

// Function to compare records based on their integer values
int compare_records(const void* a, const void* b) {
    Record* record1 = *(Record*)a;
    Record* record2 = *(Record*)b;

    if (record1->id < record2->id)
        return -1;
    else if (record1->id > record2->id)
        return 1;
    else
        return 0;
}

int main() {
    manage_records();
    return 0;
}
