    RX_UE_INFORMATION_TAG rx_ue_info;
    int RNTI;
    enum { CRCFLAG_SET, CRCFLAG_UNSAT } crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node) {
            return NULL;
        }

        new_node->rx_ue_info.some_value = rand() % 1000;
        new_node->RNTI = rand() % 1000;
        new_node->crcflag = (rand() % 2 == 0) ? CRCFLAG_SET : CRCFLAG_UNSAT;
        new_node->next = NULL;

        *tail = new_node;
        tail = &(new_node->next);
    }

    return head;
}

int serialize_linked_list(NFAPI_CRC_INDICATION_PDU_T* list, FILE* file) {
    if (!list) {
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = list;

    while (current) {
        fwrite(&current->rx_ue_info.some_value, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fputc((int)current->crcflag, file);

        current = current->next;
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_linked_list(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &list;

    int some_value, RNTI;
    enum { CRCFLAG_SET, CRCFLAG_UNSAT } crcflag;

    while (fread(&some_value, sizeof(int), 1, file) == 1 && fread(&RNTI, sizeof(int), 1, file) == 1 && fgetc(file) != EOF) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node) {
            return NULL;
        }

        new_node->rx_ue_info.some_value = some_value;
        new_node->RNTI = RNTI;
        crcflag = (fgetc(file) == (int)CRCFLAG_SET);
        new_node->crcflag = crcflag;
        new_node->next = NULL;

        *tail = new_node;
        tail = &(new_node->next);
    }

    return list;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    while (list) {
        NFAPI_CRC_INDICATION_PDU_T* current = list;
        list = list->next;

        free(current);
    }
}

int main() {
    int N = 10; // number of elements to create
    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(N);

    if (!list) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    FILE* file = fopen("test.bin", "wb"); // serialize the linked list

    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        free_linked_list(list);
        return -2;
    }

    serialize_linked_list(list, file);

    fclose(file); // close the file

    file = fopen("test.bin", "rb"); // deserialize the linked list

    if (file == NULL) {
        printf("Failed to open file for reading.\n");
        free_linked_list(list);
        return -3;
    }

    NFAPI_CRC_INDICATION_PDU_T* deserialized_list = deserialize_linked_list(file);

    fclose(file); // close the file

    if (!deserialized_list) {
        printf("Deserialization failed.\n");
        free_linked_list(list);
        free_linked_list(deserialized_list);
        return -4;
    }

    free_linked_list(list);
    free_linked_list(deserialized_list);

    return 0;
}
