} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the dynamic linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct Node *next;
} Node;

// Function to create and manage a dynamic linked list
void create_linked_list(int N, unsigned int seed) {
    srand(seed);

    // Initialize head of linked list
    Node *head = (Node *)malloc(sizeof(Node));
    head->pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    head->next = NULL;

    // Dynamically allocate and initialize each element of the linked list
    for (int i = 1; i < N; i++) {
        Node *new_node = (Node *)malloc(sizeof(Node));
        new_node->pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set random CRCFLAG for each node
        new_node->pdu->crc_indication.crcflag = rand() % 2;

        new_node->next = head->next;
        head->next = new_node;
    }

    // Implement memory-efficient design and robust error handling
    if (head == NULL) {
        printf("Memory allocation failed!\n");
    } else {
        // Function to serialize the linked list into a binary format
        void serialize_linked_list(Node *head, FILE *fp) {
            Node *current = head;
            while (current != NULL) {
                fwrite(&current->pdu->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, fp);
                fwrite(&current->pdu->rnti, sizeof(RNTI), 1, fp);
                fwrite(&current->pdu->crc_indication, sizeof(CRC_INDICATION_REL8_TAG), 1, fp);
                current = current->next;
            }
        }

        // Corresponding deserialization function
        void deserialize_linked_list(Node **head_p, FILE *fp) {
            Node *new_head = NULL;
            Node *current = NULL;

            RX_UE_INFORMATION_TAG ue_info;
            RNTI rnti;
            CRC_INDICATION_REL8_TAG crc_indication;

            while (fread(&ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, fp) == 1 &&
                   fread(&rnti, sizeof(RNTI), 1, fp) == 1 &&
                   fread(&crc_indication, sizeof(CRC_INDICATION_REL8_TAG), 1, fp) == 1) {
                Node *new_node = (Node *)malloc(sizeof(Node));
                new_node->pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

                new_node->pdu->ue_info = ue_info;
                new_node->pdu->rnti = rnti;
                new_node->pdu->crc_indication = crc_indication;

                if (new_head == NULL) {
                    new_head = new_node;
                } else {
                    current->next = new_node;
                }
                current = new_node;
            }

            *head_p = new_head;
        }

        // Test the serialization and deserialization functions
        FILE *fp = fopen("linked_list.bin", "wb");
        serialize_linked_list(head, fp);
        fclose(fp);

        Node *deserialized_head = NULL;
        fp = fopen("linked_list.bin", "rb");
        deserialize_linked_list(&deserialized_head, fp);
        fclose(fp);
    }
}
