void create_list(int n, Node** head_ref, int seed) {
    srand(seed);
    *head_ref = NULL;

    for (int i = 0; i < n; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory error\n");
            return;
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->data.RNTI = rand() % 100;
        new_node->data.CRCFLAG = rand() % 2;
        new_node->next = *head_ref;
        *head_ref = new_node;
    }
}

int serialize_list(Node* head, FILE* file) {
    if (fwrite(&head, sizeof(Node), 1, file) < 1) {
        return -1; // error writing to file
    }
    Node* temp = head;
    while (temp->next) {
        if (fwrite(&temp->next, sizeof(Node), 1, file) < 1) {
            return -1; // error writing to file
        }
        temp = temp->next;
    }
    return 0; // success
}

int deserialize_list(Node** head_ref, FILE* file) {
    Node* new_head = NULL;
    int temp;

    if (fread(&temp, sizeof(Node), 1, file) < 1) {
        *head_ref = NULL;
        return -1; // error reading from file
    }
    *head_ref = (Node*)malloc(sizeof(Node));
    if (!*head_ref) {
        printf("Memory error\n");
