        current->next = (Node*)malloc(sizeof(Node));
        if (!current->next) {
            printf("Memory error\n");
            return -1; // memory allocation failed
        }
        current->next->data = temp;
        current = current->next;
    }
    return 0; // success
}

void free_list(Node* head) {
    Node* temp = head;
    while (temp) {
        Node* next_node = temp->next;
        free(temp);
        temp = next_node;
    }
