    else {
        char buffer[1024]; // Buffer for serialization
        int size = serialize_list(list, buffer, sizeof(buffer));
        Node* deserialized_list = deserialize_list(buffer, size);

        // Round-trip testing of data integrity
        for (Node* curr = deserialized_list; curr; curr = curr->next) {
