// Define the LOG_EVENT_RECORD structure
typedef struct {
    int type;
    long long timestamp;
    int level;
} LOG_EVENT_RECORD;

// Define the doubly linked list node structure
typedef struct Node {
    LOG_EVENT_RECORD data;
    struct Node* prev;
    struct Node* next;
} NODE;

// Function to populate the linked list with exactly N elements
void populate_list(int N) {
    // Initialize head and tail pointers
    NODE* head = NULL;
    NODE* tail = NULL;

    for (int i = 0; i < N; i++) {
        NODE* new_node = malloc(sizeof(NODE));
        if (!new_node) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Initialize node data
        LOG_EVENT_RECORD log_event;
        log_event.type = i % 2 == 0 ? 1 : 2; // Alternate between types 1 and 2
        log_event.timestamp = (long long)time(NULL) * 1000000LL + i; // Generate timestamp in microseconds
        log_event.level = i % 3 == 0 ? 1 : (i % 3 == 1 ? 2 : 3); // Alternate between log levels 1, 2, and 3

        new_node->data = log_event;
        new_node->prev = tail;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }
}

// Function to insert a new node at the end of the linked list
void insert_at_end(NODE** head, NODE* new_node) {
    if (!(*head)) {
        *head = new_node;
    } else {
        (*head)->next = new_node;
        new_node->prev = (*head);
        *head = new_node;
    }
}

// Function to delete a node from the linked list
void delete_node(NODE** head, NODE* node_to_delete) {
    if (node_to_delete == (*head)) {
        *head = node_to_delete->next;
    }

    if (node_to_delete->prev) {
        node_to_delete->prev->next = node_to_delete->next;
    } else {
        *head = node_to_delete->next;
    }

    if (node_to_delete->next) {
        node_to_delete->next->prev = node_to_delete->prev;
    }

    free(node_to_delete);
}

// Function to serialize the linked list into a binary format
void serialize_list(NODE* head, FILE* file) {
    // Write the number of elements in the linked list
    fwrite(&head->data.type, sizeof(int), 1, file);

    NODE* current = head;
    while (current) {
        // Write the timestamp and log level for each element
        fwrite(&current->data.timestamp, sizeof(long long), 1, file);
        fwrite(&current->data.level, sizeof(int), 1, file);

        current = current->next;
    }
}

// Function to deserialize the binary format back into the linked list structure
void deserialize_list(NODE** head, FILE* file) {
    int num_elements;
    fread(&num_elements, sizeof(int), 1, file);

    for (int i = 0; i < num_elements; i++) {
        NODE* new_node = malloc(sizeof(NODE));
        if (!new_node) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Read the timestamp and log level from the binary format
        fread(&new_node->data.timestamp, sizeof(long long), 1, file);
        fread(&new_node->data.level, sizeof(int), 1, file);

        if (!(*head)) {
            *head = new_node;
            (*head)->prev = NULL;
        } else {
            (*head)->next = new_node;
            new_node->prev = (*head);
            (*head) = new_node;
        }
    }
}

int main() {
    // Populate the linked list with exactly N elements
    int N = 1000;
    populate_list(N);

    // Serialize the linked list into a binary format
    FILE* file = fopen("linked_list.bin", "wb");
    serialize_list(*head, file);
    fclose(file);

    // Deserialize the binary format back into the linked list structure
    NODE* deserialized_head = NULL;
    deserialize_list(&deserialized_head, file);

    return 0;
}
