typedef struct {
    int key;
    long offset;
} record_t;

record_t* allocate_memory(int max_records, int max_offset_value, int max_key_value, size_t total_limit);
void deallocate_memory(record_t** records, size_t* offset_values, int num_records);

record_t* allocate_memory(int max_records, int max_offset_value, int max_key_value, size_t total_limit) {
    record_t* records = NULL;
    long* offset_values = NULL;
    int num_records = 0;

    // Calculate the required memory
    size_t total_required = (sizeof(record_t) + sizeof(long)) * max_records + sizeof(int);

    // Check if we can allocate all at once
    void* memblock = malloc(total_limit);
    if (!memblock) {
        return NULL;
    }

    records = memblock;
    offset_values = (long*) ((char*) memblock + total_required);

    for (int i = 0; i < max_records; i++) {
        // Set the random value
        int key = rand() % max_key_value;

        // Check if there is a collision, and if so, try again
        while (key >= max_key_value || find_record(records, num_records, key) != -1) {
            key = rand() % max_key_value;
        }

        records[num_records].key = key;
        records[num_records].offset = (long) rand() % max_offset_value;

        // Reallocate if we hit the limit
        size_t total_used = (sizeof(record_t) + sizeof(long)) * (num_records + 1);
        if (total_used > total_limit) {
            deallocate_memory(&records, offset_values, num_records);
            return NULL;
        }

        num_records++;
    }

    free(memblock);

    return records;
}

void deallocate_memory(record_t** records, size_t* offset_values, int num_records) {
    if (num_records > 0) {
        free(*records);
        *offset_values = NULL;
    }
}

int find_record(record_t* records, int num_records, int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return i;
        }
    }

    return -1;
}
