typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record* records;
    int size;
    int capacity;
    void (*free_func)(void*);
} DynamicCollection;

DynamicCollection create_collection(int initial_capacity, void (*free_func)(void*)) {
    DynamicCollection collection = (DynamicCollection)malloc(sizeof(struct));
    collection->records = malloc(initial_capacity * sizeof(Record));
    collection->size = 0;
    collection->capacity = initial_capacity;
    collection->free_func = free_func;
    return collection;
}

int insert_record(DynamicCollection* collection, int key, int value) {
    if (collection->size >= collection->capacity) {
        // Double the capacity
        Record* new_records = realloc(collection->records, 2 * collection->capacity * sizeof(Record));
        if (!new_records) {
            printf("Memory allocation failed\n");
            return -1;
        }
        collection->records = new_records;
        collection->capacity *= 2;
    }
    Record record = (Record)malloc(sizeof(struct));
    record->key = key;
    record->value = value;
    // Insert at the end
    collection->records[collection->size] = record;
    collection->size++;
    return 0;
}

int delete_record(DynamicCollection* collection, int key) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i]->key == key) {
            // Free the record
            collection->free_func(collection->records[i]);
            // Move all records forward and shrink capacity
            Record* new_records = malloc((collection->size - 1) * sizeof(Record));
            int j = 0;
            for (int k = i; k < collection->size; k++) {
                new_records[j++] = collection->records[k];
            }
            free(collection->records);
            collection->records = new_records;
            collection->size--;
            return 0;
        }
    }
    printf("Record not found\n");
    return -1;
}

int get_value(DynamicCollection* collection, int key) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i]->key == key) {
            return collection->records[i]->value;
        }
    }
    printf("Record not found\n");
    return -1;
}
