        pdu_array[i].rx_ue_info = rx_ue_info_array[i];
        pdu_array[i].crc_indication_rel8_tag = crc_indication_rel8_tag_array[i];
    }

    return pdu_array;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(crc_indication_rel8_tag_array[i]);
    }
    free(rx_ue_info_array);
    free(pdu_array);
}

