    if (*head != NULL) {
        (*head)->prev = &new_node;
    }

    *head = new_node;
}

int delete_apm_list(Node** head, APM* apm) {
    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL && current->apm != apm) {
        prev = current;
        current = current->next;
    }

    if (current == NULL || current->apm != apm) {
        return -1; // Not found
    }

    if (prev != NULL) {
        prev->next = current->next;
    } else {
        *head = current->next;
    }

    free(current);
}

