// Define the structures required for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
} RX_UE_INFORMATION_TAG;

typedef struct {
    int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Define the structure to hold user information
typedef struct {
    char name[20];
    char email[30];
    int age;
} User;

// Function to process JSON data and cache users
void process_json_data(char* json_data) {
    // Initialize variables
    User* users = NULL;
    int num_users = 0;
    int max_age = 0;
    User* user_with_max_age = NULL;

    // Parse JSON data
    json_object* root = json_load_string(json_data);
    if (root == NULL) return;

    // Iterate over the users in the JSON data
    json_object_iter *iter = json_object_iter_create(root);
    while ((json_object_iter_next(iter, &key, &value))) {
        User user;
        strcpy(user.name, json_object_get_string(value, "name"));
        strcpy(user.email, json_object_get_string(value, "email"));
        user.age = json_object_get_int(value, "age");

        // Allocate memory for the user
        users = realloc(users, (num_users + 1) * sizeof(User));
        users[num_users].age = user.age;
        num_users++;

        // Update max age if necessary
        if (user.age > max_age) {
            max_age = user.age;
            user_with_max_age = &users[num_users - 1];
        }
    }

    // Free JSON memory
    json_object_iter_free(iter);
    json_decref(root);

    // Print the user with the highest age
    if (num_users > 0) {
        printf("User with the highest age: %s, Age: %d\n", user_with_max_age->name, user_with_max_age->age);
    } else {
        printf("No valid users provided.\n");
    }

    // Free memory for users
    free(users);
}

int main() {
    char* json_data = "{\"users\": [{\"name\":\"John\",\"email\":\"john@example.com\",\"age\":25},{\"name\":\"Jane\",\"email\":\"jane@example.com\",\"age\":30}]}";
    process_json_data(json_data);
    return 0;
}
