        fwrite(&data[i].CRCFLAG, sizeof(int), 1, file);
    }
    return 0;
}

int deserialize_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* data, int n, FILE* file) {
    for (int i = 0; i < n; i++) {
        fread(&data[i].RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&data[i].RNTI, sizeof(int), 1, file);
        fread(&data[i].CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        fread(&data[i].CRCFLAG, sizeof(int), 1, file);
