// Structure to hold LTE PHY Layer Statistics
typedef struct {
    float rsrq;
    float rsrp;
    int cqi;
} LTEStatistics;

void* allocateMemory(size_t size) {
    void* mem = malloc(size);
    if (!mem) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return mem;
}

int freeMemory(void* ptr) {
    free(ptr);
    return 0;
}

void logData(LTEStatistics* stats, int numStats) {
    unsigned char buffer[10000];
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    // Initialize compression context
    deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 31, 8, Z_DEFAULT_WINDOW);

    for (int i = 0; i < numStats; i++) {
        int len = sprintf(buffer + strlen((char*)buffer), "{\"rsrq\":%.2f,\"rsrp\":%.2f,\"cqi\":%d}\n", stats[i].rsrq, stats[i].rsrp, stats[i].cqi);
        strm.avail_in = len;
        strm.next_in = (unsigned char*)buffer;

        // Compress the string
        do {
            strm.avail_out = 1000; /* 1K */
            strm.next_out = buffer;
            deflate(&strm, Z_NO_COMPRESSION);
        } while (strm.avail_out == 0);

        // Write compressed data to file or send over network
    }

    // Finish compression and clean up
    strm.avail_in = 0;
    strm.next_in = Z_NULL;
    deflateEnd(&strm);
}

int main() {
    int numStats = 10; // Number of statistics entries
    LTEStatistics* stats = (LTEStatistics*)allocateMemory(numStats * sizeof(LTEStatistics));

    // Initialize and populate the array with sample data
    for (int i = 0; i < numStats; i++) {
        stats[i].rsrq = rand() / (float)RAND_MAX;
        stats[i].rsrp = rand() / (float)RAND_MAX;
        stats[i].cqi = rand() % 30;
    }

    // Log the statistics
    logData(stats, numStats);

    // Free allocated memory
    freeMemory(stats);

    return 0;
}

