#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int GUTI;
    int RRC_STATE;
    long LAST_UPDATE_TIMESTAMP;
} NFPAPI_CONNECTION_STATS_T;

typedef struct node {
    NFPAPI_CONNECTION_STATS_T stats;
    struct node* next;
} Node;

Node* list = NULL;
Node** last_node = &list;

void add_connection_stats(NFPAPI_CONNECTION_STATS_T new_stats) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Out of memory
    new_node->stats = new_stats;
    new_node->next = *last_node;
    *last_node = new_node;
}

void update_connection_stats(NFPAPI_CONNECTION_STATS_T updated_stats) {
    Node* current = list;
    Node* previous = NULL;
    while (current) {
        if (updated_stats.GUTI == current->stats.GUTI) { // Matching GUTI found
            if (updated_stats.LAST_UPDATE_TIMESTAMP > current->stats.LAST_UPDATE_TIMESTAMP) { // More recent update, update the stats and remove stale entry
                current->stats = updated_stats;
                previous->next = current->next; // Remove stale entry from the list
                free(current);
                return;
            } else if (updated_stats.LAST_UPDATE_TIMESTAMP == current->stats.LAST_UPDATE_TIMESTAMP) { // Duplicate updates, prioritize recent one
                free(updated_stats); // Free resources allocated for duplicate update
                return;
            }
        }
        previous = current;
        current = current->next;
    }
    add_connection_stats(updated_stats); // No matching GUTI found, add new stats to the list
}

void remove_stale_entries() {
    Node* current = list;
    while (current) {
        if (time(NULL) - current->stats.LAST_UPDATE_TIMESTAMP > 60 * 5) { // Stale entry detected (older than 5 minutes)
            Node* next_node = current->next;
            free(current);
            current = next_node;
        } else break; // No stale entries found, stop iterating
    }
}

void free_list() {
    while (list) {
        Node* next_node = list->next;
        free(list);
        list = next_node;
    }
}
