    srand(time(NULL));

    int num_enodebs = 5;
    int max_ue_per_enodeb = 10;

    LTE_ENODEB_CONTEXT_T* eNodebContexts = populate_enodeb_context(num_enodebs, max_ue_per_enodeb);

    // Serialize the data
    FILE* file = fopen("enodeb_data.bin", "wb");
