#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000
#define FRAME_TYPE_MAX 5
#define SUBFRAME_INDEX_MAX 10
#define TX_POWER_LEVEL_MAX 100
#define LOGGING_ENABLED 1

typedef struct {
    int frame_type;
    int subframe_index;
    int tx_power_level;
} PHY_LAYER_FRAME_T;

void* allocate_frame(int count) {
    return malloc(count * sizeof(PHY_LAYER_FRAME_T));
}

void deallocate_frames(void** frames, int count) {
    for (int i = 0; i < count; i++)
        free(frames[i]);
}

void populate_array(int* array_size, PHY_LAYER_FRAME_T*** frames, pthread_mutex_t* lock) {
    *array_size = rand() % MAX_ELEMENTS + 1;
    *frames = allocate_frame(*array_size);

    for (int i = 0; i < *array_size; i++) {
        PHY_LAYER_FRAME_T frame;
        frame.frame_type = rand() % FRAME_TYPE_MAX;
        frame.subframe_index = rand() % SUBFRAME_INDEX_MAX;
        frame.tx_power_level = rand() % TX_POWER_LEVEL_MAX + 1;

        if (LOGGING_ENABLED) {
            pthread_mutex_lock(lock);
            printf("Frame %d: Type - %d, Index - %d, Power Level - %d\n", i, frame.frame_type, frame.subframe_index, frame.tx_power_level);
            pthread_mutex_unlock(lock);
        }
    }
}

void serialize_frames(PHY_LAYER_FRAME_T*** frames, int size) {
    FILE* file = fopen("frames.dat", "wb");

    if (file == NULL)
        return;

    for (int i = 0; i < size; i++) {
        fwrite(frames[i], sizeof(PHY_LAYER_FRAME_T), 1, file);
    }

    fclose(file);
}

void parallel_processing(void** frames, int size) {
    pthread_t threads[MAX_ELEMENTS / 10];
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < size; i++) {
        if (i % 10 == 0) {
            pthread_create(&threads[i / 10], NULL, populate_array, &size);
        }
    }

    for (int i = 0; i < MAX_ELEMENTS / 10; i++)
        pthread_join(threads[i], NULL);

    pthread_mutex_destroy(&lock);
}

void main() {
    srand(time(NULL));
    int size;
    PHY_LAYER_FRAME_T*** frames;

    populate_array(&size, &frames, NULL);

    parallel_processing(frames, size);

    deallocate_frames(frames, size);
}
