['Here is the C function named `initialize_network_database` that manages memory allocation for multiple structures under constrained resources and operational requirements:

```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <rand.h>

typedef struct {
    int value;
    char* identifier;
} record;

typedef struct {
    record* ptr;
    int count;
} summary;

void initialize_network_database(int max_records, int max_summary_entries) {
    // Allocate memory for offsets
    long* offsets = (long*)malloc((max_records + 1) * sizeof(long));

    // Allocate memory for keys
    int* keys = (int*)malloc(max_records * sizeof(int));
    int key_index = 0;
    for (int i = 0; i < max_records; i++) {
        if (i > 0 && rand() % 2 == 1) { // Duplicate detected, append unique index
            char buffer[10];
            sprintf(buffer, "%d", i);
            int* key = (int*)malloc(10 * sizeof(int));
            strcpy((char*)key, buffer);
            keys[key_index] = *((int*)key);
            free(key);
        } else {
            keys[i] = i;
        }
        key_index++;
    }

    // Allocate memory for records
    record* records = (record*)malloc(max_records * sizeof(record));
    for (int i = 0; i < max_records; i++) {
        int random_value = rand() % 100;
        char buffer[10];
        sprintf(buffer, "%c%c", 'a' + rand() % 26, 'a' + rand() % 26);
        records[i].value = random_value;
        records[i].identifier = (char*)malloc(11 * sizeof(char)); // 10 for the string and 1 for null terminator
        strcpy(records[i].identifier, buffer);
    }

    // Allocate memory for summaries
    summary* summaries = (summary*)malloc(max_summary_entries * sizeof(summary));
    for (int i = 0; i < max_summary_entries; i++) {
        summaries[i].ptr = NULL;
        summaries[i].count = 0;
    }

    // Sort records based on their int values in ascending order
    record temp;
    for (int i = 0; i < max_records - 1; i++) {
        for (int j = i + 1; j < max_records; j++) {
            if (records[i].value > records[j].value) {
                temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }

    // Initialize MAC_PACKET_T structures
    int N = 10; // Configurable number of structures
    MAC_PACKET_T* mac_packets = (MAC_PACKET_T*)malloc(N * sizeof(MAC_PACKET_T));
    for (int i = 0; i < N; i++) {
        mac_packets[i].src_mac_address = (char*)malloc(18 * sizeof(char)); // 17 for the address and 1 for null terminator
        mac_packets[i].dst_mac_address = (char*)malloc(18 * sizeof(char));
        mac_packets[i].eth_payload = (char*)malloc(rand() % 100 + 10 * sizeof(char)); // Dynamically generated payload length
    }

    // Initialize secondary array of summaries
    summary* secondary_summaries = (summary*)malloc(max_summary_entries * sizeof(summary));
    for (int i = 0; i < max_summary_entries; i++) {
        secondary_summaries[i].ptr = NULL;
        secondary_summaries[i].count = 0;
    }
}
