        enum {RRC_DOWNLINK_RECEIVED, RRC_UPLINK_SENT, RRC_CONNECTED} RRC_STATE;
        char UE_ID[16];
        int SIB1;
    } UE_CONTEXT;
} LTE_ENB_CONTEXT;

void populate_array(int* size, LTE_ENB_CONTEXT** array) {
    *array = (LTE_ENB_CONTEXT*)malloc(*size * sizeof(LTE_ENB_CONTEXT));

    for (int i = 0; i < *size; i++) {
        (*array)[i].ENB_ID = i;
        (*array)[i].CELL_ID = i + 1;
        strcpy((*array)[i].UE_CONTEXT.UE_ID, "UE-ID");
        (*array)[i].UE_CONTEXT.RRC_STATE = RRC_DOWNLINK_RECEIVED;
        (*array)[i].UE_CONTEXT.SIB1 = i;
    }
}

void deallocate_array(int* size, LTE_ENB_CONTEXT** array) {
    free(*array);
    *array = NULL;
}

void serialize_to_file(const char* filename, int size, LTE_ENB_CONTEXT* array) {
    FILE* file = fopen(filename, "wb");

    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    for (int i = 0; i < size; i++) {
        fwrite(&array[i], sizeof(LTE_ENB_CONTEXT), 1, file);
    }

    fclose(file);
}

void deserialize_from_file(const char* filename, int* size, LTE_ENB_CONTEXT** array) {
    FILE* file = fopen(filename, "rb");

    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    *array = (LTE_ENB_CONTEXT*)malloc(fileSize / sizeof(LTE_ENB_CONTEXT));

    fread(*array, sizeof(LTE_ENB_CONTEXT), fileSize / sizeof(LTE_ENB_CONTEXT), file);

    fclose(file);
}

int main() {
    int size = 5;
    LTE_ENB_CONTEXT* array;

    populate_array(&size, &array);

    // Use the populated array
    // ...

    deallocate_array(&size, &array);

    serialize_to_file("data.bin", size, array);

    int newSize;
    LTE_ENB_CONTEXT* newArray;

    deserialize_from_file("data.bin", &newSize, &newArray);

    deallocate_array(&newSize, &newArray);

    return 0;
}
