void manageArray(int n, NFAPI_L1_STATS_RX_PDU_T **array) {
    // Dynamically allocate memory for the array
    *array = (NFAPI_L1_STATS_RX_PDU_T *)malloc(n * sizeof(NFAPI_L1_STATS_RX_PDU_T));

    if (*array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize and populate the array
    for (int i = 0; i < n; i++) {
        (*array)[i].RX_STATS_TAG = i;
        (*array)[i].UE_ID = i * 2;
        (*array)[i].RX_POWER = (float)i / 10.0;
        (*array)[i].SNR = (float)i / 5.0;
        (*array)[i].BER = (float)i / 20.0;
    }
}

// Function to serialize the array of structures to a file
void serializeArray(NFAPI_L1_STATS_RX_PDU_T *array, int n) {
    // Open the output file in binary write mode
    FILE *fp = fopen("output.bin", "wb");

    if (fp == NULL) {
        printf("File opening failed.\n");
        return;
    }

    // Write the array to the file
    fwrite(array, sizeof(NFAPI_L1_STATS_RX_PDU_T), n, fp);

    fclose(fp);
}

// Function to deserialize the array of structures from a file
void deserializeArray(NFAPI_L1_STATS_RX_PDU_T **array) {
    // Open the input file in binary read mode
    FILE *fp = fopen("output.bin", "rb");

    if (fp == NULL) {
        printf("File opening failed.\n");
        return;
    }

    // Read the array from the file and dynamically allocate memory for it
    int n;
    fread(&n, sizeof(int), 1, fp);
    *array = (NFAPI_L1_STATS_RX_PDU_T *)malloc(n * sizeof(NFAPI_L1_STATS_RX_PDU_T));

    if (*array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Read the array from the file
    fread(*array, sizeof(NFAPI_L1_STATS_RX_PDU_T), n, fp);

    fclose(fp);
}

int main() {
    int n = 10; // Set the size of the array

    NFAPI_L1_STATS_RX_PDU_T *array;
    manageArray(n, &array);

    serializeArray(array, n);

    deserializeArray(&array);

    free(array); // Deallocate memory for the array
    return 0;
}
