#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <zlib.h>

// Define structure LTE_ENB_CONTEXT
typedef struct {
    int ENB_ID;
    int CELL_ID;
    struct UE_CONTEXT {
        enum { RRC_STATE_IDLE, RRC_STATE_CONNECTED } RRC_STATE;
        int UE_ID;
        char SIB1[16];
    } UE_CONTEXT;
} LTE_ENB_CONTEXT;

// Define a function to manage and populate an array of LTE_ENB_CONTEXT structures
void lte_enb_context_manager(int* num_contexts, LTE_ENB_CONTEXT** contexts) {
    // Dynamic memory allocation for the context array
    *contexts = (LTE_ENB_CONTEXT*)malloc(*num_contexts * sizeof(LTE_ENB_CONTEXT));
    if (*contexts == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize each structure with valid ENB_ID, CELL_ID, and UE_CONTEXT information
    for (int i = 0; i < *num_contexts; i++) {
        (*contexts)[i].ENB_ID = i % 100 + 1;
        (*contexts)[i].CELL_ID = i % 10000 + 1;
        // Initialize UE_CONTEXT structure with RRC_STATE, UE_ID, and SIB1 configuration data
    }

    // Serialize LTE_ENB_CONTEXT structures to a file for later retrieval
    int fd = open("lte_enb_contexts.bin", O_RDWR | O_CREAT, 0644);
    if (fd < 0) {
        printf("Failed to create or open the file.\n");
        return;
    }

    // Compress and write serialized data to the file using zlib compression
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    int ret = deflateInit(&stream, 6); // Set compression level (6 for best compression)
    if (ret != Z_OK) {
        printf("Failed to initialize zlib compression.\n");
        close(fd);
        return;
    }

    char* buffer = NULL;
    size_t buffer_size = *num_contexts * sizeof(LTE_ENB_CONTEXT);

    // Serialize and compress data
    stream.next_in = (void*)((*contexts));
    stream.avail_in = buffer_size;

    do {
        size_t bytes_written = write(fd, &stream, buffer_size);
        if (bytes_written < 0) {
            printf("Failed to write to the file.\n");
            close(fd);
            return;
        }
        stream.next_out += bytes_written;
        stream.avail_out -= bytes_written;
    } while (stream.avail_in > 0);

    // Flush zlib compression
    deflateEnd(&stream);

    close(fd);

    // Report statistics about added, updated, and deleted contexts
    printf("Added %d contexts.\n", *num_contexts);
}

// Define a function to report context operation statistics and performance metrics
void report_context_stats(int num_added, int num_updated, int num_deleted) {
    printf("Context operations:\n");
    printf("  Added: %d\n", num_added);
    printf("  Updated: %d\n", num_updated);
    printf("  Deleted: %d\n", num_deleted);

    // Calculate and report performance metrics (average time taken for context operations)
    double avg_time_taken = (double)num_added + num_updated + num_deleted / 3.0;
