typedef struct {
    int physical_layer_stats;
    char channel_quality_indicator[16];
    double transmission_power;
} LTEPHY_MIB_TABLE_T;

void init_mib_table_array(LTEPHY_MIB_TABLE_T **mib_table_array, size_t *size) {
    (*mib_table_array) = (LTEPHY_MIB_TABLE_T *)malloc(sizeof(LTEPHY_MIB_TABLE_T));
    (*size) = 1;
}

int free_mib_table_array(LTEPHY_MIB_TABLE_T **mib_table_array, size_t *size) {
    if((*mib_table_array) && (*size > 0)) {
        for(size_t i = 0; i < *size; i++) {
            free((*mib_table_array) + i);
        }
        free(*mib_table_array);
        (*mib_table_array) = NULL;
        (*size) = 0;
    }
    return 0;
}

int populate_mib_table(LTEPHY_MIB_TABLE_T **mib_table_array, size_t *size, int cell_id) {
    if((*size) < (cell_id + 1)) {
        for(size_t i = *size; i <= cell_id; i++) {
            (*mib_table_array)[i].physical_layer_stats = i;
            strcpy((*mib_table_array)[i].channel_quality_indicator, "Good");
            (*mib_table_array)[i].transmission_power = 0.5 + (double)i / 100;
        }
        for(size_t i = *size; i <= cell_id; i++) {
            free((*mib_table_array) + i);
        }
        (*mib_table_array) = (LTEPHY_MIB_TABLE_T *)realloc(*mib_table_array, sizeof(LTEPHY_MIB_TABLE_T) * (cell_id + 1));
        (*size) = cell_id + 1;
    }
    return 0;
}

int serialize_mib_table_to_db(LTEPHY_MIB_TABLE_T **mib_table_array, size_t *size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if(fp == NULL) {
        printf("Failed to open file for writing.\n");
        return -1;
    }
    fwrite(*mib_table_array, sizeof(LTEPHY_MIB_TABLE_T), *size, fp);
    fclose(fp);
    return 0;
}

int deserialize_mib_table_from_db(LTEPHY_MIB_TABLE_T **mib_table_array, size_t *size, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if(fp == NULL) {
        printf("Failed to open file for reading.\n");
        return -1;
    }
    fseek(fp, 0, SEEK_END);
    size_t fileSize = ftell(fp);
    rewind(fp);
    (*mib_table_array) = (LTEPHY_MIB_TABLE_T *)malloc(fileSize);
    fread(*mib_table_array, sizeof(LTEPHY_MIB_TABLE_T), fileSize / sizeof(LTEPHY_MIB_TABLE_T), fp);
    fclose(fp);
    return 0;
}

int main() {
    LTEPHY_MIB_TABLE_T *mib_table_array = NULL;
    size_t size = 0;

    init_mib_table_array(&mib_table_array, &size);

    for(size_t i = 0; i < 10; i++) {
        populate_mib_table(&mib_table_array, &size, i);
    }

    serialize_mib_table_to_db(&mib_table_array, &size, "mib_data.bin");

    free_mib_table_array(&mib_table_array, &size);

    return 0;
}
