#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int ENB_ID;
    int CELL_ID;
    struct UE_CONTEXT {
        enum { RRC_STATE_OFF, RRC_STATE_ON } RRC_STATE;
        int UE_ID;
        char SIB1[256];
    } UE_CONTEXT;
} LTE_ENB_CONTEXT;

// Function to manage and populate an array of LTE_ENB_CONTEXT structures
void* lte_enb_context_array_manage(int size) {
    // Allocate memory for the array
    void* arr = malloc(size * sizeof(LTE_ENB_CONTEXT));

    if (arr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the array
    LTE_ENB_CONTEXT* enb_context_arr = (LTE_ENB_CONTEXT*)arr;
    for (int i = 0; i < size; i++) {
        enb_context_arr[i].ENB_ID = i + 1;
        enb_context_arr[i].CELL_ID = i + 2;
        strcpy(enb_context_arr[i].UE_CONTEXT.SIB1, "SIB1 Configuration");
    }

    return arr;
}

// Function to serialize the array to a file
void lte_enb_context_array_serialize(void* arr, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return;
    }

    LTE_ENB_CONTEXT* enb_context_arr = (LTE_ENB_CONTEXT*)arr;
    int size = sizeof(LTE_ENB_CONTEXT);
    fwrite(&size, sizeof(int), 1, file); // Write array size

    for (int i = 0; i < size; i++) {
        fwrite(&enb_context_arr[i], sizeof(LTE_ENB_CONTEXT), 1, file); // Write each LTE_ENB_CONTEXT structure
    }

    fclose(file);
}

// Function to deserialize the array from a file
void* lte_enb_context_array_deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open file for reading\n");
        return NULL;
    }

    int size;
    fread(&size, sizeof(int), 1, file); // Read array size

    void* arr = malloc(size * sizeof(LTE_ENB_CONTEXT));
    LTE_ENB_CONTEXT* enb_context_arr = (LTE_ENB_CONTEXT*)arr;

    for (int i = 0; i < size; i++) {
        fread(&enb_context_arr[i], sizeof(LTE_ENB_CONTEXT), 1, file); // Read each LTE_ENB_CONTEXT structure
    }

    fclose(file);
    return arr;
}

// Function to update the array by adding or removing UE_CONTEXT entries
void lte_enb_context_array_update(void* arr, int operation) {
    LTE_ENB_CONTEXT* enb_context_arr = (LTE_ENB_CONTEXT*)arr;
    int size = sizeof(LTE_ENB_CONTEXT);

    // Handle memory allocation and deallocation for the array dynamically
    if (operation == 1) { // Add UE_CONTEXT entry
        void* temp_arr = realloc(arr, (size + 1) * sizeof(LTE_ENB_CONTEXT));
        if (temp_arr != NULL) {
            arr = temp_arr;
        } else {
            printf("Memory allocation failed\n");
            return;
        }

        enb_context_arr[size - 1].ENB_ID = size;
        enb_context_arr[size - 1].CELL_ID = size + 1;
        strcpy(enb_context_arr[size - 1].UE_CONTEXT.SIB1, "New SIB1 Configuration");
    } else if (operation == 2) { // Remove UE_CONTEXT entry
        void* temp_arr = realloc(arr, (size - 1) * sizeof(LTE_ENB_CONTEXT));
        if (temp_arr != NULL) {
            arr = temp_arr;
        } else {
            printf("Memory allocation failed\n");
            return;
        }

        size--;
    }
}
