        int minorVersion = cJSON_GetIntValue(versionConfig);
        printf(" Detected NFAPI Version %d.%d\n", majorVersion, minorVersion);
    } else {
        printf("No version configuration found\n");
    }

    // Handle error handling and logging
    char errorBuffer[1024];
    va_list ap;
    va_start(ap, errorBuffer);
    vsnprintf(errorBuffer, sizeof(errorBuffer), "Error: %s", strerror(errno));
    va_end(ap);
    printf("%s\n", errorBuffer);

    // Release memory and close files
