// Structure definition for record type
typedef struct {
    long offset;
    int key;
} record;

// Function to dynamically manage memory allocation for records
record **manageRecords(int *count, int initialCapacity) {
    // Initialize the array of record pointers with initial capacity
    record **records = (record **)malloc(initialCapacity * sizeof(record *));

    // Initialize the total count of records
    *count = 0;

    return records;
}

// Function to add a new record dynamically
void addRecord(record ***records, int *count, long offset, int key) {
    // Resize the array if necessary (i.e., when adding more records than initial capacity)
    if (*count >= *((*records) + 1)) {
        int newCapacity = *count * 2;
        record **newRecords = (record **)realloc(*records, newCapacity * sizeof(record *));

        // Update the pointer to point to the newly allocated memory
        *records = newRecords;
    }

    // Allocate a new record structure and add it to the array
    (*records)[*count] = (record *)malloc(sizeof(record));
    (*((*records)[*count]))->offset = offset;
    (*((*records)[*count]))->key = key;

    // Update the total count of records
    (*count)++;
}

// Function to free dynamically allocated memory for records
void freeRecords(record **records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(records);
}
