typedef struct {
    char* name;
    char* value;
    int type;
} ConfigSetting;

typedef struct {
    int capacity;
    int size;
    ConfigSetting** settings;
    unsigned int hash[256]; // Simple hash table for O(1) lookups
} ConfigManager;

ConfigManager* config_manager_init(int estimated_max_settings) {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL; // Handle memory allocation error

    manager->capacity = 16;
    manager->size = 0;
    manager->settings = (ConfigSetting**)malloc(manager->capacity * sizeof(ConfigSetting*));

    for (int i = 0; i < manager->capacity; i++) {
        manager->hash[i] = -1; // Initialize hash table
    }

    return manager;
}

void config_manager_insert(ConfigManager* manager, const char* name, const char* value, int type) {
    if (!manager || !name || !value) return; // Handle invalid input

    unsigned int hash_value = 0;
    for (int i = 0; i < strlen(name); i++) {
        hash_value += (unsigned char)name[i];
    }

    ConfigSetting* setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    if (!setting) return; // Handle memory allocation error

    setting->name = strdup(name);
    setting->value = strdup(value);
    setting->type = type;

    int index = hash_value % manager->capacity;
    while (manager->hash[index] != -1 && manager->settings[index] != NULL) {
        index = (index + 1) % manager->capacity;
    }

    if (manager->size == manager->capacity) {
        // Reallocate when the array is full
        ConfigSetting** new_settings = (ConfigSetting**)malloc((manager->capacity * 2) * sizeof(ConfigSetting*));
        memcpy(new_settings, manager->settings, manager->capacity * sizeof(ConfigSetting*));

        for (int i = 0; i < manager->size; i++) {
            free(new_settings[i]->name);
            free(new_settings[i]->value);
            free(new_settings[i]);
        }

        free(manager->settings);

        manager->settings = new_settings;
        manager->capacity *= 2;
    }

    if (manager->hash[index] == -1) {
        // Insert new setting at the empty slot
        manager->settings[index] = setting;
        manager->size++;
        manager->hash[index] = (unsigned int)(setting);
    }
}

void config_manager_remove(ConfigManager* manager, const char* name) {
    if (!manager || !name) return; // Handle invalid input

    unsigned int hash_value = 0;
    for (int i = 0; i < strlen(name); i++) {
        hash_value += (unsigned char)name[i];
    }

    int index = hash_value % manager->capacity;

    while (manager->hash[index] != -1 && manager->settings[index]->name) {
        if (!strcmp(manager->settings[index]->name, name)) {
            // Remove the setting
            free(manager->settings[index]->name);
            free(manager->settings[index]->value);
            free(manager->settings[index]);
            manager->size--;

            while (manager->hash[index] != -1 && manager->settings[index]->name) {
                ConfigSetting* next = manager->settings[(index + 1) % manager->capacity];
                free(manager->settings[index]->name);
                free(manager->settings[index]->value);
                free(manager->settings[index]);
                manager->settings[index] = next;
                index = (index + 1) % manager->capacity;
            }

            return;
        }
        index = (index + 1) % manager->capacity;
    }
}

void config_manager_free(ConfigManager* manager) {
    if (!manager) return; // Handle invalid input

    for (int i = 0; i < manager->size; i++) {
        free(manager->settings[i]->name);
        free(manager->settings[i]->value);
        free(manager->settings[i]);
    }

    free(manager->settings);

    free(manager);
}
