void add_record(Record ***records, int *capacity, int *count) {
    Record **temp = (Record **)malloc(*capacity * 2 * sizeof(Record *));
    for (int i = 0; i < *capacity; i++) {
        temp[i] = records[i];
    }
    free(records);
    *records = temp;
    (*records)[*count] = malloc(sizeof(Record));
    (*count)++;
}

// Function to sort the record array using custom comparison function
void sort_records(Record **records, int count) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (compare_func(records[i], records[j]) > 0) {
                Record *temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}

// Function to log all operations performed on the records
void log_operation(const char *operation, const void *record, int timestamp) {
    FILE *log_file = fopen("records.log", "a");
    fprintf(log_file, "%s: %ld - Offset: %ld, Key: %d, String: %s\n", operation, timestamp, ((Record *)record)->offset, ((Record *)record)->key, ((Record *)record)->str);
    fclose(log_file);
}

// Function to handle concurrent access and thread safety
void *thread_safe_function(void *arg) {
    // Perform operations on records concurrently
    log_operation("Thread", arg, time(NULL));
    return NULL;
}

int main() {
    int capacity = 10;
    int count = 0;
    Record **records = init_records(capacity);

    // Initialize a thread pool for concurrent access
    pthread_t threads[capacity];
    for (int i = 0; i < capacity; i++) {
        pthread_create(&threads[i], NULL, thread_safe_function, records + i);
    }

    // Add new records dynamically and sort the array
    add_record(&records, &capacity, &count);
    sort_records(records, count);

    return 0;
}
