NFAPI_CRC_INDICATION_PDU_T* generate_and_populate_array(int n) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    CURL *curl;
    CURLcode res;
    FILE *fp;
    char buffer[256];
    int i;

    // Allocate memory for the array
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize API call and cache
    CURL *curl_handle = curl_init();
    FILE *cache_fp = fopen("bibliography_cache.txt", "r");

    for (i = 0; i < n; i++) {
        // Generate random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        strcpy(array[i].RNTI, "RNTI_");
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0;

        // Fetch bibliographical information using API call and cache
        if (i % 10 == 0 && i > 0) {
            res = curl_easy_setopt(curl_handle, CURLOPT_URL, "https://api.bibliography.com/books");
            res = curl_easy_perform(curl_handle);

            if (res != CURLE_OK) {
                printf("cURL error: %s\n", curl_easy_strerror(res));
                break;
            }

            // Save fetched data to cache
            fp = fopen("bibliography_cache.txt", "w");
            fwrite(buffer, 1, strlen(buffer), fp);
            fclose(fp);

            // Reset API call handle
            curl_easy_cleanup(curl_handle);
            curl_handle = curl_init();
        }
    }

    // Clean up memory and close files
    free(array);
    curl_easy_cleanup(curl_handle);
    fclose(cache_fp);

    return array;
}
