struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

void print_list(struct node* head) {
    while (head != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               head->data.RX_UE_INFORMATION_TAG, head->data.RNTI, head->data.CRC_INDICATION_REL8_TAG, head->data.CRCFLAG);
        head = head->next;
    }
}

struct node* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = CRCFLAG;
    new_node->next = NULL;
    return new_node;
}

int main(int argc, char* argv[]) {
    int N = 10; // number of elements
    srand(time(NULL)); // initial seed for reproducibility

    struct node* head = NULL;

    for (int i = 0; i < N; i++) {
        int RX_UE_INFORMATION_TAG = rand();
        int RNTI = rand();
        int CRC_INDICATION_REL8_TAG = rand();
        int CRCFLAG = rand();

        struct node* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);

        if (head == NULL) {
            head = new_node;
        } else {
            struct node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
