// Custom memory pool
void* my_malloc(size_t size) {
    // Allocate memory from the custom pool here
    return malloc(size);
}

void my_free(void* ptr) {
    // Free allocated memory back to the custom pool here
    free(ptr);
}

// Node structure for dynamic linked list
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node;

// Dynamic linked list with concurrent access support
node* create_list(int N, int seed) {
    srand(seed);

    // Create the head of the linked list
    node* head = NULL;
    for (int i = 0; i < N; i++) {
        node* new_node = (node*)my_malloc(sizeof(node));
        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand();
        new_node->data.CRC_INDICATION_REL8_TAG = rand();
        new_node->data.CRCFLAG = (char)(rand() % 2); // Randomly set CRCFLAG
        if (!head) {
            head = new_node;
        } else {
            node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    return head;
}

// Serialize the linked list into a compact binary format
void serialize_list(node* head, FILE* file) {
    if (!head) {
        fprintf(file, "\0"); // Write NULL to indicate end of list
        return;
    }

    node* current = head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

// Deserialize the linked list from a compact binary format
node* deserialize_list(FILE* file) {
    node* head = NULL;

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        if (!head) {
            head = (node*)my_malloc(sizeof(node));
            head->data = data;
            head->next = NULL;
        } else {
            node* current = head;
            while (current->next) {
                current = current->next;
            }
            node* new_node = (node*)my_malloc(sizeof(node));
            new_node->data = data;
            new_node->next = NULL;
            current->next = new_node;
        }
    }

    return head;
}

// Round-trip testing of data integrity
int main() {
    int N = 10; // Number of elements in the linked list
    int seed = 42; // Initial seed for reproducibility

    node* head = create_list(N, seed);
    FILE* file = fopen("test.bin", "wb"); // Write binary file
    serialize_list(head, file);

    fclose(file);
    file = fopen("test.bin", "rb"); // Read binary file
    node* deserialized_head = deserialize_list(file);

    // Verify data integrity by comparing the original and deserialized lists
    node* current1 = head;
    node* current2 = deserialized_head;
    while (current1 && current2) {
        if (current1->data.RX_UE_INFORMATION_TAG != current2->data.RX_UE_INFORMATION_TAG ||
            current1->data.RNTI != current2->data.RNTI ||
            current1->data.CRC_INDICATION_REL8_TAG != current2->data.CRC_INDICATION_REL8_TAG) {
            printf("Data integrity error!\n");
            return 1;
        }
        current1 = current1->next;
        current2 = current2->next;
    }

    // Clean up
    while (head) {
        node* next = head->next;
        my_free(head);
        head = next;
    }
    fclose(file);

    return 0;
}
