#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint16_t sequence_number;
    int transmission_mode;
    uint8_t transmitted_block_error_flag;
    uint8_t error_flag_state;
} TX_MESSAGE_PDU_T;

// Define a structure for the linked list node
typedef struct Node {
    TX_MESSAGE_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random values
Node* create_node(int N, unsigned seed) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    // Initialize the data fields with random values
    node->data.sequence_number = rand_r(&seed) % 0xFFFF;
    node->data.transmission_mode = rand_r(&seed) % 2;
    node->data.transmitted_block_error_flag = rand_r(&seed) % 256;
    node->data.error_flag_state = (rand_r(&seed) % 2);
    node->next = NULL;
    return node;
}

// Function to add a new node at the end of the linked list
void add_node(Node** head, int N, unsigned seed) {
    Node* new_node = create_node(N, seed);
    if (*head == NULL || new_node->data.sequence_number > (*head)->data.sequence_number) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->data.sequence_number >= new_node->data.sequence_number) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to serialize the linked list into a binary format
void serialize(Node* head, FILE* file) {
    if (head == NULL) return;

    // Serialize the sequence number and transmission mode
    fwrite(&head->data.sequence_number, sizeof(uint16_t), 1, file);
    fwrite(&head->data.transmission_mode, sizeof(int), 1, file);

    // Recursively serialize the rest of the linked list
    serialize(head->next, file);
}

// Function to deserialize the binary format into a linked list
Node* deserialize(FILE* file) {
    Node* head = NULL;
    uint16_t sequence_number;
    int transmission_mode;

    while (fread(&sequence_number, sizeof(uint16_t), 1, file) == 1 &&
           fread(&transmission_mode, sizeof(int), 1, file) == 1) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        node->data.sequence_number = sequence_number;
        node->data.transmission_mode = transmission_mode;
        node->next = head;
        head = node;
    }

    return head;
}

int main() {
    // Initialize the seed for random number generation
    srand(time(NULL));

    int N = 10;  // Number of elements in the linked list

    Node* head = NULL;

    // Add nodes to the linked list
    for (int i = 0; i < N; i++) {
        add_node(&head, N, time(NULL));
    }

    // Serialize the linked list into a binary format
    FILE* file = fopen("data.bin", "wb");
    serialize(head, file);
    fclose(file);

    // Deserialize the binary format back into a linked list
    Node* deserialized_head = deserialize(fopen("data.bin", "rb"));
    fclose(file);

    return 0;
}
