#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_FILE_SIZE 102400 // 100KB in bytes
#define MAX_LINE_LENGTH 1024

typedef struct {
    FILE *file;
    pthread_mutex_t mutex;
} thread_data;

void* parse_file(void* arg) {
    thread_data* data = (thread_data*)arg;
    char line[MAX_LINE_LENGTH];
    int line_count = 0;

    while(fgets(line, sizeof(line), data->file)) {
        // Filter out comments
        if(strncmp(line, "#", 1) != 0) {
            line_count++;
        }
    }

    pthread_mutex_lock(&data->mutex);
    printf("File size: %d KB\nNumber of lines: %d\n", (int)(ftell(data->file) / 1024), line_count);
    pthread_mutex_unlock(&data->mutex);

    fclose(data->file);
    free(arg);
    return NULL;
}

int main(int argc, char* argv[]) {
    int c;
    FILE *output_file = stdout;
    int manpage = 0;
    char *input_file = NULL;

    while((c = getopt(argc, argv, "o:m:")) != -1) {
        switch(c) {
            case 'o':
                output_file = fopen(optarg, "w");
                break;
            case 'm':
                manpage = 1;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", c);
                return 1;
        }
    }

    argc -= optind;

    if(argc == 0) {
        printf("Usage:\n");
        printf("%s [options] <input_file>\n", argv[0]);
        printf("Options:\n");
        printf("-o output_file, --manpage\n");
        return 1;
    }

    input_file = argv[optind];

    pthread_t threads[argc];
    thread_data* data[argc];

    if(manpage) {
        // Print manpage
        printf("This program parses command line arguments and provides detailed usage information if no input file is specified.\n");
        printf("If an input file is provided, read it line by line and print the number of lines, but only for files larger than 100KB.\n");
        printf("It also supports filtering out comments from each line before counting them.\n");
        printf("The program can handle large numbers of files efficiently and manage memory usage effectively to prevent leaks.\n");
    }

    if(access(input_file, F_OK) == -1) {
        fprintf(stderr, "Error: File not found: %s\n", input_file);
        return 1;
    }

    struct stat sb;
    stat(input_file, &sb);

    if(sb.st_size <= MAX_FILE_SIZE) {
        FILE* file = fopen(input_file, "r");
        pthread_mutex_t mutex;

        if(file == NULL) {
            fprintf(stderr, "Error: Unable to open file: %s\n", input_file);
            return 1;
        }

        for(int i = 0; i < argc; i++) {
            data[i] = (thread_data*)malloc(sizeof(thread_data));
            data[i]->file = file;
            pthread_mutex_init(&data[i]->mutex, NULL);

            if(pthread_create(&threads[i], NULL, parse_file, data[i]) != 0) {
                fprintf(stderr, "Error: Unable to create thread\n");
                return 1;
            }
        }

        for(int i = 0; i < argc; i++) {
            pthread_join(threads[i], NULL);
            free(data[i]);
        }

        fclose(file);

    } else {
        FILE* file = fopen(input_file, "r");
        int line_count = 0;

        if(file == NULL) {
            fprintf(stderr, "Error: Unable to open file: %s\n", input_file);
            return 1;
        }

        while(fgets(line, sizeof(line), file)) {
            // Filter out comments
            if(strncmp(line, "#", 1) != 0) {
                line_count++;
            }
        }

        printf("File size: %d KB\nNumber of lines: %d\n", (int)(ftell(file) / 1024), line_count);

        fclose(file);
    }

    return 0;
}

