// Structure definition for LTE RRC CTR TX INFO T
typedef struct {
    int CELL_ID;
    int MME_ID;
    int PHY_LAYER_STATUS;
    float TRANSMISSION_POWER;
} LTE_RRC_CTR_TX_INFO_T;

// Function to manage linked list of LTE RRC CTR TX INFO T structures
void* lte_rrc_ctr_tx_info_list_node_init() {
    return malloc(sizeof(LTE_RRC_CTR_TX_INFO_T));
}

void lte_rrc_ctr_tx_info_free(void* node) {
    free(node);
}

void* lte_rrc_ctr_tx_info_list_insert_after(void** head, void* new_node) {
    // Initialize the new node
    LTE_RRC_CTR_TX_INFO_T* new_lte_rrc_ctr_tx_info = (LTE_RRC_CTR_TX_INFO_T*)new_node;

    // Allocate memory for the next node
    void* temp = lte_rrc_ctr_tx_info_list_node_init();

    // Initialize the next node with random values
    LTE_RRC_CTR_TX_INFO_T* next_lte_rrc_ctr_tx_info = (LTE_RRC_CTR_TX_INFO_T*)temp;
    next_lte_rrc_ctr_tx_info->CELL_ID = rand() % 1000 + 1;
    next_lte_rrc_ctr_tx_info->MME_ID = rand() % 1000 + 1;
    next_lte_rrc_ctr_tx_info->PHY_LAYER_STATUS = rand() % 2;
    next_lte_rrc_ctr_tx_info->TRANSMISSION_POWER = (float)rand() / RAND_MAX * 100.0f;

    // Insert the new node after the current head
    if (*head == NULL) {
        *head = temp;
    } else {
        void* prev_head = *head;
        while (((LTE_RRC_CTR_TX_INFO_T*)prev_head)->TRANSMISSION_POWER < next_lte_rrc_ctr_tx_info->TRANSMISSION_POWER) {
            prev_head = ((LTE_RRC_CTR_TX_INFO_T*)prev_head)->next;
        }
        next_lte_rrc_ctr_tx_info->next = prev_head;
        *head = temp;
    }

    // Return the new node
    return new_node;
}

void lte_rrc_ctr_tx_info_list_free(void** head) {
