typedef struct custom_node {
    int value;
    struct custom_node* next;
    struct custom_node* prev;
} custom_node;

void print_custom_node(custom_node* node) {
    printf("%d -> ", node->value);
}

custom_node* create_custom_node(int value, custom_node* next = NULL, custom_node* prev = NULL) {
    custom_node* new_node = (custom_node*)malloc(sizeof(custom_node));
    if (!new_node) {
        return NULL;
    }
    new_node->value = value;
    new_node->next = next;
    new_node->prev = prev;
    return new_node;
}

void free_custom_nodes(custom_node* head) {
    custom_node* current = head;
    while (current != NULL) {
        custom_node* temp = current;
        current = current->next;
        free(temp);
    }
}

custom_node* create_linked_lists(int num_nodes, int max_value) {
    srand(time(NULL)); // Seed random number generator
    custom_node* head = NULL;
    custom_node* tail = NULL;

    for (int i = 0; i < num_nodes; i++) {
        int value = rand() % max_value;
        custom_node* new_node = create_custom_node(value);
        if (!new_node) {
            return NULL;
        }

        // Set the random integer values in the linked lists
        for (int j = 0; j < 10; j++) { // Assuming each node has a linked list of length 10
            custom_node* new_int_node = create_custom_node(rand() % max_value);
            if (!new_int_node) {
                free_custom_nodes(head); // Clean up in case of memory allocation failure
                return NULL;
            }
            if (tail != NULL) {
                tail->next = new_int_node; // Add to the linked list
                new_int_node->prev = tail; // Update previous node reference
            } else {
                head = new_int_node; // Set as the new head of the linked list
            }
            tail = new_int_node;
        }

        if (head == NULL) {
            head = new_node;
        } else {
            head->prev = new_node; // Connect previous nodes to the new node
            new_node->next = head;
            head = new_node;
        }
    }

    return head;
}

int main() {
    custom_node* linked_lists = create_linked_lists(10, 100);
    if (linked_lists == NULL) {
        printf("Memory allocation failed. Exiting.\n");
        return -1;
    }

    // Print the circular linked list
    custom_node* current = linked_lists;
    while (current != NULL) {
        print_custom_node(current);
        current = current->next;
        if (current == linked_lists) {
            break; // Stop at the head of the list to form a circle
        }
    }

    free_custom_nodes(linked_lists);

    return 0;
}

