        strcpy(identifier, "Record ");
        metadata.status_flags = 0;
        metadata.related_records = NULL;
        metadata.cross_reference = NULL;

        insert_record(value, identifier, metadata);

        free(identifier);
    }

    // Sort and print the records
    sort_records();
    print_records();

    return 0;
}

// Initialize five arrays: one for storing 'long' offset values,
// another for 'int' keys, a third for 'char' string identifiers,
// a fourth for a custom 'struct' representing metadata,
// and a fifth for timestamps.
void init_records(int max_records, int min_value, int max_value) {
    // Initialize the record array
    Record* records = malloc(max_records * sizeof(Record));
    for (int i = 0; i < max_records; i++) {
        records[i].value = 0;
        records[i].identifier = NULL;
        records[i].metadata.status_flags = 0;
        records[i].metadata.related_records = NULL;
        records[i].metadata.cross_reference = NULL;
        records[i].timestamp = time(NULL);
    }

    // Initialize the other data structures
    int* keys = malloc(max_records * sizeof(int));
    char** identifiers = malloc(max_records * sizeof(char*));
    Metadata* metadata = malloc(max_records * sizeof(Metadata));
    time_t* timestamps = malloc(max_records * sizeof(time_t));

    // ... (insertion sort implementation)
}

// Insert a new record into the sorted array
int insert_record(int value, char* identifier, Metadata metadata) {
    // Find the correct position for the new record
    int i;
    for (i = 0; i < max_records; i++) {
        if (records[i].value >= value) {
            break;
        }
    }

    // Shift records to make room for the new one
    for (int j = max_records - 1; j > i; j--) {
        records[j] = records[j-1];
        keys[j] = keys[j-1];
        identifiers[j] = identifiers[j-1];
        metadata[j] = metadata[j-1];
        timestamps[j] = timestamps[j-1];
    }

    // Insert the new record
    records[i].value = value;
    records[i].identifier = identifier;
    records[i].metadata = metadata;
    records[i].timestamp = time(NULL);

    return i;
}

// Update a record in the sorted array
int update_record(int index, int new_value, char* new_identifier, Metadata new_metadata) {
    // Find the record to update
    if (index < 0 || index >= max_records) {
        printf("Error: Record not found.\n");
        return -1;
    }

    // Update the record fields
    records[index].value = new_value;
    records[index].identifier = new_identifier;
    records[index].metadata = new_metadata;

    // Re-sort the array if necessary
    if (new_value < records[index-1].value) {
        int i;
        for (i = 0; i < max_records; i++) {
            if (records[i].value >= new_value) {
                break;
            }
        }

        // Shift records to make room for the updated one
        for (int j = max_records - 1; j > i; j--) {
            records[j] = records[j-1];
            keys[j] = keys[j-1];
            identifiers[j] = identifiers[j-1];
            metadata[j] = metadata[j-1];
            timestamps[j] = timestamps[j-1];
        }

        // Insert the updated record
        records[i].value = new_value;
        records[i].identifier = new_identifier;
        records[i].metadata = new_metadata;
        records[i].timestamp = time(NULL);
    }

    return 0;
}

// Delete a record from the sorted array
void delete_record(int index) {
    // Find the record to delete
    if (index < 0 || index >= max_records) {
        printf("Error: Record not found.\n");
        return;
    }

    // Shift records to fill the gap
    for (int i = index; i < max_records - 1; i++) {
        records[i] = records[i+1];
        keys[i] = keys[i+1];
        identifiers[i] = identifiers[i+1];
        metadata[i] = metadata[i+1];
        timestamps[i] = timestamps[i+1];
    }

    // Re-sort the array if necessary
    sort_records();
}

// Print all records in the sorted array
void print_records() {
