        : max_list_size_(max_list_size), crcflag_threshold_(crcflag_threshold) {}

    // Destructor
    ~NFAPI_CRC_INDICATION_PDU_LIST() {
        // Clean up old entries in the list based on a configurable age threshold
        while (!list_.empty()) {
            NFAPI_CRC_INDICATION_PDU_T* entry = list_.front();
            list_.pop();
            delete entry;
        }
    }

    // Add a new structure to the list
    void add(NFAPI_CRC_INDICATION_PDU_T* p) {
        if (list_.full()) {
            // Dynamically resize the list when it's full
            list_.resize(list_.capacity() * 2);
        }
        log_(p, list_.size());
        p->CRCFLAG = rand() % 256; // Generate a random CRC flag
        while (p->CRCFLAG < crcflag_threshold_) {
            p->CRCFLAG = rand() % 256;
        }
        if (!validate_CRC(p)) {
            return; // If the CRC flag is invalid, do not add it to the list
        }
        performance_monitor_(p->CRCFLAG);
        list_.push_back(p);
    }

    // Validate a structure's CRC flag
    bool validate_CRC(NFAPI_CRC_INDICATION_PDU_T* p) {
        // Custom validation logic here
        return true;
    }

    // Callback function for processing each new structure in the list
    void set_callback(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
        callback_ = callback;
    }

    // Support a priority queue for structures, where each structure has an associated priority level
    bool operator<(const NFAPI_CRC_INDICATION_PDU_T& p1, const NFAPI_CRC_INDICATION_PDU_T& p2) {
        return p1.RNTI < p2.RNTI;
    }

    // Serialize and deserialize the entire list to and from a binary file
    void serialize(const char* filename) {
        FILE* file = fopen(filename, "wb");
        if (!file) {
            // Handle error
            return;
        }
        for (int i = 0; i < list_.size(); i++) {
            NFAPI_CRC_INDICATION_PDU_T* p = list_[i];
            fwrite(&p->RNTI, sizeof(int), 1, file);
            fwrite(&p->CRCFLAG, sizeof(unsigned char), 1, file);
        }
        fclose(file);
    }

    void deserialize(const char* filename) {
        FILE* file = fopen(filename, "rb");
        if (!file) {
            // Handle error
            return;
        }
        while (fread(&p, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            list_.push_back(p);
        }
        fclose(file);
    }

    // Support a way to split the list into smaller sublists based on certain criteria
    void split_list(int start_RNTI, int end_RNTI) {
        std::list<NFAPI_CRC_INDICATION_PDU_T*> sublist;
        for (int i = 0; i < list_.size(); i++) {
            NFAPI_CRC_INDICATION_PDU_T* p = list_[i];
            if (p->RNTI >= start_RNTI && p->RNTI <= end_RNTI) {
                sublist.push_back(p);
            }
        }
    }

private:
    std::list<NFAPI_CRC_INDICATION_PDU_T*> list_;
    int max_list_size_;
    float crcflag_threshold_;
    void (*callback_)(NFAPI_CRC_INDICATION_PDU_T*);
    // Helper function for logging structures and their sizes
    void log_(NFAPI_CRC_INDICATION_PDU_T* p, int size) {
