typedef struct {
    TAI_LIST** elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} TAILIST_STRUCT;

TAILIST_STRUCT* create_tailist(int N, int tac_range, unsigned int seed) {
    TAILIST_STRUCT* tailist = (TAILIST_STRUCT*)malloc(sizeof(TAILIST_STRUCT));
    if (!tailist) {
        fprintf(stderr, "Memory allocation failed for tailist\n");
        return NULL;
    }

    srand(seed);
    tailist->size = 0;
    tailist->capacity = N;

    tailist->elements = (TAI_LIST**)malloc(tailist->capacity * sizeof(TAI_LIST*));
    if (!tailist->elements) {
        free(tailist);
        fprintf(stderr, "Memory allocation failed for elements\n");
        return NULL;
    }

    pthread_mutex_init(&tailist->lock, NULL);

    return tailist;
}

int append_tailist(TAILIST_STRUCT* tailist, int plmn_id, int tac, int* cell_ids, time_t timestamp, float quality_indicator, int priority_level) {
    if (tailist->size == tailist->capacity) {
        // Grow the list
        int new_capacity = tailist->capacity * 2;
        TAI_LIST** new_elements = (TAI_LIST**)realloc(tailist->elements, new_capacity * sizeof(TAI_LIST*));
        if (!new_elements) {
            fprintf(stderr, "Memory allocation failed for elements\n");
            return -1;
        }
        tailist->capacity = new_capacity;
        tailist->elements = new_elements;
    }

    TAI_LIST* element = (TAI_LIST*)malloc(sizeof(TAI_LIST));
    if (!element) {
        fprintf(stderr, "Memory allocation failed for element\n");
        return -1;
    }

    element->plmn_id = plmn_id;
    element->tac = tac;
    int num_cell_ids = rand() % 10 + 1; // Random number of cell IDs
    element->cell_ids = (int*)malloc(num_cell_ids * sizeof(int));
    if (!element->cell_ids) {
        free(element);
        fprintf(stderr, "Memory allocation failed for cell IDs\n");
        return -1;
    }
    for (int i = 0; i < num_cell_ids; i++) {
        element->cell_ids[i] = rand() % 10000 + 1; // Random cell ID
    }

    element->timestamp = timestamp;
    element->quality_indicator = quality_indicator;
    element->priority_level = priority_level;

    pthread_mutex_lock(&tailist->lock);
    tailist->elements[tailist->size++] = element;
    pthread_mutex_unlock(&tailist->lock);

    return 0;
}

void free_tailist(TAILIST_STRUCT* tailist) {
    for (int i = 0; i < tailist->size; i++) {
        TAI_LIST* element = tailist->elements[i];
        for (int j = 0; j < element->num_cell_ids; j++) {
            free(element->cell_ids);
        }
        free(element);
    }

    pthread_mutex_destroy(&tailist->lock);

    free(tailist->elements);
    free(tailist);

    return;
}

