typedef struct {
    int packet_id;
    size_t data_size;
    time_t transmission_timestamp;
} DATA_PACKET_T;

DATA_PACKET_T* generate_packets(int num_packets, int* packets_generated) {
    *packets_generated = 0;

    DATA_PACKET_T* buffer = (DATA_PACKET_T*)malloc(BUFFER_SIZE * sizeof(DATA_PACKET_T));
    for (int i = 0; i < num_packets; i++) {
        if (*packets_generated >= BUFFER_SIZE) {
            // flush the buffer
            int packets_flushed = *packets_generated / BUFFER_SIZE;
            for (int j = 0; j < packets_flushed; j++) {
                printf("Packet %d: packet_id=%d, data_size=%zu, transmission_timestamp=%ld\n",
                       *packets_generated - j * BUFFER_SIZE,
                       buffer[j].packet_id,
                       buffer[j].data_size,
                       (long)buffer[j].transmission_timestamp);
            }
            // free the buffer and allocate a new one
            free(buffer);
            buffer = (DATA_PACKET_T*)malloc(BUFFER_SIZE * sizeof(DATA_PACKET_T));
        }

        buffer[*packets_generated].packet_id = rand() % PACKET_ID_MAX;
        buffer[*packets_generated].data_size = rand() % 1024 + 1;
        buffer[*packets_generated].transmission_timestamp = time(NULL);

        (*packets_generated)++;
    }

    // flush the remaining packets
    int packets_flushed = *packets_generated / BUFFER_SIZE;
    for (int j = 0; j < packets_flushed; j++) {
        printf("Packet %d: packet_id=%d, data_size=%zu, transmission_timestamp=%ld\n",
               *packets_generated - j * BUFFER_SIZE,
               buffer[j].packet_id,
               buffer[j].data_size,
               (long)buffer[j].transmission_timestamp);
    }

    free(buffer);

    return NULL;
}

int serialize_packets(DATA_PACKET_T* packets, int num_packets, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return -1; // error opening file
    }

    size_t total_bytes = num_packets * sizeof(DATA_PACKET_T);
    fwrite(&packets[0], 1, total_bytes, file);

    fclose(file);

    return 0;
}

int main() {
    int num_packets = 10;
    int packets_generated = 0;

    DATA_PACKET_T* packets = generate_packets(num_packets, &packets_generated);

    serialize_packets(packets, packets_generated, "packets.dat");

    return 0;
}
