import concurrent.futures
import re

def process_log_files(log_files):
    # Filter out irrelevant entries and aggregate metrics with minimal latency
    # Ensure data integrity across concurrent processes.

    pattern = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}")
    aggregated_data = {}

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = {executor.submit(process_file, file) for file in log_files}
        for future in concurrent.futures.as_completed(futures):
            data = future.result()
            for key, value in data.items():
                if key in aggregated_data:
                    aggregated_data[key].append(value)
                else:
                    aggregated_data[key] = [value]

    return aggregated_data

def process_file(log_file):
    # Read and process a log file
    with open(log_file, "r") as f:
        content = f.read()

    pattern = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}")
    matches = pattern.finditer(content)

    data = {}
    for match in matches:
        timestamp = int(match.group(0).split(" ")[0])
        if timestamp not in data:
            data[timestamp] = []
        # Process log entry and append to the list
        data[timestamp].append({"key": "value"})

    return data

