#define MAX_CAPACITY 10000
#define LOGGING 1
#define CRCFLAG_MAX 0xFF
#define RNTI_MAX 0xFFFFFFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_nfa_pi_crc_indication_pdu_list(int num_batches, int **list_ptrs) {
    srand(time(NULL));
    for (int i = 0; i < num_batches; i++) {
        *list_ptrs = (int **)malloc(MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (*list_ptrs == NULL) return -1;

        int list_size = 0;
        int* rnti_set = (int *)calloc(MAX_CAPACITY, sizeof(int));
        int* crc_flags = (int *)calloc(MAX_CAPACITY, sizeof(int));

        for (int j = 0; j < MAX_CAPACITY; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pdu == NULL) return -1;

            pdu->RX_UE_INFORMATION_TAG = rand() % 256;
            int rnti = rand() % RNTI_MAX;
            while (rnti_set[rnti % MAX_CAPACITY] && list_size >= MAX_CAPACITY) {
                rnti = rand() % RNTI_MAX;
            }
            pdu->RNTI = rnti;
            rnti_set[rnti % MAX_CAPACITY] = 1;

            int crcflag = rand() & CRCFLAG_MAX;
            pdu->CRC_INDICATION_REL8_TAG = crcflag;
            crc_flags[j] = crcflag;

            (*list_ptrs)[j] = pdu;
            list_size++;
        }

        free(rnti_set);
        free(crc_flags);

        if (list_size > MAX_CAPACITY) {
            for (int j = 0; j < list_size; j++) {
                free((*list_ptrs)[j]);
            }
            free(*list_ptrs);
            return -1;
        }
    }

    return 0;
}

void serialize_nfa_pi_crc_indication_pdu_list(int **list_ptrs, int num_batches, FILE *file) {
    if (file == NULL) return;

    for (int i = 0; i < num_batches; i++) {
        for (int j = 0; j < MAX_CAPACITY; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (*list_ptrs)[j];
            fwrite(&pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
            fwrite(&pdu->RNTI, sizeof(int), 1, file);
            fwrite(&pdu->CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        }
    }

    for (int i = 0; i < num_batches; i++) {
        free(*list_ptrs);
        *list_ptrs = NULL;
    }
}

void log_memory_usage_and_list_size(int **list_ptrs, int num_batches) {
    printf("Memory usage: %d KB\n", (num_batches * MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T *)) / 1024);
    printf("List size: %d\n", num_batches * MAX_CAPACITY);
}

int main() {
    int num_batches = 2;
    int **list_ptrs = NULL;

    create_nfa_pi_crc_indication_pdu_list(num_batches, &list_ptrs);

    FILE* file = fopen("nfa_pi_crc_indication_pdu_list.bin", "wb");
    if (file != NULL) {
        serialize_nfa_pi_crc_indication_pdu_list(list_ptrs, num_batches, file);
        fclose(file);
    }

    log_memory_usage_and_list_size(list_ptrs, num_batches);

