    for (size_t i = 0; i < batch->size; i++) {
        if (batch->elements[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Function to insert a new element into the batch
int insert_element(BatchInfo* batch, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (batch->size >= batch->capacity) {
        // Log failed insertion attempt due to full capacity
        printf("Error: Batch is full.\n");
        return 0;
    }

    for (size_t i = 0; i < batch->size; i++) {
        if (!is_rnti_unique(batch, element->RNTI)) {
            // Log failed insertion attempt due to duplicate RNTI
            printf("Error: Duplicate RNTI detected.\n");
            return 0;
        }
    }

    batch->elements[batch->size] = *element;
    batch->size++;
    return 1;
}

// Function to serialize the batch into a binary format
int serialize_batch(BatchInfo* batch, char** buffer) {
    // Serialize batch information (size and capacity)
    char buffer_size[4];
    sprintf(buffer_size, "%zu", batch->size);
    *buffer = (char*)malloc(strlen(buffer_size) + 1);
    strcpy(*buffer, buffer_size);

    // Serialize elements
    for (size_t i = 0; i < batch->size; i++) {
        char buffer_element[32];
        sprintf(buffer_element, "%d %d %d", batch->elements[i].RX_UE_INFORMATION_TAG, batch->elements[i].RNTI, batch->elements[i].CRCFLAG);
        *buffer = (char*)realloc(*buffer, strlen(*buffer) + strlen(buffer_element) + 1);
        strcat(*buffer, buffer_element);
    }

    return 1;
}

// Function to deserialize the batch from a binary format
BatchInfo* deserialize_batch(char* buffer) {
    // Deserialize batch information (size and capacity)
    BatchInfo* batch = (BatchInfo*)malloc(sizeof(BatchInfo));
    char* buffer_size = strtok(buffer, " ");
    batch->capacity = 10000;
    batch->size = atoi(buffer_size);

    // Deserialize elements
    batch->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(batch->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    char* buffer_element = strtok(NULL, " ");
    for (size_t i = 0; i < batch->size; i++) {
        char* token = strtok(buffer_element, " ");
        batch->elements[i].RX_UE_INFORMATION_TAG = atoi(token);
        token = strtok(NULL, " ");
        batch->elements[i].RNTI = atoi(token);
        token = strtok(NULL, " ");
        batch->elements[i].CRCFLAG = atoi(token);
    }

    return batch;
}

// Function to compact the memory footprint by removing unused or obsolete entries
int compact_memory(BatchInfo* batch) {
    size_t new_capacity = batch->size * 2 + 1;
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t index = 0;

    for (size_t i = 0; i < batch->size; i++) {
        if (/* condition to check for unused or obsolete entries */) {
            continue;
        }
        new_elements[index] = batch->elements[i];
        index++;
    }

    free(batch->elements);
    batch->elements = new_elements;
    batch->capacity = new_capacity;

    return 1;
}

// Function to export the configuration settings used for memory management and serialization
int export_config(BatchInfo* batch, char** buffer) {
    // Export configuration settings (e.g., batch capacity, serialization format)
