NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfa_pi_crc_indication_pdu_t(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!list) return NULL;

    int failed_insertions = 0;
    FILE* log_file = fopen("log.txt", "w");
