#define MAX_METADATA_SIZE 1024

// Function to manage a list of TCP connection requests
TCP_CONNECTION_REQUEST_T* tcp_connection_request_manager(int client_id, struct in_addr ip_address, uint16_t port_number, char status_tag[]) {
    // Initialize the log variables
    int failed_insertions = 0;
    int successful_insertions = 0;

    // Initialize the dynamic array to store TCP connection requests
    TCP_CONNECTION_REQUEST_T* requests = (TCP_CONNECTION_REQUEST_T*)malloc(MAX_ELEMENTS * sizeof(TCP_CONNECTION_REQUEST_T));
    if (!requests) {
        printf("Memory allocation failed. Exiting.\n");
        return NULL;
    }

    int current_size = 0;

    // Initialize the external API interface
    extern void network_mgmt_api_call(int client_id, struct in_addr ip_address, uint16_t port_number);

    while (1) {
        if (current_size >= MAX_ELEMENTS) {
            // Dynamic resizing not supported yet. Exit.
            printf("Maximum capacity reached. Exiting.\n");
            free(requests);
            return NULL;
        }

        // Validate IP_ADDRESS and PORT_NUMBER pair uniqueness
        int duplicate = 0;
        for (int i = 0; i < current_size; i++) {
            if (((requests[i].ip_address.s_addr == ip_address.s_addr) && (requests[i].port_number == port_number))) {
                duplicate = 1;
                break;
            }
        }

        if (!duplicate) {
            // Insert new TCP connection request
            requests[current_size].client_id = client_id;
            requests[current_size].ip_address = ip_address;
            requests[current_size].port_number = port_number;
            strcpy(requests[current_size].status_tag, status_tag);

            network_mgmt_api_call(client_id, ip_address, port_number);

            current_size++;
            successful_insertions++;

        } else {
            // Log failed insertion attempt due to duplicate IP_ADDRESS and PORT_NUMBER pair
            printf("Failed insertion: Duplicate IP_ADDRESS and PORT_NUMBER pair. Log entry added.\n");
            failed_insertions++;
        }

        // Monitor memory usage periodically
        if (current_size % 100 == 0) {
            printf("Memory usage: %d MB\n", current_size * sizeof(TCP_CONNECTION_REQUEST_T));
        }
    }

    free(requests);
    return NULL;
}

