// Function to validate IP_ADDRESS and PORT_NUMBER pair uniqueness
int is_duplicate(TCP_CONNECTION_REQUEST_T* connection) {
    for (int i = 0; i < list_size; i++) {
        if (!strcmp(connection->ip_address, ((TCP_CONNECTION_REQUEST_T*)tcp_connection_request_list)->ip_address) &&
            connection->port_number == ((TCP_CONNECTION_REQUEST_T*)tcp_connection_request_list + i)->port_number) {
            return 1;
        }
    }
    return 0;
}

// Function to insert a new TCP connection request
int add_tcp_connection(TCP_CONNECTION_REQUEST_T* connection, int metadata_size) {
    if (list_size >= max_capacity) {
        // Log failure due to full capacity
        fprintf(log_file, "TCP Connection Request: Failed to add new connection due to full capacity at %ld.\n", time(NULL));
        return -1;
    }

    // Check for duplicate IP_ADDRESS and PORT_NUMBER pair
    if (is_duplicate(connection)) {
        // Log failure due to duplicate entry
        fprintf(log_file, "TCP Connection Request: Duplicate entry detected at %ld.\n", time(NULL));
        return -2;
    }

    // Allocate memory for new connection
    TCP_CONNECTION_REQUEST_T* new_connection = malloc(sizeof(TCP_CONNECTION_REQUEST_T) + metadata_size);
    if (!new_connection) {
        // Log failure due to memory allocation
        fprintf(log_file, "TCP Connection Request: Failed to allocate memory at %ld.\n", time(NULL));
        return -3;
    }

    memcpy(new_connection->ip_address, connection->ip_address, 16);
    new_connection->port_number = connection->port_number;
    new_connection->metadata = malloc(metadata_size);
    if (!new_connection->metadata) {
        // Log failure due to memory allocation
        fprintf(log_file, "TCP Connection Request: Failed to allocate metadata memory at %ld.\n", time(NULL));
        free(new_connection);
        return -4;
    }

    *new_connection->metadata = *((char*)connection->metadata);
    new_connection->status_tag = (rand() % 3); // Randomly set connection state

    memcpy(tcp_connection_request_list + list_size, new_connection, sizeof(TCP_CONNECTION_REQUEST_T) + metadata_size);
    free(new_connection->metadata);

    list_size++;

    return 0;
}

// Function to remove a TCP connection request
int remove_tcp_connection(int index) {
    if (index >= list_size || index < 0) {
        // Log failure due to out-of-bounds access
        fprintf(log_file, "TCP Connection Request: Out-of-bounds access detected at %ld.\n", time(NULL));
        return -1;
    }

    TCP_CONNECTION_REQUEST_T* connection = tcp_connection_request_list + index;

    // Simulate network request to API for removal
    int api_status = simulate_network_api_call("remove_tcp_connection", connection);

    if (api_status != 0) {
        // Log failure due to API error
        fprintf(log_file, "TCP Connection Request: Failed to remove connection from API at %ld.\n", time(NULL));
        return -2;
    }

    // Shift remaining connections to fill the gap
    for (int i = index; i < list_size - 1; i++) {
        memcpy(tcp_connection_request_list + i, tcp_connection_request_list + i + 1, sizeof(TCP_CONNECTION_REQUEST_T) + ((TCP_CONNECTION_REQUEST_T*)tcp_connection_request_list + i + 1)->metadata_size);
    }

    free(connection->metadata);

    // Update list size
    list_size--;

    return 0;
}

int main() {
