typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNfapiPduListWithCRC(NFAPI_CRC_INDICATION_PDU_T** pduList, size_t* capacity, size_t* size, FILE* logFile) {
    static const int MAX_CAPACITY = 1000;
    static const int RNTI_POOL_SIZE = 10000; // adjust according to requirements
    static uint16_t rntiPool[RNTI_POOL_SIZE];

    if (*capacity < *size + 1 || pduList == NULL) {
        fprintf(logFile, "Error: Insufficient memory or invalid pduList pointer.\n");
        return;
    }

    for (size_t i = 0; i < *size; i++) {
        // Generate random RNTI from the pool
        uint16_t rnti = rand() % RNTI_POOL_SIZE;
        if (!isUniqueRnti(rnti, &rntiPool[0], sizeof(rntiPool) / sizeof(rntiPool[0]))) {
            fprintf(logFile, "Error: Failed to generate unique RNTI.\n");
            return;
        }

        pduList[i]->RX_UE_INFORMATION_TAG = i;
        pduList[i]->RNTI = rnti;
        // Randomly set CRCFLAG
        srand((unsigned)time(NULL));
        pduList[i]->CRCFLAG = rand() % 2;

        if (*size == MAX_CAPACITY) {
            fprintf(logFile, "Error: Maximum capacity reached.\n");
            break; // Stop filling the list to prevent potential issues
        }
    }

    *size += 1;
}

int isUniqueRnti(uint16_t rnti, uint16_t* pool, size_t poolSize) {
    for (size_t i = 0; i < poolSize; i++) {
        if (pool[i] == rnti)
            return 0; // RNTI already exists in the pool
    }
    return 1; // Unique RNTI found
}
