    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);
    if (!pduList) return NULL;

    // Initialize the RNTI list and its size
    uint16_t* rntiList = (uint16_t*)malloc(sizeof(uint16_t)*N);
    if (!rntiList) {
        free(pduList);
        return NULL;
    }

    // Initialize the log of failed insertion attempts
    int failedInsertions = 0;

    // Populate the pduList and rntiList
    for (int i = 0; i < N; i++) {
        uint16_t rnti = rand() % 65535;
        while (rntiList[rnti] != 0) {
            if (failedInsertions >= 1000) break;
            failedInsertions++;
            rnti = rand() % 65535;
        }
        rntiList[rnti] = 1;

        // Initialize the pdu struct
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pduList[i];
        pdu->RX_UE_INFORMATION_TAG = (rand() % 255) + 1;
