#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a network statistics report
typedef struct {
    time_t timestamp;
    char interface[20];
    int packet_count;
    float error_rate;
} Report;

// Define the structure for the dynamic list of reports
typedef struct {
    Report* reports;
    int capacity;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ReportList;

// Function to create a new report list with initial capacity
ReportList* create_report_list(int capacity) {
    ReportList* list = (ReportList*)malloc(sizeof(ReportList));
    list->reports = (Report*)malloc(capacity * sizeof(Report));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// Function to insert a new report into the list
void insert_report(ReportList* list, Report* report) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // Handle full capacity by expanding the list
        int new_capacity = list->capacity * 2;
        ReportList* new_list = create_report_list(new_capacity);
        for (int i = 0; i < list->capacity; i++) {
            new_list->reports[i] = list->reports[i];
        }
        free(list->reports);
        list = new_list;
    }
    // Check if the report already exists
    int found = 0;
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(report->interface, list->reports[i].interface) &&
            list->reports[i].timestamp == report->timestamp) {
            found = 1;
            break;
        }
    }
    if (!found) {
        // Insert the new report
        list->reports[list->size] = *report;
        list->size++;
    } else {
        // Log error for duplicate report
        printf("Error: Duplicate report detected!\n");
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to prune old reports based on retention policy
void prune_reports(ReportList* list, int retention_days) {
    time_t now = time(NULL);
    Report* temp_reports = (Report*)malloc(list->size * sizeof(Report));
    int temp_size = 0;
    for (int i = 0; i < list->size; i++) {
        if ((now - list->reports[i].timestamp) / (60 * 60 * 24) <= retention_days) {
            // Keep the report
            temp_reports[temp_size] = list->reports[i];
            temp_size++;
        }
    }
    free(list->reports);
    list->size = temp_size;
    list->reports = temp_reports;
}

// Function to serialize the report list to disk
void serialize_report_list(ReportList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Could not open file for writing!\n");
        return;
    }
    fwrite(&list->size, sizeof(int), 1, file);
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->reports[i].timestamp, sizeof(time_t), 1, file);
        fwrite(list->reports[i].interface, sizeof(char), strlen(list->reports[i].interface) + 1, file);
        fwrite(&list->reports[i].packet_count, sizeof(int), 1, file);
        fwrite(&list->reports[i].error_rate, sizeof(float), 1, file);
    }
    fclose(file);
}

// Function to deserialize the report list from disk
ReportList* deserialize_report_list(const char* filename) {
    ReportList* list = (ReportList*)malloc(sizeof(ReportList));
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Could not open file for reading!\n");
        return NULL;
    }
    fread(&list->size, sizeof(int), 1, file);
    list->reports = (Report*)malloc(list->size * sizeof(Report));
    for (int i = 0; i < list->size; i++) {
        fread(&list->reports[i].timestamp, sizeof(time_t), 1, file);
        char temp_interface[20];
        fread(temp_interface, sizeof(char), strlen(list->reports[i].interface) + 1, file);
        strcpy(list->reports[i].interface, temp_interface);
        fread(&list->reports[i].packet_count, sizeof(int), 1, file);
        fread(&list->reports[i].error_rate, sizeof(float), 1, file);
    }
    fclose(file);
    return list;
}

// Function to free the report list and all its reports
void destroy_report_list(ReportList* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->reports[i].interface);
    }
    free(list->reports);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Example usage:
int main() {
    ReportList* list = create_report_list(10000);
    // ... add reports to the list ...
    serialize_report_list(list, "report_list.ser");
    ReportList* deserialized_list = deserialize_report_list("report_list.ser");
    // ... use the deserialized report list ...
    destroy_report_list(deserialized_list);
    return 0;
}
