        perror("Error opening log file");
    } else {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

// Validate RNTI uniqueness
int is_rnti_unique(NFAPI_CRC_INDICATION_PDU_T* array, int size, uint32_t rnti) {
    for (int i = 0; i < size; i++) {
        if (array[i].rnti == rnti) {
            return 0;
        }
    }
    return 1;
}

// Serialize NFAPI_CRC_INDICATION_PDU_T structures
void serialize(NFAPI_CRC_INDICATION_PDU_T* array, int size, FILE* file) {
    // Serialize using a custom format for the third-party analytics tool
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(&array[i].rx_ue_info_tag, sizeof(uint16_t), 1, file);
        fwrite(&array[i].rnti, sizeof(uint32_t), 1, file);
        fwrite(&array[i].crcflag, sizeof(uint8_t), 1, file);
    }
}

// Deserialize NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* deserialize(FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
