typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_array(int n, NFAPI_CRC_INDICATION_PDU_T **array) {
    for (int i = 0; i < n; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            printf("Memory allocation failed.\n");
            return;
        }
        array[i]->RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i]->RNTI = rand() % 1000;
        array[i]->CRCFLAG = rand() % 2;
    }
}

void serialize_array(int n, NFAPI_CRC_INDICATION_PDU_T **array) {
    FILE *file = fopen("data.bin", "wb");
    if (!file) {
        printf("Failed to open file.\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        fwrite(&array[i]->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&array[i]->RNTI, sizeof(int), 1, file);
        fwrite(&array[i]->CRCFLAG, sizeof(int), 1, file);
    }
    fclose(file);
}

void backup_data() {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, 64, "%Y-%m-%d-%H-%M-%S", localtime(&now));
    FILE *file = fopen("data.bin", "rb");
    if (!file) {
        printf("Failed to open file.\n");
        return;
    }
    FILE *backup_file = fopen(printf("backup_%s.bin", timestamp), "wb");
    if (!backup_file) {
        printf("Failed to open backup file.\n");
        fclose(file);
        return;
    }
    char buffer[1024];
    while (fread(buffer, 1, 1024, file)) {
        fwrite(buffer, 1, fread(buffer, 1, 1024, file), backup_file);
    }
    fclose(backup_file);
    fclose(file);
}

int main() {
    int n = 1000; // adjust according to your needs
    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!array) {
        printf("Memory allocation failed.\n");
        return -1;
    }
    populate_array(n, array);
    serialize_array(n, array);
    backup_data();
    for (int i = 0; i < n; i++) {
        free(array[i]);
    }
    free(array);
    return 0;
}
