        (*records)[i].RX_QUALITY = ...;      // Populate RX QUALITY
        (*records)[i].CHANNEL_UTILIZATION = ...;  // Populate CHANNEL UTILIZATION

        // Write log entry
        char log_entry[256];
        sprintf(log_entry, "Record %d: TX Power Level=%d, RX Quality=%d, Channel Utilization=%.2f\n", i + 1, (*records)[i].TX_POWER_LEVEL, (*records)[i].RX_QUALITY, (*records)[i].CHANNEL_UTILIZATION);
        write(log_fd, log_entry, strlen(log_entry));
    }

    // Close log file
    close(log_fd);

    // Compress log files periodically (e.g., every 10 minutes)
    time_t last_compress_time = time(NULL) - 600;  // 10 minutes

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_compress_time > 600) {  // 10 minutes
            last_compress_time = current_time;
            system("logrotate");  // Compress log files using a system command
        }
    }

    // Free allocated resources
    free(*records);
}
