#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for LTE ENB Context
typedef struct {
    int enb_id;
    int cell_id;
    struct {
        int ue_id;
        int rrc_state;
        char sib1_config[64];
    } ue_context;
} LTE_ENB_CONTEXT;

// Define the function to manage and populate the array of LTE ENB CONTEXT structures
int manage_enb_contexts(int num-contexts, FILE* file) {
    // Create a dynamic array for storing LTE ENB contexts
    LTE_ENB_CONTEXT** enb_context_array = (LTE_ENB_CONTEXT**)malloc(num-contexts * sizeof(LTE_ENB_CONTEXT*));

    if (!enb_context_array) {
        perror("Memory allocation failed");
        return -1;
    }

    // Initialize the semaphore for thread synchronization
    sem_t semaphore;
    if(sem_init(&semaphore, 0, 1) != 0) {
        perror("Semaphore initialization failed");
        free(enb_context_array);
        return -2;
    }

    // Create a separate thread for each context to simulate concurrent access and modification
    pthread_t threads[num-contexts];

    for (int i = 0; i < num-contexts; i++) {
        enb_context_array[i] = (LTE_ENB_CONTEXT*)malloc(sizeof(LTE_ENB_CONTEXT));

        if (!enb_context_array[i]) {
            perror("Memory allocation failed");
            return -3;
        }

        // Initialize the context with sample data
        enb_context_array[i]->enb_id = i;
        enb_context_array[i]->cell_id = i * 2;
        strcpy(enb_context_array[i]->ue_context.sib1_config, "SIB1 CONFIG");

        // Create a thread to modify the context and write it to file
        pthread_create(&threads[i], NULL, (void (*)(void*))modify_and_write_context, enb_context_array[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num-contexts; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the dynamic array and semaphore
    for (int i = 0; i < num-contexts; i++) {
        free(enb_context_array[i]);
    }

    free(enb_context_array);
    sem_destroy(&semaphore);

    return 0;
}

// Define the function to modify and write an LTE ENB context to file
void* modify_and_write_context(void* arg) {
    LTE_ENB_CONTEXT* enb_context = (LTE_ENB_CONTEXT*)arg;

    // Simulate modifying the context (e.g., update UE ID or RRC state)
    int new_ue_id = enb_context->ue_context.ue_id + 1;
    strcpy(enb_context->ue_context.sib1_config, "MODIFIED SIB1 CONFIG");

    // Serialize the modified context to file
    fwrite(&enb_context, sizeof(LTE_ENB_CONTEXT), 1, file);

    return NULL;
}
