#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct NLE {
    int nli;
    char protocol[10];
    int subnet_count;
    struct subnet {
        int id;
        char address[20];
        int latency;
        int packet_loss;
        int bandwidth;
    } *subnets;
} NLE;

void init_nle(NLE **nle, int nli) {
    *nle = (NLE *)malloc(sizeof(NLE));
    if (*nle == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    (*nle)->nli = nli;
    strcpy((*nle)->protocol, "Unknown");
    (*nle)->subnet_count = 0;
}

void add_subnet(NLE *nle, int id, char address[20], int latency, int packet_loss, int bandwidth) {
    nle->subnets = (struct subnet *)realloc(nle->subnets, sizeof(struct subnet) * (nle->subnet_count + 1));
    if (nle->subnets == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    nle->subnets[nle->subnet_count].id = id;
    strcpy(nle->subnets[nle->subnet_count].address, address);
    nle->subnets[nle->subnet_count].latency = latency;
    nle->subnets[nle->subnet_count].packet_loss = packet_loss;
    nle->subnets[nle->subnet_count].bandwidth = bandwidth;
    nle->subnet_count++;
}

void print_nle(NLE *nle) {
    printf("NLI: %d\n", nle->nli);
    printf("Protocol: %s\n", nle->protocol);
    printf("Subnets:\n");
    for (int i = 0; i < nle->subnet_count; i++) {
        printf("ID: %d, Address: %s, Latency: %d, Packet Loss: %d, Bandwidth: %d\n",
               nle->subnets[i].id, nle->subnets[i].address, nle->subnets[i].latency,
               nle->subnets[i].packet_loss, nle->subnets[i].bandwidth);
    }
}

void free_nle(NLE *nle) {
    for (int i = 0; i < nle->subnet_count; i++) {
        free(nle->subnets[i].address);
    }
    free(nle->subnets);
    free(nle);
}

