    records = (record_t *)malloc(limit * sizeof(record_t));
    offsets = (long *)malloc((limit + 1) * sizeof(long));
    keys = (int *)malloc(limit * sizeof(int));

    for (int i = 0; i < limit; i++) {
        record_t *r = &records[i];
        r->val = rand() % 100;
        strcpy(r->id, "record");
        keys[i] = r->val;
    }

    qsort(keys, record_count, sizeof(int), int_cmp);
}

void update_record(record_t *r) {
    // implement update logic here
}

int find_offset(long val) {
    int lo = 0;
    int hi = record_count;

    while (hi - lo > 1) {
        int mid = (lo + hi) / 2;
        if (keys[mid] < val)
            lo = mid;
        else
            hi = mid;
    }

    return offsets[hi];
}

void compress_offsets() {
    long *new_offsets = (long *)malloc((record_count + 1) * sizeof(long));
    int new_offset_index = 0;

    for (int i = 0; i < record_count; i++) {
        if (offsets[i] != offsets[i - 1]) {
            new_offsets[new_offset_index++] = offsets[i];
        }
    }

    free(offsets);
    offsets = new_offsets;
}

void cleanup() {
    free(records);
    free(offsets);
    free(keys);
}

