typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

void populateArray(int N, NFAPI_CRC_INDICATION_PDU_T** array) {
    *array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*array)[i].RNTI = rand() % 1000;

        srand(time(NULL) + i);
        for (int j = 0; j < 16; j++) {
            (*array)[i].CRC_INDICATION_REL8_TAG[j] = (unsigned char)(rand() % 256);
        }
    }
}

void serializeArray(const NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    FILE* file = fopen("data.bin", "wb");

    if (!file) {
        printf("Error opening file for writing.\n");
        return;
    }

    fwrite(&N, sizeof(int), 1, file);

    for (int i = 0; i < N; i++) {
        fwrite(&array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

int main() {
    int N;
    printf("Enter the number of structures to populate: ");
    scanf("%d", &N);

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    populateArray(N, &array);

    serializeArray(array, N);

    free(array);
    return 0;
}
